    ('ciencia/biologia/angulos_ramachandran_peptideos.omega',
        'modulo science_52;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Supplied empirical angle boxes and optional nonlocal hard-sphere clash tests; not a proof of protein fold viability.\n'
        'funcao execute(r)  {\n'
        '  var phi=u::q(r,"phi");\n'
        '  var psi=u::q(r,"psi");\n'
        '  var regions=u::mat(r["allowed_regions"]);\n'
        '  se(len(regions[0])!=4)  {\n'
        '    fail("Empirical Ramachandran boxes [phi_lo,phi_hi,psi_lo,psi_hi]");\n'
        '  }\n'
        '  var matches=[];\n'
        '  var i=0;\n'
        '  enquanto(i<len(regions))  {\n'
        '    var b=regions[i];\n'
        '    se(b[0]>b[1]||b[2]>b[3])  {\n'
        '      fail("Invalid angle region");\n'
        '    }\n'
        '    se(b[0]<=phi&&phi<=b[1]&&b[2]<=psi&&psi<=b[3])  {\n'
        '      push(matches,i);\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  var out=u::result("declared-Ramachandran-region-classifier",matches);\n'
        '  put(out,"steric_clearance_checked",0);\n'
        '  se(has(r,"atom_positions"))  {\n'
        '    var positions=u::mat(r["atom_positions"]);\n'
        '    var radii=u::vector(r["radii"]);\n'
        '    se(len(positions[0])!=3||len(radii)!=len(positions))  {\n'
        '      fail("Steric input shape");\n'
        '    }\n'
        '    var overlaps=[];\n'
        '    i=0;\n'
        '    enquanto(i<len(positions))  {\n'
        '      u::positive(radii[i]);\n'
        '      var j=i+3;\n'
        '      enquanto(j<len(positions))  {\n'
        '        var delta=u::add(positions[i],u::scale(positions[j],-1));\n'
        '        se(u::dot(delta,delta)<(radii[i]+radii[j])*(radii[i]+radii[j]))  {\n'
        '          push(overlaps,[i,j]);\n'
        '        }\n'
        '        j=j+1;\n'
        '      }\n'
        '      i=i+1;\n'
        '    }\n'
        '    put(out,"steric_overlaps",overlaps);\n'
        '    put(out,"steric_clearance_checked",1);\n'
        '  }\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/biologia/arvore_filogenetica_upgma.omega',
        'modulo science_44;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Exact average-linkage UPGMA; molecular-clock/ultrametric suitability remains an input-model assumption.\n'
        'funcao validate(a)  {\n'
        '  var n=len(a);\n'
        '  se(n!=len(a[0])||n>16)  {\n'
        '    fail("Distance matrix shape");\n'
        '  }\n'
        '  var i=0;\n'
        '  enquanto(i<n)  {\n'
        '    var j=0;\n'
        '    enquanto(j<n)  {\n'
        '      se(a[i][j]<0||a[i][j]!=a[j][i]||(i==j&&a[i][j]!=0))  {\n'
        '        fail("Symmetric nonnegative zero-diagonal distances required");\n'
        '      }\n'
        '      j=j+1;\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar 0;\n'
        '}\n'
        'funcao average(a,left,right)  {\n'
        '  var sum=0;\n'
        '  var i=0;\n'
        '  enquanto(i<len(left))  {\n'
        '    var j=0;\n'
        '    enquanto(j<len(right))  {\n'
        '      sum=sum+a[left[i]][right[j]];\n'
        '      j=j+1;\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar sum/(len(left)*len(right));\n'
        '}\n'
        'funcao execute(r)  {\n'
        '  var a=u::mat(r["distances"]);\n'
        '  validate(a);\n'
        '  var n=len(a);\n'
        '  se(n<2)  {\n'
        '    fail("Two taxa required");\n'
        '  }\n'
        '  var clusters=[];\n'
        '  var heights=[];\n'
        '  var ids=[];\n'
        '  var i=0;\n'
        '  enquanto(i<n)  {\n'
        '    push(clusters,[i]);\n'
        '    push(heights,0);\n'
        '    push(ids,i);\n'
        '    i=i+1;\n'
        '  }\n'
        '  var merges=[];\n'
        '  enquanto(len(clusters)>1)  {\n'
        '    var p=0;\n'
        '    var q=1;\n'
        '    var best=average(a,clusters[0],clusters[1]);\n'
        '    i=0;\n'
        '    enquanto(i<len(clusters))  {\n'
        '      var j=i+1;\n'
        '      enquanto(j<len(clusters))  {\n'
        '        var d=average(a,clusters[i],clusters[j]);\n'
        '        se(d<best)  {\n'
        '          best=d;\n'
        '          p=i;\n'
        '          q=j;\n'
        '        }\n'
        '        j=j+1;\n'
        '      }\n'
        '      i=i+1;\n'
        '    }\n'
        '    var record=obj();\n'
        '    put(record,"left",ids[p]);\n'
        '    put(record,"right",ids[q]);\n'
        '    put(record,"height",best/2);\n'
        '    put(record,"left_length",best/2-heights[p]);\n'
        '    put(record,"right_length",best/2-heights[q]);\n'
        '    push(merges,record);\n'
        '    var members=slice(clusters[p],0,len(clusters[p]));\n'
        '    i=0;\n'
        '    enquanto(i<len(clusters[q]))  {\n'
        '      push(members,clusters[q][i]);\n'
        '      i=i+1;\n'
        '    }\n'
        '    var nc=[];\n'
        '    var nh=[];\n'
        '    var ni=[];\n'
        '    i=0;\n'
        '    enquanto(i<len(clusters))  {\n'
        '      se(i!=p&&i!=q)  {\n'
        '        push(nc,clusters[i]);\n'
        '        push(nh,heights[i]);\n'
        '        push(ni,ids[i]);\n'
        '      }\n'
        '      i=i+1;\n'
        '    }\n'
        '    push(nc,members);\n'
        '    push(nh,best/2);\n'
        '    push(ni,n+len(merges)-1);\n'
        '    clusters=nc;\n'
        '    heights=nh;\n'
        '    ids=ni;\n'
        '  }\n'
        '  retornar u::result("UPGMA-average-linkage",merges);\n'
        '}\n'
    ),
    ('ciencia/biologia/cinetica_transporte_membrana.omega',
        'modulo science_53;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Closed two-compartment Fick step with exact total amount and nonnegative-concentration guard.\n'
        'funcao execute(r)  {\n'
        '  var inside=u::nonnegative(u::q(r,"inside_concentration"));\n'
        '  var outside=u::nonnegative(u::q(r,"outside_concentration"));\n'
        '  var vin=u::positive(u::q(r,"inside_volume"));\n'
        '  var vout=u::positive(u::q(r,"outside_volume"));\n'
        '  var diffusion=u::positive(u::q(r,"diffusion"));\n'
        '  var thickness=u::positive(u::q(r,"thickness"));\n'
        '  var area=u::positive(u::q(r,"area"));\n'
        '  var time=u::positive(u::q(r,"step"));\n'
        '  var flux=diffusion*(inside-outside)/thickness;\n'
        '  var transfer=flux*area*time;\n'
        '  var ni=inside*vin-transfer;\n'
        '  var no=outside*vout+transfer;\n'
        '  se(ni<0||no<0)  {\n'
        '    fail("Transport step would create negative concentration");\n'
        '  }\n'
        '  se(ni+no!=inside*vin+outside*vout)  {\n'
        '    fail("Membrane mass conservation");\n'
        '  }\n'
        '  var out=u::result("two-compartment-Fick-discrete-step",[ni/vin,no/vout]);\n'
        '  put(out,"outward_flux",flux);\n'
        '  put(out,"total_amount",ni+no);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/biologia/crescimento_logistico_populacional.omega',
        'modulo science_49;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Rational Beverton-Holt logistic discretisation preserves [0,K]; it is not the exact continuous exponential solution.\n'
        'funcao execute(r)  {\n'
        '  var x=u::nonnegative(u::q(r,"population"));\n'
        '  var k=u::positive(u::q(r,"capacity"));\n'
        '  se(x>k)  {\n'
        '    fail("Population must initially lie in [0,K]");\n'
        '  }\n'
        '  var rate=u::nonnegative(u::q(r,"rate"));\n'
        '  var h=u::positive(u::q(r,"step"));\n'
        '  var count=u::count(r,"steps",1,64);\n'
        '  var growth=1+h*rate;\n'
        '  var trace=[x];\n'
        '  var i=0;\n'
        '  enquanto(i<count)  {\n'
        '    x=u::check(k*growth*x/(k+(growth-1)*x));\n'
        '    se(x<0||x>k)  {\n'
        '      fail("Logistic invariant violated");\n'
        '    }\n'
        '    push(trace,x);\n'
        '    i=i+1;\n'
        '  }\n'
        '  var out=u::result("Beverton-Holt-discrete-logistic",x);\n'
        '  put(out,"trace",trace);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/biologia/equilibrio_hardy_weinberg.omega',
        'modulo science_50;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Two-allele random-mating model without selection/migration/mutation; exact genotype sum and allele invariance.\n'
        'funcao execute(r)  {\n'
        '  var p=0;\n'
        '  se(has(r,"genotypes"))  {\n'
        '    var g=u::vector(r["genotypes"]);\n'
        '    se(len(g)!=3||g[0]<0||g[1]<0||g[2]<0||g[0]+g[1]+g[2]!=1)  {\n'
        '      fail("Genotype probabilities must be nonnegative and sum to one");\n'
        '    }\n'
        '    p=g[0]+g[1]/2;\n'
        '  }\n'
        '  senao  {\n'
        '    p=u::q(r,"allele_frequency");\n'
        '  }\n'
        '  se(p<0||p>1)  {\n'
        '    fail("Allele frequency in [0,1]");\n'
        '  }\n'
        '  var q=1-p;\n'
        '  var g=[p*p,2*p*q,q*q];\n'
        '  se(g[0]+g[1]+g[2]!=1||g[0]+g[1]/2!=p)  {\n'
        '    fail("Mendelian equilibrium identity");\n'
        '  }\n'
        '  var out=u::result("random-mating-Hardy-Weinberg",g);\n'
        '  put(out,"allele_frequency",p);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/biologia/fm_index_bwt_aligner.omega',
        'modulo science_41;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Finite BWT/FM backward search with explicit sentinel and occurrence counts; bounded pedagogical suffix construction.\n'
        'funcao occ(text,ch,end)  {\n'
        '  var n=0;\n'
        '  var i=0;\n'
        '  enquanto(i<end)  {\n'
        '    se(text[i]==ch)  {\n'
        '      n=n+1;\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar n;\n'
        '}\n'
        'funcao execute(r)  {\n'
        '  var text=u::text_field(r,"text",512);\n'
        '  var pattern=u::text_field(r,"pattern",128);\n'
        '  se(contains(text,"$")||len(pattern)==0||contains(pattern,"$"))  {\n'
        '    fail("Nonempty pattern and unique reserved BWT sentinel required");\n'
        '  }\n'
        '  var t=text+"$";\n'
        '  var rotations=[];\n'
        '  var i=0;\n'
        '  enquanto(i<len(t))  {\n'
        '    push(rotations,[slice(t,i,len(t))+slice(t,0,i),i]);\n'
        '    i=i+1;\n'
        '  }\n'
        '  i=1;\n'
        '  enquanto(i<len(rotations))  {\n'
        '    var j=i;\n'
        '    enquanto(j>0&&rotations[j][0]<rotations[j-1][0])  {\n'
        '      var tmp=rotations[j];\n'
        '      put(rotations,j,rotations[j-1]);\n'
        '      put(rotations,j-1,tmp);\n'
        '      j=j-1;\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  var chars=[];\n'
        '  i=0;\n'
        '  enquanto(i<len(rotations))  {\n'
        '    push(chars,rotations[i][0][len(t)-1]);\n'
        '    i=i+1;\n'
        '  }\n'
        '  var bwt=join(chars,"");\n'
        '  var lo=0;\n'
        '  var hi=len(t);\n'
        '  i=len(pattern);\n'
        '  enquanto(i>0&&lo<hi)  {\n'
        '    i=i-1;\n'
        '    var ch=pattern[i];\n'
        '    var smaller=0;\n'
        '    var j=0;\n'
        '    enquanto(j<len(t))  {\n'
        '      se(t[j]<ch)  {\n'
        '        smaller=smaller+1;\n'
        '      }\n'
        '      j=j+1;\n'
        '    }\n'
        '    lo=smaller+occ(bwt,ch,lo);\n'
        '    hi=smaller+occ(bwt,ch,hi);\n'
        '  }\n'
        '  var matches=[];\n'
        '  i=lo;\n'
        '  enquanto(i<hi)  {\n'
        '    push(matches,rotations[i][1]);\n'
        '    i=i+1;\n'
        '  }\n'
        '  i=1;\n'
        '  enquanto(i<len(matches))  {\n'
        '    var j=i;\n'
        '    enquanto(j>0&&matches[j]<matches[j-1])  {\n'
        '      var x=matches[j];\n'
        '      put(matches,j,matches[j-1]);\n'
        '      put(matches,j-1,x);\n'
        '      j=j-1;\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  var out=u::result("BWT-backward-search",matches);\n'
        '  put(out,"bwt",bwt);\n'
        '  put(out,"suffix_interval",[lo,hi]);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/biologia/lotka_volterra_presa_predador.omega',
        'modulo science_48;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Positive bounded rational nonstandard map; reports continuous-integral drift instead of promising closed orbit preservation.\n'
        'funcao energy(x,y,a,b,c,d)  {\n'
        '  var lx=m::log_interval(x,16);\n'
        '  var ly=m::log_interval(y,16);\n'
        '  retornar [d*x+b*y-c*lx[1]-a*ly[1],d*x+b*y-c*lx[0]-a*ly[0]];\n'
        '}\n'
        'funcao execute(r)  {\n'
        '  var x=u::positive(u::q(r,"prey"));\n'
        '  var y=u::positive(u::q(r,"predator"));\n'
        '  var a=u::positive(u::q(r,"prey_growth"));\n'
        '  var b=u::positive(u::q(r,"predation"));\n'
        '  var c=u::positive(u::q(r,"predator_death"));\n'
        '  var d=u::positive(u::q(r,"conversion"));\n'
        '  var h=u::positive(u::q(r,"step"));\n'
        '  var steps=u::count(r,"steps",1,32);\n'
        '  var cap=u::positive(u::num(r,"population_limit",1000000));\n'
        '  var initial=energy(x,y,a,b,c,d);\n'
        '  var trace=[[x,y]];\n'
        '  var i=0;\n'
        '  enquanto(i<steps)  {\n'
        '    x=u::check(x*(1+h*a)/(1+h*b*y));\n'
        '    y=u::check(y*(1+h*d*x)/(1+h*c));\n'
        '    se(x<=0||y<=0||x>cap||y>cap)  {\n'
        '      fail("Population domain/budget exceeded");\n'
        '    }\n'
        '    push(trace,[x,y]);\n'
        '    i=i+1;\n'
        '  }\n'
        '  var final=energy(x,y,a,b,c,d);\n'
        '  var out=u::result("positive-Patankar-Lotka-Volterra-map",trace);\n'
        '  put(out,"continuous_first_integral_change",[final[0]-initial[1],final[1]-initial[0]]);\n'
        '  put(out,"closed_orbits_preserved",0);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/biologia/maxima_parcimonia_fitch.omega',
        'modulo science_46;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Fitch minimum unit-change score for one DNA character on a supplied binary tree; ambiguity sets are supported.\n'
        'funcao fitch(tree,counter)  {\n'
        '  put(counter,0,counter[0]+1);\n'
        '  se(counter[0]>255)  {\n'
        '    fail("Fitch tree size budget");\n'
        '  }\n'
        '  var out=obj();\n'
        '  se(isstr(tree))  {\n'
        '    se(len(tree)<1||len(tree)>4)  {\n'
        '      fail("Leaf state set length");\n'
        '    }\n'
        '    var states=[];\n'
        '    var i=0;\n'
        '    enquanto(i<len(tree))  {\n'
        '      se(!contains("ACGT",tree[i]))  {\n'
        '        fail("DNA states A/C/G/T required");\n'
        '      }\n'
        '      se(!contains(states,tree[i]))  {\n'
        '        push(states,tree[i]);\n'
        '      }\n'
        '      i=i+1;\n'
        '    }\n'
        '    put(out,"states",states);\n'
        '    put(out,"score",0);\n'
        '    retornar out;\n'
        '  }\n'
        '  se(!islist(tree)||len(tree)!=2)  {\n'
        '    fail("Binary rooted Fitch tree required");\n'
        '  }\n'
        '  var left=fitch(tree[0],counter);\n'
        '  var right=fitch(tree[1],counter);\n'
        '  var intersection=[];\n'
        '  var union=slice(left["states"],0,len(left["states"]));\n'
        '  var i=0;\n'
        '  enquanto(i<len(right["states"]))  {\n'
        '    var v=right["states"][i];\n'
        '    se(contains(left["states"],v))  {\n'
        '      push(intersection,v);\n'
        '    }\n'
        '    senao  {\n'
        '      push(union,v);\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  var score=left["score"]+right["score"];\n'
        '  se(len(intersection)>0)  {\n'
        '    put(out,"states",intersection);\n'
        '  }\n'
        '  senao  {\n'
        '    put(out,"states",union);\n'
        '    score=score+1;\n'
        '  }\n'
        '  put(out,"score",score);\n'
        '  retornar out;\n'
        '}\n'
        'funcao execute(r)  {\n'
        '  var out=fitch(r["tree"],[0]);\n'
        '  put(out,"model","unit-cost-Fitch-site-parsimony");\n'
        '  put(out,"formal_admission",0);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/biologia/modelo_jukes_cantor.omega',
        'modulo science_47;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Homogeneous JC69 correction with a checked saturation/log domain; empirical model applicability is not proved.\n'
        'funcao execute(r)  {\n'
        '  var difference=u::q(r,"difference_fraction");\n'
        '  se(difference<0||difference>=3/4)  {\n'
        '    fail("JC69 saturation domain 0 <= p < 3/4");\n'
        '  }\n'
        '  var log=m::log_interval(1-4*difference/3,24);\n'
        '  var out=u::result("JC69-evolutionary-distance-enclosure",[-3*log[1]/4,-3*log[0]/4]);\n'
        '  put(out,"observed_difference",difference);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/biologia/montagem_debruijn_euler.omega',
        'modulo science_42;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Spells one Eulerian traversal using every supplied kmer; repeats can make the original sequence nonunique.\n'
        'funcao vertex(names,s)  {\n'
        '  var i=0;\n'
        '  enquanto(i<len(names))  {\n'
        '    se(names[i]==s)  {\n'
        '      retornar i;\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  push(names,s);\n'
        '  retornar len(names)-1;\n'
        '}\n'
        'funcao execute(r)  {\n'
        '  var raw=s::as_list(r["kmers"]);\n'
        '  se(len(raw)<1||len(raw)>256)  {\n'
        '    fail("Kmer count budget");\n'
        '  }\n'
        '  var k=len(s::as_string(raw[0]));\n'
        '  u::integer(k,2,32);\n'
        '  var names=[];\n'
        '  var edges=[];\n'
        '  var i=0;\n'
        '  enquanto(i<len(raw))  {\n'
        '    var word=s::as_string(raw[i]);\n'
        '    se(len(word)!=k)  {\n'
        '      fail("Kmer length mismatch");\n'
        '    }\n'
        '    var a=vertex(names,slice(word,0,k-1));\n'
        '    var b=vertex(names,slice(word,1,k));\n'
        '    push(edges,[a,b]);\n'
        '    i=i+1;\n'
        '  }\n'
        '  var incoming=u::zeros(len(names));\n'
        '  var outgoing=u::zeros(len(names));\n'
        '  i=0;\n'
        '  enquanto(i<len(edges))  {\n'
        '    put(outgoing,edges[i][0],outgoing[edges[i][0]]+1);\n'
        '    put(incoming,edges[i][1],incoming[edges[i][1]]+1);\n'
        '    i=i+1;\n'
        '  }\n'
        '  var start=edges[0][0];\n'
        '  var positive=0;\n'
        '  var negative=0;\n'
        '  i=0;\n'
        '  enquanto(i<len(names))  {\n'
        '    var d=outgoing[i]-incoming[i];\n'
        '    se(d==1)  {\n'
        '      start=i;\n'
        '      positive=positive+1;\n'
        '    }\n'
        '    senao  {\n'
        '      se(d==-1)  {\n'
        '        negative=negative+1;\n'
        '      }\n'
        '      senao  {\n'
        '        se(d!=0)  {\n'
        '          fail("Non-Eulerian degree sequence");\n'
        '        }\n'
        '      }\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  se(!((positive==0&&negative==0)||(positive==1&&negative==1)))  {\n'
        '    fail("Eulerian path endpoint imbalance");\n'
        '  }\n'
        '  var used=u::zeros(len(edges));\n'
        '  var stack=[start];\n'
        '  var walk=[];\n'
        '  enquanto(len(stack)>0)  {\n'
        '    var v=stack[len(stack)-1];\n'
        '    var e=0;\n'
        '    enquanto(e<len(edges)&&(used[e]||edges[e][0]!=v))  {\n'
        '      e=e+1;\n'
        '    }\n'
        '    se(e==len(edges))  {\n'
        '      push(walk,v);\n'
        '      stack=slice(stack,0,len(stack)-1);\n'
        '    }\n'
        '    senao  {\n'
        '      put(used,e,1);\n'
        '      push(stack,edges[e][1]);\n'
        '    }\n'
        '  }\n'
        '  se(len(walk)!=len(edges)+1)  {\n'
        '    fail("Disconnected kmer graph");\n'
        '  }\n'
        '  var sequence=names[walk[len(walk)-1]];\n'
        '  i=len(walk)-1;\n'
        '  enquanto(i>0)  {\n'
        '    i=i-1;\n'
        '    var word=names[walk[i]];\n'
        '    sequence=sequence+word[k-2];\n'
        '  }\n'
        '  var out=u::result("Hierholzer-kmer-spelling",sequence);\n'
        '  put(out,"unique_original_reconstruction",0);\n'
        '  put(out,"edges_consumed",len(edges));\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/biologia/needleman_wunsch_exato.omega',
        'modulo science_39;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Global affine-gap dynamic programming and deterministic traceback; byte sequences up to 128 bytes.\n'
        'funcao table(n,k,value)  {\n'
        '  var a=[];\n'
        '  var i=0;\n'
        '  enquanto(i<n)  {\n'
        '    var row=[];\n'
        '    var j=0;\n'
        '    enquanto(j<k)  {\n'
        '      push(row,value);\n'
        '      j=j+1;\n'
        '    }\n'
        '    push(a,row);\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar a;\n'
        '}\n'
        'funcao max3(a,b,c)  {\n'
        '  retornar m::max(a,m::max(b,c));\n'
        '}\n'
        'funcao reverse(xs)  {\n'
        '  var out=[];\n'
        '  var i=len(xs);\n'
        '  enquanto(i>0)  {\n'
        '    i=i-1;\n'
        '    push(out,xs[i]);\n'
        '  }\n'
        '  retornar join(out,"");\n'
        '}\n'
        'funcao execute(r)  {\n'
        '  var a=u::text_field(r,"sequence1",128);\n'
        '  var b=u::text_field(r,"sequence2",128);\n'
        '  var match=u::q(r,"match");\n'
        '  var mismatch=u::q(r,"mismatch");\n'
        '  var open=u::positive(u::q(r,"gap_open"));\n'
        '  var extend=u::positive(u::q(r,"gap_extend"));\n'
        '  var n=len(a);\n'
        '  var k=len(b);\n'
        '  var low=-(n+k+2)*(m::abs(match)+m::abs(mismatch)+open+extend+1);\n'
        '  var mm=table(n+1,k+1,low);\n'
        '  var xx=table(n+1,k+1,low);\n'
        '  var yy=table(n+1,k+1,low);\n'
        '  put(mm[0],0,0);\n'
        '  var i=1;\n'
        '  enquanto(i<=n)  {\n'
        '    put(xx[i],0,-open-(i-1)*extend);\n'
        '    i=i+1;\n'
        '  }\n'
        '  var j=1;\n'
        '  enquanto(j<=k)  {\n'
        '    put(yy[0],j,-open-(j-1)*extend);\n'
        '    j=j+1;\n'
        '  }\n'
        '  i=1;\n'
        '  enquanto(i<=n)  {\n'
        '    j=1;\n'
        '    enquanto(j<=k)  {\n'
        '      var score=mismatch;\n'
        '      se(a[i-1]==b[j-1])  {\n'
        '        score=match;\n'
        '      }\n'
        '      put(mm[i],j,max3(mm[i-1][j-1],xx[i-1][j-1],yy[i-1][j-1])+score);\n'
        '      put(xx[i],j,max3(mm[i-1][j]-open,xx[i-1][j]-extend,yy[i-1][j]-open));\n'
        '      put(yy[i],j,max3(mm[i][j-1]-open,xx[i][j-1]-open,yy[i][j-1]-extend));\n'
        '      j=j+1;\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  var best=max3(mm[n][k],xx[n][k],yy[n][k]);\n'
        '  var state=0;\n'
        '  se(best!=mm[n][k])  {\n'
        '    state=1;\n'
        '    se(best!=xx[n][k])  {\n'
        '      state=2;\n'
        '    }\n'
        '  }\n'
        '  var left=[];\n'
        '  var right=[];\n'
        '  i=n;\n'
        '  j=k;\n'
        '  enquanto(i>0||j>0)  {\n'
        '    se(state==0)  {\n'
        '      se(i==0||j==0)  {\n'
        '        fail("Alignment traceback state");\n'
        '      }\n'
        '      push(left,a[i-1]);\n'
        '      push(right,b[j-1]);\n'
        '      var prev=max3(mm[i-1][j-1],xx[i-1][j-1],yy[i-1][j-1]);\n'
        '      state=0;\n'
        '      se(prev!=mm[i-1][j-1])  {\n'
        '        state=1;\n'
        '        se(prev!=xx[i-1][j-1])  {\n'
        '          state=2;\n'
        '        }\n'
        '      }\n'
        '      i=i-1;\n'
        '      j=j-1;\n'
        '    }\n'
        '    senao  {\n'
        '      se(state==1)  {\n'
        '        se(i==0)  {\n'
        '          fail("Alignment gap traceback");\n'
        '        }\n'
        '        push(left,a[i-1]);\n'
        '        push(right,"-");\n'
        '        var value=xx[i][j];\n'
        '        se(value==xx[i-1][j]-extend)  {\n'
        '          state=1;\n'
        '        }\n'
        '        senao  {\n'
        '          state=0;\n'
        '          se(value!=mm[i-1][j]-open)  {\n'
        '            state=2;\n'
        '          }\n'
        '        }\n'
        '        i=i-1;\n'
        '      }\n'
        '      senao  {\n'
        '        se(j==0)  {\n'
        '          fail("Alignment gap traceback");\n'
        '        }\n'
        '        push(left,"-");\n'
        '        push(right,b[j-1]);\n'
        '        var value=yy[i][j];\n'
        '        se(value==yy[i][j-1]-extend)  {\n'
        '          state=2;\n'
        '        }\n'
        '        senao  {\n'
        '          state=0;\n'
        '          se(value!=mm[i][j-1]-open)  {\n'
        '            state=1;\n'
        '          }\n'
        '        }\n'
        '        j=j-1;\n'
        '      }\n'
        '    }\n'
        '  }\n'
        '  var out=u::result("global-affine-gap-alignment",best);\n'
        '  put(out,"alignment",[reverse(left),reverse(right)]);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/biologia/neighbor_joining_tree.omega',
        'modulo science_45;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Exact NJ Q-criterion and branch lengths; negative limbs from nonadditive data are reported without clamping.\n'
        'funcao execute(r)  {\n'
        '  var d=u::mat(r["distances"]);\n'
        '  var n=len(d);\n'
        '  se(n<2||n!=len(d[0])||n>16)  {\n'
        '    fail("NJ distance matrix shape");\n'
        '  }\n'
        '  var ids=[];\n'
        '  var i=0;\n'
        '  enquanto(i<n)  {\n'
        '    push(ids,i);\n'
        '    var j=0;\n'
        '    enquanto(j<n)  {\n'
        '      se(d[i][j]<0||d[i][j]!=d[j][i]||(i==j&&d[i][j]!=0))  {\n'
        '        fail("Invalid initial NJ distances");\n'
        '      }\n'
        '      j=j+1;\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  var next=n;\n'
        '  var edges=[];\n'
        '  var negative=0;\n'
        '  enquanto(len(d)>2)  {\n'
        '    var k=len(d);\n'
        '    var sums=[];\n'
        '    i=0;\n'
        '    enquanto(i<k)  {\n'
        '      var sum=0;\n'
        '      var j=0;\n'
        '      enquanto(j<k)  {\n'
        '        sum=sum+d[i][j];\n'
        '        j=j+1;\n'
        '      }\n'
        '      push(sums,sum);\n'
        '      i=i+1;\n'
        '    }\n'
        '    var p=0;\n'
        '    var q=1;\n'
        '    var best=(k-2)*d[0][1]-sums[0]-sums[1];\n'
        '    i=0;\n'
        '    enquanto(i<k)  {\n'
        '      var j=i+1;\n'
        '      enquanto(j<k)  {\n'
        '        var score=(k-2)*d[i][j]-sums[i]-sums[j];\n'
        '        se(score<best)  {\n'
        '          best=score;\n'
        '          p=i;\n'
        '          q=j;\n'
        '        }\n'
        '        j=j+1;\n'
        '      }\n'
        '      i=i+1;\n'
        '    }\n'
        '    var limb=d[p][q]/2+(sums[p]-sums[q])/(2*(k-2));\n'
        '    push(edges,[next,ids[p],limb]);\n'
        '    push(edges,[next,ids[q],d[p][q]-limb]);\n'
        '    se(limb<0||d[p][q]-limb<0)  {\n'
        '      negative=negative+1;\n'
        '    }\n'
        '    var keep=[];\n'
        '    i=0;\n'
        '    enquanto(i<k)  {\n'
        '      se(i!=p&&i!=q)  {\n'
        '        push(keep,i);\n'
        '      }\n'
        '      i=i+1;\n'
        '    }\n'
        '    var matrix=[];\n'
        '    var ni=[];\n'
        '    i=0;\n'
        '    enquanto(i<len(keep))  {\n'
        '      var row=[];\n'
        '      var j=0;\n'
        '      enquanto(j<len(keep))  {\n'
        '        push(row,d[keep[i]][keep[j]]);\n'
        '        j=j+1;\n'
        '      }\n'
        '      push(row,(d[p][keep[i]]+d[q][keep[i]]-d[p][q])/2);\n'
        '      push(matrix,row);\n'
        '      push(ni,ids[keep[i]]);\n'
        '      i=i+1;\n'
        '    }\n'
        '    var row=[];\n'
        '    i=0;\n'
        '    enquanto(i<len(keep))  {\n'
        '      push(row,(d[p][keep[i]]+d[q][keep[i]]-d[p][q])/2);\n'
        '      i=i+1;\n'
        '    }\n'
        '    push(row,0);\n'
        '    push(matrix,row);\n'
        '    push(ni,next);\n'
        '    d=matrix;\n'
        '    ids=ni;\n'
        '    next=next+1;\n'
        '  }\n'
        '  push(edges,[ids[0],ids[1],d[0][1]]);\n'
        '  var out=u::result("neighbor-joining-unrooted-tree",edges);\n'
        '  put(out,"negative_limb_events",negative);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/biologia/potencial_lennard_jones_molecular.omega',
        'modulo science_51;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Exact squared-distance potential and force on a pair; singular coincident positions are rejected.\n'
        'funcao execute(r)  {\n'
        '  var displacement=u::vector(r["displacement"]);\n'
        '  se(len(displacement)<1||len(displacement)>3)  {\n'
        '    fail("One to three spatial coordinates required");\n'
        '  }\n'
        '  var epsilon=u::positive(u::q(r,"epsilon"));\n'
        '  var sigma=u::positive(u::q(r,"sigma"));\n'
        '  var d2=u::positive(u::dot(displacement,displacement));\n'
        '  var q=u::power(sigma*sigma/d2,3);\n'
        '  var potential=4*epsilon*(q*q-q);\n'
        '  var force=u::scale(displacement,24*epsilon*(2*q*q-q)/d2);\n'
        '  var out=u::result("Lennard-Jones-12-6-pair",potential);\n'
        '  put(out,"force",force);\n'
        '  put(out,"distance_squared",d2);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/biologia/scoring_matrices_pam_blosum.omega',
        'modulo science_43;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'importar "../core/intervalos.omega" como iv;\n'
        'exportar execute;\n'
        '# Derives bounded log-odds from supplied counts and pseudocounts; does not invent published PAM/BLOSUM datasets.\n'
        'funcao execute(r)  {\n'
        '  var counts=u::mat(r["counts"]);\n'
        '  var n=len(counts);\n'
        '  se(n!=len(counts[0])||n>20)  {\n'
        '    fail("Square substitution count matrix up to 20");\n'
        '  }\n'
        '  var pseudo=u::positive(u::num(r,"pseudocount",1));\n'
        '  var row=u::zeros(n);\n'
        '  var col=u::zeros(n);\n'
        '  var total=0;\n'
        '  var i=0;\n'
        '  enquanto(i<n)  {\n'
        '    var j=0;\n'
        '    enquanto(j<n)  {\n'
        '      u::nonnegative(counts[i][j]);\n'
        '      var value=counts[i][j]+pseudo;\n'
        '      put(counts[i],j,value);\n'
        '      put(row,i,row[i]+value);\n'
        '      put(col,j,col[j]+value);\n'
        '      total=total+value;\n'
        '      j=j+1;\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  var scale=u::positive(u::num(r,"scale",2));\n'
        '  var ln2=m::log_interval(2,16);\n'
        '  var scores=[];\n'
        '  i=0;\n'
        '  enquanto(i<n)  {\n'
        '    var line=[];\n'
        '    var j=0;\n'
        '    enquanto(j<n)  {\n'
        '      var ratio=counts[i][j]*total/(row[i]*col[j]);\n'
        '      var logarithm=m::log_interval(ratio,16);\n'
        '      push(line,iv::scale(iv::div(logarithm,ln2),scale));\n'
        '      j=j+1;\n'
        '    }\n'
        '    push(scores,line);\n'
        '    i=i+1;\n'
        '  }\n'
        '  var out=u::result("count-derived-log-odds-substitution-enclosures",scores);\n'
        '  put(out,"published_PAM_BLOSUM_parameters",0);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/biologia/smith_waterman_local.omega',
        'modulo science_40;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Smith-Waterman score and endpoint with two rows of memory; linear gaps, no reconstructed traceback.\n'
        'funcao execute(r)  {\n'
        '  var a=u::text_field(r,"sequence1",256);\n'
        '  var b=u::text_field(r,"sequence2",256);\n'
        '  var match=u::positive(u::q(r,"match"));\n'
        '  var mismatch=u::q(r,"mismatch");\n'
        '  var gap=u::positive(u::q(r,"gap"));\n'
        '  var previous=u::zeros(len(b)+1);\n'
        '  var best=0;\n'
        '  var endpoint=[0,0];\n'
        '  var i=1;\n'
        '  enquanto(i<=len(a))  {\n'
        '    var row=u::zeros(len(b)+1);\n'
        '    var j=1;\n'
        '    enquanto(j<=len(b))  {\n'
        '      var score=mismatch;\n'
        '      se(a[i-1]==b[j-1])  {\n'
        '        score=match;\n'
        '      }\n'
        '      var value=m::max(0,m::max(previous[j-1]+score,m::max(previous[j]-gap,row[j-1]-gap)));\n'
        '      put(row,j,value);\n'
        '      se(value>best)  {\n'
        '        best=value;\n'
        '        endpoint=[i,j];\n'
        '      }\n'
        '      j=j+1;\n'
        '    }\n'
        '    previous=row;\n'
        '    i=i+1;\n'
        '  }\n'
        '  var out=u::result("linear-space-local-alignment-score",best);\n'
        '  put(out,"endpoint",endpoint);\n'
        '  put(out,"traceback_available",0);\n'
        '  retornar out;\n'
        '}\n'
    ),
