    ('ciencia/core/exato.omega',
        'modulo science_exact;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math.omega" como m;\n'
        'exportar rem_int, val, q, num, count, vector, mat, check, positive, nonnegative, integer, power, copy, zeros, eye, dot, add, scale, transpose, mul, rref, solve, determinant, polynomial, orient, result, budget, text_field;\n'
        'funcao check(v)  {\n'
        '  se(qbits(v)>8192)  {\n'
        '    fail("Scientific rational bit budget exceeded");\n'
        '  }\n'
        '  retornar v;\n'
        '}\n'
        'funcao val(x)  {\n'
        '  se(!isnum(x)&&!isstr(x))  {\n'
        '    fail("Exact scalar required");\n'
        '  }\n'
        '  se(isstr(x)&&len(x)>640)  {\n'
        '    fail("Scalar text budget");\n'
        '  }\n'
        '  retornar check(s::rational(text(x)));\n'
        '}\n'
        'funcao q(r,k)  {\n'
        '  retornar val(r[k]);\n'
        '}\n'
        'funcao num(r,k,fallback)  {\n'
        '  se(has(r,k))  {\n'
        '    retornar q(r,k);\n'
        '  }\n'
        '  retornar fallback;\n'
        '}\n'
        'funcao integer(x,lo,hi)  {\n'
        '  se(!isnum(x)||qden(x)!=1||x<lo||x>hi)  {\n'
        '    fail("Integer outside scientific domain/budget");\n'
        '  }\n'
        '  retornar x;\n'
        '}\n'
        'funcao count(r,k,lo,hi)  {\n'
        '  retornar integer(q(r,k),lo,hi);\n'
        '}\n'
        'funcao positive(x)  {\n'
        '  se(x<=0)  {\n'
        '    fail("Strictly positive quantity required");\n'
        '  }\n'
        '  retornar x;\n'
        '}\n'
        'funcao nonnegative(x)  {\n'
        '  se(x<0)  {\n'
        '    fail("Nonnegative quantity required");\n'
        '  }\n'
        '  retornar x;\n'
        '}\n'
        'funcao budget(n,limit)  {\n'
        '  retornar integer(n,0,limit);\n'
        '}\n'
        'funcao vector(raw)  {\n'
        '  se(!islist(raw)||len(raw)>1024)  {\n'
        '    fail("Vector budget/shape");\n'
        '  }\n'
        '  var a=[];\n'
        '  var i=0;\n'
        '  enquanto(i<len(raw))  {\n'
        '    push(a,val(raw[i]));\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar a;\n'
        '}\n'
        'funcao mat(raw)  {\n'
        '  se(!islist(raw)||len(raw)<1||len(raw)>32||!islist(raw[0])||len(raw[0])<1||len(raw[0])>33)  {\n'
        '    fail("Matrix shape/budget");\n'
        '  }\n'
        '  var a=[];\n'
        '  var i=0;\n'
        '  enquanto(i<len(raw))  {\n'
        '    var row=vector(raw[i]);\n'
        '    se(len(row)!=len(raw[0]))  {\n'
        '      fail("Ragged matrix");\n'
        '    }\n'
        '    push(a,row);\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar a;\n'
        '}\n'
        'funcao copy(a)  {\n'
        '  var out=[];\n'
        '  var i=0;\n'
        '  enquanto(i<len(a))  {\n'
        '    push(out,slice(a[i],0,len(a[i])));\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar out;\n'
        '}\n'
        'funcao zeros(n)  {\n'
        '  integer(n,0,1024);\n'
        '  var a=[];\n'
        '  var i=0;\n'
        '  enquanto(i<n)  {\n'
        '    push(a,0);\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar a;\n'
        '}\n'
        'funcao eye(n)  {\n'
        '  integer(n,1,32);\n'
        '  var a=[];\n'
        '  var i=0;\n'
        '  enquanto(i<n)  {\n'
        '    var row=zeros(n);\n'
        '    put(row,i,1);\n'
        '    push(a,row);\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar a;\n'
        '}\n'
        'funcao power(x,n)  {\n'
        '  integer(n,-128,128);\n'
        '  se(n<0)  {\n'
        '    se(x==0)  {\n'
        '      fail("Negative power of zero");\n'
        '    }\n'
        '    retornar 1/power(x,-n);\n'
        '  }\n'
        '  var y=1;\n'
        '  enquanto(n>0)  {\n'
        '    se(n%2==1)  {\n'
        '      y=check(y*x);\n'
        '    }\n'
        '    n=qfloor(n/2);\n'
        '    se(n>0)  {\n'
        '      x=check(x*x);\n'
        '    }\n'
        '  }\n'
        '  retornar y;\n'
        '}\n'
        'funcao dot(a,b)  {\n'
        '  se(len(a)!=len(b))  {\n'
        '    fail("Dot shape");\n'
        '  }\n'
        '  var v=0;\n'
        '  var i=0;\n'
        '  enquanto(i<len(a))  {\n'
        '    v=check(v+a[i]*b[i]);\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar v;\n'
        '}\n'
        'funcao add(a,b)  {\n'
        '  se(len(a)!=len(b))  {\n'
        '    fail("Vector sum shape");\n'
        '  }\n'
        '  var out=[];\n'
        '  var i=0;\n'
        '  enquanto(i<len(a))  {\n'
        '    push(out,check(a[i]+b[i]));\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar out;\n'
        '}\n'
        'funcao scale(a,x)  {\n'
        '  var out=[];\n'
        '  var i=0;\n'
        '  enquanto(i<len(a))  {\n'
        '    push(out,check(a[i]*x));\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar out;\n'
        '}\n'
        'funcao transpose(a)  {\n'
        '  var out=[];\n'
        '  var j=0;\n'
        '  enquanto(j<len(a[0]))  {\n'
        '    var row=[];\n'
        '    var i=0;\n'
        '    enquanto(i<len(a))  {\n'
        '      push(row,a[i][j]);\n'
        '      i=i+1;\n'
        '    }\n'
        '    push(out,row);\n'
        '    j=j+1;\n'
        '  }\n'
        '  retornar out;\n'
        '}\n'
        'funcao mul(a,b)  {\n'
        '  se(len(a[0])!=len(b))  {\n'
        '    fail("Matrix product shape");\n'
        '  }\n'
        '  var bt=transpose(b);\n'
        '  var out=[];\n'
        '  var i=0;\n'
        '  enquanto(i<len(a))  {\n'
        '    var row=[];\n'
        '    var j=0;\n'
        '    enquanto(j<len(bt))  {\n'
        '      push(row,dot(a[i],bt[j]));\n'
        '      j=j+1;\n'
        '    }\n'
        '    push(out,row);\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar out;\n'
        '}\n'
        'funcao rref(raw)  {\n'
        '  var a=copy(raw);\n'
        '  var row=0;\n'
        '  var col=0;\n'
        '  var pivots=[];\n'
        '  enquanto(row<len(a)&&col<len(a[0]))  {\n'
        '    var p=row;\n'
        '    enquanto(p<len(a)&&a[p][col]==0)  {\n'
        '      p=p+1;\n'
        '    }\n'
        '    se(p<len(a))  {\n'
        '      var t=a[row];\n'
        '      put(a,row,a[p]);\n'
        '      put(a,p,t);\n'
        '      var d=a[row][col];\n'
        '      var j=0;\n'
        '      enquanto(j<len(a[0]))  {\n'
        '        put(a[row],j,check(a[row][j]/d));\n'
        '        j=j+1;\n'
        '      }\n'
        '      var i=0;\n'
        '      enquanto(i<len(a))  {\n'
        '        se(i!=row)  {\n'
        '          var f=a[i][col];\n'
        '          j=0;\n'
        '          enquanto(j<len(a[0]))  {\n'
        '            put(a[i],j,check(a[i][j]-f*a[row][j]));\n'
        '            j=j+1;\n'
        '          }\n'
        '        }\n'
        '        i=i+1;\n'
        '      }\n'
        '      push(pivots,col);\n'
        '      row=row+1;\n'
        '    }\n'
        '    col=col+1;\n'
        '  }\n'
        '  var out=obj();\n'
        '  put(out,"matrix",a);\n'
        '  put(out,"pivots",pivots);\n'
        '  put(out,"rank",row);\n'
        '  retornar out;\n'
        '}\n'
        'funcao solve(a,b)  {\n'
        '  var n=len(a);\n'
        '  se(n!=len(a[0])||len(b)!=n)  {\n'
        '    fail("Square solve shape");\n'
        '  }\n'
        '  var augmented=copy(a);\n'
        '  var i=0;\n'
        '  enquanto(i<n)  {\n'
        '    push(augmented[i],b[i]);\n'
        '    i=i+1;\n'
        '  }\n'
        '  var reduced=rref(augmented);\n'
        '  se(reduced["rank"]!=n)  {\n'
        '    fail("Singular linear system");\n'
        '  }\n'
        '  var x=[];\n'
        '  i=0;\n'
        '  enquanto(i<n)  {\n'
        '    se(reduced["pivots"][i]!=i)  {\n'
        '      fail("Inconsistent linear system");\n'
        '    }\n'
        '    push(x,reduced["matrix"][i][n]);\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar x;\n'
        '}\n'
        'funcao determinant(raw)  {\n'
        '  var a=copy(raw);\n'
        '  var n=len(a);\n'
        '  se(n!=len(a[0]))  {\n'
        '    fail("Square determinant shape");\n'
        '  }\n'
        '  var previous=1;\n'
        '  var sign=1;\n'
        '  var k=0;\n'
        '  enquanto(k<n-1)  {\n'
        '    var p=k;\n'
        '    enquanto(p<n&&a[p][k]==0)  {\n'
        '      p=p+1;\n'
        '    }\n'
        '    se(p==n)  {\n'
        '      retornar 0;\n'
        '    }\n'
        '    se(p!=k)  {\n'
        '      var row=a[p];\n'
        '      put(a,p,a[k]);\n'
        '      put(a,k,row);\n'
        '      sign=-sign;\n'
        '    }\n'
        '    var pivot=a[k][k];\n'
        '    var i=k+1;\n'
        '    enquanto(i<n)  {\n'
        '      var j=k+1;\n'
        '      enquanto(j<n)  {\n'
        '        put(a[i],j,check((pivot*a[i][j]-a[i][k]*a[k][j])/previous));\n'
        '        j=j+1;\n'
        '      }\n'
        '      put(a[i],k,0);\n'
        '      i=i+1;\n'
        '    }\n'
        '    previous=pivot;\n'
        '    k=k+1;\n'
        '  }\n'
        '  retornar sign*a[n-1][n-1];\n'
        '}\n'
        'funcao polynomial(coeffs,x)  {\n'
        '  var y=0;\n'
        '  var i=len(coeffs);\n'
        '  enquanto(i>0)  {\n'
        '    i=i-1;\n'
        '    y=check(y*x+coeffs[i]);\n'
        '  }\n'
        '  retornar y;\n'
        '}\n'
        'funcao orient(a,b,c)  {\n'
        '  retornar (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);\n'
        '}\n'
        'funcao result(kind,value)  {\n'
        '  var r=obj();\n'
        '  put(r,"model",kind);\n'
        '  put(r,"value",value);\n'
        '  put(r,"formal_admission",0);\n'
        '  retornar r;\n'
        '}\n'
        'funcao text_field(r,k,limit)  {\n'
        '  var v=s::as_string(r[k]);\n'
        '  se(len(v)>limit)  {\n'
        '    fail("Scientific text budget");\n'
        '  }\n'
        '  retornar v;\n'
        '}\n'
        'funcao rem_int(a,n)  {\n'
        '  se(qden(a)!=1||qden(n)!=1||n<=0)  {\n'
        '    fail("Integer remainder domain");\n'
        '  }\n'
        '  retornar a-n*qfloor(a/n);\n'
        '}\n'
    ),
    ('ciencia/core/intervalos.omega',
        'modulo science_intervals;\n'
        'importar "../../std/math.omega" como m;\n'
        'exportar box, point, add, sub, mul, div, scale, square, sqrt, exp, log, midpoint, encloses, intersect;\n'
        'funcao box(lo,hi)  {\n'
        '  se(lo>hi)  {\n'
        '    fail("Empty interval");\n'
        '  }\n'
        '  retornar [lo,hi];\n'
        '}\n'
        'funcao point(x)  {\n'
        '  retornar [x,x];\n'
        '}\n'
        'funcao add(a,b)  {\n'
        '  retornar [a[0]+b[0],a[1]+b[1]];\n'
        '}\n'
        'funcao sub(a,b)  {\n'
        '  retornar [a[0]-b[1],a[1]-b[0]];\n'
        '}\n'
        'funcao mul(a,b)  {\n'
        '  var p=[a[0]*b[0],a[0]*b[1],a[1]*b[0],a[1]*b[1]];\n'
        '  var lo=p[0];\n'
        '  var hi=lo;\n'
        '  var i=1;\n'
        '  enquanto(i<4)  {\n'
        '    lo=m::min(lo,p[i]);\n'
        '    hi=m::max(hi,p[i]);\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar [lo,hi];\n'
        '}\n'
        'funcao div(a,b)  {\n'
        '  se(b[0]<=0&&b[1]>=0)  {\n'
        '    fail("Interval divisor contains zero");\n'
        '  }\n'
        '  retornar mul(a,[1/b[1],1/b[0]]);\n'
        '}\n'
        'funcao scale(a,k)  {\n'
        '  retornar mul(a,[k,k]);\n'
        '}\n'
        'funcao square(a)  {\n'
        '  var hi=m::max(a[0]*a[0],a[1]*a[1]);\n'
        '  var lo=m::min(a[0]*a[0],a[1]*a[1]);\n'
        '  se(a[0]<=0&&a[1]>=0)  {\n'
        '    lo=0;\n'
        '  }\n'
        '  retornar [lo,hi];\n'
        '}\n'
        'funcao sqrt(a,bits)  {\n'
        '  se(a[0]<0)  {\n'
        '    fail("Square-root interval domain");\n'
        '  }\n'
        '  var lo=m::sqrt_interval(a[0],bits);\n'
        '  var hi=m::sqrt_interval(a[1],bits);\n'
        '  retornar [lo[0],hi[1]];\n'
        '}\n'
        'funcao exp(a,bits)  {\n'
        '  var lo=m::exp_interval(a[0],bits);\n'
        '  var hi=m::exp_interval(a[1],bits);\n'
        '  retornar [lo[0],hi[1]];\n'
        '}\n'
        'funcao log(a,bits)  {\n'
        '  var lo=m::log_interval(a[0],bits);\n'
        '  var hi=m::log_interval(a[1],bits);\n'
        '  retornar [lo[0],hi[1]];\n'
        '}\n'
        'funcao midpoint(a)  {\n'
        '  retornar (a[0]+a[1])/2;\n'
        '}\n'
        'funcao encloses(a,x)  {\n'
        '  retornar a[0]<=x&&x<=a[1];\n'
        '}\n'
        'funcao intersect(a,b)  {\n'
        '  retornar box(m::max(a[0],b[0]),m::min(a[1],b[1]));\n'
        '}\n'
    ),
    ('ciencia/engenharia/analise_curto_circuito_simetrico.omega',
        'modulo science_76;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'importar "../../std/math/complex_rational.omega" como c;\n'
        'exportar execute;\n'
        '# Balanced RMS positive-sequence fault calculation; breaker sizing is a model calculation, never a trip action.\n'
        'funcao execute(r)  {\n'
        '  var voltage=u::vector(r["phase_voltage"]);\n'
        '  var source=u::vector(r["source_impedance"]);\n'
        '  var fault=u::vector(r["fault_impedance"]);\n'
        '  se(len(voltage)!=2||len(source)!=2||len(fault)!=2)  {\n'
        '    fail("Complex [real,imag] phase values required");\n'
        '  }\n'
        '  var impedance=c::add(source,fault);\n'
        '  var current=c::div(voltage,impedance);\n'
        '  var magnitude=m::sqrt_interval(c::norm2(current),24);\n'
        '  var out=u::result("balanced-three-phase-positive-sequence-fault",current);\n'
        '  put(out,"current_magnitude",magnitude);\n'
        '  put(out,"negative_sequence",[0,0]);\n'
        '  put(out,"zero_sequence",[0,0]);\n'
        '  se(has(r,"breaker_ratings"))  {\n'
        '    var ratings=u::vector(r["breaker_ratings"]);\n'
        '    var selected=0;\n'
        '    var i=0;\n'
        '    enquanto(i<len(ratings))  {\n'
        '      u::positive(ratings[i]);\n'
        '      se(ratings[i]>=magnitude[1]&&(selected==0||ratings[i]<selected))  {\n'
        '        selected=ratings[i];\n'
        '      }\n'
        '      i=i+1;\n'
        '    }\n'
        '    put(out,"adequate_interrupting_rating",selected);\n'
        '    put(out,"rating_available",selected>0);\n'
        '  }\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/engenharia/atitude_quaternions_espaciais.omega',
        'modulo science_70;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Rational Cayley rotation update preserves unit norm; it approximates, rather than equals, the angular-rate exponential.\n'
        'funcao multiply(a,b)  {\n'
        '  retornar [a[0]*b[0]-a[1]*b[1]-a[2]*b[2]-a[3]*b[3],a[0]*b[1]+a[1]*b[0]+a[2]*b[3]-a[3]*b[2],a[0]*b[2]-a[1]*b[3]+a[2]*b[0]+a[3]*b[1],a[0]*b[3]+a[1]*b[2]-a[2]*b[1]+a[3]*b[0]];\n'
        '}\n'
        'funcao execute(r)  {\n'
        '  var q=u::vector(r["quaternion"]);\n'
        '  var w=u::vector(r["angular_velocity"]);\n'
        '  se(len(q)!=4||len(w)!=3||u::dot(q,q)!=1)  {\n'
        '    fail("Unit rational quaternion and three angular velocities required");\n'
        '  }\n'
        '  var step=u::q(r,"step");\n'
        '  var v=u::scale(w,step/4);\n'
        '  var squared=u::dot(v,v);\n'
        '  var increment=[(1-squared)/(1+squared),2*v[0]/(1+squared),2*v[1]/(1+squared),2*v[2]/(1+squared)];\n'
        '  var next=multiply(increment,q);\n'
        '  se(u::dot(next,next)!=1)  {\n'
        '    fail("Quaternion norm preservation");\n'
        '  }\n'
        '  var out=u::result("Cayley-unit-quaternion-update",next);\n'
        '  put(out,"norm_squared",1);\n'
        '  put(out,"exact_constant_rate_exponential",0);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/engenharia/cinematica_direta_denavit_hartenberg.omega',
        'modulo science_72;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Exact homogeneous DH transforms parameterised by rational half-angle tangents; angles at the tangent pole need another chart.\n'
        'funcao execute(r)  {\n'
        '  var links=u::mat(r["links"]);\n'
        '  se(len(links)>16||len(links[0])!=4)  {\n'
        '    fail("DH rows [tan(theta/2),d,a,tan(alpha/2)]");\n'
        '  }\n'
        '  var transform=u::eye(4);\n'
        '  var trace=[];\n'
        '  var i=0;\n'
        '  enquanto(i<len(links))  {\n'
        '    var t=links[i][0];\n'
        '    var d=links[i][1];\n'
        '    var a=links[i][2];\n'
        '    var v=links[i][3];\n'
        '    var ct=(1-t*t)/(1+t*t);\n'
        '    var st=2*t/(1+t*t);\n'
        '    var ca=(1-v*v)/(1+v*v);\n'
        '    var sa=2*v/(1+v*v);\n'
        '    var h=[[ct,-st*ca,st*sa,a*ct],[st,ct*ca,-ct*sa,a*st],[0,sa,ca,d],[0,0,0,1]];\n'
        '    transform=u::mul(transform,h);\n'
        '    push(trace,transform);\n'
        '    i=i+1;\n'
        '  }\n'
        '  var out=u::result("DH-rational-half-angle-forward-kinematics",transform);\n'
        '  put(out,"trace",trace);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/engenharia/cinematica_inversa_geometrica.omega',
        'modulo science_73;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'importar "../core/intervalos.omega" como iv;\n'
        'exportar execute;\n'
        '# Both planar 2R elbow branches and reachability/singularity checks; arbitrary six-axis IK is explicitly unsupported.\n'
        'funcao execute(r)  {\n'
        '  se(has(r,"robot_model")&&r["robot_model"]!="planar-2R")  {\n'
        '    fail("This geometry solver supports planar-2R, not unspecified six-axis robots");\n'
        '  }\n'
        '  var x=u::q(r,"x");\n'
        '  var y=u::q(r,"y");\n'
        '  var a=u::positive(u::q(r,"length1"));\n'
        '  var b=u::positive(u::q(r,"length2"));\n'
        '  var distance=x*x+y*y;\n'
        '  var out=u::result("planar-2R-geometric-inverse",[]);\n'
        '  se(distance==0)  {\n'
        '    put(out,"singular_continuum",a==b);\n'
        '    se(a!=b)  {\n'
        '      fail("Unreachable folded target");\n'
        '    }\n'
        '    retornar out;\n'
        '  }\n'
        '  var cosine=(distance-a*a-b*b)/(2*a*b);\n'
        '  se(m::abs(cosine)>1)  {\n'
        '    fail("Unreachable planar target");\n'
        '  }\n'
        '  var sine=m::sqrt_interval(1-cosine*cosine,24);\n'
        '  var branches=[];\n'
        '  var sign=-1;\n'
        '  enquanto(sign<=1)  {\n'
        '    var ss=iv::scale(sine,sign);\n'
        '    var k=a+b*cosine;\n'
        '    var c1=iv::scale(iv::add([k*x,k*x],iv::scale(ss,b*y)),1/distance);\n'
        '    var s1=iv::scale(iv::sub([k*y,k*y],iv::scale(ss,b*x)),1/distance);\n'
        '    push(branches,[c1,s1,[cosine,cosine],ss]);\n'
        '    sign=sign+2;\n'
        '  }\n'
        '  put(out,"value",branches);\n'
        '  put(out,"representation","[cos(q1),sin(q1),cos(q2),sin(q2)] enclosures");\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/engenharia/equacao_foguete_tsiolkovsky.omega',
        'modulo science_68;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'importar "../core/intervalos.omega" como iv;\n'
        'exportar execute;\n'
        '# Ideal vacuum rocket equation, interval logarithms and mass-consistent staging; external gravity/drag losses omitted.\n'
        'funcao execute(r)  {\n'
        '  var stages=u::mat(r["stages"]);\n'
        '  se(len(stages)>8||len(stages[0])!=3)  {\n'
        '    fail("Stages [initial_mass,final_mass,exhaust_velocity], up to eight");\n'
        '  }\n'
        '  var total=[0,0];\n'
        '  var values=[];\n'
        '  var i=0;\n'
        '  enquanto(i<len(stages))  {\n'
        '    var a=stages[i];\n'
        '    u::positive(a[0]);\n'
        '    u::positive(a[1]);\n'
        '    u::positive(a[2]);\n'
        '    se(a[0]<=a[1]||(i>0&&a[0]>stages[i-1][1]))  {\n'
        '      fail("Invalid burn mass or staging creates mass");\n'
        '    }\n'
        '    var logarithm=m::log_interval(a[0]/a[1],24);\n'
        '    var dv=iv::scale(logarithm,a[2]);\n'
        '    total=iv::add(total,dv);\n'
        '    push(values,dv);\n'
        '    i=i+1;\n'
        '  }\n'
        '  var out=u::result("ideal-multistage-Tsiolkovsky",total);\n'
        '  put(out,"stage_delta_v",values);\n'
        '  put(out,"gravity_drag_losses_included",0);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/engenharia/escoamento_tubulacoes_darcy_weisbach.omega',
        'modulo science_79;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'importar "../core/intervalos.omega" como iv;\n'
        'exportar execute;\n'
        '# Laminar exact friction or enclosed Colebrook root; empirical transitional regime is explicitly rejected.\n'
        'funcao colebrook(y,rough,diameter,re)  {\n'
        '  var arg=rough/(3.7*diameter)+2.51*y/re;\n'
        '  var ln=m::log_interval(arg,32);\n'
        '  var ten=m::log_interval(10,32);\n'
        '  var ratio=iv::div(ln,ten);\n'
        '  retornar [y+2*ratio[0],y+2*ratio[1]];\n'
        '}\n'
        'funcao execute(r)  {\n'
        '  var rho=u::positive(u::q(r,"density"));\n'
        '  var v=m::abs(u::q(r,"velocity"));\n'
        '  var d=u::positive(u::q(r,"diameter"));\n'
        '  var length=u::positive(u::q(r,"length"));\n'
        '  var viscosity=u::positive(u::q(r,"dynamic_viscosity"));\n'
        '  var rough=u::nonnegative(u::num(r,"roughness",0));\n'
        '  se(rough>d/10)  {\n'
        '    fail("Colebrook roughness domain");\n'
        '  }\n'
        '  var re=rho*v*d/viscosity;\n'
        '  var friction=[0,0];\n'
        '  var regime="zero-flow";\n'
        '  se(re>0)  {\n'
        '    se(re<=2300)  {\n'
        '      regime="laminar";\n'
        '      friction=[64/re,64/re];\n'
        '    }\n'
        '    senao  {\n'
        '      se(re<4000||re>100000000)  {\n'
        '        fail("Transition flow or Reynolds outside model domain");\n'
        '      }\n'
        '      regime="turbulent-Colebrook";\n'
        '      var lo=1;\n'
        '      var hi=32;\n'
        '      var first=colebrook(lo,rough,d,re);\n'
        '      var last=colebrook(hi,rough,d,re);\n'
        '      se(first[1]>=0||last[0]<=0)  {\n'
        '        fail("Uncertified Colebrook bracket");\n'
        '      }\n'
        '      var i=0;\n'
        '      enquanto(i<48)  {\n'
        '        var mid=(lo+hi)/2;\n'
        '        var f=colebrook(mid,rough,d,re);\n'
        '        se(f[1]<0)  {\n'
        '          lo=mid;\n'
        '        }\n'
        '        senao  {\n'
        '          se(f[0]>0)  {\n'
        '            hi=mid;\n'
        '          }\n'
        '          senao  {\n'
        '            var radius=m::max(m::abs(f[0]),m::abs(f[1]));\n'
        '            lo=m::max(lo,mid-radius);\n'
        '            hi=m::min(hi,mid+radius);\n'
        '            parar;\n'
        '          }\n'
        '        }\n'
        '        i=i+1;\n'
        '      }\n'
        '      friction=[1/(hi*hi),1/(lo*lo)];\n'
        '    }\n'
        '  }\n'
        '  var out=u::result("Darcy-Weisbach-pressure-loss",iv::scale(friction,length*rho*v*v/(2*d)));\n'
        '  put(out,"friction_factor",friction);\n'
        '  put(out,"Reynolds",re);\n'
        '  put(out,"regime",regime);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/engenharia/estabilidade_transiente_geradores.omega',
        'modulo science_77;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Single-machine swing model with interval force and energy accounting; no unproved global transient-stability claim.\n'
        'funcao energy(delta,omega,inertia,mechanical,maximum)  {\n'
        '  var cosine=m::cos_interval(delta,24);\n'
        '  var kinetic=inertia*omega*omega/2-mechanical*delta;\n'
        '  retornar [kinetic-maximum*cosine[1],kinetic-maximum*cosine[0]];\n'
        '}\n'
        'funcao execute(r)  {\n'
        '  var delta=u::q(r,"angle");\n'
        '  var omega=u::q(r,"speed_deviation");\n'
        '  var inertia=u::positive(u::q(r,"inertia"));\n'
        '  var damping=u::nonnegative(u::q(r,"damping"));\n'
        '  var pm=u::q(r,"mechanical_power");\n'
        '  var maximum=u::positive(u::q(r,"maximum_electrical_power"));\n'
        '  var step=u::positive(u::q(r,"step"));\n'
        '  var sine=m::sin_interval(delta,24);\n'
        '  var acceleration=[(pm-maximum*sine[1]-damping*omega)/inertia,(pm-maximum*sine[0]-damping*omega)/inertia];\n'
        '  var next=[delta+step*omega,omega+step*(acceleration[0]+acceleration[1])/2];\n'
        '  var before=energy(delta,omega,inertia,pm,maximum);\n'
        '  var after=energy(next[0],next[1],inertia,pm,maximum);\n'
        '  var out=u::result("single-machine-infinite-bus-swing-step",next);\n'
        '  put(out,"acceleration_interval",acceleration);\n'
        '  put(out,"continuous_energy_derivative",-damping*omega*omega);\n'
        '  put(out,"discrete_energy_change",[after[0]-before[1],after[1]-before[0]]);\n'
        '  put(out,"global_stability_proved",0);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/engenharia/filtro_kalman_racional_discreto.omega',
        'modulo science_71;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Rational Joseph update; positive-definite priors/measurement noise and positive semidefinite process noise are checked.\n'
        'funcao plus(a,b)  {\n'
        '  se(len(a)!=len(b)||len(a[0])!=len(b[0]))  {\n'
        '    fail("Covariance shape");\n'
        '  }\n'
        '  var out=[];\n'
        '  var i=0;\n'
        '  enquanto(i<len(a))  {\n'
        '    push(out,u::add(a[i],b[i]));\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar out;\n'
        '}\n'
        'funcao positive_definite(a)  {\n'
        '  var n=len(a);\n'
        '  se(n!=len(a[0]))  {\n'
        '    fail("Square covariance required");\n'
        '  }\n'
        '  var i=0;\n'
        '  enquanto(i<n)  {\n'
        '    var j=0;\n'
        '    enquanto(j<n)  {\n'
        '      se(a[i][j]!=a[j][i])  {\n'
        '        fail("Symmetric covariance required");\n'
        '      }\n'
        '      j=j+1;\n'
        '    }\n'
        '    var leading=[];\n'
        '    j=0;\n'
        '    enquanto(j<=i)  {\n'
        '      push(leading,slice(a[j],0,i+1));\n'
        '      j=j+1;\n'
        '    }\n'
        '    se(u::determinant(leading)<=0)  {\n'
        '      fail("Strict positive definiteness certificate failed");\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar 1;\n'
        '}\n'
        'funcao positive_semidefinite(a) {\n'
        '  var n=len(a);\n'
        '  var i=0;\n'
        '  enquanto(i<n) {\n'
        '    var j=0;\n'
        '    enquanto(j<n) {\n'
        '      se(a[i][j]!=a[j][i]) { fail("Symmetric process covariance required"); }\n'
        '      j=j+1;\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  var mask=1;\n'
        '  enquanto(mask<u::power(2,n)) {\n'
        '    var selected=[];\n'
        '    i=0;\n'
        '    enquanto(i<n) {\n'
        '      se(qfloor(mask/u::power(2,i))%2==1) { push(selected,i); }\n'
        '      i=i+1;\n'
        '    }\n'
        '    var principal=[];\n'
        '    i=0;\n'
        '    enquanto(i<len(selected)) {\n'
        '      var row=[];\n'
        '      var j=0;\n'
        '      enquanto(j<len(selected)) {\n'
        '        push(row,a[selected[i]][selected[j]]);\n'
        '        j=j+1;\n'
        '      }\n'
        '      push(principal,row);\n'
        '      i=i+1;\n'
        '    }\n'
        '    se(u::determinant(principal)<0) { fail("Process covariance is not positive semidefinite"); }\n'
        '    mask=mask+1;\n'
        '  }\n'
        '  retornar 1;\n'
        '}\n'
        'funcao inverse(a)  {\n'
        '  var n=len(a);\n'
        '  var columns=[];\n'
        '  var j=0;\n'
        '  enquanto(j<n)  {\n'
        '    var b=u::zeros(n);\n'
        '    put(b,j,1);\n'
        '    push(columns,u::solve(a,b));\n'
        '    j=j+1;\n'
        '  }\n'
        '  retornar u::transpose(columns);\n'
        '}\n'
        'funcao apply(a,x)  {\n'
        '  var out=[];\n'
        '  var i=0;\n'
        '  enquanto(i<len(a))  {\n'
        '    push(out,u::dot(a[i],x));\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar out;\n'
        '}\n'
        'funcao execute(r)  {\n'
        '  var f=u::mat(r["transition"]);\n'
        '  var h=u::mat(r["observation"]);\n'
        '  var p=u::mat(r["covariance"]);\n'
        '  var q=u::mat(r["process_noise"]);\n'
        '  var rr=u::mat(r["measurement_noise"]);\n'
        '  var x=u::vector(r["state"]);\n'
        '  var z=u::vector(r["measurement"]);\n'
        '  var n=len(x);\n'
        '  se(n<1||n>6||len(f)!=n||len(f[0])!=n||len(h[0])!=n||len(h)!=len(z)||len(z)>4||len(p)!=n||len(p[0])!=n||len(q)!=n||len(q[0])!=n||len(rr)!=len(z)||len(rr[0])!=len(z))  {\n'
        '    fail("Kalman shapes/budget");\n'
        '  }\n'
        '  positive_definite(p);\n'
        '  positive_definite(rr);\n'
        '  positive_semidefinite(q);\n'
        '  var i=0;\n'
        '  var predicted=apply(f,x);\n'
        '  var prior=plus(u::mul(u::mul(f,p),u::transpose(f)),q);\n'
        '  positive_definite(prior);\n'
        '  var ht=u::transpose(h);\n'
        '  var innovation=plus(u::mul(u::mul(h,prior),ht),rr);\n'
        '  positive_definite(innovation);\n'
        '  var gain=u::mul(u::mul(prior,ht),inverse(innovation));\n'
        '  var residual=u::add(z,u::scale(apply(h,predicted),-1));\n'
        '  var state=u::add(predicted,apply(gain,residual));\n'
        '  var kh=u::mul(gain,h);\n'
        '  var identity=u::eye(n);\n'
        '  var subtract=[];\n'
        '  i=0;\n'
        '  enquanto(i<n)  {\n'
        '    push(subtract,u::add(identity[i],u::scale(kh[i],-1)));\n'
        '    i=i+1;\n'
        '  }\n'
        '  var covariance=plus(u::mul(u::mul(subtract,prior),u::transpose(subtract)),u::mul(u::mul(gain,rr),u::transpose(gain)));\n'
        '  positive_definite(covariance);\n'
        '  var out=u::result("exact-Joseph-form-Kalman-update",state);\n'
        '  put(out,"covariance",covariance);\n'
        '  put(out,"gain",gain);\n'
        '  put(out,"innovation",residual);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/engenharia/fluxo_potencia_newton_raphson.omega',
        'modulo science_75;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Damped Newton for quadratic resistive DC power flow; checks local contraction inequalities, not generic AC convergence.\n'
        'funcao residual(g,p,v,slack)  {\n'
        '  var result=[];\n'
        '  var i=0;\n'
        '  enquanto(i<len(v))  {\n'
        '    var sum=g[i+1][0]*slack;\n'
        '    var j=0;\n'
        '    enquanto(j<len(v))  {\n'
        '      sum=sum+g[i+1][j+1]*v[j];\n'
        '      j=j+1;\n'
        '    }\n'
        '    push(result,v[i]*sum-p[i]);\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar result;\n'
        '}\n'
        'funcao jacobian(g,v,slack)  {\n'
        '  var out=[];\n'
        '  var i=0;\n'
        '  enquanto(i<len(v))  {\n'
        '    var sum=g[i+1][0]*slack;\n'
        '    var j=0;\n'
        '    enquanto(j<len(v))  {\n'
        '      sum=sum+g[i+1][j+1]*v[j];\n'
        '      j=j+1;\n'
        '    }\n'
        '    var row=[];\n'
        '    j=0;\n'
        '    enquanto(j<len(v))  {\n'
        '      var a=v[i]*g[i+1][j+1];\n'
        '      se(i==j)  {\n'
        '        a=a+sum;\n'
        '      }\n'
        '      push(row,a);\n'
        '      j=j+1;\n'
        '    }\n'
        '    push(out,row);\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar out;\n'
        '}\n'
        'funcao norm(v)  {\n'
        '  var x=0;\n'
        '  var i=0;\n'
        '  enquanto(i<len(v))  {\n'
        '    x=m::max(x,m::abs(v[i]));\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar x;\n'
        '}\n'
        'funcao execute(r)  {\n'
        '  var g=u::mat(r["conductance"]);\n'
        '  var v=u::vector(r["initial_voltages"]);\n'
        '  var p=u::vector(r["power_injections"]);\n'
        '  var n=len(v);\n'
        '  se(n<1||n>8||len(p)!=n||len(g)!=n+1||len(g[0])!=n+1)  {\n'
        '    fail("Resistive DC power-flow shape");\n'
        '  }\n'
        '  var slack=u::positive(u::q(r,"slack_voltage"));\n'
        '  var steps=u::integer(u::num(r,"steps",8),1,16);\n'
        '  var grid=u::power(2,32);\n'
        '  var i=0;\n'
        '  enquanto(i<n)  {\n'
        '    u::positive(v[i]);\n'
        '    i=i+1;\n'
        '  }\n'
        '  i=0;\n'
        '  enquanto(i<steps)  {\n'
        '    var f=residual(g,p,v,slack);\n'
        '    se(norm(f)==0)  {\n'
        '      parar;\n'
        '    }\n'
        '    var j=jacobian(g,v,slack);\n'
        '    var delta=u::solve(j,u::scale(f,-1));\n'
        '    var factor=1;\n'
        '    var accepted=0;\n'
        '    var trial=[];\n'
        '    var line=0;\n'
        '    enquanto(line<16)  {\n'
        '      trial=[];\n'
        '      var good=1;\n'
        '      var k=0;\n'
        '      enquanto(k<n)  {\n'
        '        var x=qfloor((v[k]+factor*delta[k])*grid)/grid;\n'
        '        se(x<=0)  {\n'
        '          good=0;\n'
        '        }\n'
        '        push(trial,x);\n'
        '        k=k+1;\n'
        '      }\n'
        '      se(good&&norm(residual(g,p,trial,slack))<norm(f))  {\n'
        '        accepted=1;\n'
        '        parar;\n'
        '      }\n'
        '      factor=factor/2;\n'
        '      line=line+1;\n'
        '    }\n'
        '    se(!accepted)  {\n'
        '      parar;\n'
        '    }\n'
        '    v=trial;\n'
        '    i=i+1;\n'
        '  }\n'
        '  var f=residual(g,p,v,slack);\n'
        '  var j=jacobian(g,v,slack);\n'
        '  var inv=[];\n'
        '  i=0;\n'
        '  enquanto(i<n)  {\n'
        '    var e=u::zeros(n);\n'
        '    put(e,i,1);\n'
        '    push(inv,u::solve(j,e));\n'
        '    i=i+1;\n'
        '  }\n'
        '  inv=u::transpose(inv);\n'
        '  var correction=[];\n'
        '  i=0;\n'
        '  enquanto(i<n)  {\n'
        '    push(correction,u::dot(inv[i],f));\n'
        '    i=i+1;\n'
        '  }\n'
        '  var hessian=0;\n'
        '  i=0;\n'
        '  enquanto(i<n)  {\n'
        '    var sum=0;\n'
        '    var k=0;\n'
        '    enquanto(k<n)  {\n'
        '      sum=sum+2*m::abs(g[i+1][k+1]);\n'
        '      k=k+1;\n'
        '    }\n'
        '    hessian=m::max(hessian,sum);\n'
        '    i=i+1;\n'
        '  }\n'
        '  var inverse_norm=0;\n'
        '  i=0;\n'
        '  enquanto(i<n)  {\n'
        '    var sum=0;\n'
        '    var k=0;\n'
        '    enquanto(k<n)  {\n'
        '      sum=sum+m::abs(inv[i][k]);\n'
        '      k=k+1;\n'
        '    }\n'
        '    inverse_norm=m::max(inverse_norm,sum);\n'
        '    i=i+1;\n'
        '  }\n'
        '  var bound=inverse_norm*hessian;\n'
        '  var radius=u::positive(u::num(r,"certificate_radius",1/100));\n'
        '  var eta=norm(correction);\n'
        '  var safe=bound*radius<1&&eta+bound*radius*radius/2<=radius;\n'
        '  i=0;\n'
        '  enquanto(i<n)  {\n'
        '    se(v[i]<=radius)  {\n'
        '      safe=0;\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  var out=u::result("resistive-DC-damped-Newton-with-local-certificate-conditions",v);\n'
        '  put(out,"residual",f);\n'
        '  put(out,"newton_correction_bound",eta);\n'
        '  put(out,"jacobian_lipschitz_bound",bound);\n'
        '  put(out,"radius",radius);\n'
        '  put(out,"local_contraction_conditions",safe);\n'
        '  put(out,"AC_network_supported",0);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/engenharia/planejamento_trajetoria_quintica.omega',
        'modulo science_74;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Exact six-boundary-condition quintic polynomial and position/velocity/acceleration samples.\n'
        'funcao derivative(c)  {\n'
        '  var out=[];\n'
        '  var i=1;\n'
        '  enquanto(i<len(c))  {\n'
        '    push(out,i*c[i]);\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar out;\n'
        '}\n'
        'funcao execute(r)  {\n'
        '  var p0=u::q(r,"position0");\n'
        '  var v0=u::q(r,"velocity0");\n'
        '  var a0=u::q(r,"acceleration0");\n'
        '  var p1=u::q(r,"position1");\n'
        '  var v1=u::q(r,"velocity1");\n'
        '  var a1=u::q(r,"acceleration1");\n'
        '  var t=u::positive(u::q(r,"duration"));\n'
        '  var sample=u::q(r,"time");\n'
        '  se(sample<0||sample>t)  {\n'
        '    fail("Trajectory sample outside [0,T]");\n'
        '  }\n'
        '  var d=p1-p0-v0*t-a0*t*t/2;\n'
        '  var v=v1-v0-a0*t;\n'
        '  var a=a1-a0;\n'
        '  var c=[p0,v0,a0/2,(10*d-4*v*t+a*t*t/2)/u::power(t,3),(-15*d+7*v*t-a*t*t)/u::power(t,4),(6*d-3*v*t+a*t*t/2)/u::power(t,5)];\n'
        '  var dc=derivative(c);\n'
        '  var ddc=derivative(dc);\n'
        '  se(u::polynomial(c,t)!=p1||u::polynomial(dc,t)!=v1||u::polynomial(ddc,t)!=a1)  {\n'
        '    fail("Quintic endpoint contract failed");\n'
        '  }\n'
        '  var out=u::result("quintic-boundary-value-trajectory",[u::polynomial(c,sample),u::polynomial(dc,sample),u::polynomial(ddc,sample)]);\n'
        '  put(out,"coefficients",c);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/engenharia/pressao_hidrostatica_barragens.omega',
        'modulo science_80;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Static vertical-wall hydrostatic load only; seepage, foundation, earthquakes and structural safety are separate models.\n'
        'funcao execute(r)  {\n'
        '  var rho=u::positive(u::q(r,"density"));\n'
        '  var gravity=u::positive(u::q(r,"gravity"));\n'
        '  var height=u::positive(u::q(r,"water_height"));\n'
        '  var width=u::positive(u::q(r,"width"));\n'
        '  var force=rho*gravity*width*height*height/2;\n'
        '  var moment=rho*gravity*width*u::power(height,3)/6;\n'
        '  var out=u::result("vertical-wall-hydrostatic-triangular-load",force);\n'
        '  put(out,"base_overturning_moment",moment);\n'
        '  put(out,"centre_above_base",height/3);\n'
        '  put(out,"maximum_pressure",rho*gravity*height);\n'
        '  se(has(r,"resisting_moment"))  {\n'
        '    var resisting=u::nonnegative(u::q(r,"resisting_moment"));\n'
        '    put(out,"moment_safety_ratio",resisting/moment);\n'
        '    put(out,"resisting_exceeds_water_moment",resisting>=moment);\n'
        '  }\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/engenharia/reentrada_atmosferica_perfil.omega',
        'modulo science_69;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Lumped one-step frozen-density reentry and Sutton-Graves-type heating enclosure; no flight safety certification.\n'
        'funcao execute(r)  {\n'
        '  var height=u::nonnegative(u::q(r,"height"));\n'
        '  var speed=u::nonnegative(u::q(r,"speed"));\n'
        '  var mass=u::positive(u::q(r,"mass"));\n'
        '  var density=u::nonnegative(u::q(r,"density"));\n'
        '  var cd=u::nonnegative(u::q(r,"drag_coefficient"));\n'
        '  var area=u::positive(u::q(r,"area"));\n'
        '  var g=u::positive(u::q(r,"gravity"));\n'
        '  var sine=u::q(r,"flight_path_sine");\n'
        '  se(m::abs(sine)>1)  {\n'
        '    fail("Flight-path sine domain");\n'
        '  }\n'
        '  var step=u::positive(u::q(r,"step"));\n'
        '  var drag=density*cd*area*speed*speed/2;\n'
        '  var acceleration=-drag/mass-g*sine;\n'
        '  var next=[height+step*speed*sine,speed+step*acceleration];\n'
        '  se(next[0]<0||next[1]<0)  {\n'
        '    fail("Reentry step leaves nonnegative height/speed domain");\n'
        '  }\n'
        '  var nose=u::positive(u::q(r,"nose_radius"));\n'
        '  var heat=u::positive(u::q(r,"heating_coefficient"));\n'
        '  var root=m::sqrt_interval(density/nose,24);\n'
        '  var out=u::result("frozen-density-point-mass-reentry-step",next);\n'
        '  put(out,"drag",drag);\n'
        '  put(out,"heating_rate_interval",[heat*root[0]*u::power(speed,3),heat*root[1]*u::power(speed,3)]);\n'
        '  put(out,"acceleration",acceleration);\n'
        '  put(out,"continuous_trajectory_certified",0);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/engenharia/trelica_metodo_dos_nos.omega',
        'modulo science_78;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'importar "../core/intervalos.omega" como iv;\n'
        'exportar execute;\n'
        '# Exact force-density nodal solve; irrational member lengths produce axial-force enclosures, singular mechanisms fail.\n'
        'funcao execute(r)  {\n'
        '  var points=u::mat(r["nodes"]);\n'
        '  var members=u::mat(r["members"]);\n'
        '  var loads=u::mat(r["loads"]);\n'
        '  var supports=u::mat(r["supports"]);\n'
        '  var n=len(points);\n'
        '  var columns=len(members)+len(supports);\n'
        '  se(n>8||len(points[0])!=2||len(loads)!=n||len(loads[0])!=2||len(members[0])!=2||len(supports[0])!=2||columns!=2*n)  {\n'
        '    fail("Statically determinate 2D truss shapes required");\n'
        '  }\n'
        '  var a=[];\n'
        '  var b=[];\n'
        '  var i=0;\n'
        '  enquanto(i<2*n)  {\n'
        '    push(a,u::zeros(columns));\n'
        '    push(b,-loads[qfloor(i/2)][i%2]);\n'
        '    i=i+1;\n'
        '  }\n'
        '  i=0;\n'
        '  enquanto(i<len(members))  {\n'
        '    var left=u::integer(members[i][0],0,n-1);\n'
        '    var right=u::integer(members[i][1],0,n-1);\n'
        '    se(left==right)  {\n'
        '      fail("Zero truss member");\n'
        '    }\n'
        '    var delta=u::add(points[right],u::scale(points[left],-1));\n'
        '    u::positive(u::dot(delta,delta));\n'
        '    var axis=0;\n'
        '    enquanto(axis<2)  {\n'
        '      put(a[2*left+axis],i,delta[axis]);\n'
        '      put(a[2*right+axis],i,-delta[axis]);\n'
        '      axis=axis+1;\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  i=0;\n'
        '  enquanto(i<len(supports))  {\n'
        '    var node=u::integer(supports[i][0],0,n-1);\n'
        '    var axis=u::integer(supports[i][1],0,1);\n'
        '    put(a[2*node+axis],len(members)+i,1);\n'
        '    i=i+1;\n'
        '  }\n'
        '  var solution=u::solve(a,b);\n'
        '  var forces=[];\n'
        '  i=0;\n'
        '  enquanto(i<len(members))  {\n'
        '    var left=members[i][0];\n'
        '    var right=members[i][1];\n'
        '    var delta=u::add(points[right],u::scale(points[left],-1));\n'
        '    var length=m::sqrt_interval(u::dot(delta,delta),24);\n'
        '    push(forces,iv::scale(length,solution[i]));\n'
        '    i=i+1;\n'
        '  }\n'
        '  i=0;\n'
        '  enquanto(i<len(a))  {\n'
        '    se(u::dot(a[i],solution)!=b[i])  {\n'
        '      fail("Nodal equilibrium certificate");\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  var out=u::result("truss-force-density-equilibrium",solution);\n'
        '  put(out,"member_axial_force_enclosures",forces);\n'
        '  retornar out;\n'
        '}\n'
    ),
