    ('ciencia/fisica/ciclo_carnot_reversivel.omega',
        'modulo science_9;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Two equilibrium reservoirs, cyclic working fluid, positive absolute temperatures; no universal physical axiom is inferred.\n'
        'funcao execute(r)  {\n'
        '  var hot=u::positive(u::q(r,"hot_temperature"));\n'
        '  var cold=u::positive(u::q(r,"cold_temperature"));\n'
        '  se(cold>=hot)  {\n'
        '    fail("Hot reservoir must be hotter");\n'
        '  }\n'
        '  var heat=u::positive(u::q(r,"heat_in"));\n'
        '  var limit=1-cold/hot;\n'
        '  var work=u::num(r,"work",heat*limit);\n'
        '  se(work<0||work>heat*limit)  {\n'
        '    fail("Proposed engine exceeds Carnot bound");\n'
        '  }\n'
        '  var rejected=heat-work;\n'
        '  var entropy=rejected/cold-heat/hot;\n'
        '  se(entropy<0)  {\n'
        '    fail("Reservoir entropy decreased");\n'
        '  }\n'
        '  var out=u::result("two-reservoir-Carnot-bound",work/heat);\n'
        '  put(out,"maximum_efficiency",limit);\n'
        '  put(out,"heat_out",rejected);\n'
        '  put(out,"entropy_production",entropy);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/fisica/colisoes_rigidas_conservativas.omega',
        'modulo science_6;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Momentum is exact; kinetic energy is conserved only for elastic collisions, otherwise heat accounts for loss.\n'
        'funcao execute(r)  {\n'
        '  var m1=u::positive(u::q(r,"mass1"));\n'
        '  var m2=u::positive(u::q(r,"mass2"));\n'
        '  var v1=u::q(r,"velocity1");\n'
        '  var v2=u::q(r,"velocity2");\n'
        '  var e=u::q(r,"restitution");\n'
        '  se(e<0||e>1)  {\n'
        '    fail("Restitution in [0,1]");\n'
        '  }\n'
        '  var center=(m1*v1+m2*v2)/(m1+m2);\n'
        '  var relative=-e*(v1-v2);\n'
        '  var w1=center+m2*relative/(m1+m2);\n'
        '  var w2=center-m1*relative/(m1+m2);\n'
        '  var loss=(1-e*e)*m1*m2*(v1-v2)*(v1-v2)/(2*(m1+m2));\n'
        '  se(m1*w1+m2*w2!=m1*v1+m2*v2||m1*w1*w1/2+m2*w2*w2/2+loss!=m1*v1*v1/2+m2*v2*v2/2)  {\n'
        '    fail("Collision conservation");\n'
        '  }\n'
        '  var out=u::result("one-dimensional-restitution-collision",[w1,w2]);\n'
        '  put(out,"heat_generated",loss);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/fisica/desvio_luz_gravitacional.omega',
        'modulo science_21;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Leading weak-field deflection plus a strong-field turning-point bracket; full strong-field bending is not claimed.\n'
        'funcao execute(r)  {\n'
        '  var mass=u::positive(u::q(r,"mass"));\n'
        '  var impact=u::positive(u::q(r,"impact_parameter"));\n'
        '  var out=u::result("Schwarzschild-light-leading-deflection",4*mass/impact);\n'
        '  put(out,"weak_field_parameter",mass/impact);\n'
        '  put(out,"strong_field_angle_computed",0);\n'
        '  se(impact*impact<=27*mass*mass)  {\n'
        '    put(out,"critical_or_capture",1);\n'
        '  }\n'
        '  senao  {\n'
        '    put(out,"critical_or_capture",0);\n'
        '    var lo=3*mass;\n'
        '    var hi=impact;\n'
        '    var i=0;\n'
        '    enquanto(i<48)  {\n'
        '      var mid=(lo+hi)/2;\n'
        '      var value=mid*mid*mid-impact*impact*mid+2*mass*impact*impact;\n'
        '      se(value>0)  {\n'
        '        hi=mid;\n'
        '      }\n'
        '      senao  {\n'
        '        lo=mid;\n'
        '      }\n'
        '      i=i+1;\n'
        '    }\n'
        '    put(out,"outer_turning_radius",[lo,hi]);\n'
        '  }\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/fisica/distribuicao_maxwell_boltzmann.omega',
        'modulo science_10;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'importar "../core/intervalos.omega" como iv;\n'
        'exportar execute;\n'
        '# Normalised discrete speed-grid approximation; continuous Maxwell density is not claimed rational/exact.\n'
        'funcao execute(r)  {\n'
        '  var speeds=u::vector(r["speeds"]);\n'
        '  se(len(speeds)<1||len(speeds)>32)  {\n'
        '    fail("Velocity grid budget");\n'
        '  }\n'
        '  var mass=u::positive(u::q(r,"mass"));\n'
        '  var kt=u::positive(u::q(r,"thermal_energy"));\n'
        '  var weights=[];\n'
        '  var total=[0,0];\n'
        '  var chosen=[];\n'
        '  var sum=0;\n'
        '  var i=0;\n'
        '  enquanto(i<len(speeds))  {\n'
        '    u::nonnegative(speeds[i]);\n'
        '    var w=iv::scale(m::exp_interval(-mass*speeds[i]*speeds[i]/(2*kt),16),speeds[i]*speeds[i]);\n'
        '    push(weights,w);\n'
        '    total=iv::add(total,w);\n'
        '    push(chosen,iv::midpoint(w));\n'
        '    sum=sum+iv::midpoint(w);\n'
        '    i=i+1;\n'
        '  }\n'
        '  u::positive(total[0]);\n'
        '  var probabilities=[];\n'
        '  var enclosures=[];\n'
        '  i=0;\n'
        '  enquanto(i<len(weights))  {\n'
        '    push(probabilities,chosen[i]/sum);\n'
        '    push(enclosures,iv::div(weights[i],total));\n'
        '    i=i+1;\n'
        '  }\n'
        '  var out=u::result("finite-speed-grid-Maxwell-weights",probabilities);\n'
        '  put(out,"probability_enclosures",enclosures);\n'
        '  put(out,"continuous_distribution",0);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/fisica/equacao_friedmann.omega',
        'modulo science_22;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Flat homogeneous Friedmann model with explicit kappa (8*pi*G/3), matter/radiation scaling and root bounds.\n'
        'funcao execute(r)  {\n'
        '  var a=u::positive(u::q(r,"scale_factor"));\n'
        '  var matter=u::nonnegative(u::q(r,"matter_density_at_one"));\n'
        '  var radiation=u::nonnegative(u::q(r,"radiation_density_at_one"));\n'
        '  var kappa=u::positive(u::q(r,"kappa"));\n'
        '  var lambda=u::q(r,"cosmological_constant");\n'
        '  var h2=kappa*(matter/u::power(a,3)+radiation/u::power(a,4))+lambda/3;\n'
        '  u::nonnegative(h2);\n'
        '  var h=m::sqrt_interval(h2,24);\n'
        '  var out=u::result("flat-Friedmann-constitutive-field",h);\n'
        '  put(out,"H_squared",h2);\n'
        '  put(out,"scale_factor_derivative",[a*h[0],a*h[1]]);\n'
        '  put(out,"matter_density",matter/u::power(a,3));\n'
        '  put(out,"radiation_density",radiation/u::power(a,4));\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/fisica/gas_van_der_waals.omega',
        'modulo science_8;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Exact van der Waals isotherm and analytic critical parameters; phase coexistence needs an additional construction.\n'
        'funcao execute(r)  {\n'
        '  var n=u::positive(u::q(r,"moles"));\n'
        '  var a=u::positive(u::q(r,"attraction"));\n'
        '  var b=u::positive(u::q(r,"excluded_volume"));\n'
        '  var gas=u::positive(u::q(r,"gas_constant"));\n'
        '  var t=u::positive(u::q(r,"temperature"));\n'
        '  var v=u::q(r,"volume");\n'
        '  se(v<=n*b)  {\n'
        '    fail("Volume must exceed excluded volume");\n'
        '  }\n'
        '  var pressure=n*gas*t/(v-n*b)-a*n*n/(v*v);\n'
        '  var out=u::result("van-der-Waals-isotherm",pressure);\n'
        '  put(out,"critical_pressure",a/(27*b*b));\n'
        '  put(out,"critical_volume",3*n*b);\n'
        '  put(out,"critical_temperature",8*a/(27*gas*b));\n'
        '  put(out,"dP_dV",-n*gas*t/((v-n*b)*(v-n*b))+2*a*n*n/(v*v*v));\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/fisica/geodesicas_schwarzschild.omega',
        'modulo science_20;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Exterior equatorial timelike geodesic field in G=c=1 units; mass-shell inconsistency is reported, not hidden.\n'
        'funcao execute(r)  {\n'
        '  var mass=u::positive(u::q(r,"central_mass"));\n'
        '  var radius=u::q(r,"radius");\n'
        '  se(radius<=2*mass)  {\n'
        '    fail("Exterior Schwarzschild coordinates require r > 2M");\n'
        '  }\n'
        '  var velocity=u::q(r,"radial_velocity");\n'
        '  var angular=u::q(r,"angular_momentum");\n'
        '  var energy=u::positive(u::q(r,"energy"));\n'
        '  var f=1-2*mass/radius;\n'
        '  var constraint=velocity*velocity+f*(1+angular*angular/(radius*radius))-energy*energy;\n'
        '  var acceleration=-mass/(radius*radius)+angular*angular/u::power(radius,3)-3*mass*angular*angular/u::power(radius,4);\n'
        '  var out=u::result("equatorial-timelike-Schwarzschild-proper-time-field",[velocity,acceleration,angular/(radius*radius),energy/f]);\n'
        '  put(out,"mass_shell_residual",constraint);\n'
        '  put(out,"on_mass_shell",constraint==0);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/fisica/integrador_simplico_verlet.omega',
        'modulo science_2;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Symplectic Verlet preserves a modified quadratic energy; physical-energy drift is reported, not set to zero.\n'
        'funcao execute(r)  {\n'
        '  var q=u::q(r,"position");\n'
        '  var p=u::q(r,"momentum");\n'
        '  var mass=u::positive(u::q(r,"mass"));\n'
        '  var k=u::positive(u::q(r,"spring"));\n'
        '  var h=u::q(r,"step");\n'
        '  var a=h*h*k/(4*mass);\n'
        '  se(a>=1)  {\n'
        '    fail("Oscillator Verlet stability domain h^2*k/m < 4");\n'
        '  }\n'
        '  var half=p-h*k*q/2;\n'
        '  var qn=q+h*half/mass;\n'
        '  var pn=half-h*k*qn/2;\n'
        '  var modified=p*p/(2*mass)+k*(1-a)*q*q/2;\n'
        '  var after=pn*pn/(2*mass)+k*(1-a)*qn*qn/2;\n'
        '  se(modified!=after)  {\n'
        '    fail("Verlet modified invariant");\n'
        '  }\n'
        '  var out=u::result("velocity-Verlet-quadratic-oscillator",[qn,pn]);\n'
        '  put(out,"modified_energy",modified);\n'
        '  put(out,"physical_energy_change",pn*pn/(2*mass)+k*qn*qn/2-p*p/(2*mass)-k*q*q/2);\n'
        '  put(out,"jacobian_determinant",1);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/fisica/lei_snell_refracao_exata.omega',
        'modulo science_14;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Exact Snell sine relation and cosine enclosure; arbitrary angles are not rational numbers.\n'
        'funcao execute(r)  {\n'
        '  var n1=u::positive(u::q(r,"index1"));\n'
        '  var n2=u::positive(u::q(r,"index2"));\n'
        '  var sine=u::q(r,"incident_sine");\n'
        '  se(m::abs(sine)>1)  {\n'
        '    fail("Incident sine domain");\n'
        '  }\n'
        '  var transmitted=n1*sine/n2;\n'
        '  var out=u::result("Snell-sine-constraint",transmitted);\n'
        '  put(out,"total_internal_reflection",m::abs(transmitted)>1);\n'
        '  se(m::abs(transmitted)<=1)  {\n'
        '    put(out,"transmitted_cosine",m::sqrt_interval(1-transmitted*transmitted,24));\n'
        '  }\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/fisica/maxwell_discreto_fdtd.omega',
        'modulo science_12;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Periodic 2D TE Yee discretisation preserves discrete magnetic divergence; this is not a charge-conservation theorem.\n'
        'funcao divergence(bx,by,dx,dy,i,j,n,k)  {\n'
        '  retornar (bx[(i+1)%n][j]-bx[i][j])/dx+(by[i][(j+1)%k]-by[i][j])/dy;\n'
        '}\n'
        'funcao execute(r)  {\n'
        '  var e=u::mat(r["electric_z"]);\n'
        '  var bx=u::mat(r["magnetic_x"]);\n'
        '  var by=u::mat(r["magnetic_y"]);\n'
        '  var n=len(e);\n'
        '  var k=len(e[0]);\n'
        '  se(n>8||k>8||len(bx)!=n||len(by)!=n||len(bx[0])!=k||len(by[0])!=k)  {\n'
        '    fail("Yee field shapes");\n'
        '  }\n'
        '  var dt=u::positive(u::q(r,"step"));\n'
        '  var dx=u::positive(u::q(r,"dx"));\n'
        '  var dy=u::positive(u::q(r,"dy"));\n'
        '  se(dt*dt/(dx*dx)+dt*dt/(dy*dy)>1)  {\n'
        '    fail("Yee CFL domain");\n'
        '  }\n'
        '  var nx=u::copy(bx);\n'
        '  var ny=u::copy(by);\n'
        '  var ne=u::copy(e);\n'
        '  var i=0;\n'
        '  enquanto(i<n)  {\n'
        '    var j=0;\n'
        '    enquanto(j<k)  {\n'
        '      put(nx[i],j,bx[i][j]-dt*(e[i][(j+1)%k]-e[i][j])/dy);\n'
        '      put(ny[i],j,by[i][j]+dt*(e[(i+1)%n][j]-e[i][j])/dx);\n'
        '      j=j+1;\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  var maximum=0;\n'
        '  i=0;\n'
        '  enquanto(i<n)  {\n'
        '    var j=0;\n'
        '    enquanto(j<k)  {\n'
        '      var before=divergence(bx,by,dx,dy,i,j,n,k);\n'
        '      var after=divergence(nx,ny,dx,dy,i,j,n,k);\n'
        '      se(before!=after)  {\n'
        '        fail("Discrete magnetic divergence changed");\n'
        '      }\n'
        '      maximum=m::max(maximum,m::abs(after));\n'
        '      put(ne[i],j,e[i][j]+dt*((ny[i][j]-ny[(i+n-1)%n][j])/dx-(nx[i][j]-nx[i][(j+k-1)%k])/dy));\n'
        '      j=j+1;\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  var out=u::result("periodic-2D-TE-Yee-step",ne);\n'
        '  put(out,"magnetic_x",nx);\n'
        '  put(out,"magnetic_y",ny);\n'
        '  put(out,"maximum_magnetic_divergence",maximum);\n'
        '  put(out,"divergence_preserved",1);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/fisica/mecanica_hamiltoniana.omega',
        'modulo science_1;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Energy-exact Cayley midpoint map for one quadratic oscillator, not arbitrary Hamiltonian flows.\n'
        'funcao execute(r)  {\n'
        '  var q=u::q(r,"position");\n'
        '  var p=u::q(r,"momentum");\n'
        '  var mass=u::positive(u::q(r,"mass"));\n'
        '  var k=u::positive(u::q(r,"spring"));\n'
        '  var h=u::q(r,"step");\n'
        '  var d=1+h*h*k/(4*mass);\n'
        '  var qn=((1-h*h*k/(4*mass))*q+h*p/mass)/d;\n'
        '  var pn=((1-h*h*k/(4*mass))*p-h*k*q)/d;\n'
        '  var before=p*p/(2*mass)+k*q*q/2;\n'
        '  var after=pn*pn/(2*mass)+k*qn*qn/2;\n'
        '  se(before!=after)  {\n'
        '    fail("Quadratic Hamiltonian conservation failure");\n'
        '  }\n'
        '  var out=u::result("implicit-midpoint-quadratic-Hamiltonian",[qn,pn]);\n'
        '  put(out,"energy_before",before);\n'
        '  put(out,"energy_after",after);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/fisica/modelo_ising_2d.omega',
        'modulo science_11;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'importar "../core/intervalos.omega" como iv;\n'
        'exportar execute;\n'
        '# All configurations on finite 2..4 square tori; Boltzmann weights are enclosed, not irrational exact samples.\n'
        'funcao spin(state,k)  {\n'
        '  retornar 2*(qfloor(state/u::power(2,k))%2)-1;\n'
        '}\n'
        'funcao execute(r)  {\n'
        '  var n=u::count(r,"size",2,4);\n'
        '  var j=u::q(r,"coupling");\n'
        '  var h=u::num(r,"field",0);\n'
        '  var beta=u::positive(u::q(r,"inverse_temperature"));\n'
        '  var states=u::power(2,n*n);\n'
        '  var z=[0,0];\n'
        '  var energy_sum=[0,0];\n'
        '  var magnet_sum=[0,0];\n'
        '  var state=0;\n'
        '  enquanto(state<states)  {\n'
        '    var energy=0;\n'
        '    var magnet=0;\n'
        '    var x=0;\n'
        '    enquanto(x<n)  {\n'
        '      var y=0;\n'
        '      enquanto(y<n)  {\n'
        '        var v=spin(state,x*n+y);\n'
        '        energy=energy-j*v*(spin(state,((x+1)%n)*n+y)+spin(state,x*n+(y+1)%n))-h*v;\n'
        '        magnet=magnet+v;\n'
        '        y=y+1;\n'
        '      }\n'
        '      x=x+1;\n'
        '    }\n'
        '    var weight=m::exp_interval(-beta*energy,8);\n'
        '    z=iv::add(z,weight);\n'
        '    energy_sum=iv::add(energy_sum,iv::scale(weight,energy));\n'
        '    magnet_sum=iv::add(magnet_sum,iv::scale(weight,m::abs(magnet)));\n'
        '    state=state+1;\n'
        '  }\n'
        '  var out=u::result("finite-periodic-Ising-exhaustive-enumeration",z);\n'
        '  put(out,"mean_energy",iv::div(energy_sum,z));\n'
        '  put(out,"mean_abs_magnetisation",iv::div(magnet_sum,z));\n'
        '  put(out,"configurations",states);\n'
        '  put(out,"thermodynamic_limit",0);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/fisica/orbita_kepler_exata.omega',
        'modulo science_3;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'importar "../core/intervalos.omega" como iv;\n'
        'exportar execute;\n'
        '# Encloses the elliptic Kepler root and planar coordinates; no rational exact representation of general anomalies.\n'
        'funcao execute(r)  {\n'
        '  var e=u::nonnegative(u::q(r,"eccentricity"));\n'
        '  se(e>=1)  {\n'
        '    fail("Elliptic eccentricity must be < 1");\n'
        '  }\n'
        '  var mean=u::q(r,"mean_anomaly");\n'
        '  se(m::abs(mean)>3)  {\n'
        '    fail("Principal anomaly domain [-3,3]");\n'
        '  }\n'
        '  var bits=u::integer(u::num(r,"bits",24),8,64);\n'
        '  var steps=u::integer(u::num(r,"steps",32),1,64);\n'
        '  var lo=mean-e;\n'
        '  var hi=mean+e;\n'
        '  var i=0;\n'
        '  enquanto(i<steps&&lo<hi)  {\n'
        '    var mid=(lo+hi)/2;\n'
        '    var sine=m::sin_interval(mid,bits);\n'
        '    var f=[mid-e*sine[1]-mean,mid-e*sine[0]-mean];\n'
        '    se(f[1]<0)  {\n'
        '      lo=mid;\n'
        '    }\n'
        '    senao  {\n'
        '      se(f[0]>0)  {\n'
        '        hi=mid;\n'
        '      }\n'
        '      senao  {\n'
        '        var radius=m::max(m::abs(f[0]),m::abs(f[1]))/(1-e);\n'
        '        lo=m::max(lo,mid-radius);\n'
        '        hi=m::min(hi,mid+radius);\n'
        '        parar;\n'
        '      }\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  var mid=(lo+hi)/2;\n'
        '  var radius=(hi-lo)/2;\n'
        '  var cs=m::cos_interval(mid,bits);\n'
        '  var sn=m::sin_interval(mid,bits);\n'
        '  var a=u::positive(u::num(r,"semi_major_axis",1));\n'
        '  var root=m::sqrt_interval(1-e*e,bits);\n'
        '  var x=[a*(m::max(-1,cs[0]-radius)-e),a*(m::min(1,cs[1]+radius)-e)];\n'
        '  var y=iv::scale(iv::mul(root,[m::max(-1,sn[0]-radius),m::min(1,sn[1]+radius)]),a);\n'
        '  var out=u::result("Kepler-equation-interval-bisection",[lo,hi]);\n'
        '  put(out,"x",x);\n'
        '  put(out,"y",y);\n'
        '  put(out,"steps",i);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/fisica/oscilador_harmonico_quantico.omega',
        'modulo science_18;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Rational unnormalised Fock basis with factorial metric; finite truncation cannot satisfy the infinite CCR exactly.\n'
        'funcao execute(r)  {\n'
        '  var n=u::count(r,"levels",1,16);\n'
        '  var omega=u::positive(u::q(r,"omega"));\n'
        '  var hbar=u::positive(u::q(r,"hbar"));\n'
        '  var down=[];\n'
        '  var up=[];\n'
        '  var metric=[];\n'
        '  var energies=[];\n'
        '  var fact=1;\n'
        '  var i=0;\n'
        '  enquanto(i<n)  {\n'
        '    var a=u::zeros(n);\n'
        '    var b=u::zeros(n);\n'
        '    se(i+1<n)  {\n'
        '      put(a,i+1,i+1);\n'
        '    }\n'
        '    se(i>0)  {\n'
        '      put(b,i-1,1);\n'
        '    }\n'
        '    push(down,a);\n'
        '    push(up,b);\n'
        '    push(metric,fact);\n'
        '    push(energies,hbar*omega*(i+1/2));\n'
        '    fact=fact*(i+1);\n'
        '    i=i+1;\n'
        '  }\n'
        '  var comm=[];\n'
        '  var du=u::mul(down,up);\n'
        '  var ud=u::mul(up,down);\n'
        '  i=0;\n'
        '  enquanto(i<n)  {\n'
        '    push(comm,u::add(du[i],u::scale(ud[i],-1)));\n'
        '    i=i+1;\n'
        '  }\n'
        '  var out=u::result("truncated-unnormalized-Fock-basis",energies);\n'
        '  put(out,"annihilation",down);\n'
        '  put(out,"creation",up);\n'
        '  put(out,"metric_diagonal",metric);\n'
        '  put(out,"commutator",comm);\n'
        '  put(out,"boundary_commutator_defect",n);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('ciencia/fisica/pendulo_duplo_caotico.omega',
        'modulo science_5;\n'
        'importar "../core/exato.omega" como u;\n'
        'importar "../../std/math.omega" como m;\n'
        'importar "../../std/string.omega" como s;\n'
        'importar "../../std/math/linalg_exact.omega" como la;\n'
        'importar "../core/intervalos.omega" como iv;\n'
        'exportar execute;\n'
        '# Rational enclosures of accelerations and optional measured finite-time separation; no asymptotic chaos proof.\n'
        'funcao execute(r)  {\n'
        '  var t1=u::q(r,"theta1");\n'
        '  var t2=u::q(r,"theta2");\n'
        '  se(m::abs(t1)>8||m::abs(t2)>8)  {\n'
        '    fail("Angle domain [-8,8]");\n'
        '  }\n'
        '  var w1=u::q(r,"omega1");\n'
        '  var w2=u::q(r,"omega2");\n'
        '  var l1=u::positive(u::q(r,"length1"));\n'
        '  var l2=u::positive(u::q(r,"length2"));\n'
        '  var m1=u::positive(u::q(r,"mass1"));\n'
        '  var m2=u::positive(u::q(r,"mass2"));\n'
        '  var g=u::positive(u::q(r,"gravity"));\n'
        '  var bits=u::integer(u::num(r,"bits",16),8,64);\n'
        '  var delta=t1-t2;\n'
        '  var sd=m::sin_interval(delta,bits);\n'
        '  var cd=m::cos_interval(delta,bits);\n'
        '  var denominator=iv::sub([2*m1+m2,2*m1+m2],iv::scale(m::cos_interval(2*delta,bits),m2));\n'
        '  var numerator1=iv::sub(iv::scale(m::sin_interval(t1,bits),-g*(2*m1+m2)),iv::scale(m::sin_interval(t1-2*t2,bits),m2*g));\n'
        '  numerator1=iv::sub(numerator1,iv::scale(iv::mul(sd,iv::add([w2*w2*l2,w2*w2*l2],iv::scale(cd,w1*w1*l1))),2*m2));\n'
        '  var inner=iv::add([w1*w1*l1*(m1+m2),w1*w1*l1*(m1+m2)],iv::add(iv::scale(m::cos_interval(t1,bits),g*(m1+m2)),iv::scale(cd,w2*w2*l2*m2)));\n'
        '  var a1=iv::div(numerator1,iv::scale(denominator,l1));\n'
        '  var a2=iv::div(iv::scale(iv::mul(sd,inner),2),iv::scale(denominator,l2));\n'
        '  var out=u::result("double-pendulum-interval-vector-field",[a1,a2]);\n'
        '  se(has(r,"separation_initial"))  {\n'
        '    var first=u::positive(u::q(r,"separation_initial"));\n'
        '    var last=u::positive(u::q(r,"separation_final"));\n'
        '    var elapsed=u::positive(u::q(r,"elapsed"));\n'
        '    put(out,"finite_time_growth_rate",iv::scale(m::log_interval(last/first,bits),1/elapsed));\n'
        '  }\n'
        '  put(out,"asymptotic_Lyapunov_proved",0);\n'
        '  retornar out;\n'
        '}\n'
    ),
