    ('exemplos/evolucao_xor/geracao_0.omega',
        '# Programa sintetizado automaticamente por Omega.\n'
        'parametro x = 0;\n'
        'parametro y = 0;\n'
        'parametro esperado = 0;\n'
        'tensor soma_xy = x + y + 0;\n'
        'tensor h0 = relu(relu(soma_xy));\n'
        'tensor h1 = relu(soma_xy - 1);\n'
        'tensor h2 = relu(soma_xy - 2);\n'
        'tensor saida = (0) * h0 + (0) * h1 + (0) * h2 + 0;\n'
        'perda custo = (saida - esperado)^2;\n'
        'mostrar saida;\n'
    ),
