        '        "intrinsic_dim": model.signature["intrinsic_dim"],\n'
        '        "sparse_features": features.shape[1],\n'
        '        "trained_steps": model.trained_steps,\n'
        '    }\n'
        '    atomic_json(args.output / "report.json", result)\n'
        '    print(json.dumps(result, indent=2))\n'
        '    if accuracy < 0.8:\n'
        '        raise SystemExit("Held-out Iris smoke test failed: accuracy below 0.8")\n'
        '\n'
        '\n'
        'if __name__ == "__main__":\n'
        '    main()\n'
