    ('exemplos/nextorch/render_gallery.py',
        '"""Render actual Orange widgets in a headless environment after iris_workflow.py."""\n'
        '\n'
        'import os\n'
        'from pathlib import Path\n'
        '\n'
        'os.environ.setdefault("QT_QPA_PLATFORM", "offscreen")\n'
        'os.environ.setdefault("MPLCONFIGDIR", "/tmp/nextorch-matplotlib")\n'
        'os.environ.setdefault("XDG_CACHE_HOME", "/tmp/nextorch-cache")\n'
        'os.environ.setdefault("XDG_CONFIG_HOME", "/tmp/nextorch-config")\n'
        'import torch\n'
        'from AnyQt.QtWidgets import QApplication\n'
        'from Orange.data import Table\n'
        '\n'
        'from nextorch import NextorchModel\n'
        'from nextorch.core import OrangeBridge\n'
        'from nextorch.orange.OWFormalLoopMonitor import OWFormalLoopMonitor, replay_to_table\n'
        'from nextorch.orange.OWLatentInspector import OWLatentInspector, inspect_model\n'
        'from nextorch.orange.OWNextorchSynthesizer import OWNextorchSynthesizer\n'
        '\n'
        '\n'
        'class State:\n'
        '    def set_status(self, value):\n'
        '        pass\n'
        '\n'
        '    def is_interruption_requested(self):\n'
        '        return False\n'
        '\n'
        '\n'
        'def main():\n'
        '    torch.set_num_threads(2)\n'
        '    app = QApplication.instance() or QApplication([])\n'
        '    directory = Path("artifacts/gallery")\n'
        '    directory.mkdir(parents=True, exist_ok=True)\n'
        '    model = NextorchModel.load("artifacts/iris/iris_model.pt")\n'
        '    table = Table("iris")\n'
        '    synth = OWNextorchSynthesizer()\n'
        '    synth.data = table\n'
        '    values = [\n'
        '        model.signature["intrinsic_dim"],\n'
        '        model.diagnostics["synflow"],\n'
        '        model.diagnostics["isometry_ratio"],\n'
        '    ]\n'
        '    diagnostics = OrangeBridge.tensors_to_table(\n'
        '        torch.tensor([values]), ["dimension", "synflow", "isometry"]\n'
        '    )\n'
        '    synth.on_done((model, diagnostics))\n'
        '    inspector = OWLatentInspector()\n'
        '    inspector.model = model\n'
        '    inspector.data = table\n'
        '    inspector.dimension_index = 1\n'
        '    inspector.on_done(inspect_model(model, table, "PCA", 3, State()))\n'
        '    monitor = OWFormalLoopMonitor()\n'
        '    engine = model.make_formal_engine()\n'
        '    for _ in range(3):\n'
        '        report = engine.execute_self_improvement_cycle(n_problems=8)\n'
        '        monitor.on_partial_result((engine, report, replay_to_table(engine)))\n'
        '    for name, widget in [("synthesizer", synth), ("inspector", inspector), ("formal", monitor)]:\n'
        '        widget.resize(1050, 700)\n'
        '        widget.show()\n'
        '        app.processEvents()\n'
        '        assert widget.grab().save(str(directory / f"{name}.png"))\n'
        '        widget.onDeleteWidget()\n'
        '        widget.close()\n'
        '    print(f"Saved three real widget screenshots to {directory}")\n'
        '\n'
        '\n'
        'if __name__ == "__main__":\n'
        '    main()\n'
    ),
