    ('exemplos/otimizacao_ir.omega',
        '# Transformações estruturais locais: eliminam transpostas e ReLU repetidas.\n'
        'parametro matriz W = [[1, 2], [3, 4]];\n'
        'vetor x = [2, 1];\n'
        'tensor Wduplo = transposta(transposta(W));\n'
        'tensor ativacao = relu(relu(Wduplo @ x));\n'
        'perda custo = dot(ativacao, ativacao) + 0;\n'
        'mostrar custo;\n'
    ),
