    ('exemplos/primeiro_programa.omega',
        '# Ômega 0.1: dois parâmetros e uma perda quadrática.\n'
        'parametro x = 3;\n'
        'parametro y = -1;\n'
        '\n'
        '# A perda depende de duas variáveis diferenciáveis.\n'
        'perda objetivo = (x - 1)^2 + (y + 2)^2;\n'
        'mostrar objetivo;\n'
        '\n'
        'gradiente objetivo em x;\n'
        'gradiente objetivo em y;\n'
        '\n'
        '# Cada passo só é aceito com prova local de não aumento da perda.\n'
        'passo objetivo em x taxa 1/4;\n'
        'passo objetivo em y taxa 1/4;\n'
        'mostrar objetivo;\n'
        '\n'
        '# Identidade formal, válida para todos os valores de a e b.\n'
        'provar (a + b)^2 == a^2 + 2*a*b + b^2;\n'
        '\n'
        '# Transformação sintática aceita somente após equivalência algébrica.\n'
        'reescrever objetivo = (y + 2)^2 + (x - 1)^2;\n'
        'mostrar x;\n'
        'mostrar y;\n'
        'mostrar objetivo;\n'
    ),
