    ('formal/Tier2/CompilerSelfPreservation.lean',
        'import Tier2.GPUInvariantBridge\n'
        'import Omega.VerifiedRewrite\n'
        '\n'
        'namespace OmegaHyper\n'
        'abbrev Rational := ℚ\n'
        'abbrev Tensor (α : Type) := List α\n'
        'abbrev OmegaAST := OmegaTensor.Expr\n'
        'abbrev Environment := OmegaTensor.Env\n'
        '\n'
        'def withInputs (env : Environment) (x : Tensor Rational) : Environment :=\n'
        '  fun i => if i < x.length then x[i]! else env (i-x.length)\n'
        '\n'
        'def eval_ast (p : OmegaAST) (env : Environment) (x : Tensor Rational) : Rational :=\n'
        '  OmegaTensor.eval (withInputs env x) p\n'
        '\n'
        'def SemanticEquivalence (orig opt : OmegaAST) : Prop :=\n'
        '  ∀ env x, eval_ast orig env x = eval_ast opt env x ∧\n'
        '    OmegaTensor.defined (withInputs env x) orig = OmegaTensor.defined (withInputs env x) opt ∧\n'
        '    ∀ v, OmegaTensor.eval (withInputs env x) (OmegaTensor.derive orig v) =\n'
        '      OmegaTensor.eval (withInputs env x) (OmegaTensor.derive opt v)\n'
        '\n'
        'theorem compiler_mutation_preserves_semantics\n'
        '    (orig_ast opt_ast : OmegaAST) (p : SemanticEquivalence orig_ast opt_ast) :\n'
        '    ∀ (env : Environment) (x : Tensor Rational),\n'
        '      eval_ast orig_ast env x = eval_ast opt_ast env x := fun env x => (p env x).1\n'
        '\n'
        'theorem semantic_equivalence_transitive (a b c : OmegaAST)\n'
        '    (ab : SemanticEquivalence a b) (bc : SemanticEquivalence b c) : SemanticEquivalence a c := by\n'
        '  intro env x\n'
        '  exact ⟨(ab env x).1.trans (bc env x).1,\n'
        '    (ab env x).2.1.trans (bc env x).2.1,\n'
        '    fun v => ((ab env x).2.2 v).trans ((bc env x).2.2 v)⟩\n'
        '\n'
        "-- This theorem requires every step's equivalence; bootstrap hash equality\n"
        '-- alone is deliberately not a proof of arbitrary compiler correctness.\n'
        'theorem generations_preserve (versions : Nat → OmegaAST)\n'
        '    (step : ∀ n, SemanticEquivalence (versions n) (versions (n+1))) :\n'
        '    ∀ n, SemanticEquivalence (versions 0) (versions n) := by\n'
        '  intro n\n'
        '  induction n with\n'
        '  | zero => intro env x; exact ⟨rfl,rfl,fun _ => rfl⟩\n'
        '  | succ n ih => exact semantic_equivalence_transitive _ _ _ ih (step n)\n'
        '\n'
        '#print axioms compiler_mutation_preserves_semantics\n'
        '#print axioms semantic_equivalence_transitive\n'
        '#print axioms generations_preserve\n'
        'end OmegaHyper\n'
    ),
