        '\n'
        'def Contains (i : RationalInterval) (x : ℚ) : Prop := i.lower ≤ x ∧ x ≤ i.upper\n'
        '\n'
        'theorem interval_add_sound (a b : RationalInterval) (x y : ℚ)\n'
