    ('formal/Universal/SoundnessTheorem.lean',
        'import Omega.Refinement\n'
        'namespace OmegaUniversal\n'
        'inductive Ty where | rational | proposition deriving DecidableEq\n'
        'inductive Expr : Ty → Type where\n'
        ' | rational (q : ℚ) : Expr .rational\n'
        ' | add (a b : Expr .rational) : Expr .rational\n'
        ' | mul (a b : Expr .rational) : Expr .rational\n'
        ' | le (a b : Expr .rational) : Expr .proposition\n'
        ' | conj (a b : Expr .proposition) : Expr .proposition\n'
        ' | divide (a : Expr .rational) (denominator : {q : ℚ // q ≠ 0}) : Expr .rational\n'
        'abbrev Value : Ty → Type | .rational => ℚ | .proposition => Prop\n'
        'def eval : {t : Ty} → Expr t → Value t\n'
        ' | _, .rational q => q\n'
        ' | _, .add a b => eval a + eval b\n'
        ' | _, .mul a b => eval a * eval b\n'
        ' | _, .le a b => eval a ≤ eval b\n'
        ' | _, .conj a b => eval a ∧ eval b\n'
        ' | _, .divide a d => eval a / d.val\n'
        'theorem type_soundness {t : Ty} (e : Expr t) : ∃ v : Value t, eval e = v := ⟨eval e,rfl⟩\n'
        'theorem division_defined (a : Expr .rational) (d : {q : ℚ // q ≠ 0}) : d.val ≠ 0 := d.property\n'
        'theorem quorum_intersection_bound (n f q : Nat) (faults : 3*f < n) (quorum : q=n-f) : n+f < 2*q := by omega\n'
        '#print axioms type_soundness\n'
        '#print axioms division_defined\n'
        '#print axioms quorum_intersection_bound\n'
        'end OmegaUniversal\n'
    ),
