    ('formal/science_axioms/NeedlemanWunschOptimality.lean',
        'import Mathlib.Algebra.Order.Field.Rat\n'
        'import Mathlib.Tactic.Ring\n'
        'import Mathlib.Tactic.FieldSimp\n'
        'import Mathlib.Tactic.Linarith\n'
        'import Mathlib.Tactic.NormNum\n'
        'import Mathlib.Tactic.Positivity\n'
        '\n'
        'namespace OmegaScience\n'
        'def nwRow (sub : ℕ → ℕ → ℚ) (gap : ℚ) (previous : ℕ → ℚ) (row : ℕ) : ℕ → ℚ\n'
        '  | 0 => ((row+1:ℕ):ℚ)*gap\n'
        '  | n+1 => max (previous n+sub row n)\n'
        '      (max (previous (n+1)+gap) (nwRow sub gap previous row n+gap))\n'
        'def nwScore (sub : ℕ → ℕ → ℚ) (gap : ℚ) : ℕ → ℕ → ℚ\n'
        '  | 0, n => (n:ℚ)*gap\n'
        '  | m+1, n => nwRow sub gap (nwScore sub gap m) m n\n'
        'inductive NWAlignment (sub : ℕ → ℕ → ℚ) (gap : ℚ) : ℕ → ℕ → ℚ → Prop\n'
        '  | empty : NWAlignment sub gap 0 0 0\n'
        '  | delete {m n v} : NWAlignment sub gap m n v → NWAlignment sub gap (m+1) n (v+gap)\n'
        '  | insert {m n v} : NWAlignment sub gap m n v → NWAlignment sub gap m (n+1) (v+gap)\n'
        '  | diagonal {m n v} : NWAlignment sub gap m n v → NWAlignment sub gap (m+1) (n+1) (v+sub m n)\n'
        'theorem nw_zero_col (sub : ℕ → ℕ → ℚ) (gap : ℚ) (m : ℕ) : nwScore sub gap m 0=(m:ℚ)*gap := by\n'
        '  cases m <;> rfl\n'
        'theorem nw_succ (sub : ℕ → ℕ → ℚ) (gap : ℚ) (m n : ℕ) :\n'
        '    nwScore sub gap (m+1) (n+1)=max (nwScore sub gap m n+sub m n)\n'
        '      (max (nwScore sub gap m (n+1)+gap) (nwScore sub gap (m+1) n+gap)) := rfl\n'
        'theorem nw_alignment_upper {sub : ℕ → ℕ → ℚ} {gap : ℚ} {m n : ℕ} {v : ℚ}\n'
        '    (alignment : NWAlignment sub gap m n v) : v ≤ nwScore sub gap m n := by\n'
        '  induction alignment with\n'
        '  | empty => simp [nwScore]\n'
        '  | @delete m n v _ ih =>\n'
        '      apply (add_le_add_right ih gap).trans\n'
        '      cases n with\n'
        '      | zero => simp [nw_zero_col, Nat.cast_add, add_mul]\n'
        '      | succ n =>\n'
        '          rw [nw_succ]\n'
        '          exact (le_max_left _ _).trans (le_max_right _ _)\n'
        '  | @insert m n v _ ih =>\n'
        '      apply (add_le_add_right ih gap).trans\n'
        '      cases m with\n'
        '      | zero => simp [nwScore, Nat.cast_add, add_mul]\n'
        '      | succ m =>\n'
        '          rw [nw_succ]\n'
        '          exact (le_max_right _ _).trans (le_max_right _ _)\n'
        '  | @diagonal m n v _ ih =>\n'
        '      rw [nw_succ]\n'
        '      exact (add_le_add_right ih _).trans (le_max_left _ _)\n'
        'theorem nw_score_attainable (sub : ℕ → ℕ → ℚ) (gap : ℚ) (m n : ℕ) :\n'
        '    NWAlignment sub gap m n (nwScore sub gap m n) := by\n'
        '  induction m generalizing n with\n'
        '  | zero =>\n'
        '      induction n with\n'
        '      | zero => simpa [nwScore] using (NWAlignment.empty : NWAlignment sub gap 0 0 0)\n'
        '      | succ n ih =>\n'
        '          simpa [nwScore, Nat.cast_add, add_mul] using NWAlignment.insert ih\n'
        '  | succ m ih =>\n'
        '      induction n with\n'
        '      | zero =>\n'
        '          simpa [nw_zero_col, Nat.cast_add, add_mul] using NWAlignment.delete (ih 0)\n'
        '      | succ n left =>\n'
        '          rw [nw_succ]\n'
        '          rcases le_total (nwScore sub gap m n+sub m n)\n'
        '              (max (nwScore sub gap m (n+1)+gap) (nwScore sub gap (m+1) n+gap)) with h | h\n'
        '          · rw [max_eq_right h]\n'
        "            rcases le_total (nwScore sub gap m (n+1)+gap) (nwScore sub gap (m+1) n+gap) with h' | h'\n"
        "            · rw [max_eq_right h']; exact NWAlignment.insert left\n"
        "            · rw [max_eq_left h']; exact NWAlignment.delete (ih (n+1))\n"
        '          · rw [max_eq_left h]; exact NWAlignment.diagonal (ih n)\n'
        'theorem needleman_wunsch_optimal (sub : ℕ → ℕ → ℚ) (gap : ℚ) (m n : ℕ) :\n'
        '    NWAlignment sub gap m n (nwScore sub gap m n) ∧\n'
        '    ∀ v, NWAlignment sub gap m n v → v ≤ nwScore sub gap m n :=\n'
        '  ⟨nw_score_attainable sub gap m n, fun _ alignment => nw_alignment_upper alignment⟩\n'
        '\n'
        '#print axioms needleman_wunsch_optimal\n'
        'end OmegaScience\n'
    ),
