        '  exact inv_bounds (Real.sqrt x) a b ha ⟨lower, upper⟩\n'
        '\n'
        'theorem exp_interval (x l u a b : ℝ) (hx : l ≤ x ∧ x ≤ u)\n'
        '    (ha : a ≤ Real.exp l) (hb : Real.exp u ≤ b) :\n'
        '    a ≤ Real.exp x ∧ Real.exp x ≤ b :=\n'
        '  ⟨ha.trans (Real.exp_le_exp.mpr hx.1), (Real.exp_le_exp.mpr hx.2).trans hb⟩\n'
        '\n'
        'theorem exp_double (x l u a b : ℝ) (hl : 0 ≤ l)\n'
        '    (hx : l ≤ Real.exp x ∧ Real.exp x ≤ u)\n'
        '    (ha : a ≤ l*l) (hb : u*u ≤ b) :\n'
        '    a ≤ Real.exp (x+x) ∧ Real.exp (x+x) ≤ b := by\n'
        '  rw [Real.exp_add]\n'
        '  have hp := Real.exp_pos x\n'
        '  exact ⟨ha.trans (mul_le_mul hx.1 hx.1 hl (le_of_lt hp)),\n'
        '         (mul_le_mul hx.2 hx.2 (le_of_lt hp) (hl.trans (hx.1.trans hx.2))).trans hb⟩\n'
        '\n'
        'theorem normalized_scale (x d c : ℝ) (hc : c ≠ 0) :\n'
        '    (c*x)/(c*d) = x/d := by\n'
        '  rw [mul_div_mul_left _ _ hc]\n'
        '\n'
        'noncomputable def softmax {n : ℕ} (v : Fin (n+1) → ℝ) (i : Fin (n+1)) : ℝ :=\n'
        '  Real.exp (v i) / ∑ k, Real.exp (v k)\n'
        '\n'
        'theorem softmax_order {n : ℕ} (v : Fin (n+1) → ℝ) (i j : Fin (n+1)) :\n'
        '    softmax v i < softmax v j ↔ v i < v j := by\n'
        '  have positive : 0 < ∑ k, Real.exp (v k) :=\n'
        '    Finset.sum_pos (fun k _ => Real.exp_pos (v k)) Finset.univ_nonempty\n'
        '  rw [softmax, softmax, div_lt_div_iff_of_pos_right positive, Real.exp_lt_exp]\n'
        '\n'
        'theorem taylor_uniform (x : ℝ) (n : ℕ) (hn : 0 < n) (hx : |x| ≤ 1) :\n'
