        'import TensorKernel\n'
        'namespace OmegaVerifiedRewrite\n'
        'open OmegaTensor\n'
        'def Preserves (f : Expr → Expr) : Prop := ∀ e s,\n'
        '    eval s (f e) = eval s e ∧ defined s (f e) = defined s e ∧\n'
        '    ∀ x, eval s (derive (f e) x) = eval s (derive e x)\n'
        'theorem identity_preserves : Preserves id := by intro e s; exact ⟨rfl,rfl,fun _ => rfl⟩\n'
        'theorem compose_preserves (f g : Expr → Expr) (hf : Preserves f) (hg : Preserves g) :\n'
        '    Preserves (fun e => g (f e)) := by\n'
        '  intro e s\n'
        '  exact ⟨(hg (f e) s).1.trans (hf e s).1,\n'
        '    (hg (f e) s).2.1.trans (hf e s).2.1,\n'
        '    fun x => ((hg (f e) s).2.2 x).trans ((hf e s).2.2 x)⟩\n'
        'theorem generations_preserve (versions : Nat → Expr → Expr)\n'
        '    (initial : Preserves (versions 0))\n'
        '    (step : ∀ n, Preserves (versions n) → Preserves (versions (n+1))) :\n'
        '    ∀ n, Preserves (versions n) := by intro n; induction n with | zero => exact initial | succ n ih => exact step n ih\n'
        '#print axioms compose_preserves\n'
        '#print axioms generations_preserve\n'
        'end OmegaVerifiedRewrite\n'
