        '#ifndef OMEGA_CUDA_RATIONAL_TYPES_CUH\n'
        '#define OMEGA_CUDA_RATIONAL_TYPES_CUH\n'
        '#include <stdint.h>\n'
        '#include <limits.h>\n'
        '#ifdef __CUDACC__\n'
