        '#define OMEGA_HD inline\n'
        '#define OMEGA_ALIGN(n) alignas(n)\n'
        '#endif\n'
        '\n'
        'namespace omega_gpu {\n'
        '// Alignment is an ABI property, not a guarantee of a particular LDG instruction.\n'
        'struct OMEGA_ALIGN(16) Rational64 { int64_t num; uint64_t den; };\n'
        'struct OMEGA_ALIGN(32) Rational128 { __int128_t num; unsigned __int128 den; };\n'
