    ('nextorch/engine/dynamic_depth.py',
        '"""Per-sample early exit based on normalized predictive entropy."""\n'
        '\n'
        'import math\n'
        '\n'
        'import torch\n'
        '\n'
        '\n'
        'def normalized_entropy(logits):\n'
        '    if logits.shape[-1] < 2:\n'
        '        return torch.zeros(logits.shape[:-1], device=logits.device, dtype=logits.dtype)\n'
        '    logp = logits.log_softmax(-1)\n'
        '    return -(logp.exp() * logp).sum(-1) / math.log(logits.shape[-1])\n'
        '\n'
        '\n'
        'class EntropyExit:\n'
        '    def __init__(self, threshold=0.15, min_steps=1):\n'
        '        if not 0 <= threshold <= 1 or min_steps < 1:\n'
        '            raise ValueError("Invalid entropy exit settings")\n'
        '        self.threshold, self.min_steps = threshold, min_steps\n'
        '\n'
        '    def __call__(self, logits, step):\n'
        '        return (normalized_entropy(logits) <= self.threshold) & (step >= self.min_steps)\n'
    ),
    ('nextorch/engine/latent_ttc.py',
        '"""Trainable continuous recurrence and branching, per-sample latent beam search."""\n'
        '\n'
        'import math\n'
        'from dataclasses import dataclass\n'
        '\n'
        'import torch\n'
        'from torch import nn\n'
        '\n'
        'from nextorch.verifier.mup import MuPScaleCoordinator\n'
        '\n'
        'from .dynamic_depth import EntropyExit\n'
        '\n'
        '\n'
        '@dataclass\n'
        'class BeamResult:\n'
        '    logits: torch.Tensor\n'
        '    uncertainty: torch.Tensor\n'
        '    trajectory: torch.Tensor  # [steps + 1, batch, width], including h0\n'
        '    steps: torch.Tensor\n'
        '    beam_scores: torch.Tensor\n'
        '\n'
        '\n'
        'class LatentThoughtBlock(nn.Module):\n'
        '    def __init__(self, d_model):\n'
        '        super().__init__()\n'
        '        self.state_gate = nn.Linear(2 * d_model, d_model)\n'
        '        self.candidate_transform = nn.Sequential(\n'
        '            nn.Linear(2 * d_model, d_model), nn.GELU(), nn.Linear(d_model, d_model)\n'
        '        )\n'
        '        self.layer_norm = nn.LayerNorm(d_model)\n'
        '\n'
        '    def forward(self, h, context):\n'
        '        combined = torch.cat((h, context), -1)\n'
        '        gate = torch.sigmoid(self.state_gate(combined))\n'
        '        return self.layer_norm(h.lerp(torch.tanh(self.candidate_transform(combined)), gate))\n'
        '\n'
        '\n'
        'class NextorchReasoner(nn.Module):\n'
        '    def __init__(self, vocab_size=16, d_model=64, thought_steps=4, max_length=128):\n'
        '        super().__init__()\n'
        '        if min(vocab_size, d_model, thought_steps, max_length) <= 0:\n'
        '            raise ValueError("All reasoner dimensions must be positive")\n'
        '        self.vocab_size, self.d_model, self.thought_steps = vocab_size, d_model, thought_steps\n'
        '        self.max_length = max_length\n'
        '        # One extra symbol is reserved for padding, never a logical proposition.\n'
        '        self.embedding = nn.Embedding(vocab_size + 1, d_model, padding_idx=vocab_size)\n'
        '        self.input_layer = nn.Linear(d_model, d_model)\n'
        '        self.thought_cell = LatentThoughtBlock(d_model)\n'
        '        self.value_head = nn.Linear(d_model, 1)\n'
        '        self.policy_head = nn.Linear(d_model, vocab_size)\n'
        '        position = torch.arange(max_length).float()[:, None]\n'
        '        freq = torch.exp(torch.arange(0, d_model, 2).float() * (-math.log(10000) / d_model))\n'
        '        encoding = torch.zeros(max_length, d_model)\n'
        '        encoding[:, 0::2] = torch.sin(position * freq)\n'
        '        encoding[:, 1::2] = torch.cos(position * freq[: d_model // 2])\n'
        '        self.register_buffer("position_encoding", encoding)\n'
        '        MuPScaleCoordinator.apply_mup_coordinates(self, d_model)\n'
        '        with torch.no_grad():\n'
        '            self.embedding.weight[vocab_size].zero_()\n'
        '\n'
        '    def embed(self, tokens):\n'
        '        if tokens.ndim != 2 or tokens.shape[1] == 0 or tokens.shape[1] > self.max_length:\n'
        '            raise ValueError("Expected [batch, nonempty sequence] within max_length")\n'
        '        if tokens.dtype not in (torch.int32, torch.int64):\n'
        '            raise TypeError("Token indices must be integers")\n'
        '        mask = tokens != self.vocab_size\n'
        '        if not mask.any(-1).all():\n'
        '            raise ValueError("A sequence cannot consist entirely of padding")\n'
        '        values = self.embedding(tokens) + self.position_encoding[: tokens.shape[1]]\n'
        '        # Position-dependent gates preserve order; simple mean pooling would lose edge directions.\n'
        '        gate = torch.sigmoid(self.position_encoding[: tokens.shape[1]])\n'
        '        context = (values * gate * mask[..., None]).sum(1) / mask.sum(1, keepdim=True)\n'
        '        return torch.tanh(self.input_layer(context))\n'
        '\n'
        '    def forward_embeddings(self, h0, capture_trajectory=False):\n'
        '        h, trajectory = h0, []\n'
        '        for _ in range(self.thought_steps):\n'
        '            h = self.thought_cell(h, h0)\n'
        '            trajectory.append(h)\n'
        '        output = (self.policy_head(h), nn.functional.softplus(self.value_head(h)))\n'
        '        return (*output, trajectory) if capture_trajectory else output\n'
        '\n'
        '    def forward(self, x, capture_trajectory=False):\n'
        '        return self.forward_embeddings(self.embed(x), capture_trajectory)\n'
        '\n'
        '    @torch.no_grad()\n'
        '    def beam_search(\n'
        '        self,\n'
        '        tokens,\n'
        '        beam_width=4,\n'
        '        branches=2,\n'
        '        noise_std=0.05,\n'
        '        entropy_threshold=0.15,\n'
        '        min_steps=1,\n'
        '        growth_limit=4.0,\n'
        '        generator=None,\n'
        '    ):\n'
        '        if min(beam_width, branches) <= 0 or noise_std < 0 or growth_limit <= 1:\n'
        '            raise ValueError("Invalid beam search configuration")\n'
        '        h0 = self.embed(tokens)\n'
        '        batch, width = h0.shape\n'
        '        h = h0[:, None, :]\n'
        '        scores = h0.new_zeros(batch, 1)\n'
        '        previous = nn.functional.softplus(self.value_head(h)).squeeze(-1)\n'
        '        histories = h.unsqueeze(2)  # [batch, beam, time, width]\n'
        '        done = torch.zeros(batch, dtype=torch.bool, device=h.device)\n'
        '        steps = torch.full((batch,), self.thought_steps, device=h.device, dtype=torch.long)\n'
        '        exit_gate = EntropyExit(entropy_threshold, min_steps)\n'
        '        for step in range(1, self.thought_steps + 1):\n'
        '            parents = h.shape[1]\n'
        '            expanded = h[:, :, None, :].expand(-1, -1, branches, -1)\n'
        '            context = h0[:, None, None, :].expand_as(expanded)\n'
        '            candidate = self.thought_cell(expanded, context)\n'
        '            noise = torch.randn(\n'
        '                candidate.shape, device=h.device, dtype=h.dtype, generator=generator\n'
        '            )\n'
        '            candidate = candidate + noise * noise_std\n'
        '            candidate = torch.where(done[:, None, None, None], expanded, candidate)\n'
        '            uncertainty = nn.functional.softplus(self.value_head(candidate)).squeeze(-1)\n'
        '            cost = scores[:, :, None] + uncertainty\n'
        '            cost = torch.where(done[:, None, None], scores[:, :, None].expand_as(cost), cost)\n'
        '            bad = uncertainty > previous[:, :, None] * growth_limit\n'
        '            cost = cost.masked_fill(bad & ~done[:, None, None], torch.inf)\n'
        '            flat = cost.flatten(1)\n'
        '            # Always retain a finite fallback when every branch violates the pruning threshold.\n'
        '            all_bad = ~torch.isfinite(flat).any(-1)\n'
        '            flat = torch.where(\n'
        '                all_bad[:, None], (scores[:, :, None] + uncertainty).flatten(1), flat\n'
        '            )\n'
        '            count = min(beam_width, parents * branches)\n'
        '            scores, indices = flat.topk(count, largest=False, dim=1)\n'
        '            chosen = indices // branches\n'
        '            h = candidate.flatten(1, 2).gather(1, indices[..., None].expand(-1, -1, width))\n'
        '            previous = uncertainty.flatten(1).gather(1, indices)\n'
        '            histories = histories.gather(1, chosen[..., None, None].expand(-1, -1, step, width))\n'
        '            histories = torch.cat((histories, h.unsqueeze(2)), dim=2)\n'
        '            newly_done = exit_gate(self.policy_head(h[:, 0]), step) & ~done\n'
        '            steps[newly_done] = step\n'
        '            done |= newly_done\n'
        '            if done.all():\n'
        '                break\n'
        '        best = h[:, 0]\n'
        '        return BeamResult(\n'
        '            self.policy_head(best),\n'
        '            nn.functional.softplus(self.value_head(best)),\n'
        '            histories[:, 0].transpose(0, 1),\n'
        '            steps,\n'
        '            scores,\n'
        '        )\n'
        '\n'
        '\n'
        'class ContinuousReasoner(nn.Module):\n'
        '    """Continuous wrapper for Jacobian/SynFlow diagnostics of a discrete reasoner."""\n'
        '\n'
        '    def __init__(self, reasoner):\n'
        '        super().__init__()\n'
        '        self.thought_cell = reasoner.thought_cell\n'
        '        self.policy_head = reasoner.policy_head\n'
        '        self.thought_steps = reasoner.thought_steps\n'
        '\n'
        '    def forward(self, h):\n'
        '        context = h\n'
        '        for _ in range(self.thought_steps):\n'
        '            h = self.thought_cell(h, context)\n'
        '        return self.policy_head(h)\n'
    ),
