    ('nextorch/formal/barrier.py',
        '"""Canonical logical problem encoding and a proof gate for replay admission."""\n'
        '\n'
        'import asyncio\n'
        'from dataclasses import dataclass\n'
        '\n'
        'import torch\n'
        '\n'
        'from .z3_gateway import FormalVerificationGateway\n'
        '\n'
        '\n'
        '@dataclass(frozen=True)\n'
        'class LogicalProblem:\n'
        '    premises: tuple[tuple[int, int], ...]\n'
        '    source: int\n'
        '\n'
        '    def __post_init__(self):\n'
        '        edges = tuple(tuple(edge) for edge in self.premises)\n'
        '        if any(len(edge) != 2 for edge in edges):\n'
        '            raise ValueError("Each premise must have two proposition indices")\n'
        '        if any(type(i) is not int or i < 0 for i in (self.source, *(i for e in edges for i in e))):\n'
        '            raise ValueError("Proposition indices must be nonnegative integers")\n'
        '        object.__setattr__(self, "premises", edges)\n'
        '\n'
        '    def encode(self, vocab_size, device="cpu"):\n'
        '        tokens = [self.source] + [i for edge in self.premises for i in edge]\n'
        '        if max(tokens) >= vocab_size:\n'
        '            raise ValueError("Problem exceeds model vocabulary")\n'
        '        return torch.tensor([tokens], dtype=torch.long, device=device)\n'
        '\n'
        '    def reachable(self):\n'
        '        visited, frontier = {self.source}, [self.source]\n'
        '        while frontier:\n'
        '            current = frontier.pop(0)\n'
        '            for a, b in self.premises:\n'
        '                if a == current and b not in visited:\n'
        '                    visited.add(b)\n'
        '                    frontier.append(b)\n'
        '        return sorted(visited)\n'
        '\n'
        '\n'
        'class FormalBarrier:\n'
        '    def __init__(self, timeout_ms=2000, require_lean=False, lean_bridge=None):\n'
        '        self.timeout_ms = timeout_ms\n'
        '        self.require_lean = require_lean\n'
        '        self.lean_bridge = lean_bridge\n'
        '\n'
        '    def _z3(self, problem, target):\n'
        '        return FormalVerificationGateway.certify_deduction(\n'
        '            problem.premises, problem.source, target, self.timeout_ms\n'
        '        )\n'
        '\n'
        '    async def certify_async(self, problem, target):\n'
        '        from .lean_bridge import LeanBridge\n'
        '        from .z3_gateway import VerificationResult\n'
        '\n'
        '        result = self._z3(problem, target)\n'
        '        if not result.valid or not self.require_lean:\n'
        '            return result\n'
        '        lean = await (self.lean_bridge or LeanBridge()).verify_deduction(problem, target)\n'
        '        if not lean.valid:\n'
        '            return VerificationResult("lean_" + lean.status, result.statement, reason=lean.output)\n'
        '        return VerificationResult(\n'
        '            "valid", result.statement, proof=result.proof + "\\nLEAN KERNEL CHECK\\n" + lean.output\n'
        '        )\n'
        '\n'
        '    def certify(self, problem, target):\n'
        '        if not self.require_lean:\n'
        '            return self._z3(problem, target)\n'
        '        try:\n'
        '            asyncio.get_running_loop()\n'
        '        except RuntimeError:\n'
        '            return asyncio.run(self.certify_async(problem, target))\n'
        '        raise RuntimeError("An event loop is running; await barrier.certify_async instead")\n'
    ),
    ('nextorch/formal/lean_bridge.py',
        '"""Asynchronous Lean 4 checking of a restricted propositional proof language.\n'
        '\n'
        'Only generated Bool/Prop deduction statements and a small, kernel-checked tactic\n'
        'subset are admitted. Arbitrary Lean metaprograms are not safe to execute; this\n'
        'API deliberately does not run user-supplied Lean files/imports or a permissive REPL.\n'
        'Every check uses a fresh process, a hard timeout and checks #print axioms.\n'
        '"""\n'
        '\n'
        'import asyncio\n'
        'import os\n'
        'import re\n'
        'import shutil\n'
        'import tempfile\n'
        'from dataclasses import dataclass\n'
        'from pathlib import Path\n'
        '\n'
        'from .barrier import LogicalProblem\n'
        '\n'
        '\n'
        '@dataclass(frozen=True)\n'
        'class LeanResult:\n'
        '    status: str\n'
        '    output: str = ""\n'
        '\n'
        '    @property\n'
        '    def valid(self):\n'
        '        return self.status == "valid"\n'
        '\n'
        '\n'
        'class LeanBridge:\n'
        '    def __init__(self, executable=None, timeout=10.0):\n'
        '        self.executable = executable or os.environ.get("NEXTORCH_LEAN") or shutil.which("lean")\n'
        '        self.timeout = timeout\n'
        '        if timeout <= 0:\n'
        '            raise ValueError("Lean timeout must be positive")\n'
        '\n'
        '    @staticmethod\n'
        '    def _source(problem: LogicalProblem, target: int, proof: str):\n'
        '        if type(target) is not int or target < 0:\n'
        '            raise ValueError("Invalid proposition index")\n'
        '        # Restriction is an allowlist of proof tokens, not a blacklist for arbitrary Lean.\n'
        '        tokens = re.findall(r"[A-Za-z_][A-Za-z_0-9]*|[()·;,.]|\\s+", proof)\n'
        '        if "".join(tokens) != proof:\n'
        '            raise ValueError("Proof contains syntax outside the supported tactic subset")\n'
        '        identifiers = re.findall(r"[A-Za-z_][A-Za-z_0-9]*", proof)\n'
        '        allowed = {\n'
        '            "by",\n'
        '            "exact",\n'
        '            "apply",\n'
        '            "assumption",\n'
        '            "intro",\n'
        '            "intros",\n'
        '            "constructor",\n'
        '            "first",\n'
        '            "rfl",\n'
        '            "hp",\n'
        '        } | {f"h{i}" for i in range(len(problem.premises))}\n'
        '        if not identifiers or identifiers[0] != "by" or any(i not in allowed for i in identifiers):\n'
        '            raise ValueError(\n'
        '                "Unsupported tactic/identifier; axioms, sorry and metaprograms are forbidden"\n'
        '            )\n'
        '        props = sorted({problem.source, target, *(i for e in problem.premises for i in e)})\n'
        '        binders = " ".join(f"(P{i} : Prop)" for i in props)\n'
        '        hypotheses = " ".join(f"(h{i} : P{a} → P{b})" for i, (a, b) in enumerate(problem.premises))\n'
        '        return (\n'
        '            f"set_option maxHeartbeats 100000\\n"\n'
        '            f"theorem nextorch_checked {binders} {hypotheses} (hp : P{problem.source}) "\n'
        '            f": P{target} := {proof}\\n#print axioms nextorch_checked\\n"\n'
        '        )\n'
        '\n'
        '    async def verify(self, problem, target, proof):\n'
        '        try:\n'
        '            source = self._source(problem, target, proof)\n'
        '        except ValueError as exc:\n'
        '            return LeanResult("rejected", str(exc))\n'
        '        if not self.executable:\n'
        '            return LeanResult("unavailable", "Lean 4 executable not found; configure NEXTORCH_LEAN")\n'
        '        with tempfile.TemporaryDirectory(prefix="nextorch-lean-") as directory:\n'
        '            path = Path(directory) / "Proof.lean"\n'
        '            path.write_text(source, encoding="utf-8")\n'
        '            try:\n'
        '                process = await asyncio.create_subprocess_exec(\n'
        '                    self.executable,\n'
        '                    str(path),\n'
        '                    cwd=directory,\n'
        '                    stdout=asyncio.subprocess.PIPE,\n'
        '                    stderr=asyncio.subprocess.STDOUT,\n'
        '                )\n'
        '            except OSError as exc:\n'
        '                return LeanResult("unavailable", str(exc))\n'
        '            try:\n'
        '                output, _ = await asyncio.wait_for(process.communicate(), self.timeout)\n'
        '            except (asyncio.TimeoutError, asyncio.CancelledError) as exc:\n'
        '                process.kill()\n'
        '                await process.wait()\n'
        '                if isinstance(exc, asyncio.CancelledError):\n'
        '                    raise\n'
        '                return LeanResult("timeout", "Lean check exceeded its time budget")\n'
        '            text = output.decode("utf-8", errors="replace")\n'
        '            clean = "does not depend on any axioms" in text\n'
        '            # Unused-premise warnings are benign; kernel errors and extra axioms still reject.\n'
        '            if process.returncode == 0 and clean:\n'
        '                return LeanResult("valid", text)\n'
        '            return LeanResult("invalid", text)\n'
        '\n'
        '    async def verify_deduction(self, problem, target):\n'
        '        # Construct a proof term by explicit implication application along a BFS path.\n'
        '        terms, queue = {problem.source: "hp"}, [problem.source]\n'
        '        while queue:\n'
        '            src = queue.pop(0)\n'
        '            for i, (a, b) in enumerate(problem.premises):\n'
        '                if a == src and b not in terms:\n'
        '                    terms[b] = f"(h{i} {terms[a]})"\n'
        '                    queue.append(b)\n'
        '        if target not in terms:\n'
        '            return LeanResult("invalid", "No implication path from source to target")\n'
        '        return await self.verify(problem, target, "by exact " + terms[target])\n'
    ),
    ('nextorch/formal/z3_gateway.py',
        '"""Proof by refutation, with consistency checks and fail-closed solver outcomes."""\n'
        '\n'
        'import hashlib\n'
        'import json\n'
        'from dataclasses import dataclass\n'
        '\n'
        'import z3\n'
        '\n'
        '\n'
        '@dataclass(frozen=True)\n'
        'class VerificationResult:\n'
        '    status: str\n'
        '    statement: str\n'
        '    proof: str = ""\n'
        '    counterexample: str = ""\n'
        '    reason: str = ""\n'
        '\n'
        '    @property\n'
        '    def valid(self):\n'
        '        return self.status == "valid"\n'
        '\n'
        '    @property\n'
        '    def digest(self):\n'
        '        return hashlib.sha256(\n'
        '            json.dumps([self.status, self.statement, self.proof], ensure_ascii=True).encode()\n'
        '        ).hexdigest()\n'
        '\n'
        '\n'
        'class FormalVerificationGateway:\n'
        '    @staticmethod\n'
        '    def prove(axioms, claim, timeout_ms=2000):\n'
        '        if timeout_ms <= 0 or not z3.is_bool(claim) or not all(z3.is_bool(a) for a in axioms):\n'
        '            raise ValueError("Boolean axioms/claim and positive timeout required")\n'
        '        context = z3.Context(proof=True)\n'
        '        solver = z3.Solver(ctx=context)\n'
        '        solver.set(timeout=timeout_ms)\n'
        '        for axiom in axioms:\n'
        '            solver.add(axiom.translate(context))\n'
        '        statement = solver.sexpr() + "\\nCLAIM " + claim.sexpr()\n'
        '        base = solver.check()\n'
        '        if base == z3.unsat:\n'
        '            return VerificationResult("inconsistent", statement, reason="Premises are inconsistent")\n'
        '        if base == z3.unknown:\n'
        '            return VerificationResult("unknown", statement, reason=solver.reason_unknown())\n'
        '        solver.add(z3.Not(claim.translate(context)))\n'
        '        result = solver.check()\n'
        '        if result == z3.unsat:\n'
        '            return VerificationResult("valid", statement, proof=solver.proof().sexpr())\n'
        '        if result == z3.sat:\n'
        '            return VerificationResult(\n'
        '                "counterexample", statement, counterexample=str(solver.model())\n'
        '            )\n'
        '        return VerificationResult("unknown", statement, reason=solver.reason_unknown())\n'
        '\n'
        '    @staticmethod\n'
        '    def certify_deduction(premises, query_src, query_target, timeout_ms=2000):\n'
        '        indices = [query_src, query_target] + [i for edge in premises for i in edge]\n'
        '        if any(type(i) is not int or i < 0 for i in indices):\n'
        '            raise ValueError("Proposition indices must be nonnegative integers")\n'
        '        context = z3.Context()\n'
        '        variables = {i: z3.Bool(f"P_{i}", ctx=context) for i in set(indices)}\n'
        '        axioms = [variables[query_src]]\n'
        '        axioms.extend(z3.Implies(variables[a], variables[b]) for a, b in premises)\n'
        '        return FormalVerificationGateway.prove(axioms, variables[query_target], timeout_ms)\n'
        '\n'
        '    @staticmethod\n'
        '    def verify_deduction(premises, query_src, query_target):\n'
        '        return FormalVerificationGateway.certify_deduction(premises, query_src, query_target).valid\n'
        '\n'
        '\n'
        'Z3Gateway = FormalVerificationGateway\n'
    ),
