    ('nextorch/verifier/curvature.py',
        '"""Matrix-free Hessian diagnostics. The caller supplies a scalar differentiable loss."""\n'
        '\n'
        'import torch\n'
        '\n'
        '\n'
        'def _hvp(loss, parameters):\n'
        '    params = tuple(p for p in parameters if p.requires_grad)\n'
        '    if loss.ndim != 0 or not params:\n'
        '        raise ValueError("Need a scalar loss and trainable parameters")\n'
        '    grads = torch.autograd.grad(loss, params, create_graph=True, allow_unused=True)\n'
        '\n'
        '    def product(vectors):\n'
        '        terms = [(g * v).sum() for g, v in zip(grads, vectors) if g is not None and g.requires_grad]\n'
        '        if not terms:\n'
        '            return tuple(torch.zeros_like(p) for p in params)\n'
        '        second = torch.autograd.grad(sum(terms), params, retain_graph=True, allow_unused=True)\n'
        '        return tuple(torch.zeros_like(p) if h is None else h for h, p in zip(second, params))\n'
        '\n'
        '    return params, product\n'
        '\n'
        '\n'
        'def hutchinson_trace(loss, parameters, samples=16, seed=42):\n'
        '    if samples <= 0:\n'
        '        raise ValueError("samples must be positive")\n'
        '    params, product = _hvp(loss, parameters)\n'
        '    generator = torch.Generator(device=params[0].device).manual_seed(seed)\n'
        '    values = []\n'
        '    for _ in range(samples):\n'
        '        vectors = [\n'
        '            torch.randint(0, 2, p.shape, generator=generator, device=p.device).to(p.dtype) * 2 - 1\n'
        '            for p in params\n'
        '        ]\n'
        '        values.append(sum((v * h).sum() for v, h in zip(vectors, product(vectors))))\n'
        '    return float(torch.stack(values).mean())\n'
        '\n'
        '\n'
        'def dominant_hessian_eigenvalue(loss, parameters, iterations=20):\n'
        '    if iterations <= 0:\n'
        '        raise ValueError("iterations must be positive")\n'
        '    params, product = _hvp(loss, parameters)\n'
        '    vectors = [torch.randn_like(p) for p in params]\n'
        '    norm = torch.sqrt(sum(v.square().sum() for v in vectors)).clamp_min(1e-12)\n'
        '    vectors = [v / norm for v in vectors]\n'
        '    value = torch.zeros((), device=params[0].device)\n'
        '    for _ in range(iterations):\n'
        '        hv = product(vectors)\n'
        '        value = sum((v * h).sum() for v, h in zip(vectors, hv))\n'
        '        norm = torch.sqrt(sum(h.square().sum() for h in hv))\n'
        '        if norm < 1e-12:\n'
        '            return 0.0\n'
        '        vectors = [h.detach() / norm.detach() for h in hv]\n'
        '    return float(value)\n'
    ),
