        "    def adicionar(valor: Fraction, pais: tuple[tuple[int, Fraction], ...]=(), variavel='') -> int:\n"
        '        if len(fita) >= LIMITE:\n'
        "            raise ErroOmega(f'Grafo de diferenciação excede {LIMITE} nós')\n"
        '        fita.append(No(valor, pais, variavel))\n'
        '        return len(fita)-1\n'
