    ('omega/certified_proof.py',
        '"""Shared admission for proofs rendered from validated data by this package.\n'
        '\n'
        'This is a trusted renderer boundary, not an API for accepting untrusted Lean.\n'
        '"""\n'
        'import hashlib\n'
        'import os\n'
        'from pathlib import Path\n'
        'import tempfile\n'
        '\n'
        'from omega_platform.budget import PROOF_BUDGET\n'
        'from omega_platform.sandbox import trusted\n'
        'from omega_selfhost.axiom_policy import DEFAULT, forbid_admissions\n'
        'from omega_selfhost.proof import lake_binary\n'
        '\n'
        '\n'
        'def rational_literal(value):\n'
        '    from fractions import Fraction\n'
        '    q = Fraction(value)\n'
        "    return f'(({q.numerator} : ℚ) / {q.denominator})'\n"
        '\n'
        '\n'
        'def check(source, declarations):\n'
        '    """Require kernel success and an explicit allowed-axiom report per theorem."""\n'
        '    import re\n'
        '    forbid_admissions(source)\n'
        '    if not declarations or len(set(declarations)) != len(declarations):\n'
        "        raise ValueError('Nonempty unique theorem names required')\n"
        "    root = Path(os.environ.get('OMEGA_TENSOR_PROJECT', str(Path(__file__).resolve().parents[1] / 'formal/tensor')))\n"
        "    with tempfile.TemporaryDirectory(prefix='omega-certified-') as tmp:\n"
        "        path = Path(tmp) / 'Certificate.lean'\n"
        '        path.write_text(source)\n'
        "        result = trusted([str(lake_binary()), 'env', 'lean', str(path)],\n"
        '                         cwd=root, budget=PROOF_BUDGET)\n'
        '    output = result.stdout + result.stderr\n'
        "    if not result.ok or 'warning:' in output:\n"
        "        diagnostics = output if len(output) <= 10000 else output[:4000] + '\\n...\\n' + output[-6000:]\n"
        "        raise ValueError('Lean rejected certificate: ' + diagnostics)\n"
        '    reports = {}\n'
        '    for name, body in re.findall(r"\'([^\']+)\' depends on axioms: \\[([^\\]]*)\\]", output):\n'
        "        reports[name] = {s.strip() for s in body.split(',') if s.strip()}\n"
        '    for name in re.findall(r"\'([^\']+)\' does not depend on any axioms", output):\n'
        '        reports[name] = set()\n'
        '    if any(name not in reports or not reports[name] <= DEFAULT for name in declarations):\n'
        "        raise ValueError('Missing or unauthorized theorem dependencies')\n"
        "    return {'checker': 'Lean 4.19.0', 'source_sha256': hashlib.sha256(source.encode()).hexdigest(),\n"
        "            'theorems': list(declarations), 'axioms': {n: sorted(reports[n]) for n in declarations}}\n"
    ),
    ('omega/certify.py',
        '"""Explicit opt-in PyTorch FX -> exact rational Omega -> GMP + Lean export."""\n'
        'import copy\n'
        'from fractions import Fraction\n'
        'import json\n'
        'from pathlib import Path\n'
        '\n'
        'from .certified_graph import evaluate, omega_source, validate\n'
        'from .pci import issue\n'
        '\n'
        '\n'
        'def trace(model, example_inputs):\n'
        '    from .transformer import trace_model\n'
        '    return trace_model(model, example_inputs)\n'
        '\n'
        '\n'
        'def export(model, example_inputs, directory, *, input_bounds, output_bounds,\n'
        "           signing_key, nonce, static=True, target='critical-system', max_error=None,\n"
        '           precision_bits=32):\n'
        '    graph = trace(model, example_inputs)\n'
        '    inputs = [Fraction(float(x)) for x in example_inputs.detach().cpu().reshape(-1)]\n'
        '    from .certified_graph import real_operations\n'
        '    if real_operations(graph):\n'
        '        from .transformer_certificate import export_real\n'
        '        if max_error is None:\n'
        "            raise ValueError('Real operations require an explicit max_error contract')\n"
        "        graph['precision_bits'] = precision_bits\n"
        '        return export_real(graph, inputs, directory, input_bounds=input_bounds,\n'
        '                           output_bounds=output_bounds, signing_key=signing_key, nonce=nonce,\n'
        '                           static=static, target=target, max_error=max_error)\n'
        '    certificate = issue(graph, inputs, input_bounds=input_bounds, output_bounds=output_bounds,\n'
        '                        signing_key=signing_key, nonce=nonce, context=target)\n'
        '    root = Path(directory).absolute()\n'
        '    root.mkdir(parents=True, exist_ok=False)\n'
        "    source = root / 'model.omega'\n"
        '    source.write_text(omega_source(graph, inputs))\n'
        '    from omega_selfhost.driver import build, run\n'
        "    binary = root / 'model'\n"
        '    build(source, binary, static=static)\n'
        '    result, admission = run(binary)\n'
        '    # Native outputs have the same order as mostrar statements.\n'
        '    expected = [str(x) for x in evaluate(graph, inputs)]\n'
        "    observed = [str(Fraction(result['values'][f'x{ref}'])) for ref in graph['outputs']]\n"
        '    if observed != expected:\n'
        "        raise ValueError('Native execution disagrees with exact FX graph')\n"
        '    import hashlib\n'
        '    artifacts = {name: hashlib.sha256((root / name).read_bytes()).hexdigest()\n'
        "                                for name in ('model.omega', 'model.c', 'model')}\n"
        '    # Artifact provenance is separately signed; core PCI remains independently portable.\n'
        '    from omega_selfhost.proof_protocol import encode\n'
        "    bundle = {'pci': certificate, 'artifacts': artifacts,\n"
        "              'artifact_signature': signing_key.sign(encode({'pci_sha256': hashlib.sha256(encode(certificate)).hexdigest(),\n"
        "                                                           'artifacts': artifacts})).hex()}\n"
        "    (root / 'bounds.lean').write_text(certificate['proof'])\n"
        "    (root / 'execution.lean').write_text(certificate['execution_proof'])\n"
        "    (root / 'certificate.json').write_text(json.dumps(bundle, sort_keys=True, indent=2) + '\\n')\n"
        "    (root / 'native-result.json').write_text(json.dumps(result, sort_keys=True, indent=2) + '\\n')\n"
        "    return {'directory': str(root), 'outputs': expected, 'native_admission': admission,\n"
        "            'certificate': certificate, 'static': static,\n"
        "            'scope': 'exact reinterpretation of frozen float weights; this input binary; universal box bounds'}\n"
        '\n'
        '\n'
        "def certify(*, target='critical-system', precision='exact-rational'):\n"
        "    if precision not in ('exact-rational', 'certified-rational') or type(target) is not str or not target:\n"
        "        raise ValueError('A named target and an explicit rational precision mode are required')\n"
        '    def decorate(cls):\n'
        "        if hasattr(cls, 'export_certified'):\n"
        "            raise ValueError('export_certified already exists')\n"
        '        def export_certified(self, example_inputs, directory, **kwargs):\n'
        "            if precision == 'exact-rational' and kwargs.get('max_error') is not None:\n"
        '                raise ValueError(\'Use precision="certified-rational" to permit transcendental approximation\')\n'
        '            return export(self, example_inputs, directory, target=target, **kwargs)\n'
        '        cls.export_certified = export_certified\n'
        '        return cls\n'
        '    return decorate\n'
    ),
