        '\n'
        'def serializar_estado(estado: dict[str, Fraction]) -> dict[str, str]:\n'
        '    return {nome: str(valor) for nome, valor in sorted(estado.items())}\n'
        '\n'
        '\n'
        '\n'
        '\n'
        'class MaquinaOmega:\n'
        '    def __init__(self):\n'
        '        self.parametros: dict[str, Fraction] = {}\n'
