        '            if c.nome in self.parametros:\n'
        '                self.saidas.append(f"{c.nome} = {self.parametros[c.nome]}")\n'
        '                return\n'
        '            if c.nome in self.perdas:\n'
        '                _, p = self.perda(c.nome)\n'
        '                self.saidas.append(f"{c.nome} = {p.avaliar(self.parametros)}")\n'
        '                return\n'
