        '        raise ProvaInvalida("Número racional inválido") from erro\n'
        '\n'
        '\n'
        'def limpar(poly: dict) -> dict:\n'
        '    limpo = {m: c for m, c in poly.items() if c}\n'
        '    if len(limpo) > MONOMIOS_MAX:\n'
        '        raise ProvaInvalida("Limite de monômios excedido")\n'
        '    return limpo\n'
