        '\n'
        'def soma(a: dict, b: dict, fator: int = 1) -> dict:\n'
        '    out = dict(a)\n'
        '    for monomio, coeficiente in b.items():\n'
        '        out[monomio] = out.get(monomio, Fraction(0)) + fator * coeficiente\n'
        '    return limpar(out)\n'
        '\n'
        '\n'
        'def produto(a: dict, b: dict) -> dict:\n'
