        '\n'
        'def polinomio(ast: object, nivel: int = 0) -> dict:\n'
        '    if not isinstance(ast, dict) or nivel > PROFUNDIDADE_MAX:\n'
        '        raise ProvaInvalida("AST inválida ou profunda demais")\n'
