        '        raise ProvaInvalida("Expoente não inteiro")\n'
        '    return potencia(a, int(constante))\n'
        '\n'
        '\n'
        'def forma_normal(p: dict) -> list[dict]:\n'
        '    return [{"monomio": [[nome, grau] for nome, grau in monomio],\n'
        '             "coeficiente": str(coef)} for monomio, coef in sorted(p.items())]\n'
        '\n'
        '\n'
        'def derivada(p: dict, variavel: str) -> dict:\n'
        '    out: dict = {}\n'
        '    for monomio, coef in p.items():\n'
        '        expoentes = dict(monomio)\n'
        '        grau = expoentes.get(variavel, 0)\n'
