        '            return False\n'
        '        tipo = cert.get("tipo")\n'
        '        if tipo == "expansao_tensor":\n'
        '            from .nucleo_tensor import validar_expansao\n'
        '            return validar_expansao(cert)\n'
        '        if tipo == "identidade_tensorial":\n'
        '            from .nucleo_tensor import validar_identidade_tensorial\n'
        '            return validar_identidade_tensorial(cert)\n'
        '        if tipo == "gradiente_tensor":\n'
        '            from .nucleo_parametros import validar_gradiente_tensor\n'
        '            return validar_gradiente_tensor(cert)\n'
        '        if tipo == "passo_tensor":\n'
        '            from .nucleo_parametros import validar_passo_tensor\n'
        '            return validar_passo_tensor(cert)\n'
        '        if tipo == "retropropagacao":\n'
        '            p = polinomio(cert["expressao"])\n'
        '            estado = ler_estado(cert["estado"])\n'
        '            resultados = cert["resultados"]\n'
        '            return (isinstance(resultados, dict) and\n'
        '                    set(resultados) == set(estado) and\n'
        '                    all(isinstance(resultados[x], str) and\n'
        '                        resultados[x] == str(avaliar(derivada(p, x), estado))\n'
        '                        for x in estado))\n'
