        "        if args.mode=='synthesize-native':\n"
        '            from omega_coder.native_synthesis import run\n'
        '            return run(problem,args.saida,max_nodes=args.max_size,max_candidates=args.max_candidates)\n'
        '        return solve(args.mode,problem,args.max_candidates,args.max_size)\n'
        "    result=attempt('agent',operation)\n"
