    ('omega_agent_sandbox/actions.py',
        '"""Turn an action intent into code, a Hoare obligation and a pinned snapshot."""\n'
        'import hashlib\n'
        'import json\n'
        'from omega_refine_check.syntax import parse,rational,evaluate,substitute,render,identifier\n'
        'from omega_refine_check.contracts import verify_contract\n'
        'from omega_selfhost.proof_protocol import encode\n'
        'from .policy import Policy\n'
        '\n'
        '\n'
        'def _and(predicates):\n'
        "    result=('true',)\n"
        "    for p in predicates:result=('and',result,p)\n"
        '    return result\n'
        '\n'
        '\n'
        'def plan(policy,state,proposal):\n'
        "    if type(policy) is not Policy:raise TypeError('Immutable host policy required')\n"
        '    data=policy.data\n'
        "    if type(state) is not dict or set(state)!={'version','values'} or type(state['version']) is not int or state['version']<0 or set(state['values'])!=set(data['state']):raise ValueError('Invalid state snapshot')\n"
        "    if type(proposal) is not dict or set(proposal)!={'action','parameters','nonce','expected_version'}:raise ValueError('Unknown action proposal')\n"
        "    if type(proposal['expected_version']) is not int or proposal['expected_version']!=state['version']:raise ValueError('Stale action proposal')\n"
        "    identifier(proposal['action'])\n"
        "    if type(proposal['nonce']) is not str or not 1<=len(proposal['nonce'])<=128 or any(ord(c)<32 for c in proposal['nonce']):raise ValueError('Bounded action nonce required')\n"
        "    if proposal['action'] not in data['actions']:raise PermissionError('Action is not admitted by the policy')\n"
        "    action=data['actions'][proposal['action']]\n"
        "    if type(proposal['parameters']) is not dict or set(proposal['parameters'])!=set(action['parameters']):raise ValueError('Action parameter mismatch')\n"
        "    values={k:rational(state['values'][k]) for k in data['state']}\n"
        "    params={k:rational(proposal['parameters'][k]) for k in action['parameters']}\n"
        '    env={**values,**params}\n'
        "    for name,predicate in {**data['state'],**action['parameters']}.items():\n"
        "        if evaluate(parse(predicate),{**env,'self':env[name]}) is not True:raise ValueError('State or parameter invariant violated')\n"
        "    if any(evaluate(parse(p),env) is not True for p in action['requires']):raise ValueError('Action precondition is false')\n"
        "    updates={name:parse(expr) for name,expr in action['updates'].items()}\n"
        '    after={name:evaluate(expr,env) for name,expr in updates.items()}\n'
        "    if any(evaluate(parse(predicate),{**after,'self':after[name]}) is not True for name,predicate in data['state'].items()):raise ValueError('Action would violate a state invariant')\n"
        "    post=[substitute(parse(predicate),{'self':updates[name],**updates}) for name,predicate in data['state'].items()]\n"
        "    variables={**data['state'],**action['parameters']}\n"
        "    expression=('vector',tuple(updates.values()))\n"
        "    statement={'policy_sha256':policy.sha256,'state':{'version':state['version'],'values':{k:str(v) for k,v in values.items()}},\n"
        "               'proposal':{**proposal,'parameters':{k:str(v) for k,v in params.items()}},\n"
        "               'post_state':{'version':state['version']+1,'values':{k:str(v) for k,v in after.items()}},'effect':action['effect']}\n"
        '    source=\'\\n\'.join(f\'parametro {name}={render(("const",str(value)))};\' for name,value in env.items())+\'\\n\'\n'
        "    for i,(name,expr) in enumerate(updates.items()):source+=f'tensor after_{i}={render(expr)};\\nmostrar after_{i};\\n'\n"
        "    return statement,source,variables,expression,_and(post),action['requires']\n"
        '\n'
        '\n'
        'def prepare(policy,state,proposal,*,signing_key):\n'
        '    statement,program,variables,expression,post,requires=plan(policy,state,proposal)\n'
        '    proof=verify_contract(variables,expression,post,requires=requires)\n'
        "    payload={'format':'omega-action-pcc-1','statement':statement,\n"
        "             'program_sha256':hashlib.sha256(program.encode()).hexdigest(),\n"
        "             'proof_sha256':hashlib.sha256(proof['source'].encode()).hexdigest()}\n"
        '    subject=hashlib.sha256(encode(payload)).hexdigest()\n'
        "    return {'payload':payload,'subject':subject,'program':program,'proof':proof['source'],\n"
        "            'admission':proof['admission'],'signature':signing_key.sign(encode(payload)).hex()}\n"
    ),
    ('omega_agent_sandbox/adapters.py',
        '"""Host-supplied effects. Tests and demos use Recorder, never actual actuators."""\n'
        'from dataclasses import dataclass\n'
        'from threading import RLock\n'
        'from urllib.parse import urlsplit\n'
        'import json\n'
        '\n'
        '\n'
        'class Recorder:\n'
        '    def __init__(self):self.receipts={};self.lock=RLock()\n'
        '    def dispatch(self,statement,*,idempotency_key):\n'
        '        with self.lock:\n'
        '            if idempotency_key in self.receipts:return self.receipts[idempotency_key]\n'
        "            receipt={'acknowledged':True,'idempotency_key':idempotency_key,'effect':statement['effect'],\n"
        "                     'parameters':statement['proposal']['parameters']}\n"
        '            self.receipts[idempotency_key]=receipt\n'
        '            return receipt\n'
        '\n'
        '\n'
        'class CallbackAdapter:\n'
        '    def __init__(self,callback):\n'
        "        if not callable(callback):raise TypeError('Host driver callback required')\n"
        '        self.callback=callback\n'
        '    def dispatch(self,statement,*,idempotency_key):\n'
        "        return self.callback(statement['proposal']['parameters'],idempotency_key=idempotency_key)\n"
        '\n'
        '\n'
        'class HTTPSAdapter:\n'
        '    def __init__(self,url,*,allowed_hosts,headers=None,timeout=5):\n'
        '        parsed=urlsplit(url)\n'
        "        if parsed.scheme!='https' or parsed.hostname not in allowed_hosts or parsed.username or parsed.password or parsed.fragment:\n"
        "            raise ValueError('Explicit HTTPS host allowlist and credential-free URL required')\n"
        "        if type(timeout) not in (int,float) or not 0<timeout<=30:raise ValueError('Bounded HTTPS timeout required')\n"
        '        self.url=url;self.headers=dict(headers or {});self.timeout=timeout\n'
        '    def dispatch(self,statement,*,idempotency_key):\n'
        '        import urllib.request\n'
        '        class NoRedirect(urllib.request.HTTPRedirectHandler):\n'
        "            def redirect_request(self,*args,**kwargs):raise PermissionError('Action redirects are refused')\n"
        "        body=json.dumps(statement['proposal']['parameters'],sort_keys=True).encode()\n"
        "        headers={**self.headers,'Content-Type':'application/json','Idempotency-Key':idempotency_key}\n"
        "        request=urllib.request.Request(self.url,data=body,headers=headers,method='POST')\n"
        '        with urllib.request.build_opener(NoRedirect()).open(request,timeout=self.timeout) as response:\n'
        '            data=response.read(65537)\n'
        "            if len(data)>65536:raise ValueError('Action response byte budget exceeded')\n"
        "            return {'acknowledged':200<=response.status<300,'status':response.status,'idempotency_key':idempotency_key,\n"
        "                    'response_sha256':__import__('hashlib').sha256(data).hexdigest()}\n"
    ),
