    ('omega_agent_sandbox/ledger.py',
        '"""Durable state/version CAS and exactly-once dispatch reservations.\n'
        '\n'
        'An external effect and SQLite cannot form one general atomic transaction.\n'
        'Uncertain outcomes remain locked for explicit host reconciliation, never retry.\n'
        '"""\n'
        'import json\n'
        'from pathlib import Path\n'
        'import sqlite3\n'
        'import hashlib\n'
        'from omega_selfhost.proof_protocol import encode\n'
        '\n'
        '\n'
        'class Ledger:\n'
        '    def __init__(self,path):\n'
        '        self.path=Path(path)\n'
        "        if self.path.is_symlink():raise ValueError('Symlinked ledgers are refused')\n"
        '        self.path.parent.mkdir(parents=True,exist_ok=True)\n'
        '        with self.connect() as db:\n'
        "            db.executescript('CREATE TABLE IF NOT EXISTS states (domain TEXT PRIMARY KEY, version INTEGER NOT NULL, body TEXT NOT NULL, busy TEXT);'\n"
        "                             'CREATE TABLE IF NOT EXISTS operations (subject TEXT PRIMARY KEY, domain TEXT NOT NULL, nonce TEXT NOT NULL, status TEXT NOT NULL, body TEXT NOT NULL, receipt TEXT, UNIQUE(domain,nonce));')\n"
        '    def connect(self):\n'
        "        db=sqlite3.connect(self.path,timeout=10,isolation_level=None);db.execute('PRAGMA journal_mode=WAL');db.execute('PRAGMA synchronous=FULL');return db\n"
        '    def initialize(self,domain,values):\n'
        '        from omega_refine_check.syntax import identifier,rational\n'
        '        identifier(domain);normalized={k:str(rational(v)) for k,v in values.items()}\n'
        '        with self.connect() as db:\n'
        "            db.execute('INSERT INTO states VALUES (?,?,?,NULL)',(domain,0,encode(normalized).decode()))\n"
        '    def snapshot(self,domain):\n'
        "        with self.connect() as db:row=db.execute('SELECT version,body,busy FROM states WHERE domain=?',(domain,)).fetchone()\n"
        "        if row is None:raise ValueError('Unknown state domain')\n"
        "        if row[2] is not None:raise RuntimeError('Domain has an unresolved external action')\n"
        "        return {'version':row[0],'values':json.loads(row[1])}\n"
        '    def claim(self,domain,subject,statement):\n'
        '        with self.connect() as db:\n'
        '            try:\n'
        "                db.execute('BEGIN IMMEDIATE')\n"
        "                row=db.execute('SELECT version,body,busy FROM states WHERE domain=?',(domain,)).fetchone()\n"
        "                if row is None or row[2] is not None or row[0]!=statement['state']['version'] or json.loads(row[1])!=statement['state']['values']:raise ValueError('Action snapshot is stale or already reserved')\n"
        "                db.execute('INSERT INTO operations VALUES (?,?,?,?,?,NULL)',(subject,domain,statement['proposal']['nonce'],'reserved',encode(statement).decode()))\n"
        "                db.execute('UPDATE states SET busy=? WHERE domain=?',(subject,domain));db.execute('COMMIT')\n"
        '            except BaseException:\n'
        "                if db.in_transaction:db.execute('ROLLBACK')\n"
        '                raise\n'
        '    def finish(self,domain,subject,statement,receipt):\n'
        '        raw=encode(receipt)\n'
        "        if len(raw)>65536:raise ValueError('External receipt exceeds budget')\n"
        '        with self.connect() as db:\n'
        '            try:\n'
        "                db.execute('BEGIN IMMEDIATE')\n"
        "                row=db.execute('SELECT busy FROM states WHERE domain=?',(domain,)).fetchone()\n"
        "                if row!=(subject,):raise ValueError('Dispatch reservation changed')\n"
        "                post=statement['post_state']\n"
        "                db.execute('UPDATE states SET version=?,body=?,busy=NULL WHERE domain=?',(post['version'],encode(post['values']).decode(),domain))\n"
        "                db.execute('UPDATE operations SET status=?,receipt=? WHERE subject=?',('completed',raw.decode(),subject));db.execute('COMMIT')\n"
        '            except BaseException:\n'
        "                if db.in_transaction:db.execute('ROLLBACK')\n"
        '                raise\n'
        '    def uncertain(self,subject,error):\n'
        "        with self.connect() as db:db.execute('UPDATE operations SET status=?,receipt=? WHERE subject=?',('uncertain',str(error)[:2000],subject))\n"
        '    def operation(self,subject):\n'
        "        with self.connect() as db:row=db.execute('SELECT status,receipt FROM operations WHERE subject=?',(subject,)).fetchone()\n"
        "        if row is None:raise ValueError('Unknown operation')\n"
        "        return {'status':row[0],'receipt':row[1]}\n"
    ),
    ('omega_agent_sandbox/policy.py',
        '"""Host-owned immutable transition policies, not prompts for the proposer."""\n'
        'from dataclasses import dataclass\n'
        'import json\n'
        'from omega_refine_check.syntax import parse,identifier\n'
        'from omega_selfhost.proof_protocol import encode\n'
        'import hashlib\n'
        '\n'
        '\n'
        '@dataclass(frozen=True)\n'
        'class Policy:\n'
        '    encoded:bytes\n'
        '    def __init__(self,data):\n'
        "        fields={'id','version','state','actions'}\n"
        "        if type(data) is not dict or set(data)!=fields or type(data['version']) is not int or data['version']<1:raise ValueError('Explicit versioned action policy required')\n"
        "        identifier(data['id'])\n"
        "        if type(data['state']) is not dict or not 1<=len(data['state'])<=32 or type(data['actions']) is not dict or not 1<=len(data['actions'])<=32:raise ValueError('Policy cardinality budget exceeded')\n"
        "        for name,predicate in data['state'].items():identifier(name);parse(predicate)\n"
        "        for name,action in data['actions'].items():\n"
        '            identifier(name)\n'
        "            if type(action) is not dict or set(action)!={'parameters','requires','updates','effect'}:raise ValueError('Unknown action policy fields')\n"
        "            identifier(action['effect'])\n"
        "            if type(action['parameters']) is not dict or len(action['parameters'])>16 or set(action['parameters'])&set(data['state']):raise ValueError('Invalid or shadowing action parameters')\n"
        "            for var,predicate in action['parameters'].items():identifier(var);parse(predicate)\n"
        "            if type(action['requires']) is not list or len(action['requires'])>32:raise ValueError('Bounded preconditions required')\n"
        "            for predicate in action['requires']:parse(predicate)\n"
        "            if set(action['updates'])!=set(data['state']):raise ValueError('Every state coordinate must have an explicit simultaneous update')\n"
        "            for expr in action['updates'].values():parse(expr)\n"
        '        raw=encode(data)\n'
        "        if len(raw)>65536:raise ValueError('Policy byte budget exceeded')\n"
        "        object.__setattr__(self,'encoded',raw)\n"
        '    @property\n'
        '    def data(self):return json.loads(self.encoded)\n'
        '    @property\n'
        '    def sha256(self):return hashlib.sha256(self.encoded).hexdigest()\n'
    ),
    ('omega_agent_sandbox/proofs.py',
        'import hashlib\n'
        'from .actions import prepare\n'
        'from omega_selfhost.proof_protocol import encode\n'
        '\n'
        '\n'
        'def verify(policy,state,bundle,*,public_key):\n'
        "    fields={'payload','subject','program','proof','admission','signature'}\n"
        "    if type(bundle) is not dict or set(bundle)!=fields:raise ValueError('Unknown proof-carrying action envelope')\n"
        "    if len(encode(bundle))>8*1024**2:raise ValueError('Action proof byte budget exceeded')\n"
        '    from cryptography.exceptions import InvalidSignature\n'
        "    try:public_key.verify(bytes.fromhex(bundle['signature']),encode(bundle['payload']))\n"
        "    except (InvalidSignature,TypeError,ValueError) as error:raise PermissionError('Invalid action signature') from error\n"
        "    if hashlib.sha256(encode(bundle['payload'])).hexdigest()!=bundle['subject']:raise ValueError('Action subject mismatch')\n"
        "    if bundle['payload']['statement']['policy_sha256']!=policy.sha256:raise ValueError('Unrelated policy proof')\n"
        '    class Capture:\n'
        '        def sign(self,raw):\n'
        "            if raw!=encode(bundle['payload']):raise ValueError('Action code, state or postcondition changed')\n"
        "            return bytes.fromhex(bundle['signature'])\n"
        "    expected=prepare(policy,state,bundle['payload']['statement']['proposal'],signing_key=Capture())\n"
        "    if any(expected[k]!=bundle[k] for k in ('program','proof','subject','payload')):raise ValueError('Changed action code or proof')\n"
        "    return expected['payload']['statement']\n"
    ),
    ('omega_agent_sandbox/runtime.py',
        '"""Admission and compilation finish before the registered external effect runs."""\n'
        'from pathlib import Path\n'
        'import tempfile\n'
        'from types import MappingProxyType\n'
        'from .proofs import verify\n'
        'from .policy import Policy\n'
        '\n'
        '\n'
        'class Runtime:\n'
        '    def __init__(self,policy,ledger,*,public_key,capability_verifier,principal,adapters):\n'
        "        if type(policy) is not Policy:raise TypeError('Host-owned immutable policy required')\n"
        "        if not hasattr(capability_verifier,'require'):raise TypeError('Independent signed capability verifier required')\n"
        '        self.policy=policy;self.ledger=ledger;self.public_key=public_key\n'
        '        self.verifier=capability_verifier;self.principal=principal;self.adapters=MappingProxyType(dict(adapters))\n'
        '    def dispatch(self,bundle,capability):\n'
        "        domain=self.policy.data['id'];snapshot=self.ledger.snapshot(domain)\n"
        '        statement=verify(self.policy,snapshot,bundle,public_key=self.public_key)\n'
        "        subject=bundle['subject'];effect=statement['effect']\n"
        "        if effect not in self.adapters:raise PermissionError('No host adapter is registered for this effect')\n"
        "        self.verifier.require(capability,self.principal,'agent.dispatch.'+effect,subject=subject)\n"
        '        # Never execute proposer-supplied code: the proof renderer already\n'
        '        # reconstructed this exact pure arithmetic program from policy data.\n'
        '        from omega_selfhost.driver import build,run\n'
        "        with tempfile.TemporaryDirectory(prefix='omega-proof-action-') as temporary:\n"
        "            root=Path(temporary);source=root/'action.omega';source.write_text(bundle['program'])\n"
        "            build(source,root/'action');result,admission=run(root/'action')\n"
        "            for i,(name,value) in enumerate(statement['post_state']['values'].items()):\n"
        '                from fractions import Fraction\n'
        "                if Fraction(result['values'][f'after_{i}'])!=Fraction(value):raise ValueError('Native action disagrees with its proved poststate')\n"
        '        # Recheck authorization after proof/build latency and reserve the state\n'
        '        # transactionally. No adapter has run before these gates.\n'
        "        self.verifier.require(capability,self.principal,'agent.dispatch.'+effect,subject=subject)\n"
        '        self.ledger.claim(domain,subject,statement)\n'
        '        try:\n'
        '            receipt=self.adapters[effect].dispatch(statement,idempotency_key=subject)\n'
        "            if type(receipt) is not dict or receipt.get('acknowledged') is not True or receipt.get('idempotency_key')!=subject:raise ValueError('External adapter did not acknowledge this exact action')\n"
        '            self.ledger.finish(domain,subject,statement,receipt)\n'
        '        except BaseException as error:\n'
        '            self.ledger.uncertain(subject,error);raise\n'
        "        return {'valid':True,'subject':subject,'post_state':statement['post_state'],'native_admission':admission,'receipt':receipt}\n"
    ),
