    ('omega_coder/ast_editor.py',
        '"""AST-span edits preserve every byte outside the selected Python node."""\n'
        'import ast,hashlib\n'
        'from pathlib import Path\n'
        'def replace_node(source,node,replacement,expected_sha256):\n'
        "    data=source.encode('utf-8')\n"
        "    if hashlib.sha256(data).hexdigest()!=expected_sha256:raise ValueError('Source changed before edit')\n"
        "    if not isinstance(node,(ast.expr,ast.stmt)) or node.end_lineno is None:raise ValueError('A located expression/statement is required')\n"
        "    parsed=ast.parse(replacement,mode='eval' if isinstance(node,ast.expr) else 'exec')\n"
        "    if isinstance(node,ast.stmt) and len(parsed.body)!=1:raise ValueError('Exactly one replacement statement required')\n"
        '    lines=data.splitlines(keepends=True)\n'
        '    start=sum(map(len,lines[:node.lineno-1]))+node.col_offset\n'
        '    end=sum(map(len,lines[:node.end_lineno-1]))+node.end_col_offset\n'
        "    indent=lines[node.lineno-1][:node.col_offset].decode('utf-8')\n"
        "    text=replacement.replace('\\n','\\n'+indent) if isinstance(node,ast.stmt) else replacement\n"
        '    result=data[:start]+text.encode()+data[end:]\n'
        '    ast.parse(result.decode())\n'
        '    return result.decode()\n'
        'def apply_in_worktree(path,content,capability,verifier,principal):\n'
        "    path=Path(path);verifier.require(capability,principal,'code.write',path=path)\n"
        "    if path.is_symlink():raise PermissionError('Cannot edit symlink')\n"
        '    from omega_security.filesystem import write\n'
        "    claim=verifier.require(capability,principal,'code.write',path=path)\n"
        "    root=Path(claim['root']).resolve(strict=True)\n"
        "    write(root,path.resolve().relative_to(root).as_posix(),content.encode('utf-8'))\n"
    ),
    ('omega_coder/change_plan.py',
        'from dataclasses import dataclass\n'
        'from pathlib import PurePosixPath\n'
        '@dataclass(frozen=True)\n'
        'class Change:\n'
        '    path: str\n'
        '    reason: str\n'
        '    depends_on: tuple[str,...]=()\n'
        '    def __post_init__(self):\n'
        '        path=PurePosixPath(self.path)\n'
        "        if path.is_absolute() or '..' in path.parts or not self.reason:raise ValueError('Unsafe/unjustified change')\n"
        'def plan(changes,index):\n'
        '    changes=tuple(changes);names={c.path for c in changes}\n'
        "    if len(names)!=len(changes):raise ValueError('Duplicate changed path')\n"
        '    done=set();ordered=[]\n'
        '    while len(done)<len(names):\n'
        '        ready=sorted((c for c in changes if c.path not in done and set(c.depends_on)<=done),key=lambda c:c.path)\n'
        "        if not ready:raise ValueError('Cyclic/missing change dependency')\n"
        '        for change in ready:done.add(change.path);ordered.append(change)\n'
        "    impacts={c.path:tuple(sorted(p for p,r in index.items() if c.path.replace('/','.') in str(r.get('imports',())))) for c in changes}\n"
        "    return {'changes':tuple(ordered),'potential_dependents':impacts}\n"
    ),
    ('omega_coder/contract_synthesis.py',
        '"""Bounded scalar synthesis over exact finite observations, never a proof.\n'
        '\n'
        'Only data expressions (+, -, *) are enumerated. No generated Python or Omega\n'
        'source executes here. Native execution belongs to the isolated workflow.\n'
        '"""\n'
        'from fractions import Fraction\n'
        'from itertools import product\n'
        'import re\n'
        '\n'
        'MAX_VARIABLES = 32\n'
        'MAX_CONSTANTS = 64\n'
        'MAX_EXAMPLES = 256\n'
        'MAX_RATIONAL_BITS = 256\n'
        '\n'
        '\n'
        'def rational(value):\n'
        '    """Reject approximate/bool inputs and cap integers before arithmetic."""\n'
        '    if type(value) is str:\n'
        "        if len(value) > 160 or not re.fullmatch(r'-?[0-9]+(?:/[1-9][0-9]*)?', value):\n"
        "            raise ValueError('Exact integer or rational literal required')\n"
        '    elif type(value) not in (int, Fraction):\n'
        "        raise ValueError('Exact integer or rational required; floats/bools are ambiguous')\n"
        '    if type(value) is int and value.bit_length() > MAX_RATIONAL_BITS:\n'
        "        raise ValueError('Rational bit budget exceeded')\n"
        '    result = Fraction(value)\n'
        '    if max(result.numerator.bit_length(), result.denominator.bit_length()) > MAX_RATIONAL_BITS:\n'
        "        raise ValueError('Rational bit budget exceeded')\n"
        '    return result\n'
        '\n'
        '\n'
        'def variables_contract(variables):\n'
        '    if type(variables) not in (list, tuple) or len(variables) > MAX_VARIABLES:\n'
        "        raise ValueError('Bounded variable list required')\n"
        "    if any(type(v) is not str or not re.fullmatch(r'[A-Za-z_][A-Za-z_0-9]{0,63}', v)\n"
        '           for v in variables) or len(set(variables)) != len(variables):\n'
        "        raise ValueError('Unique scalar identifiers required')\n"
        '    return tuple(variables)\n'
        '\n'
        '\n'
        'def observations(variables, examples):\n'
        '    if type(examples) not in (list, tuple) or not 1 <= len(examples) <= MAX_EXAMPLES:\n'
        "        raise ValueError('Nonempty bounded finite observations required')\n"
        '    result = []\n'
        '    seen = set()\n'
        '    for example in examples:\n'
        '        if type(example) not in (list, tuple) or len(example) != 2:\n'
        "            raise ValueError('Observation must contain an environment and a target')\n"
        '        env, target = example\n'
        '        if type(env) is not dict or set(env) != set(variables):\n'
        "            raise ValueError('Observation variables do not match the contract')\n"
        '        normalized = {v: rational(env[v]) for v in variables}\n'
        '        key = tuple(normalized.values())\n'
        '        if key in seen:\n'
        "            raise ValueError('Duplicate observation inputs are not independent cases')\n"
        '        seen.add(key)\n'
        '        result.append((normalized, rational(target)))\n'
        '    return tuple(result)\n'
        '\n'
        '\n'
        'def _evaluate(expression, env):\n'
        "    if expression[0] == 'var':\n"
        '        return env[expression[1]]\n'
        "    if expression[0] == 'const':\n"
        '        return expression[1]\n'
        '    a, b = _evaluate(expression[1], env), _evaluate(expression[2], env)\n'
        "    if expression[0] == '+':\n"
        '        return a + b\n'
        "    if expression[0] == '-':\n"
        '        return a - b\n'
        '    return a * b\n'
        '\n'
        '\n'
        'def synthesize(variables, constants, examples, *, max_nodes=7, max_candidates=10000):\n'
        '    if type(max_nodes) is not int or not 1 <= max_nodes <= 31:\n'
        "        raise ValueError('Expression node budget must be in [1,31]')\n"
        '    if type(max_candidates) is not int or not 1 <= max_candidates <= 100000:\n'
        "        raise ValueError('Candidate budget must be in [1,100000]')\n"
        '    variables = variables_contract(variables)\n'
        '    if type(constants) not in (list, tuple) or len(constants) > MAX_CONSTANTS:\n'
        "        raise ValueError('Bounded constants required')\n"
        '    constants = tuple(dict.fromkeys(rational(c) for c in constants))\n'
        '    examples = observations(variables, examples)\n'
        "    atoms = [('var', v) for v in variables] + [('const', c) for c in constants]\n"
        '    if not atoms:\n'
        "        raise ValueError('At least one expression atom required')\n"
        '    levels = {}\n'
        '    checked = 0\n'
        '    for size in range(1, max_nodes + 1, 2):\n'
        '        level = []\n'
        '        levels[size] = level\n'
        '        if size == 1:\n'
        '            candidates = iter(atoms)\n'
        '        else:\n'
        '            candidates = (\n'
        '                (op, a, b)\n'
        '                for left in range(1, size - 1, 2)\n'
        "                for op, a, b in product(('+', '-', '*'), levels[left], levels[size - 1 - left])\n"
        '            )\n'
        '        for expression in candidates:\n'
        '            if checked == max_candidates:\n'
        '                return None\n'
        '            checked += 1\n'
        '            # Retain only examined candidates. The former implementation built\n'
        '            # whole products before applying the global candidate budget.\n'
        '            level.append(expression)\n'
        '            if all(_evaluate(expression, env) == target for env, target in examples):\n'
        "                return {'expression': expression, 'checked': checked, 'universal': False}\n"
        '    return None\n'
    ),
