    ('omega_coder/generation.py',
        '"""Generators return source data; executing it requires an isolated runner."""\n'
        'from dataclasses import dataclass\n'
        'import hashlib\n'
        "LANGUAGES=frozenset({'omega','python','c','lean'})\n"
        '@dataclass(frozen=True)\n'
        'class Candidate:\n'
        '    language: str\n'
        '    source: str\n'
        '    origin: str\n'
        '    def __post_init__(self):\n'
        "        if self.language not in LANGUAGES or len(self.source.encode())>1024*1024:raise ValueError('Invalid candidate')\n"
        '    @property\n'
        '    def sha256(self):return hashlib.sha256(self.source.encode()).hexdigest()\n'
        'def generate(specification,provider,language,limit=16):\n'
        "    if language not in LANGUAGES or not 1<=limit<=256:raise ValueError('Invalid generation request')\n"
        '    result=[];seen=set()\n'
        '    for text in provider(specification,language,limit):\n'
        '        if len(result)>=limit:break\n'
        '        candidate=Candidate(language,text,type(provider).__name__)\n'
        '        if candidate.sha256 not in seen:result.append(candidate);seen.add(candidate.sha256)\n'
        '    return tuple(result)\n'
    ),
    ('omega_coder/native_synthesis.py',
        '"""Executable finite coding workflow: search, native build, isolation and replay.\n'
        '\n'
        'Reserved observations are never mounted in the search worker. A failed reserved\n'
        'case rejects the first candidate; it does not initiate tuning against that set.\n'
        'The independent Lean kernel checks observed native computations, not universal\n'
        'correctness of a program inferred from examples or refinement of arbitrary C.\n'
        '"""\n'
        'from pathlib import Path\n'
        'from fractions import Fraction\n'
        'import hashlib\n'
        'import re\n'
        'import stat\n'
        'import sys\n'
        'import tempfile\n'
        '\n'
        'from omega_platform.budget import Budget\n'
        'from omega_platform.manifest import artifact_record\n'
        'from omega_platform.sandbox import run as isolated_run\n'
        'from omega_security.encoding import canonical, decode\n'
        'from .contract_synthesis import rational, variables_contract, observations, MAX_CONSTANTS\n'
        '\n'
        "FORMAT = 'omega-native-synthesis-1'\n"
        'MAX_BYTES = 1024 * 1024\n'
        'MAX_CASES = 64\n'
        'ARTIFACT_NAMES = frozenset({\n'
        "    'problem.json', 'search.json', 'candidate.json', 'program.omega', 'program',\n"
        "    'program.c', 'program.build.json', 'native-result.json',\n"
        "    'native-result.lean', 'native-result.verification.json', 'report.json',\n"
        '})\n'
        'SEARCH_BUDGET = Budget(wall_seconds=30, cpu_seconds=20)\n'
        '\n'
        '\n'
        'def _write(path, value):\n'
        "    with path.open('xb') as stream:\n"
        '        stream.write(canonical(value, max_bytes=16 * MAX_BYTES, max_nodes=500000))\n'
        '\n'
        '\n'
        'def _read(path, limit=MAX_BYTES):\n'
        '    if not stat.S_ISREG(path.lstat().st_mode):\n'
        "        raise ValueError('Regular synthesis artifact required; symlinks refused')\n"
        "    with path.open('rb') as stream:\n"
        '        data = stream.read(limit + 1)\n'
        '    if len(data) > limit:\n'
        "        raise ValueError('Synthesis artifact byte budget exceeded')\n"
        '    return data\n'
        '\n'
        '\n'
        'def _examples(variables, cases):\n'
        "    if type(cases) is not list or any(type(c) is not dict or set(c) != {'inputs', 'output'} for c in cases):\n"
        "        raise ValueError('Cases must have exactly inputs and output')\n"
        "    return observations(variables, [(c['inputs'], c['output']) for c in cases])\n"
        '\n'
        '\n'
        'def contract(data):\n'
        "    fields = {'variables', 'constants', 'examples', 'validation_examples'}\n"
        "    if type(data) is not dict or not fields - {'constants'} <= set(data) <= fields:\n"
        "        raise ValueError('Variables, training examples and reserved validation examples required')\n"
        "    variables = variables_contract(data['variables'])\n"
        "    constants = data.get('constants', [0, 1])\n"
        '    if type(constants) is not list or len(constants) > MAX_CONSTANTS:\n'
        "        raise ValueError('Bounded constants required')\n"
        '    constants = [str(rational(c)) for c in constants]\n'
        '    if not variables and not constants:\n'
        "        raise ValueError('An expression atom is required')\n"
        "    train = _examples(variables, data['examples'])\n"
        "    reserved = _examples(variables, data['validation_examples'])\n"
        '    if len(train) + len(reserved) > MAX_CASES:\n'
        "        raise ValueError('At most 64 total native observations allowed')\n"
        '    keys = {tuple(env[v] for v in variables) for env, _ in train}\n'
        '    if any(tuple(env[v] for v in variables) in keys for env, _ in reserved):\n'
        "        raise ValueError('Training and validation inputs overlap')\n"
        '    def pack(cases):\n'
        "        return [{'inputs': {v: str(env[v]) for v in variables}, 'output': str(target)}\n"
        '                for env, target in cases]\n'
        "    return {'variables': list(variables), 'constants': constants,\n"
        "            'examples': pack(train), 'validation_examples': pack(reserved)}\n"
        '\n'
        '\n'
        'def _expression(expression, variables, *, max_nodes):\n'
        '    remaining = max_nodes\n'
        '    # Copy into an immutable bounded AST. No eval, templates or source snippets.\n'
        '    def visit(expr):\n'
        '        nonlocal remaining\n'
        '        remaining -= 1\n'
        '        if remaining < 0 or type(expr) not in (list, tuple) or not expr or type(expr[0]) is not str:\n'
        "            raise ValueError('Expression tree budget/schema violation')\n"
        '        op = expr[0]\n'
        "        if op == 'var' and len(expr) == 2 and type(expr[1]) is str and expr[1] in variables:\n"
        '            return (op, expr[1])\n'
        "        if op == 'const' and len(expr) == 2:\n"
        '            return (op, rational(expr[1]))\n'
        "        if op in ('+', '-', '*') and len(expr) == 3:\n"
        '            return (op, visit(expr[1]), visit(expr[2]))\n'
        "        raise ValueError('Unsupported scalar expression')\n"
        '    return visit(expression)\n'
        '\n'
        '\n'
        'def _render(expression, names):\n'
        "    if expression[0] == 'var':\n"
        '        return names[expression[1]]\n'
        "    if expression[0] == 'const':\n"
        '        value = expression[1]\n'
        "        return f'({value.numerator}/{value.denominator})'\n"
        "    return f'({_render(expression[1], names)}{expression[0]}{_render(expression[2], names)})'\n"
        '\n'
        '\n'
        'def source_for(expression, problem):\n'
        '    lines = []\n'
        "    for i, case in enumerate(problem['examples'] + problem['validation_examples']):\n"
        "        names = {v: f'input_{i}_{j}' for j, v in enumerate(problem['variables'])}\n"
        '        for variable, name in names.items():\n'
        "            value = rational(case['inputs'][variable])\n"
        "            lines.append(f'parametro {name}=({value.numerator}/{value.denominator});')\n"
        "        lines.append(f'tensor result_{i}={_render(expression, names)};')\n"
        "        lines.append(f'mostrar result_{i};')\n"
        "    text = '\\n'.join(lines) + '\\n'\n"
        '    if len(text.encode()) > 256 * 1024:\n'
        "        raise ValueError('Generated native source byte budget exceeded')\n"
        '    return text\n'
        '\n'
        '\n'
        'def _search(problem, directory, max_nodes, max_candidates, budget):\n'
        '    # Do not mount problem.json: it contains the reserved targets and inputs.\n'
        "    public = {k: problem[k] for k in ('variables', 'constants', 'examples')}\n"
        '    public.update(max_nodes=max_nodes, max_candidates=max_candidates)\n'
        "    path = directory / 'search.json'\n"
        '    _write(path, public)\n'
        '    package = Path(__file__).resolve().parent\n'
        "    worker = package / 'synthesis_worker.py'\n"
        '    outcome = isolated_run(\n'
        "        [sys.executable, '-E', '-S', '-B', worker, path],\n"
        "        readonly=[worker, package / 'contract_synthesis.py', path, Path(sys.base_prefix) / 'lib'],\n"
        '        budget=budget, check=True,\n'
        '    )\n'
        '    response = decode(outcome.stdout.encode())\n'
        "    if type(response) is not dict or set(response) != {'format', 'candidate'} or response['format'] != 'omega-scalar-search-1':\n"
        "        raise ValueError('Invalid isolated search response')\n"
        "    candidate = response['candidate']\n"
        '    if candidate is not None:\n'
        "        if type(candidate) is not dict or set(candidate) != {'expression', 'checked', 'universal'}:\n"
        "            raise ValueError('Invalid candidate schema')\n"
        "        if candidate['universal'] is not False or type(candidate['checked']) is not int or not 1 <= candidate['checked'] <= max_candidates:\n"
        "            raise ValueError('Invalid candidate claim/budget')\n"
        "        _expression(candidate['expression'], problem['variables'], max_nodes=max_nodes)\n"
        "    return candidate, {'sandboxed': outcome.sandboxed, 'budget': outcome.budget,\n"
        "                       'wall_seconds': outcome.wall_seconds}\n"
        '\n'
        '\n'
        'def run(problem, directory, *, max_nodes=7, max_candidates=10000,\n'
        '        search_budget=SEARCH_BUDGET, execution_budget=Budget()):\n'
        '    """Write to a fresh directory. Exceptions preserve partial evidence, never pass."""\n'
        '    if type(max_nodes) is not int or not 1 <= max_nodes <= 31:\n'
        "        raise ValueError('Invalid expression node budget')\n"
        '    if type(max_candidates) is not int or not 1 <= max_candidates <= 100000:\n'
        "        raise ValueError('Invalid candidate budget')\n"
        '    if type(search_budget) is not Budget or type(execution_budget) is not Budget:\n'
        "        raise ValueError('Explicit validated OS budgets required')\n"
        '    problem = contract(problem)\n'
        '    directory = Path(directory).absolute()\n'
        '    directory.mkdir(parents=True, exist_ok=False)\n'
        '    subject = hashlib.sha256(canonical(problem)).hexdigest()\n'
        "    _write(directory / 'problem.json', problem)\n"
        "    report = {'format': FORMAT, 'status': 'failed', 'problem_sha256': subject,\n"
        "              'checks_passed': False, 'universal_proof': False, 'promoted': False,\n"
        "              'claim': 'exact observations only; no universal or C refinement proof',\n"
        "              'limits': {'max_nodes': max_nodes, 'max_candidates': max_candidates},\n"
        "              'execution_budget': execution_budget.__dict__, 'cases': []}\n"
        "    stage = 'search'\n"
        '    try:\n'
        '        candidate, telemetry = _search(problem, directory, max_nodes, max_candidates, search_budget)\n'
        "        report['search_execution'] = telemetry\n"
        "        report['candidate'] = candidate\n"
        "        _write(directory / 'candidate.json', candidate)\n"
        '        if candidate is None:\n'
        "            report['status'] = 'exhausted'\n"
        '        else:\n'
        "            stage = 'build'\n"
        "            expression = _expression(candidate['expression'], problem['variables'], max_nodes=max_nodes)\n"
        "            source = directory / 'program.omega'\n"
        "            with source.open('x', encoding='utf-8') as stream:\n"
        '                stream.write(source_for(expression, problem))\n'
        '            from omega_selfhost import driver\n'
        "            driver.build_checked(source, directory / 'program').unwrap()\n"
        "            stage = 'execute_and_verify'\n"
        "            data, admission = driver.run(directory / 'program', destination=directory / 'native-result.json',\n"
        '                                         budget=execution_budget)\n'
        "            if admission.get('valid') is not True or admission.get('execution', {}).get('sandboxed') is not True:\n"
        "                raise ValueError('Native independent admission/isolation missing')\n"
        "            stage = 'observations'\n"
        "            for group in ('examples', 'validation_examples'):\n"
        "                offset = 0 if group == 'examples' else len(problem['examples'])\n"
        '                for j, case in enumerate(problem[group]):\n'
        "                    actual = data['values'][f'result_{offset+j}']\n"
        '                    # The native protocol is canonical rational text. Its kernel\n'
        '                    # has already checked these values against the actual IR.\n'
        "                    passed = actual == case['output']\n"
        "                    report['cases'].append({'split': 'train' if group == 'examples' else 'reserved',\n"
        "                                            'index': j, 'expected': case['output'],\n"
        "                                            'actual': actual, 'passed': passed})\n"
        "            report['checks_passed'] = all(case['passed'] for case in report['cases'])\n"
        "            report['status'] = 'checks_passed' if report['checks_passed'] else 'rejected'\n"
        '    except Exception as exc:\n'
        '        report.update(stage=stage, error_type=type(exc).__name__)\n'
        '        raise\n'
        '    finally:\n'
        "        _write(directory / 'report.json', report)\n"
        '        files = [p for p in directory.iterdir() if p.name in ARTIFACT_NAMES and p.is_file()]\n'
        "        _write(directory / 'manifest.json', {'format': 'omega-synthesis-artifacts-1',\n"
        "                                           'problem_sha256': subject,\n"
        "                                           'files': artifact_record(files, directory)})\n"
        '    return report\n'
        '\n'
        '\n'
        'def _replay_budget(record, policy):\n'
        '    if type(policy) is not Budget or type(record) is not dict:\n'
        "        raise ValueError('Supervisor replay budget policy required')\n"
        '    recorded = Budget(**record)\n'
        '    if any(getattr(recorded, field) > value for field, value in policy.__dict__.items()):\n'
        "        raise ValueError('Archived replay budget exceeds supervisor policy')\n"
        '    return recorded\n'
        '\n'
        '\n'
        'def audit(directory, *, expected_problem_sha256=None,\n'
        '          search_policy=SEARCH_BUDGET, execution_policy=Budget()):\n'
        '    """Rebuild and rerun independently. Integrity is not origin authentication.\n'
        '\n'
        '    An external supervisor may bind this review to an expected problem digest.\n'
        '    Never execute the archived binary: rebuild from the bounded regenerated AST.\n'
        '    """\n'
        '    directory = Path(directory).absolute()\n'
        "    manifest = decode(_read(directory / 'manifest.json'))\n"
        "    if type(manifest) is not dict or set(manifest) != {'format', 'problem_sha256', 'files'} or manifest['format'] != 'omega-synthesis-artifacts-1':\n"
        "        raise ValueError('Invalid synthesis artifact manifest')\n"
        "    files = manifest['files']\n"
        "    required = {'problem.json', 'search.json', 'candidate.json', 'report.json'}\n"
        '    if type(files) is not dict or not required <= set(files) <= ARTIFACT_NAMES:\n'
        "        raise ValueError('Missing or unknown synthesis artifacts')\n"
        '    for name, record in files.items():\n'
        '        data = _read(directory / name, limit=64 * MAX_BYTES)\n'
        "        if record != {'sha256': hashlib.sha256(data).hexdigest(), 'bytes': len(data)}:\n"
        "            raise ValueError('Synthesis artifact integrity mismatch: ' + name)\n"
        "    problem = contract(decode(_read(directory / 'problem.json')))\n"
        '    subject = hashlib.sha256(canonical(problem)).hexdigest()\n'
        "    if manifest['problem_sha256'] != subject:\n"
        "        raise ValueError('Problem/manifest subject mismatch')\n"
        '    if expected_problem_sha256 is not None:\n'
        "        if type(expected_problem_sha256) is not str or not re.fullmatch('[0-9a-f]{64}', expected_problem_sha256) or expected_problem_sha256 != subject:\n"
        "            raise ValueError('Artifact does not match the authorized problem')\n"
        "    previous = decode(_read(directory / 'report.json'))\n"
        "    if type(previous) is not dict or previous.get('format') != FORMAT or previous.get('problem_sha256') != subject:\n"
        "        raise ValueError('Invalid synthesis report/subject')\n"
        "    if previous.get('candidate') is not None:\n"
        "        native_files = {'program.omega', 'program', 'program.c', 'program.build.json',\n"
        "                        'native-result.json', 'native-result.verification.json'}\n"
        '        if not native_files <= set(files):\n'
        "            raise ValueError('Incomplete native synthesis artifact set')\n"
        "    if previous.get('search_execution', {}).get('sandboxed') is not True:\n"
        "        raise ValueError('Archived search isolation evidence missing')\n"
        "    limits = previous['limits']\n"
        "    if type(limits) is not dict or set(limits) != {'max_nodes', 'max_candidates'}:\n"
        "        raise ValueError('Invalid synthesis replay limits')\n"
        "    search_budget = _replay_budget(previous['search_execution']['budget'], search_policy)\n"
        "    execution_budget = _replay_budget(previous['execution_budget'], execution_policy)\n"
        "    with tempfile.TemporaryDirectory(prefix='omega-synthesis-audit-') as tmp:\n"
        "        rebuilt = Path(tmp) / 'replay'\n"
        '        current = run(problem, rebuilt, **limits, search_budget=search_budget, execution_budget=execution_budget)\n'
        "        for name in ('problem.json', 'search.json', 'candidate.json', 'program.omega',\n"
        "                     'program.c', 'program', 'program.build.json', 'native-result.json'):\n"
        '            if (rebuilt / name).exists():\n'
        '                if name not in files or _read(directory / name, 64 * MAX_BYTES) != _read(rebuilt / name, 64 * MAX_BYTES):\n'
        "                    raise ValueError('Independent synthesis replay disagreement: ' + name)\n"
        "        for key in ('status', 'checks_passed', 'candidate', 'cases', 'universal_proof', 'promoted'):\n"
        '            if previous.get(key) != current.get(key):\n'
        "                raise ValueError('Independent report replay disagreement: ' + key)\n"
        "    return {'format': 'omega-native-synthesis-audit-1', 'matches_archived': True,\n"
        "            'checks_passed': current['checks_passed'], 'status': current['status'],\n"
        "            'problem_sha256': subject, 'problem_bound': expected_problem_sha256 is not None,\n"
        "            'origin_authenticated': False, 'universal_proof': False, 'promoted': False}\n"
    ),
    ('omega_coder/patch_review.py',
        '"""Review findings are advisory; they do not establish correctness."""\n'
        'from pathlib import PurePosixPath\n'
        'from omega_security.secrets import redact\n'
        "PROTECTED=('.github/','formal/','omega_security/','omega_evolution/promotion.py')\n"
        'def review(changes,protected=PROTECTED):\n'
        '    findings=[]\n'
        '    for path,content in sorted(changes.items()):\n'
        '        p=PurePosixPath(path)\n'
        "        if p.is_absolute() or '..' in p.parts:findings.append({'path':path,'severity':'block','reason':'path escape'})\n"
        "        if any(path.startswith(prefix) for prefix in protected):findings.append({'path':path,'severity':'review','reason':'trusted component change'})\n"
        "        if redact(content)!=content:findings.append({'path':path,'severity':'block','reason':'possible secret disclosure'})\n"
        "        if path.endswith('.lean') and any(word in content.split() for word in ('sorry','admit','axiom')):findings.append({'path':path,'severity':'block','reason':'proof admission declaration'})\n"
        "    return {'findings':findings,'blocked':any(f['severity']=='block' for f in findings),'requires_independent_review':True}\n"
    ),
    ('omega_coder/program_search.py',
        '"""Equal candidate budgets for enumerative, evolutionary and model proposals."""\n'
        'import random,time\n'
        'from dataclasses import dataclass\n'
        '@dataclass(frozen=True)\n'
        'class SearchBudget:\n'
        '    candidates: int=128\n'
        '    seconds: float=30\n'
        '    seed: int=0\n'
        '    def __post_init__(self):\n'
        "        if not 1<=self.candidates<=100000 or not 0<self.seconds<=3600:raise ValueError('Invalid search budget')\n"
        'def compare(methods,verifier,budget=SearchBudget()):\n'
        '    results={}\n'
        '    for name,method in sorted(methods.items()):\n'
        '        start=time.monotonic();attempts=0;solution=None\n'
        '        for candidate in method(random.Random(budget.seed)):\n'
        '            if attempts>=budget.candidates or time.monotonic()-start>=budget.seconds:break\n'
        '            attempts+=1\n'
        '            if verifier(candidate) is True:solution=candidate;break\n'
        "        results[name]={'attempts':attempts,'seconds':time.monotonic()-start,'solution':solution,'seed':budget.seed}\n"
        '    return results\n'
    ),
    ('omega_coder/pull_requests.py',
        '"""Explicitly authorized PR publication; never merges a pull request."""\n'
        'from dataclasses import dataclass\n'
        'import re,tempfile\n'
        'from pathlib import Path\n'
        'from omega_platform.sandbox import trusted\n'
        'from omega_platform.budget import BUILD_BUDGET\n'
        '@dataclass(frozen=True)\n'
        'class PullRequest:\n'
        '    repository: str\n'
        '    branch: str\n'
        '    title: str\n'
        '    body: str\n'
        "    base: str='main'\n"
        '    def __post_init__(self):\n'
        "        if not re.fullmatch(r'[\\w.-]+/[\\w.-]+',self.repository) or not re.fullmatch(r'[\\w./-]+',self.branch):raise ValueError('Invalid PR identity')\n"
        "        if not self.title or len(self.body)>100000:raise ValueError('Invalid review content')\n"
        'def publish(request,*,capability,verifier,principal,approval,approval_gate):\n'
        "    verifier.require(capability,principal,'github.pr.create')\n"
        '    approval_gate.consume(request.__dict__,approval,principal)\n'
        "    with tempfile.TemporaryDirectory(prefix='omega-pr-') as tmp:\n"
        "        path=Path(tmp)/'body.md';path.write_text(request.body)\n"
        "        result=trusted(['gh','pr','create','--draft','--repo',request.repository,'--base',request.base,\n"
        "                        '--head',request.branch,'--title',request.title,'--body-file',path],budget=BUILD_BUDGET,check=True)\n"
        '    return result.stdout.strip()\n'
    ),
    ('omega_coder/repair.py',
        '"""Bounded propose/check repair. Existing failing checks cannot be removed."""\n'
        'from dataclasses import dataclass\n'
        '@dataclass(frozen=True)\n'
        'class RepairOutcome:\n'
        '    accepted: bool\n'
        '    candidate: object\n'
        '    attempts: tuple\n'
        'class RepairLoop:\n'
        '    def __init__(self,propose,isolated_check,required_checks):self.propose=propose;self.check=isolated_check;self.required=frozenset(required_checks)\n'
        '    def run(self,candidate,diagnostic,max_attempts=8):\n'
        "        if not 1<=max_attempts<=64:raise ValueError('Invalid repair budget')\n"
        '        history=[]\n'
        '        for index in range(max_attempts):\n'
        '            report=self.check(candidate)\n'
        "            if not self.required<=set(report):raise ValueError('Repair removed required checks')\n"
        '            passed=all(report[name] is True for name in self.required)\n'
        "            history.append({'attempt':index,'checks':report,'accepted':passed})\n"
        '            if passed:return RepairOutcome(True,candidate,tuple(history))\n'
        '            candidate=self.propose(candidate,diagnostic,report)\n'
        '        return RepairOutcome(False,candidate,tuple(history))\n'
    ),
    ('omega_coder/repository_index.py',
        '"""Bounded static symbol/import/call index; dynamic resolution is not inferred."""\n'
        'import ast,hashlib,re\n'
        'from pathlib import Path\n'
        'def index(root,max_bytes=16*1024**2,max_files=2048):\n'
        '    root=Path(root).resolve();records={};total=0\n'
        "    for path in sorted(root.rglob('*')):\n"
        "        if any(p in {'.git','.venv','.lake','__pycache__','node_modules'} for p in path.relative_to(root).parts):continue\n"
        "        if path.is_symlink() or not path.is_file() or path.suffix not in {'.py','.omega','.c','.h','.lean'}:continue\n"
        '        data=path.read_bytes();total+=len(data)\n'
        "        if total>max_bytes or len(records)>=max_files:raise ValueError('Repository index budget exceeded')\n"
        "        source=data.decode('utf-8');symbols=[];calls=[];imports=[]\n"
        "        if path.suffix=='.py':\n"
        '            tree=ast.parse(source)\n'
        '            for node in ast.walk(tree):\n'
        "                if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)):symbols.append({'name':node.name,'line':node.lineno,'kind':type(node).__name__})\n"
        "                if isinstance(node,ast.Call):calls.append({'callee':ast.unparse(node.func),'line':node.lineno})\n"
        '                if isinstance(node,ast.Import):imports.extend(x.name for x in node.names)\n'
        "                if isinstance(node,ast.ImportFrom):imports.append('.'*node.level+(node.module or ''))\n"
        '        else:\n'
        "            pattern=r'\\b(funcao|def|theorem|lemma)\\s+([^\\W\\d]\\w*)'\n"
        "            for match in re.finditer(pattern,source):symbols.append({'name':match[2],'line':source.count('\\n',0,match.start())+1,'kind':match[1]})\n"
        '            imports=re.findall(r\'^\\s*(?:import\\s+([^\\n]+)|#include\\s+"([^"]+)")\',source,re.MULTILINE)\n'
        "        records[path.relative_to(root).as_posix()]={'sha256':hashlib.sha256(data).hexdigest(),'symbols':symbols,'calls':calls,'imports':imports}\n"
        '    return records\n'
    ),
