    ('omega_coder/test_generation.py',
        '"""Product API generating reviewable test source, not running generated code."""\n'
        'import ast,json\n'
        'from dataclasses import dataclass\n'
        '@dataclass(frozen=True)\n'
        'class Example:\n'
        '    arguments: tuple\n'
        '    expected: object\n'
        'def generate_python(function,examples):\n'
        "    if not function.isidentifier():raise ValueError('Python function identifier required')\n"
        '    examples=tuple(examples)\n'
        "    if not 1<=len(examples)<=256:raise ValueError('Example budget exceeded')\n"
        "    lines=['def test_generated_contract():']\n"
        '    for example in examples:\n'
        '        # literal roundtrip prevents executable objects from entering generated source.\n'
        '        arguments=ast.literal_eval(repr(example.arguments));expected=ast.literal_eval(repr(example.expected))\n'
        "        lines.append('    assert '+function+'(*'+repr(arguments)+') == '+repr(expected))\n"
        "    return '\\n'.join(lines)+'\\n'\n"
        'def mutation_score(mutations,isolated_runner,oracle):\n'
        '    killed=0;total=0\n'
        '    for candidate in mutations:\n'
        "        if total>=256:raise ValueError('Mutation budget exceeded')\n"
        '        observation=isolated_runner(candidate)\n'
        '        if oracle(observation) is False:killed+=1\n'
        '        total+=1\n'
        "    return {'mutants':total,'killed':killed,'score':killed/total if total else None}\n"
    ),
