    ('omega_coder/worktrees.py',
        '"""Disposable detached worktrees. Git metadata is never writable by candidates."""\n'
        'import re,shutil\n'
        'from pathlib import Path\n'
        'from omega_platform.sandbox import trusted,run\n'
        'from omega_platform.budget import BUILD_BUDGET,Budget\n'
        'class Worktree:\n'
        '    def __init__(self,repository,destination,commit):\n'
        "        if not re.fullmatch('[0-9a-f]{40}',commit):raise ValueError('Full existing commit SHA required')\n"
        '        self.repository=Path(repository).resolve(strict=True);self.path=Path(destination).absolute();self.commit=commit;self.created=False\n'
        '    def _git(self,*args):\n'
        "        return trusted(['git','-c','core.hooksPath=/dev/null','-C',self.repository,*args],budget=BUILD_BUDGET,check=True)\n"
        '    def create(self):\n'
        '        if self.path.exists():raise FileExistsError(self.path)\n'
        "        self._git('worktree','add','--detach',str(self.path),self.commit);self.created=True;return self\n"
        '    def execute(self,argv,*,readonly=(),budget=Budget()):\n'
        "        if not self.created:raise ValueError('Worktree is not active')\n"
        "        return run(argv,cwd=self.path,writable=[self.path],readonly=[self.path/'.git',*readonly],budget=budget)\n"
        "    def diff(self):return self._git('-C',str(self.path),'diff','--no-ext-diff','--binary').stdout\n"
        '    def close(self):\n'
        "        if self.created:self._git('worktree','remove','--force',str(self.path));self.created=False\n"
        '    def __enter__(self):return self.create()\n'
        '    def __exit__(self,*exc):self.close()\n'
    ),
