        '        from .glass import certify_trace,replay\n'
        "        result=replay(spec) if args.mode=='replay' else certify_trace(spec['graph'],spec['inputs'])\n"
        '    print(json.dumps(result,sort_keys=True,indent=2));return 0\n'
