    ('omega_cognition/glass.py',
        '"""Grounded logical coordinates and replayable arithmetic traces.\n'
        '\n'
        'Orthogonality is a geometric property. Concept meaning requires an explicit\n'
        'logical contract; an axis label alone never grants a semantic certificate.\n'
        '"""\n'
        'from fractions import Fraction as Q\n'
        'import hashlib\n'
        'from omega.certified_graph import validate,evaluate\n'
        'from omega.certified_proof import check,rational_literal as lit\n'
        'from omega_refine_check.contracts import verify_contract\n'
        'from omega_selfhost.proof_protocol import encode\n'
        '\n'
        '\n'
        'def orthogonal_basis(rows):\n'
        "    if type(rows) not in (list,tuple) or not 1<=len(rows)<=64:raise ValueError('Bounded rational basis required')\n"
        '    basis=[list(map(Q,row)) for row in rows];width=len(basis[0])\n'
        "    if not 1<=width<=64 or len(basis)>width or any(len(row)!=width for row in basis):raise ValueError('Basis shape mismatch')\n"
        "    lines=['import Omega.Glass','namespace OmegaBasis'];names=[]\n"
        '    for i,row in enumerate(basis):\n'
        '        for j,other in enumerate(basis):\n'
        '            value=sum((a*b for a,b in zip(row,other)),Q(0));expected=Q(int(i==j))\n'
        "            if value!=expected:raise ValueError('Concept axes must be exactly orthonormal')\n"
        "            lines += [f'theorem dot_{i}_{j} : {lit(value)} = {lit(expected)} := by norm_num',f'#print axioms dot_{i}_{j}']\n"
        "            names.append(f'OmegaBasis.dot_{i}_{j}')\n"
        "    lines.append('end OmegaBasis');source='\\n'.join(lines)+'\\n'\n"
        "    return {'basis':[[str(x) for x in row] for row in basis],'proof':source,'admission':check(source,names)}\n"
        '\n'
        '\n'
        'def graph_ast(graph,ref):\n'
        "    if ref<graph['inputs']:return ('var',f'input_{ref}')\n"
        "    node=graph['nodes'][ref-graph['inputs']];op=node['op']\n"
        "    if op=='affine':\n"
        "        result=('const',node['bias'])\n"
        "        for parent,weight in node['terms']:result=('+',result,('*',('const',weight),graph_ast(graph,parent)))\n"
        '        return result\n'
        "    if op=='relu':return ('relu',graph_ast(graph,node['input']))\n"
        "    if op=='square':return ('*',graph_ast(graph,node['input']),graph_ast(graph,node['input']))\n"
        "    if op in ('mul','div'):return ('*' if op=='mul' else '/',graph_ast(graph,node['left']),graph_ast(graph,node['right']))\n"
        "    raise ValueError('Universal concept grounding currently requires rational arithmetic; real activations retain observational traces')\n"
        '\n'
        '\n'
        'def certify_concepts(graph,basis,concepts,input_contracts):\n'
        '    validate(graph);geometry=orthogonal_basis(basis)\n'
        "    if len(basis[0])!=len(graph['outputs']) or len(concepts)!=len(basis):raise ValueError('Concept/basis/output shape mismatch')\n"
        '    grounded=[]\n'
        '    for row,concept in zip(basis,concepts):\n'
        "        if type(concept) is not dict or set(concept)!={'name','ensures'}:raise ValueError('Every concept needs an explicit semantic contract')\n"
        "        projection=('const','0')\n"
        "        for weight,ref in zip(row,graph['outputs']):projection=('+',projection,('*',('const',str(Q(weight))),graph_ast(graph,ref)))\n"
        "        proof=verify_contract(input_contracts,projection,concept['ensures'])\n"
        "        grounded.append({'name':concept['name'],'proof':proof})\n"
        "    return {'geometry':geometry,'concepts':grounded,'graph_sha256':hashlib.sha256(encode(graph)).hexdigest(),\n"
        "            'scope':'declared logical predicates, not automatic natural-language neuron meaning'}\n"
        '\n'
        '\n'
        'def trace(graph,inputs,*,annotations=None,thresholds=None):\n'
        '    validate(graph)\n'
        '    from omega.real_graph import execute,analyze\n'
        '    values=execute(graph,inputs)\n'
        '    from omega.certified_graph import real_operations\n'
        '    boxes=analyze(graph,[(Q(x),Q(x)) for x in inputs])[0] if real_operations(graph) else [(x,x) for x in values]\n'
        '    events=[];annotations=dict(annotations or {});thresholds=dict(thresholds or {})\n'
        "    for i,node in enumerate(graph['nodes'],graph['inputs']):\n"
        '        from .memory import dependencies\n'
        "        event={'node':i,'operation':node['op'],'parents':dependencies(node),'value':str(values[i]),\n"
        "               'real_interval':list(map(str,boxes[i])),'annotation':annotations.get(i)}\n"
        "        if node['op']=='relu':event['branch']='positive' if values[node['input']]>0 else 'zero'\n"
        '        if i in thresholds:\n'
        '            limit=Q(thresholds[i]);a,b=boxes[i]\n'
        "            event['threshold']={'value':str(limit),'decision':'above' if a>limit else 'below_or_equal' if b<=limit else 'uncertified'}\n"
        '        events.append(event)\n'
        "    body={'format':'omega-glass-trace-1','graph':graph,'inputs':list(map(lambda x:str(Q(x)),inputs)),\n"
        "          'events':events,'outputs':[str(values[i]) for i in graph['outputs']]}\n"
        "    return {**body,'sha256':hashlib.sha256(encode(body)).hexdigest()}\n"
        '\n'
        '\n'
        'def replay(record):\n'
        "    if 'certificate' in record:\n"
        "        expected=certify_trace(record['graph'],record['inputs'],annotations={e['node']:e['annotation'] for e in record['events'] if e['annotation'] is not None},\n"
        "                               thresholds={e['node']:e['threshold']['value'] for e in record['events'] if 'threshold' in e})\n"
        "        if encode(expected)!=encode(record):raise ValueError('Changed certified glass trace')\n"
        "        return {'valid':True,'outputs':expected['outputs']}\n"
        "    expected=trace(record['graph'],record['inputs'],annotations={e['node']:e['annotation'] for e in record['events'] if e['annotation'] is not None},\n"
        "                   thresholds={e['node']:e['threshold']['value'] for e in record['events'] if 'threshold' in e})\n"
        "    if encode(expected)!=encode(record):raise ValueError('Changed or unrelated glass trace')\n"
        "    return {'valid':True,'outputs':expected['outputs']}\n"
        '\n'
        '\n'
        'def certify_trace(graph,inputs,*,annotations=None,thresholds=None):\n'
        '    record=trace(graph,inputs,annotations=annotations,thresholds=thresholds)\n'
        '    from omega.certified_graph import certify_bounds\n'
        "    selected=sorted(thresholds or graph['outputs'])\n"
        "    proof_graph={**graph,'outputs':selected}\n"
        "    proof_graph.pop('output_shape',None)\n"
        "    events={e['node']:e for e in record['events']}\n"
        "    output_bounds=[events[i]['real_interval'] if i>=graph['inputs'] else [str(Q(inputs[i]))]*2 for i in selected]\n"
        '    source,admission=certify_bounds(proof_graph,[(Q(x),Q(x)) for x in inputs],output_bounds)\n'
        "    body={k:v for k,v in record.items() if k!='sha256'}\n"
        "    body['certificate']={'proof':source,'admission':admission,'selected':selected}\n"
        "    return {**body,'sha256':hashlib.sha256(encode(body)).hexdigest()}\n"
        '\n'
        '\n'
        'def native_trace(graph,inputs,directory,input_bounds,**options):\n'
        '    from omega.real_native import build_runtime,run_runtime\n'
        '    build_runtime(graph,directory,input_bounds,trace_values=True)\n'
        "    outputs,admission=run_runtime(graph,__import__('pathlib').Path(directory)/'model',inputs)\n"
        '    record=certify_trace(graph,inputs,**options)\n'
        "    if outputs!=record['outputs'] or admission.get('native_trace')!=[str(v) for v in __import__('omega.real_graph',fromlist=['execute']).execute(graph,inputs)]:\n"
        "        raise ValueError('Native intermediate trace differs from certified replay')\n"
        "    return {'trace':record,'native_admission':admission}\n"
    ),
    ('omega_cognition/linear.py',
        '"""Generation-tagged linear ownership; borrowing never duplicates ownership."""\n'
        'from dataclasses import dataclass\n'
        '\n'
        '\n'
        '@dataclass(frozen=True)\n'
        'class Borrow:\n'
        '    resource:int\n'
        '    generation:int\n'
        '    serial:int\n'
        '    mutable:bool\n'
        '\n'
        '\n'
        'class LinearContext:\n'
        '    def __init__(self,capacity):\n'
        "        if type(capacity) is not int or not 1<=capacity<=2**30:raise ValueError('Bounded linear arena capacity required')\n"
        '        self.capacity=capacity;self.resources={};self.names={};self.borrows={};self.serial=0;self.used=0;self.events=[]\n'
        '    def allocate(self,name,size):\n'
        "        if type(name) is not str or not name or name in self.names or type(size) is not int or not 1<=size<=self.capacity-self.used:raise ValueError('Invalid linear allocation')\n"
        "        identity=len(self.resources);self.resources[identity]={'owner':name,'bytes':size,'generation':0,'alive':True}\n"
        "        self.names[name]=identity;self.used+=size;self.events.append(('allocate',name,size));return identity\n"
        '    def _resource(self,name):\n'
        "        if name not in self.names:raise ValueError('Unknown or consumed owner')\n"
        '        identity=self.names[name];resource=self.resources[identity]\n'
        "        if not resource['alive'] or resource['owner']!=name:raise ValueError('Use after move or release')\n"
        '        return identity,resource\n'
        '    def move(self,source,target):\n'
        '        identity,resource=self._resource(source)\n'
        "        if target in self.names or any(b.resource==identity for b in self.borrows.values()):raise ValueError('Move requires exclusive ownership and a fresh destination')\n"
        "        del self.names[source];self.names[target]=identity;resource['owner']=target;resource['generation']+=1\n"
        "        self.events.append(('move',source,target));return identity\n"
        '    def borrow(self,name,*,mutable=False):\n'
        '        identity,resource=self._resource(name)\n'
        "        if type(mutable) is not bool:raise ValueError('Explicit borrow mutability required')\n"
        '        active=[b for b in self.borrows.values() if b.resource==identity]\n'
        "        if active and (mutable or any(b.mutable for b in active)):raise ValueError('Aliasing mutable borrow')\n"
        "        self.serial+=1;token=Borrow(identity,resource['generation'],self.serial,mutable);self.borrows[token.serial]=token\n"
        '        return token\n'
        '    def release_borrow(self,token):\n'
        "        if type(token) is not Borrow or self.borrows.get(token.serial)!=token:raise ValueError('Expired or forged borrow')\n"
        '        resource=self.resources[token.resource]\n'
        "        if not resource['alive'] or resource['generation']!=token.generation:raise ValueError('Borrow generation expired')\n"
        '        del self.borrows[token.serial]\n'
        '    def consume(self,name):\n'
        '        identity,resource=self._resource(name)\n'
        "        if any(b.resource==identity for b in self.borrows.values()):raise ValueError('Resource still borrowed')\n"
        "        resource['alive']=False;resource['generation']+=1;self.used-=resource['bytes'];del self.names[name]\n"
        "        self.events.append(('consume',name));return resource['bytes']\n"
        '    def finish(self):\n'
        "        if self.names or self.borrows:raise ValueError('Unconsumed linear resources or outstanding borrows')\n"
        "        return {'valid':True,'peak_capacity':self.capacity,'events':tuple(self.events),'remaining_bytes':self.used}\n"
    ),
    ('omega_cognition/memory.py',
        '"""Last-use interval allocation for flat static tensor graphs."""\n'
        'from omega.certified_graph import validate\n'
        'from omega.certified_proof import check\n'
        '\n'
        '\n'
        'def dependencies(node):\n'
        "    if node['op']=='affine':return [ref for ref,_ in node['terms']]\n"
        "    if node['op'] in ('mul','div'):return [node['left'],node['right']]\n"
        "    return [node['input']]\n"
        '\n'
        '\n'
        'def plan_buffers(graph,*,bytes_per_value=16,prove=True):\n'
        '    validate(graph)\n'
        "    if type(bytes_per_value) is not int or not 1<=bytes_per_value<=4096:raise ValueError('Fixed value width required')\n"
        "    count=graph['inputs']+len(graph['nodes']);last=list(range(count));starts=[0]*graph['inputs']+list(range(graph['inputs'],count))\n"
        "    for i,node in enumerate(graph['nodes'],graph['inputs']):\n"
        '        for ref in dependencies(node):last[ref]=max(last[ref],i)\n'
        "    for ref in graph['outputs']:last[ref]=count\n"
        '    slots=[];ends=[]\n'
        '    for i,start in enumerate(starts):\n'
        '        free=next((slot for slot,end in enumerate(ends) if end<start),None)\n'
        '        if free is None:free=len(ends);ends.append(last[i])\n'
        '        else:ends[free]=last[i]\n'
        '        slots.append(free)\n'
        '    obligations=[];previous={}\n'
        '    for i,slot in enumerate(slots):\n'
        '        if slot in previous:\n'
        '            j=previous[slot]\n'
        "            if not last[j]<starts[i]:raise ValueError('Buffer liveness overlap')\n"
        '            obligations.append((j,i))\n'
        '        previous[slot]=i\n'
        "    result={'slots':slots,'starts':starts,'last_uses':last,'slot_count':len(ends),'bytes':len(ends)*bytes_per_value,\n"
        "            'unreused_bytes':count*bytes_per_value,'allocation':'fixed buffers; no hidden dynamic tensor allocation'}\n"
        '    if prove:\n'
        "        lines=['import Omega.LinearMemory','namespace OmegaBufferPlan','set_option maxRecDepth 10000'];names=[]\n"
        '        # One proof per reused slot covers every pair sharing that slot.\n'
        '        for slot in range(len(ends)):\n'
        '            pairs=[(i,j) for i,j in obligations if slots[i]==slot]\n'
        "            claims=[f'({last[i]} < {starts[j]} ∨ {last[j]} < {starts[i]})' for i,j in pairs]\n"
        "            lines += [f'theorem slot_{slot} : '+(' ∧ '.join(claims) if claims else 'True')+' := by norm_num',f'#print axioms slot_{slot}']\n"
        "            names.append(f'OmegaBufferPlan.slot_{slot}')\n"
        "        lines.append('end OmegaBufferPlan');source='\\n'.join(lines)+'\\n'\n"
        "        result['proof']=source;result['admission']=check(source,names)\n"
        '    return result\n'
    ),
