        '"""Intent must supply a logical specification; prose never grants authority."""\n'
        'import json\n'
        'from pathlib import Path\n'
        'from omega_synth_mcts.search import synthesize\n'
        '\n'
        '\n'
        'def distill(intent,specification,directory,**limits):\n'
