        '  retornar poly_clean(p);\n'
        '}\n'
        'funcao poly_const(c,n) {\n'
        '  se(c==0) { retornar []; }\n'
        '  retornar [[u::check(c),u::zeros(n)]];\n'
        '}\n'
        'funcao poly_var(i,n) {\n'
        '  u::integer(i,0,n-1); var e=u::zeros(n); put(e,i,1); retornar [[1,e]];\n'
        '}\n'
        'funcao poly_add(a,b) {\n'
        '  var c=[]; var i=0;\n'
        '  enquanto(i<len(a)) { poly_insert(c,a[i][0],a[i][1]); i=i+1; }\n'
        '  i=0;\n'
        '  enquanto(i<len(b)) { poly_insert(c,b[i][0],b[i][1]); i=i+1; }\n'
        '  retornar poly_clean(c);\n'
        '}\n'
        'funcao poly_scale(a,x) {\n'
        '  var c=[]; var i=0;\n'
        '  enquanto(i<len(a)) { poly_insert(c,u::check(a[i][0]*x),a[i][1]); i=i+1; }\n'
        '  retornar poly_clean(c);\n'
        '}\n'
        'funcao poly_mul(a,b) {\n'
        '  var c=[]; var i=0;\n'
        '  enquanto(i<len(a)) {\n'
        '    var j=0;\n'
        '    enquanto(j<len(b)) {\n'
        '      var e=u::add(a[i][1],b[j][1]); var k=0; var degree=0;\n'
        '      enquanto(k<len(e)) { degree=degree+e[k]; k=k+1; }\n'
        '      se(degree>24) { fail("Intermediate polynomial degree budget"); }\n'
        '      poly_insert(c,u::check(a[i][0]*b[j][0]),e); j=j+1;\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar poly_clean(c);\n'
        '}\n'
        'funcao poly_diff(p,i) {\n'
        '  var out=[]; var j=0;\n'
        '  enquanto(j<len(p)) {\n'
        '    var e=slice(p[j][1],0,len(p[j][1]));\n'
        '    se(i<0||i>=len(e)) { fail("Derivative variable outside polynomial"); }\n'
        '    se(e[i]>0) { var c=u::check(p[j][0]*e[i]); put(e,i,e[i]-1); poly_insert(out,c,e); }\n'
        '    j=j+1;\n'
        '  }\n'
        '  retornar poly_clean(out);\n'
        '}\n'
        'funcao poly_eval(p,x) {\n'
        '  var v=0; var i=0;\n'
        '  enquanto(i<len(p)) {\n'
        '    se(len(p[i][1])!=len(x)) { fail("Polynomial evaluation dimension"); }\n'
        '    var t=p[i][0]; var j=0;\n'
        '    enquanto(j<len(x)) { t=u::check(t*u::power(x[j],p[i][1][j])); j=j+1; }\n'
        '    v=u::check(v+t); i=i+1;\n'
        '  }\n'
        '  retornar v;\n'
        '}\n'
        'funcao poly_extend(p,n) {\n'
        '  var out=[]; var i=0;\n'
        '  enquanto(i<len(p)) {\n'
        '    var e=slice(p[i][1],0,len(p[i][1]));\n'
        '    se(len(e)>n) { fail("Cannot discard polynomial variables"); }\n'
        '    enquanto(len(e)<n) { push(e,0); }\n'
        '    push(out,[p[i][0],e]); i=i+1;\n'
        '  }\n'
        '  retornar out;\n'
        '}\n'
        'funcao poly_power(p,k,n) {\n'
        '  u::integer(k,0,12); var q=poly_const(1,n); var i=0;\n'
        '  enquanto(i<k) { q=poly_mul(q,p); i=i+1; }\n'
        '  retornar q;\n'
        '}\n'
        'funcao poly_text(p) {\n'
        '  var code="0"; var i=0;\n'
        '  enquanto(i<len(p)) {\n'
        '    var term="("+text(p[i][0])+")"; var j=0;\n'
