        '      var k=0;\n'
        '      enquanto(k<p[i][1][j]) { term=term+"*x["+text(j)+"]"; k=k+1; }\n'
        '      j=j+1;\n'
        '    }\n'
        '    code=code+"+("+term+")"; i=i+1;\n'
        '  }\n'
        '  retornar code;\n'
