        '    for(uint32_t i=0;i<runtime.actors;i++) {\n'
        '        OmegaMicroCell *cell=omega_micro_cell(&runtime,i);\n'
        '        printf("S %u %u %u %u\\\\n",i,cell->status,cell->pc,cell->count);\n'
        '        for(uint32_t j=0;j<runtime.registers;j++)printf("R %u %u %" PRId64 " %" PRIu64 "\\\\n",i,j,cell->registers[j].n,cell->registers[j].d);\n'
        '    }\n'
        '    printf("T %" PRIu64 " %" PRIu64 " %" PRIu64 " %" PRIu64 " %u %u\\\\n",runtime.turns,runtime.instructions,runtime.messages,runtime.mailbox_peak,runtime.completed,runtime.deadlock);\n'
        '    printf("A %zu %zu\\\\n",bytes,sizeof(OmegaMicroCell));\n'
        '    if(munmap(memory,bytes))return 23;\n'
        '    return 0;\n'
        '}\n'
        "'''\n"
        "    replacements = {'PROGRAM': ',\\n'.join(instructions), 'ACTORS': str(actors), 'STRIDE': str(stride),\n"
        "                    'REGISTERS': str(registers), 'MAILBOX': str(int(Q(request['mailbox_capacity']))),\n"
        "                    'QUANTUM': str(int(Q(request['quantum']))), 'MAX_TURNS': str(int(Q(request['max_turns']))),\n"
        "                    'INITIALIZER': '\\n'.join(initializer)}\n"
        "    source = re.sub(r'\\b(?:'+ '|'.join(replacements)+r')\\b', lambda m: replacements[m.group()], source)\n"
