        '    for i in range(len(slow)):\n'
        "        for j in range(len(slow)): right_coefficients.append(observed['value'][i][j]/2); right_terms.append(slow[i]*slow[j])\n"
        "    right_coefficients.extend(observed['linear']+[observed['constant']]); right_terms.extend(slow+[Q(1)])\n"
        "    return [{'left_dot': [left_coefficients,left_terms], 'right_dot': [right_coefficients,right_terms]}]\n"
        '\n'
        '\n'
        'def prove(identifier, request, destination):\n'
