        'from dataclasses import dataclass\n'
        '@dataclass(frozen=True)\n'
        'class Version:\n'
        '    id: str\n'
        '    parents: tuple[str,...]\n'
        '    experiment: str\n'
        '    artifact_digest: str\n'
        'class Lineage:\n'
        '    def __init__(self):self.versions={}\n'
        '    def add(self,version):\n'
        "        if not version.id or version.id in self.versions or any(p not in self.versions for p in version.parents):raise ValueError('Invalid version ancestry')\n"
        "        if not version.experiment or len(version.artifact_digest)!=64:raise ValueError('Provenance required')\n"
