        '    def ancestors(self,id):\n'
        '        visited=set();pending=[id]\n'
        '        while pending:\n'
        '            node=pending.pop()\n'
        '            if node in visited:continue\n'
        '            visited.add(node);pending.extend(self.versions[node].parents)\n'
