        '__global__ void reward_backprop(TensorMCTS tree,const uint32_t *selected,uint32_t rollouts,uint32_t iteration,\n'
        ' const Rational64 *values,const Rational64 *targets,const uint8_t *errors,uint32_t examples,uint32_t *rewards);\n'
        '__global__ void select_elites(const uint8_t *admissible,const uint8_t *errors,const uint32_t *rewards,\n'
        ' const uint16_t *tokens,const uint16_t *lengths,uint32_t candidates,uint32_t requested,Elite *out,uint32_t *count,uint64_t *survivors);\n'
        '#endif\n'
        '}\n'
