    ('omega_ingest/cli.py',
        '"""Explicit foreign numerical models and reviewable native source output."""\n'
        'import argparse,json\n'
        'from pathlib import Path\n'
        'from .frontends import python_function,c_function,wasm_function,save\n'
        '\n'
        '\n'
        'def main(argv=None):\n'
        "    p=argparse.ArgumentParser(prog='omega ingest');sub=p.add_subparsers(dest='language',required=True)\n"
        "    for name in ('python','c','wasm'):\n"
        "        sp=sub.add_parser(name);sp.add_argument('source',type=Path);sp.add_argument('--function',required=True);sp.add_argument('--output',type=Path,required=True)\n"
        "        if name!='wasm':sp.add_argument('--rational-reals',action='store_true',help='Explicitly change float semantics to rational real arithmetic')\n"
        "    neural=sub.add_parser('onnx');neural.add_argument('source',type=Path);neural.add_argument('--output',type=Path,required=True);neural.add_argument('--allow-approx',action='store_true');neural.add_argument('--precision-bits',type=int,default=32)\n"
        "    tensor=sub.add_parser('safetensors');tensor.add_argument('source',type=Path)\n"
        '    args=p.parse_args(argv)\n'
        '    try:\n'
        "        if args.language=='safetensors':\n"
        '            from .tensors import safetensors\n'
        "            output={name:{'shape':t.shape,'weights':[str(x) for x in t.values]} for name,t in safetensors(args.source).items()}\n"
        '        else:\n'
        "            if args.language=='python':result=python_function(args.source,args.function,rational_reals=args.rational_reals)\n"
        "            elif args.language=='c':result=c_function(args.source,args.function,rational_reals=args.rational_reals)\n"
        "            elif args.language=='wasm':result=wasm_function(args.source,args.function)\n"
        '            else:\n'
        '                from .tensors import onnx\n'
        '                result=onnx(args.source,allow_approx=args.allow_approx,precision_bits=args.precision_bits)\n'
        '            output=save(result,args.output)\n'
        '        print(json.dumps(output,ensure_ascii=False,sort_keys=True,indent=2));return 0\n'
        "    except (ValueError,RuntimeError,OSError) as error:p.exit(1,str(error)+'\\n')\n"
        '\n'
        '\n'
        "if __name__=='__main__':raise SystemExit(main())\n"
    ),
