    ('omega_live/ipc.py',
        '"""A fork-shared, fixed-slot memory ring; payload views avoid serialization.\n'
        '\n'
        'Reserve/commit and borrow/release are explicit. The lock orders metadata; this\n'
        'is not a zero-latency claim or an unrestricted C pointer lifetime proof.\n'
        '"""\n'
        'import mmap\n'
        'import multiprocessing\n'
        'import struct\n'
        'from contextlib import contextmanager\n'
        '\n'
        "HEADER=struct.Struct('<QQ');SLOT=struct.Struct('<QQ')\n"
        '\n'
        '\n'
        'class SharedRing:\n'
        '    def __init__(self,capacity=64,slot_bytes=4096):\n'
        "        if type(capacity) is not int or not 1<=capacity<=4096 or type(slot_bytes) is not int or not 1<=slot_bytes<=1048576 or capacity*slot_bytes>64*1024**2:raise ValueError('Shared ring capacity budget')\n"
        '        self.capacity=capacity;self.slot_bytes=slot_bytes;self.lock=multiprocessing.RLock();self.memory=mmap.mmap(-1,HEADER.size+capacity*(SLOT.size+slot_bytes));HEADER.pack_into(self.memory,0,0,0)\n'
        '    def _slot(self,sequence):return HEADER.size+(sequence%self.capacity)*(SLOT.size+self.slot_bytes)\n'
        '    @contextmanager\n'
        '    def reserve(self,size):\n'
        "        if type(size) is not int or not 0<=size<=self.slot_bytes:raise ValueError('Slot payload budget')\n"
        '        with self.lock:\n'
        '            read,write=HEADER.unpack_from(self.memory)\n'
        "            if write-read>=self.capacity:raise BufferError('Ring full')\n"
        "            if write==2**64-1:raise OverflowError('Ring sequence exhausted')\n"
        '            at=self._slot(write);view=memoryview(self.memory)[at+SLOT.size:at+SLOT.size+size]\n'
        '            try:\n'
        '                yield view\n'
        '                SLOT.pack_into(self.memory,at,write,size);HEADER.pack_into(self.memory,0,read,write+1)\n'
        '            finally:view.release()\n'
        '    @contextmanager\n'
        '    def borrow(self):\n'
        '        with self.lock:\n'
        '            read,write=HEADER.unpack_from(self.memory)\n'
        "            if read==write:raise BufferError('Ring empty')\n"
        '            at=self._slot(read);sequence,size=SLOT.unpack_from(self.memory,at)\n'
        "            if sequence!=read or size>self.slot_bytes:raise ValueError('Ring metadata corrupted')\n"
        '            view=memoryview(self.memory)[at+SLOT.size:at+SLOT.size+size].toreadonly()\n'
        '            try:\n'
        '                yield view\n'
        '                HEADER.pack_into(self.memory,0,read+1,write)\n'
        '            finally:view.release()\n'
        '    def close(self):self.memory.close()\n'
    ),
