        "async function watch(){if(stream)stream.abort();stream=new AbortController();try{let response=await fetch('/api/stream?after='+cursor,{headers:{Authorization:'Bearer '+$('token').value},signal:stream.signal});if(!response.ok)throw Error(await response.text());let reader=response.body.getReader(),decoder=new TextDecoder(),pending='';while(true){let {value,done}=await reader.read();if(done)break;pending+=decoder.decode(value,{stream:true});let blocks=pending.split('\\\\n\\\\n');pending=blocks.pop();for(let b of blocks){let data=b.split('\\\\n').find(l=>l.startsWith('data: '));if(data){let event=JSON.parse(data.slice(6));cursor=event.seq;$('history').textContent+=JSON.stringify(event)+'\\\\n';let lines=$('history').textContent.split('\\\\n');if(lines.length>501)$('history').textContent=lines.slice(-500).join('\\\\n');$('history').scrollTop=$('history').scrollHeight;await refresh()}}}}catch(e){if(e.name!=='AbortError')$('message').textContent=e.message+' · reconectando'}setTimeout(watch,1000)}\n"
