    ('omega_nextorch/constrained_generation.py',
        '"""Token-level masking with grammar/type-state supplied by a bounded decoder."""\n'
        'import math,random\n'
        'class ConstrainedDecoder:\n'
        '    def __init__(self,grammar,max_tokens=4096):\n'
        "        if not 1<=max_tokens<=65536:raise ValueError('Invalid decoding budget')\n"
        '        self.grammar=grammar;self.max_tokens=max_tokens\n'
        '    def generate(self,logits,initial,seed=0):\n'
        '        state=initial;tokens=[];rng=random.Random(seed)\n'
        '        for _ in range(self.max_tokens):\n'
        '            if self.grammar.complete(state):return tuple(tokens),state\n'
        '            allowed=tuple(sorted(self.grammar.allowed(state)))\n'
        '            scores=logits(tuple(tokens),state)\n'
        "            if not allowed or any(t<0 or t>=len(scores) for t in allowed):raise ValueError('Grammar has no valid next token')\n"
        '            finite=[(t,scores[t]) for t in allowed if math.isfinite(scores[t])]\n'
        "            if not finite:raise ValueError('No finite valid proposal logits')\n"
        '            maximum=max(s for t,s in finite);weights=[math.exp(s-maximum) for t,s in finite]\n'
        '            token=rng.choices([t for t,s in finite],weights=weights,k=1)[0]\n'
        '            state=self.grammar.advance(state,token);tokens.append(token)\n'
        "        raise TimeoutError('Constrained generation budget exhausted')\n"
    ),
    ('omega_nextorch/devices.py',
        "def resolve(name='cpu',precision='float32'):\n"
        '    import torch\n'
        '    device=torch.device(name)\n'
        "    if device.type not in {'cpu','cuda'}:raise ValueError('Unsupported compute device')\n"
        "    if device.type=='cuda' and not torch.cuda.is_available():raise RuntimeError('Requested CUDA device unavailable')\n"
        "    dtypes={'float32':torch.float32,'float16':torch.float16,'bfloat16':torch.bfloat16}\n"
        "    if precision not in dtypes or (device.type=='cpu' and precision=='float16'):raise ValueError('Unsupported precision/device pair')\n"
        '    return device,dtypes[precision]\n'
        'def parity(reference,candidate,absolute=1e-6,relative=1e-5):\n'
        '    import torch\n'
        "    if reference.shape!=candidate.shape:raise ValueError('Numerical comparison shape mismatch')\n"
        "    if not torch.isfinite(reference).all() or not torch.isfinite(candidate).all():return {'within_tolerance':False,'nonfinite':True}\n"
        "    return {'within_tolerance':bool(torch.allclose(reference.double(),candidate.double(),atol=absolute,rtol=relative)),\n"
        "            'max_absolute_error':float((reference.double()-candidate.double()).abs().max())}\n"
    ),
    ('omega_nextorch/distributed_training.py',
        '"""DDP requires an explicitly initialized host process group; no implicit network setup."""\n'
        'from omega_learning.versioning import Checkpoints\n'
        'def wrap(model,device_ids=None):\n'
        '    import torch\n'
        "    if not torch.distributed.is_available() or not torch.distributed.is_initialized():raise RuntimeError('Host must initialize the distributed process group')\n"
        '    return torch.nn.parallel.DistributedDataParallel(model,device_ids=device_ids)\n'
        'def partition(ids,rank,world_size):\n'
        "    if not 0<=rank<world_size or world_size<1:raise ValueError('Invalid distributed rank')\n"
        '    return tuple(sorted(set(ids)))[rank::world_size]\n'
        'def checkpoint(model,root,name,metadata):\n'
        '    import torch\n'
        '    group=torch.distributed\n'
        "    if not group.is_initialized():raise RuntimeError('Distributed group unavailable')\n"
        '    result=None\n'
        "    if group.get_rank()==0:result=Checkpoints(root).save(name,model.module if hasattr(model,'module') else model,metadata)\n"
        '    group.barrier();return result\n'
    ),
    ('omega_nextorch/gate.py',
        '"""Independent admission of finite Boolean circuits. No neural imports."""\n'
        'from __future__ import annotations\n'
        '\n'
        'import copy\n'
        'import json\n'
        'from pathlib import Path\n'
        '\n'
        'from omega_open.checker import canonical, evaluate, fingerprint, validate_task, validate_tree\n'
        '\n'
        'FORMAT = "omega-nextorch-certificate-1"\n'
        'MAX_ROWS = 4096\n'
        'MAX_NODES = 20000\n'
        'MAX_DEPTH = 128\n'
        '\n'
        '\n'
        'def validate_domain(task):\n'
        '    # Check the bound before validate_task computes 2**arity.\n'
        '    if type(task) is not dict or type(task.get("arity")) is not int:\n'
        '        raise ValueError("Tarefa inválida")\n'
        '    if not 0 <= task["arity"] <= 12:\n'
        '        raise ValueError("A certificação aceita Bool^0 até Bool^12 (4096 linhas)")\n'
        '    validate_task(task, MAX_ROWS)\n'
        '\n'
        '\n'
        'def circuit_metrics(ast, arity):\n'
        '    validate_tree(ast, arity, MAX_NODES)\n'
        '    stack = [(ast, 1)]\n'
        '    unique = set()\n'
        '    depth = 0\n'
        '    while stack:\n'
        '        node, level = stack.pop()\n'
        '        if level > MAX_DEPTH:\n'
        '            raise ValueError("Circuito excede a profundidade máxima")\n'
        '        depth = max(depth, level)\n'
        '        unique.add(canonical(node))\n'
        '        if node[0] not in ("c", "v"):\n'
        '            stack.extend((child, level + 1) for child in node[1:])\n'
        '    return {"nos": len(unique), "profundidade": depth,\n'
        '            "operacoes": sum(json.loads(n)[0] not in ("c", "v") for n in unique)}\n'
        '\n'
        '\n'
        'def certify(task, ast, origin):\n'
        '    """Reject malformed or incorrect proposals, including unreachable branches."""\n'
        '    validate_domain(task)\n'
        '    if type(origin) is not str or not origin:\n'
        '        raise ValueError("Origem deve ser uma string não vazia")\n'
        '    metrics = circuit_metrics(ast, task["arity"])\n'
        '    for row, expected in enumerate(task["outputs"]):\n'
        '        if evaluate(ast, row, task["arity"]) != expected:\n'
        '            raise ValueError(f"Proposta rejeitada: contraexemplo na linha {row}")\n'
        '    body = {"format": FORMAT, "task": copy.deepcopy(task), "ast": copy.deepcopy(ast),\n'
        '            "origin": origin, "metrics": metrics, "checked_rows": len(task["outputs"])}\n'
        '    return {**body, "sha256": fingerprint(body)}\n'
        '\n'
        '\n'
        'def verify(certificate):\n'
        '    """Recompute admission; a hash alone never authorizes execution."""\n'
        '    try:\n'
        '        expected = certify(certificate["task"], certificate["ast"], certificate["origin"])\n'
        '        return canonical(certificate) == canonical(expected)\n'
        '    except (KeyError, ValueError, TypeError, RecursionError, OverflowError, IndexError):\n'
        '        return False\n'
        '\n'
        '\n'
        'def load_verified(path):\n'
        '    path = Path(path)\n'
        '    if path.stat().st_size > 8_000_000:\n'
        '        raise ValueError("Certificado excede o limite de 8 MB")\n'
        '    certificate = json.loads(path.read_text(encoding="utf-8"))\n'
        '    if not verify(certificate):\n'
        '        raise ValueError("Certificado Ômega/Nextorch inválido")\n'
        '    return certificate\n'
    ),
    ('omega_nextorch/inference_metrics.py',
        'import statistics,time,resource\n'
        'def measure(model,inputs,repetitions=10,energy_reader=None):\n'
        '    import torch\n'
        "    if not 1<=repetitions<=1000:raise ValueError('Invalid inference measurement budget')\n"
        '    use_cuda=any(p.is_cuda for p in model.parameters());timings=[];training=model.training;model.eval()\n'
        '    initial_energy=energy_reader() if energy_reader else None\n'
        '    try:\n'
        '        with torch.no_grad():\n'
        '            for _ in range(repetitions):\n'
        '                if use_cuda:torch.cuda.synchronize()\n'
        '                started=time.perf_counter();model(inputs)\n'
        '                if use_cuda:torch.cuda.synchronize()\n'
        '                timings.append(time.perf_counter()-started)\n'
        '    finally:model.train(training)\n'
        '    final_energy=energy_reader() if energy_reader else None\n'
        "    return {'median_seconds':statistics.median(timings),'repetitions':repetitions,\n"
        "            'process_max_rss_kib':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss,\n"
        "            'cuda_allocated_bytes':torch.cuda.memory_allocated() if use_cuda else None,\n"
        "            'energy_joules':final_energy-initial_energy if energy_reader else None}\n"
    ),
    ('omega_nextorch/lean.py',
        '"""Render only validated circuits into closed, reproducible Lean proof sources."""\n'
        'from __future__ import annotations\n'
        '\n'
        'import os\n'
        'from pathlib import Path\n'
        'import shutil\n'
        'from dataclasses import replace\n'
        'from omega_platform.budget import PROOF_BUDGET\n'
        'from omega_platform.sandbox import trusted\n'
        'import tempfile\n'
        '\n'
        'from .gate import verify\n'
        'from .native import bytecode\n'
        '\n'
        '\n'
        'def expression(ast):\n'
        '    op = ast[0]\n'
        '    if op == "c":\n'
        '        return ".lit " + ("true" if ast[1] else "false")\n'
        '    if op == "v":\n'
        '        return f".var {ast[1]}"\n'
        '    name = {"not": "neg", "and": "conj", "or": "disj", "xor": "xor", "ite": "ite"}[op]\n'
        '    return "." + name + " " + " ".join("(" + expression(a) + ")" for a in ast[1:])\n'
        '\n'
        '\n'
        'def source(certificate):\n'
        '    if not verify(certificate):\n'
        '        raise ValueError("Lean exige um certificado Ômega válido")\n'
        '    kernel = Path(__file__).with_name("Kernel.lean").read_text(encoding="utf-8")\n'
        '    rows = [f"((fun j => ({i} / 2^j) % 2 == 1), {\'true\' if b else \'false\'})"\n'
        '            for i, b in enumerate(certificate["task"]["outputs"])]\n'
        '    instructions = []\n'
        '    for ins in bytecode(certificate["ast"]):\n'
        '        if ins[0] == "c":\n'
        '            instructions.append(".push " + ("true" if ins[1] else "false"))\n'
        '        elif ins[0] == "v":\n'
        '            instructions.append(f".load {ins[1]}")\n'
        '        else:\n'
        '            instructions.append("." + {"not": "neg", "and": "conj", "or": "disj",\n'
        '                                       "xor": "xor", "ite": "ite"}[ins[0]])\n'
        '    return kernel + "\\nset_option maxRecDepth 100000\\nset_option maxHeartbeats 4000000\\nnamespace OmegaCertificate\\nopen Omega\\n" + \\\n'
        '        "def circuit : Expr := " + expression(certificate["ast"]) + "\\n" + \\\n'
        '        "def rows : List ((Nat → Bool) × Bool) := [" + ",\\n".join(rows) + "]\\n" + \\\n'
        '        "def instructions : List Instr := [" + ", ".join(instructions) + "]\\n" + """\n'
        'theorem table_checked : check circuit rows = true := by decide\n'
        'theorem lowering_matches : instructions = compile circuit := by rfl\n'
        'theorem accepted_execution (row) (hm : row ∈ rows) (s : List Bool) :\n'
        '    run row.1 instructions s = some (row.2 :: s) := by\n'
        '  rw [lowering_matches]\n'
        '  exact certified_execution circuit rows table_checked row hm s\n'
        '#print axioms table_checked\n'
        '#print axioms lowering_matches\n'
        '#print axioms accepted_execution\n'
        'end OmegaCertificate\n'
        '"""\n'
        '\n'
        '\n'
        'def check(certificate, destination=None, executable=None, timeout=60):\n'
        '    generated = source(certificate)\n'
        '    lean = shutil.which(executable or os.environ.get("OMEGA_LEAN", "lean"))\n'
        '    if lean is None:\n'
        '        raise RuntimeError("Lean 4 ausente; configure OMEGA_LEAN com o executável")\n'
        '    with tempfile.TemporaryDirectory(prefix="omega-lean-") as tmp:\n'
        '        proof = Path(tmp) / "Certificate.lean"\n'
        '        proof.write_text(generated, encoding="utf-8")\n'
        '        proc = trusted([lean, str(proof)], budget=replace(PROOF_BUDGET,wall_seconds=timeout))\n'
        '        output = proc.stdout + proc.stderr\n'
        '        if proc.returncode or "sorryAx" in output or "warning:" in output:\n'
        '            raise ValueError("Lean rejeitou a prova: " + output[-4000:])\n'
        '        # These declarations must have been elaborated, not just a successful process.\n'
        '        for declaration in ("Omega.compile_correct", "Omega.check_sound",\n'
        '                            "OmegaCertificate.table_checked", "OmegaCertificate.accepted_execution"):\n'
        '            if "\'" + declaration + "\'" not in output:\n'
        '                raise ValueError("Saída Lean incompleta: " + declaration)\n'
        '    if destination is not None:\n'
        '        Path(destination).write_text(generated, encoding="utf-8")\n'
        '    return {"valid": True, "scope": "finite-boolean-kernel-and-stack-compiler",\n'
        '            "axioms": ["propext", "Quot.sound"], "output": output}\n'
    ),
    ('omega_nextorch/model_api.py',
        '"""Swappable proposal protocol. Models do not possess verification authority."""\n'
        'from typing import Protocol\n'
        'class ReasoningModel(Protocol):\n'
        '    def propose(self,problem,limit:int):...\n'
        'class ModelAdapter:\n'
        '    def __init__(self,model,encode,decode):self.model=model;self.encode=encode;self.decode=decode\n'
        '    def propose(self,problem,limit):\n'
        "        if not 1<=limit<=256:raise ValueError('Proposal budget exceeded')\n"
        '        encoded=self.encode(problem);outputs=self.model.generate(encoded,max_candidates=limit)\n'
        '        for i,output in enumerate(outputs):\n'
        '            if i>=limit:break\n'
        '            yield self.decode(output)\n'
        'class ModelRegistry:\n'
        '    def __init__(self):self.models={}\n'
        '    def register(self,name,model):\n'
        "        if not name or name in self.models or not callable(getattr(model,'propose',None)):raise ValueError('Invalid model registration')\n"
        '        self.models[name]=model\n'
        '    def get(self,name):return self.models[name]\n'
        '\n'
        '\n'
        'class NextorchBooleanAdapter:\n'
        '    """Adapter for the existing Omega/Nextorch finite Boolean proposer."""\n'
        '    def __init__(self,budget=None):self.budget=budget\n'
        '    def propose(self,problem,limit):\n'
        '        from .proposer import propose,NeuralBudget\n'
        "        if not 1<=limit<=256:raise ValueError('Proposal budget exceeded')\n"
        "        task=dict(problem['inputs']) if isinstance(problem,dict) and 'inputs' in problem else problem\n"
        "        if isinstance(problem,dict) and 'id' in problem and 'id' not in task:task['id']=problem['id']\n"
        '        proposals,diagnostics=propose(task,self.budget or NeuralBudget())\n'
        '        for origin,candidate in proposals[:limit]:yield candidate\n'
        '\n'
        '\n'
        'def byte_reasoner(vocab_size=259,width=128,heads=4,layers=2,context=1024,seed=0):\n'
        '    """Construct an actual bounded causal byte Transformer, without pretrained weights.\n'
        '\n'
        '    Wrap it in ModelAdapter with a tokenizer encoder and a data-only decoder.\n'
        '    Training/generation are explicit calls, never import-time side effects.\n'
        '    """\n'
        '    import torch\n'
        '    from torch import nn\n'
        '    if not 4<=vocab_size<=65536 or not 16<=width<=1024 or not 1<=layers<=24 or not 1<=heads<=16 or width%heads or not 1<=context<=2048:\n'
        "        raise ValueError('Invalid sequence-model dimensions')\n"
        "    if 2*vocab_size*width+context*width+12*layers*width*width>50000000:raise ValueError('Sequence-model parameter budget exceeded')\n"
        '    class ByteReasoner(nn.Module):\n'
        '        def __init__(self):\n'
        '            super().__init__();self.context=context;self.vocab_size=vocab_size\n'
        '            self.embedding=nn.Embedding(vocab_size,width);self.position=nn.Embedding(context,width)\n'
        '            layer=nn.TransformerEncoderLayer(width,heads,dim_feedforward=4*width,dropout=0,batch_first=True)\n'
        '            self.transformer=nn.TransformerEncoder(layer,layers);self.output=nn.Linear(width,vocab_size)\n'
        '        def forward(self,tokens):\n'
        '            if tokens.ndim!=2 or tokens.dtype!=torch.long or not 0<tokens.shape[1]<=context or tokens.shape[0]*tokens.shape[1]**2>2000000:\n'
        "                raise ValueError('Sequence batch/attention budget exceeded')\n"
        "            if torch.any(tokens<0) or torch.any(tokens>=vocab_size):raise ValueError('Sequence token outside vocabulary')\n"
        '            positions=torch.arange(tokens.shape[1],device=tokens.device)\n'
        '            hidden=self.embedding(tokens)+self.position(positions)\n'
        '            mask=torch.triu(torch.ones(tokens.shape[1],tokens.shape[1],dtype=torch.bool,device=tokens.device),diagonal=1)\n'
        '            return self.output(self.transformer(hidden,mask=mask))\n'
        '        def generate(self,prompt,*,max_candidates=4,max_new_tokens=128,seed=0,eos=257):\n'
        "            if not 1<=max_candidates<=32 or not 1<=max_new_tokens<=256 or max_candidates*max_new_tokens>4096:raise ValueError('Generation budget exceeded')\n"
        "            if not prompt or any(type(t) is not int or not 0<=t<vocab_size for t in prompt):raise ValueError('Valid prefix tokens required')\n"
        '            device=next(self.parameters()).device;generator=torch.Generator(device=device).manual_seed(seed);training=self.training\n'
        '            self.eval();results=[]\n'
        '            try:\n'
        '                with torch.no_grad():\n'
        '                    for _ in range(max_candidates):\n'
        '                        sequence=list(prompt[-context:]);generated=[]\n'
        '                        for _ in range(max_new_tokens):\n'
        '                            tokens=torch.tensor([sequence[-context:]],dtype=torch.long,device=device)\n'
        '                            logits=self(tokens)[0,-1].float()\n'
        '                            if vocab_size>258:logits[256]=-torch.inf;logits[258]=-torch.inf\n'
        "                            if not torch.isfinite(logits).any():raise ValueError('Model has no finite next token')\n"
        '                            token=int(torch.multinomial(torch.softmax(logits,dim=-1),1,generator=generator))\n'
        '                            generated.append(token);sequence.append(token)\n'
        '                            if token==eos:break\n'
        '                        results.append(tuple(generated))\n'
        '            finally:self.train(training)\n'
        '            return tuple(results)\n'
        '    with torch.random.fork_rng(devices=[]):\n'
        '        torch.manual_seed(seed);return ByteReasoner()\n'
    ),
    ('omega_nextorch/native.py',
        '"""Native C backend for certified finite Boolean circuits (not tensor IR)."""\n'
        'from __future__ import annotations\n'
        '\n'
        'import hashlib\n'
        'import json\n'
        'import os\n'
        'from pathlib import Path\n'
        'import shutil\n'
        'import tempfile\n'
        '\n'
        'from .gate import verify\n'
        'from omega_platform.budget import BUILD_BUDGET\n'
        'from omega_platform.sandbox import c_tool,run as isolated_run\n'
        '\n'
        '\n'
        'def bytecode(ast):\n'
        '    op = ast[0]\n'
        '    if op in ("c", "v"):\n'
        '        return [[op, ast[1]]]\n'
        '    return [i for child in ast[1:] for i in bytecode(child)] + [[op]]\n'
        '\n'
        '\n'
        'def source(certificate):\n'
        '    if not verify(certificate):\n'
        '        raise ValueError("O backend nativo exige um certificado válido")\n'
        '    code = bytecode(certificate["ast"])\n'
        '    statements = []\n'
        '    for ins in code:\n'
        '        op = ins[0]\n'
        '        if op == "c":\n'
        '            line = f"s[p++] = {ins[1]};"\n'
        '        elif op == "v":\n'
        '            line = f"s[p++] = (row >> {ins[1]}) & 1u;"\n'
        '        elif op == "not":\n'
        '            line = "s[p-1] = !s[p-1];"\n'
        '        elif op == "ite":\n'
        '            line = "s[p-3] = s[p-3] ? s[p-1] : s[p-2]; p -= 2;"\n'
        '        else:\n'
        '            symbol = {"and": "&", "or": "|", "xor": "^"}[op]\n'
        '            line = f"s[p-2] = s[p-2] {symbol} s[p-1]; --p;"\n'
        '        statements.append("  " + line)\n'
        '    rows = certificate["checked_rows"]\n'
        '    return """/* Generated from a validated Omega Boolean certificate. */\n'
        '#include <stdio.h>\n'
        '#include <stdlib.h>\n'
        '#include <errno.h>\n'
        'static unsigned circuit(unsigned row) {\n'
        '  (void)row;\n'
        '""" + f"  unsigned s[{len(code)}], p = 0;\\n" + "\\n".join(statements) + """\n'
        '  return s[0];\n'
        '}\n'
        'int main(int argc, char **argv) {\n'
        '  if (argc == 2) {\n'
        '    char *end = NULL;\n'
        '    errno = 0;\n'
        '    unsigned long row = strtoul(argv[1], &end, 10);\n'
        '""" + f"    if (errno || !argv[1][0] || argv[1][0] == \'-\' || *end || row >= {rows}u) return 2;\\n" + """\n'
        '    printf("%u\\\\n", circuit((unsigned)row));\n'
        '    return 0;\n'
        '  }\n'
        '  if (argc != 1) return 2;\n'
        "  putchar('[');\n"
        '""" + f"  for (unsigned row = 0; row < {rows}u; ++row) {{\\n" + """\n'
        "    if (row) putchar(',');\n"
        '    printf("%u", circuit(row));\n'
        '  }\n'
        '  puts("]");\n'
        '  return 0;\n'
        '}\n'
        '"""\n'
        '\n'
        '\n'
        'def digest(path):\n'
        '    return hashlib.sha256(Path(path).read_bytes()).hexdigest()\n'
        '\n'
        '\n'
        'def build(certificate, destination, cc=None):\n'
        '    """Compile and exhaustively validate before publishing an executable."""\n'
        '    code = source(certificate)\n'
        '    compiler = shutil.which(cc or os.environ.get("CC", "cc"))\n'
        '    if compiler is None:\n'
        '        raise RuntimeError("Compilador C não encontrado; instale GCC ou Clang")\n'
        '    target = Path(destination)\n'
        '    if target.exists() or target.with_suffix(".c").exists():\n'
        '        raise ValueError("O destino nativo já existe")\n'
        '    target.parent.mkdir(parents=True, exist_ok=True)\n'
        '    with tempfile.TemporaryDirectory(prefix=".omega-native-", dir=target.parent) as tmp:\n'
        '        src, exe = Path(tmp) / "circuit.c", Path(tmp) / "circuit"\n'
        '        src.write_text(code, encoding="utf-8")\n'
        '        proc = c_tool([compiler, "-std=c11", "-O2", "-Wall", "-Wextra", "-Werror",\n'
        '                        str(src.resolve()), "-o", str(exe.resolve())],inputs=[src],\n'
        '                        output_directory=Path(tmp),budget=BUILD_BUDGET)\n'
        '        if proc.returncode:\n'
        '            raise RuntimeError("Compilação C falhou: " + proc.stderr[-4000:])\n'
        '        result = isolated_run([str(exe.resolve())])\n'
        '        if result.returncode or json.loads(result.stdout) != certificate["task"]["outputs"]:\n'
        '            raise ValueError("Executável diverge da especificação exata")\n'
        '        metadata = {"backend": "c11-boolean-stack", "compiler": compiler,\n'
        '                    "checked_rows": certificate["checked_rows"],\n'
        '                    "source_sha256": digest(src), "binary_sha256": digest(exe)}\n'
        '        os.replace(src, target.with_suffix(".c"))\n'
        '        os.replace(exe, target)\n'
        '    return metadata\n'
    ),
    ('omega_nextorch/orange/OWOmegaCertifier.py',
        '"""Finite-domain synthesis with explicit proof gating and no stale outputs."""\n'
        'import tempfile\n'
        'from pathlib import Path\n'
        '\n'
        'from Orange.data import Table\n'
        'from Orange.widgets import gui\n'
        'from Orange.widgets.settings import Setting\n'
        'from Orange.widgets.utils.concurrent import ConcurrentWidgetMixin\n'
        'from Orange.widgets.widget import Input, Msg, Output, OWWidget\n'
        '\n'
        'from omega_nextorch.gate import load_verified\n'
        'from omega_nextorch.orange_bridge import task_from_table\n'
        'from omega_nextorch.pipeline import synthesize\n'
        'from omega_nextorch.proposer import NeuralBudget\n'
        '\n'
        '\n'
        'def certify_table(data, epochs, require_lean, state):\n'
        '    task = task_from_table(data)\n'
        '    state.set_status("Nextorch propõe; Ômega verifica todas as entradas")\n'
        '    with tempfile.TemporaryDirectory(prefix="omega-orange-") as tmp:\n'
        '        target = Path(tmp) / "result"\n'
        '        manifest = synthesize([task], target, NeuralBudget(epochs=epochs), require_lean)\n'
        '        if state.is_interruption_requested():\n'
        '            return None\n'
        '        return load_verified(target / "task_000.json"), manifest["tasks"][0]\n'
        '\n'
        '\n'
        'class OWOmegaCertifier(OWWidget, ConcurrentWidgetMixin):\n'
        '    name = "Omega Certifier"\n'
        '    description = "Certifica a síntese neural em uma tabela-verdade booleana completa."\n'
        '    icon = "omega.svg"\n'
        '    priority = 10\n'
        '    want_main_area = False\n'
        '    epochs = Setting(20)\n'
        '    require_lean = Setting(True)\n'
        '\n'
        '    class Inputs:\n'
        '        data = Input("Truth Table", Table)\n'
        '\n'
        '    class Outputs:\n'
        '        certificate = Output("Certified Circuit", dict, auto_summary=False)\n'
        '        report = Output("Admission Report", dict, auto_summary=False)\n'
        '\n'
        '    class Error(OWWidget.Error):\n'
        '        failed = Msg("{}")\n'
        '\n'
        '    def __init__(self):\n'
        '        super().__init__()\n'
        '        ConcurrentWidgetMixin.__init__(self)\n'
        '        self.data = None\n'
        '        box = gui.vBox(self.controlArea, "Ômega + Nextorch")\n'
        '        gui.spin(box, self, "epochs", 1, 1000, label="Épocas")\n'
        '        gui.checkBox(box, self, "require_lean", "Exigir prova Lean 4")\n'
        '        gui.button(box, self, "Sintetizar e certificar", callback=self.apply)\n'
        '        self.summary = gui.label(box, self, "Conecte uma tabela-verdade completa (0/1).")\n'
        '\n'
        '    @Inputs.data\n'
        '    def set_data(self, data):\n'
        '        self.cancel()\n'
        '        self.data = data\n'
        '        self.Error.failed.clear()\n'
        '        self.Outputs.certificate.send(None)\n'
        '        self.Outputs.report.send(None)\n'
        '        self.summary.setText("Conecte uma tabela-verdade completa (0/1)." if data is None\n'
        '                             else f"{len(data)} linhas; clique para certificar.")\n'
        '\n'
        '    def apply(self):\n'
        '        self.cancel()\n'
        '        self.Error.failed.clear()\n'
        '        self.Outputs.certificate.send(None)\n'
        '        self.Outputs.report.send(None)\n'
        '        if self.data is not None:\n'
        '            self.start(certify_table, self.data, self.epochs, self.require_lean)\n'
        '\n'
        '    def on_done(self, result):\n'
        '        if result is not None:\n'
        '            certificate, report = result\n'
        '            self.Outputs.certificate.send(certificate)\n'
        '            self.Outputs.report.send(report)\n'
        '            self.summary.setText(f"Certificado: {certificate[\'checked_rows\']} linhas verificadas.")\n'
        '\n'
        '    def on_exception(self, error):\n'
        '        self.Error.failed(str(error))\n'
        '\n'
        '    def onDeleteWidget(self):\n'
        '        self.shutdown()\n'
        '        super().onDeleteWidget()\n'
    ),
