    ('omega_nextorch/orange_bridge.py',
        '"""Complete Boolean Orange tables become explicit Omega specifications."""\n'
        'from .gate import validate_domain\n'
        '\n'
        '\n'
        'def task_from_table(table, task_id="orange"):\n'
        '    import numpy as np\n'
        '\n'
        '    attrs = table.domain.attributes\n'
        '    classes = table.domain.class_vars\n'
        '    if not 0 <= len(attrs) <= 12 or len(classes) != 1 or len(table) != 2 ** len(attrs):\n'
        '        raise ValueError("Forneça uma tabela-verdade completa, até 12 entradas e um alvo")\n'
        '\n'
        '    def bit(value, variable):\n'
        '        number = float(value)\n'
        '        if not np.isfinite(number):\n'
        '            raise ValueError("Valores ausentes não definem uma especificação exata")\n'
        '        if variable.is_discrete:\n'
        '            if number != int(number) or not 0 <= int(number) < len(variable.values):\n'
        '                raise ValueError("Código categórico inválido")\n'
        '            label = variable.values[int(number)]\n'
        '            if label not in ("0", "1"):\n'
        '                raise ValueError("Categorias devem ser os rótulos 0 e 1")\n'
        '            return int(label)\n'
        '        if number not in (0.0, 1.0):\n'
        '            raise ValueError("A ponte exata exige valores booleanos 0/1")\n'
        '        return int(number)\n'
        '\n'
        '    outputs = [None] * len(table)\n'
        '    for row in table:\n'
        '        index = sum(bit(row[var], var) << i for i, var in enumerate(attrs))\n'
        '        if outputs[index] is not None:\n'
        '            raise ValueError("Linha de entrada duplicada; domínio incompleto")\n'
        '        outputs[index] = bit(row[classes[0]], classes[0])\n'
        '    task = {"id": task_id, "arity": len(attrs), "outputs": outputs}\n'
        '    validate_domain(task)\n'
        '    return task\n'
    ),
    ('omega_nextorch/pipeline.py',
        '"""Omega-owned orchestration and atomic admission of Nextorch proposals."""\n'
        'from __future__ import annotations\n'
        '\n'
        'from dataclasses import asdict\n'
        'import json\n'
        'import os\n'
        'from pathlib import Path\n'
        'import shutil\n'
        'import tempfile\n'
        '\n'
        'from omega_open.checker import fingerprint\n'
        'from .gate import certify, load_verified, validate_domain\n'
        'from . import lean, native\n'
        'from .proposer import NeuralBudget, propose\n'
        '\n'
        'FORMAT = "omega-nextorch-run-1"\n'
        '\n'
        '\n'
        'def write_json(path, data):\n'
        '    Path(path).write_text(json.dumps(data, ensure_ascii=False, indent=2, sort_keys=True,\n'
        '                                    allow_nan=False) + "\\n", encoding="utf-8")\n'
        '\n'
        '\n'
        'def synthesize(tasks, destination, budget=None, require_lean=False, build_native=False):\n'
        '    if type(tasks) is not list or not 1 <= len(tasks) <= 32:\n'
        '        raise ValueError("Forneça entre 1 e 32 tarefas")\n'
        '    for task in tasks:\n'
        '        validate_domain(task)\n'
        '    if len({t["id"] for t in tasks}) != len(tasks):\n'
        '        raise ValueError("IDs duplicados")\n'
        '    target = Path(destination).resolve()\n'
        '    if target.exists():\n'
        '        raise ValueError("O diretório de saída já existe; escolha um novo destino")\n'
        '    budget = budget or NeuralBudget()\n'
        '    target.parent.mkdir(parents=True, exist_ok=True)\n'
        '    stage = Path(tempfile.mkdtemp(prefix=".omega-admission-", dir=target.parent))\n'
        '    try:\n'
        '        records = []\n'
        '        for index, task in enumerate(tasks):\n'
        '            proposals, diagnostics = propose(task, budget)\n'
        '            accepted, decisions = [], []\n'
        '            for origin, ast in proposals:\n'
        '                decision = {"origin": origin, "proposal_sha256": fingerprint(ast)}\n'
        '                try:\n'
        '                    cert = certify(task, ast, origin)\n'
        '                except (ValueError, TypeError, RecursionError, OverflowError) as exc:\n'
        '                    decision.update(accepted=False, reason=str(exc))\n'
        '                else:\n'
        '                    accepted.append(cert)\n'
        '                    decision.update(accepted=True, certificate_sha256=cert["sha256"])\n'
        '                decisions.append(decision)\n'
        '            if not accepted:\n'
        '                raise ValueError("Nenhuma proposta passou pelo núcleo Ômega: " + task["id"])\n'
        '            selected = min(accepted, key=lambda c: (c["metrics"]["nos"],\n'
        '                                                   c["metrics"]["profundidade"], c["origin"]))\n'
        '            stem = f"task_{index:03d}"\n'
        '            write_json(stage / (stem + ".json"), selected)\n'
        '            record = {"id": task["id"], "certificate": stem + ".json",\n'
        '                      "diagnostics": diagnostics, "decisions": decisions,\n'
        '                      "selected_origin": selected["origin"], "lean": None, "native": None}\n'
        '            if require_lean:\n'
        '                record["lean"] = lean.check(selected, stage / (stem + ".lean"))\n'
        '            if build_native:\n'
        '                record["native"] = native.build(selected, stage / stem)\n'
        '            records.append(record)\n'
        '        manifest = {"format": FORMAT, "budget": asdict(budget), "tasks": records,\n'
        '                    "nextorch_commit": "d449ab637fc3f89749075714c4d7bd7a2d0bf198"}\n'
        '        manifest["sha256"] = fingerprint(manifest)\n'
        '        write_json(stage / "manifest.json", manifest)\n'
        '        # No active result is published until every required gate succeeds.\n'
        '        os.rename(stage, target)\n'
        '        return manifest\n'
        '    finally:\n'
        '        if stage.exists():\n'
        '            shutil.rmtree(stage)\n'
        '\n'
        '\n'
        'def audit(directory, recheck_lean=False, recheck_native=False):\n'
        '    directory = Path(directory)\n'
        '    manifest_path = directory / "manifest.json"\n'
        '    if manifest_path.stat().st_size > 8_000_000:\n'
        '        raise ValueError("Manifesto muito grande")\n'
        '    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))\n'
        '    if manifest.get("format") != FORMAT or manifest.get("sha256") != fingerprint(\n'
        '            {k: v for k, v in manifest.items() if k != "sha256"}):\n'
        '        raise ValueError("Manifesto inválido")\n'
        '    records = manifest["tasks"]\n'
        '    if type(records) is not list or not 1 <= len(records) <= 32:\n'
        '        raise ValueError("Lista de tarefas inválida")\n'
        '    checked = 0\n'
        '    for i, record in enumerate(records):\n'
        '        stem = f"task_{i:03d}"\n'
        '        if record["certificate"] != stem + ".json":\n'
        '            raise ValueError("Caminho de certificado inválido")\n'
        '        certificate = load_verified(directory / (stem + ".json"))\n'
        '        if record["id"] != certificate["task"]["id"] or record["selected_origin"] != certificate["origin"]:\n'
        '            raise ValueError("Manifesto diverge do certificado")\n'
        '        if record["lean"] is not None:\n'
        '            if (directory / (stem + ".lean")).read_text(encoding="utf-8") != lean.source(certificate):\n'
        '                raise ValueError("Fonte da prova Lean adulterada")\n'
        '        if recheck_lean:\n'
        '            lean.check(certificate)\n'
        '        if record["native"] is not None:\n'
        '            code = directory / (stem + ".c")\n'
        '            if code.read_text(encoding="utf-8") != native.source(certificate):\n'
        '                raise ValueError("Fonte nativa adulterada")\n'
        '            if native.digest(directory / stem) != record["native"]["binary_sha256"]:\n'
        '                raise ValueError("Binário nativo adulterado")\n'
        '            if native.digest(code) != record["native"]["source_sha256"]:\n'
        '                raise ValueError("Hash da fonte nativa incorreto")\n'
        '        if recheck_native:\n'
        '            # Never execute an arbitrary binary supplied by an artifact directory.\n'
        '            with tempfile.TemporaryDirectory(prefix="omega-reaudit-") as tmp:\n'
        '                native.build(certificate, Path(tmp) / "circuit")\n'
        '        checked += certificate["checked_rows"]\n'
        '    return {"valid": True, "tasks": len(records), "checked_rows": checked,\n'
        '            "lean_rechecked": recheck_lean, "native_rebuilt": recheck_native}\n'
    ),
    ('omega_nextorch/proposer.py',
        '"""Bounded Nextorch proposals, explicitly separate from exact admission."""\n'
        'from __future__ import annotations\n'
        '\n'
        'from dataclasses import dataclass\n'
        '\n'
        'from omega_open import logic\n'
        'from .gate import validate_domain\n'
        '\n'
        '\n'
        '@dataclass(frozen=True)\n'
        'class NeuralBudget:\n'
        '    epochs: int = 80\n'
        '    width: int = 16\n'
        '    candidates: int = 4\n'
        '    policy_steps: int = 3\n'
        '    seed: int = 42\n'
        '\n'
        '    def __post_init__(self):\n'
        '        for name, upper in (("epochs", 1000), ("width", 128), ("candidates", 32),\n'
        '                            ("policy_steps", 100)):\n'
        '            value = getattr(self, name)\n'
        '            if type(value) is not int or not 1 <= value <= upper:\n'
        '                raise ValueError(f"{name} deve estar entre 1 e {upper}")\n'
        '        if type(self.seed) is not int or not 0 <= self.seed < 2**32:\n'
        '            raise ValueError("Seed inválida")\n'
        '\n'
        '\n'
        'def propose(task, budget):\n'
        '    validate_domain(task)\n'
        '    try:\n'
        '        import torch\n'
        '        from nextorch import NextorchModel, seed_everything\n'
        '    except ImportError as exc:\n'
        '        raise RuntimeError("Instale o extra neural: pip install -e \'.[neural]\'") from exc\n'
        '    seed_everything(budget.seed)\n'
        '    n = task["arity"]\n'
        '    # A constant input supports the valid zero-arity Boolean domain.\n'
        '    x = torch.tensor([[(row >> j) & 1 for j in range(max(n, 1))]\n'
        '                      for row in range(len(task["outputs"]))], dtype=torch.float32)\n'
        '    y = torch.tensor(task["outputs"], dtype=torch.long)\n'
        '    model = NextorchModel.from_tensor(x, width=budget.width, candidates=budget.candidates,\n'
        '                                     policy_steps=budget.policy_steps)\n'
        '    history = model.fit(x, y, epochs=budget.epochs, lr=0.03)\n'
        '    with torch.no_grad():\n'
        '        logits = model(x)\n'
        '        if not torch.isfinite(logits).all():\n'
        '            raise ValueError("Nextorch produziu valores não finitos")\n'
        '        predicted = logits.argmax(-1).tolist()\n'
        '        trajectory = model.trajectory(x)\n'
        '        _, features = model.sae(trajectory[-1])\n'
        '        active = float((features != 0).float().sum(-1).mean())\n'
        '    # Saliency selects variable order. It cannot establish circuit correctness.\n'
        '    probe = x.clone().requires_grad_(True)\n'
        '    scores = model(probe)\n'
        '    gradients = torch.autograd.grad((scores[:, 1] - scores[:, 0]).sum(), probe)[0]\n'
        '    importance = gradients.abs().mean(0).tolist()\n'
        '    order = sorted(range(n), key=lambda j: (-importance[j], j))\n'
        '    return [\n'
        '        ("nextorch:predicted-table", logic.encode(logic.anf(predicted, n))),\n'
        '        ("nextorch:saliency+exact-shannon",\n'
        '         logic.encode(logic.shannon(task["outputs"], n, order))),\n'
        '    ], {\n'
        '        "training_rows": len(y), "evaluation": "exhaustive specification, not held-out generalization",\n'
        '        "epochs": len(history), "first_loss": history[0], "last_loss": history[-1],\n'
        '        "prediction_matches": sum(a == b for a, b in zip(predicted, task["outputs"])),\n'
        '        "variable_order": order, "mean_active_sae_features": active,\n'
        '        "latent_steps": model.thought_steps,\n'
        '        "architecture": model.graph.architecture.to_dict(),\n'
        '    }\n'
    ),
    ('omega_nextorch/reward_integrity.py',
        '"""External judgments remain hidden from candidate selection feedback."""\n'
        'def crosscheck(problem,candidate,development_verifier,external_verifier):\n'
        '    development=development_verifier(problem,candidate);external=external_verifier(problem,candidate)\n'
        "    if type(development) is not bool or type(external) is not bool:raise ValueError('Boolean independent judgments required')\n"
        "    return {'development':development,'external':external,'disagreement':development!=external,'accepted':development and external}\n"
        'def discrepancy(development,external):\n'
        "    if not development or len(development)!=len(external):raise ValueError('Paired verifier observations required')\n"
        '    opportunistic=sum(a and not b for a,b in zip(development,external))\n'
        "    return {'cases':len(development),'opportunistic_cases':opportunistic,'rate':opportunistic/len(development)}\n"
    ),
    ('omega_nextorch/routing.py',
        'import math\n'
        'class Router:\n'
        '    def __init__(self):self.metrics={}\n'
        '    def observe(self,domain,model,correct,cost):\n'
        "        if type(correct) is not bool or not math.isfinite(cost) or cost<=0:raise ValueError('Invalid routing observation')\n"
        '        key=(domain,model);n,success,total=self.metrics.get(key,(0,0,0.0));self.metrics[key]=(n+1,success+correct,total+cost)\n'
        '    def choose(self,domain,models,min_success=.5):\n'
        '        ranked=[]\n'
        '        for model in models:\n'
        '            n,success,cost=self.metrics.get((domain,model),(0,0,0))\n'
        '            if n and success/n>=min_success:ranked.append((-(success+1)/(n+2)/(cost/n),model))\n'
        "        if not ranked:raise ValueError('No model has sufficient routing evidence')\n"
        '        return min(ranked)[1]\n'
    ),
    ('omega_nextorch/supervised_training.py',
        '"""Budgeted supervised optimization; held-out measurement remains a separate caller."""\n'
        "def train(model,batches,*,steps=100,learning_rate=.001,device='cpu',grad_clip=1.0):\n"
        '    import torch\n'
        "    if not 1<=steps<=100000 or not 0<learning_rate<=1 or grad_clip<=0:raise ValueError('Invalid training configuration')\n"
        '    model=model.to(device);model.train();optimizer=torch.optim.AdamW(model.parameters(),lr=learning_rate);history=[]\n'
        '    for inputs,targets in batches:\n'
        '        if len(history)>=steps:break\n'
        '        inputs=inputs.to(device);targets=targets.to(device)\n'
        "        if inputs.numel()>10000000 or targets.numel()>10000000:raise ValueError('Batch element budget exceeded')\n"
        '        logits=model(inputs)\n'
        '        loss=torch.nn.functional.cross_entropy(logits.reshape(-1,logits.shape[-1]),targets.reshape(-1),ignore_index=-100)\n'
        "        if not torch.isfinite(loss):raise FloatingPointError('Nonfinite supervised loss')\n"
        '        optimizer.zero_grad(set_to_none=True);loss.backward();torch.nn.utils.clip_grad_norm_(model.parameters(),grad_clip);optimizer.step()\n'
        '        history.append(float(loss.detach()))\n'
        "    return {'steps':len(history),'training_loss':tuple(history),'optimizer_state':optimizer.state_dict(),'heldout_evaluated':False}\n"
    ),
    ('omega_nextorch/tokenizer.py',
        '"""Lossless UTF-8 byte tokenizer, versioned independently of neural weights."""\n'
        "VERSION='omega-byte-tokenizer-1'\n"
        'BOS,EOS,PAD=256,257,258\n'
        'VOCAB_SIZE=259\n'
        'def encode(text,*,boundaries=True,max_bytes=65536):\n'
        "    if type(text) is not str:raise TypeError('Text required')\n"
        "    data=text.encode('utf-8')\n"
        "    if len(data)>max_bytes:raise ValueError('Token budget exceeded')\n"
        '    return ([BOS] if boundaries else [])+list(data)+([EOS] if boundaries else [])\n'
        'def decode(tokens):\n'
        '    tokens=tuple(tokens)\n'
        "    if len(tokens)>65538 or any(type(v) is not int or not 0<=v<VOCAB_SIZE for v in tokens):raise ValueError('Invalid token stream')\n"
        '    if tokens and tokens[0]==BOS:tokens=tokens[1:]\n'
        '    if tokens and tokens[-1]==EOS:tokens=tokens[:-1]\n'
        "    if any(v>255 for v in tokens):raise ValueError('Special token inside text')\n"
        "    return bytes(tokens).decode('utf-8')\n"
        "def descriptor():return {'version':VERSION,'vocab_size':VOCAB_SIZE,'encoding':'utf-8','normalization':'none'}\n"
    ),
    ('omega_nextorch/uncertainty.py',
        'import math\n'
        'def entropy(probabilities):\n'
        '    values=tuple(probabilities)\n'
        "    if not values or any(not math.isfinite(p) or p<0 for p in values) or abs(sum(values)-1)>1e-6:raise ValueError('Probability simplex required')\n"
        '    return -sum(p*math.log(p) for p in values if p)\n'
        'def selective_risk(confidences,correct,threshold):\n'
        "    if len(confidences)!=len(correct) or not 0<=threshold<=1:raise ValueError('Invalid selective observations')\n"
        '    accepted=[bool(ok) for c,ok in zip(confidences,correct) if c>=threshold]\n'
        "    return {'coverage':len(accepted)/len(correct) if correct else 0.0,\n"
        "            'risk':1-sum(accepted)/len(accepted) if accepted else None,'accepted':len(accepted)}\n"
        'def abstain(probabilities,threshold=.8):\n'
        '    entropy(probabilities)\n'
        '    return max(probabilities)<threshold\n'
    ),
    ('omega_nextorch/verified_search.py',
        '"""Verifier-in-the-loop proposal search, with immutable attempt accounting."""\n'
        'import time\n'
        'def search(problem,model,decode,verify,*,max_candidates=32,seconds=30):\n'
        "    if not 1<=max_candidates<=256 or not 0<seconds<=3600:raise ValueError('Invalid neural search budget')\n"
        '    start=time.monotonic();attempts=[]\n'
        '    for raw in model.propose(problem,max_candidates):\n'
        '        if len(attempts)>=max_candidates or time.monotonic()-start>=seconds:break\n'
        '        candidate=decode(raw);result=verify(problem,candidate)\n'
        "        if type(result) is not dict or type(result.get('valid')) is not bool:raise ValueError('Verifier protocol error')\n"
        "        attempts.append({'valid':result['valid'],'elapsed':time.monotonic()-start})\n"
        "        if result['valid']:return {'candidate':candidate,'certificate':result.get('certificate'),'attempts':tuple(attempts)}\n"
        "    return {'candidate':None,'certificate':None,'attempts':tuple(attempts)}\n"
    ),
