    ('omega_open/checker.py',
        '"""Microverificador sem dependência do sintetizador nem de seu avaliador.\n'
        '\n'
        'Verifica semântica total em Bool^n; NÃO prova equivalência sobre R nem AGI.\n'
        '"""\n'
        'from __future__ import annotations\n'
        'import hashlib\n'
        'import json\n'
        '\n'
        "OPS={'const':0,'c':1,'v':1,'not':1,'and':2,'or':2,'xor':2,'ite':3}\n"
        '\n'
        'def canonical(obj):\n'
        "    return json.dumps(obj,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode('utf-8')\n"
        '\n'
        'def fingerprint(obj):\n'
        '    return hashlib.sha256(canonical(obj)).hexdigest()\n'
        '\n'
        'def evaluate(node,bits,arity,fuel=100000):\n'
        '    """Iterador de programa prefixado: sem eval/exec nem imports de executor."""\n'
        '    # Valida tipagem e executa recursão restrita por combustível.\n'
        '    if fuel <= 0 or not isinstance(node,list) or not node or not isinstance(node[0],str):\n'
        "        raise ValueError('AST inválida/limite de combustível')\n"
        '    op=node[0]\n'
        "    if op not in OPS or len(node)-1 != OPS[op]:raise ValueError('Operação/aridade inválida')\n"
        "    if op=='c':\n"
        "        if type(node[1]) is not int or node[1] not in (0,1):raise ValueError('Constante inválida')\n"
        '        return node[1]\n'
        "    if op=='v':\n"
        "        if type(node[1]) is not int or not 0<=node[1]<arity:raise ValueError('Variável inválida')\n"
        '        return int(bool(bits&(1<<node[1])))\n'
        "    if op=='not': return 1-evaluate(node[1],bits,arity,fuel-1)\n"
        "    if op=='ite':\n"
        '        test=evaluate(node[1],bits,arity,fuel-1)\n'
        '        # valida somente ramo alcançado? Check structural every node separately.\n'
        '        return evaluate(node[3] if test else node[2],bits,arity,fuel-1)\n'
        '    left=evaluate(node[1],bits,arity,fuel-1)\n'
        '    right=evaluate(node[2],bits,arity,fuel-1)\n'
        "    if op=='and': return int(bool(left and right))\n"
        "    if op=='or': return int(bool(left or right))\n"
        '    return (left+right)%2\n'
        '\n'
        'def validate_tree(node,arity,budget=200000):\n'
        '    stack=[node]\n'
        '    count=0\n'
        '    while stack:\n'
        '        count+=1\n'
        "        if count>budget:raise ValueError('AST excede orçamento')\n"
        '        x=stack.pop()\n'
        "        if not isinstance(x,list) or not x or x[0] not in ('c','v','not','and','or','xor','ite'):\n"
        "            raise ValueError('Nó inválido')\n"
        '        op=x[0]\n'
        "        if len(x)!=OPS[op]+1:raise ValueError('Número de operandos inválido')\n"
        "        if op=='v' and (type(x[1]) is not int or x[1]<0 or x[1]>=arity):raise ValueError('Índice de variável inválido')\n"
        "        if op=='c' and (type(x[1]) is not int or x[1] not in (0,1)):raise ValueError('Constante inválida')\n"
        "        if op not in ('v','c'):stack.extend(x[1:])\n"
        '    return True\n'
        '\n'
        'def validate_task(t,max_rows=4096):\n'
        "    if type(t) is not dict or set(t)!={'id','arity','outputs'}:raise ValueError('Tarefa deve conter id, arity, outputs')\n"
        "    n=t['arity']; outputs=t['outputs']\n"
        "    if type(t['id']) is not str or not t['id'] or len(t['id'])>100:raise ValueError('Identificador inválido')\n"
        "    if type(n) is not int or n<0:raise ValueError('Número de entradas inválido')\n"
        '    if type(outputs) is not list or len(outputs)>max_rows or len(outputs)!=(1<<n):\n'
        "        raise ValueError('Tabela excede orçamento ou tem dimensão inválida')\n"
        "    if any(type(v) is not int or v not in (0,1) for v in outputs):raise ValueError('Saídas devem ser bits')\n"
        '    return True\n'
        '\n'
        'def verify_solution(task,solution,max_rows=4096,max_nodes=200000):\n'
        '    try:\n'
        '        validate_task(task,max_rows)\n'
        "        if type(solution) is not dict or set(solution)!={'ast','semantica_sha256','metricas','estrategia'}:return False\n"
        "        n=task['arity'];ast=solution['ast']\n"
        '        validate_tree(ast,n,max_nodes)\n'
        "        outputs=[evaluate(ast,i,n) for i in range(len(task['outputs']))]\n"
        "        if outputs!=task['outputs']:return False\n"
        "        if solution['semantica_sha256']!=fingerprint({'arity':n,'outputs':outputs}):return False\n"
        '        # Independently tally unique nodes and DAG depth.\n'
        '        seen=set()\n'
        '        def tally(x):\n'
        '            k=canonical(x)\n'
        '            if k in seen:return\n'
        '            seen.add(k)\n'
        '            for child in x[1:]:\n'
        '                if isinstance(child,list):tally(child)\n'
        '        tally(ast)\n'
        '        def depth(x):return 1+max((depth(c) for c in x[1:] if isinstance(c,list)),default=0)\n'
        "        reported=solution['metricas']\n"
        "        if type(reported) is not dict or reported.get('nos')!=len(seen) or reported.get('profundidade')!=depth(ast):return False\n"
        "        if reported.get('operacoes')!=sum(json.loads(x)[0] not in ('c','v') for x in seen):return False\n"
        "        return type(solution['estrategia']) is str\n"
        '    except (ValueError,TypeError,KeyError,IndexError,RecursionError,OverflowError):\n'
        '        return False\n'
    ),
    ('omega_open/engine.py',
        '"""Ômega 1.3: síntese aberta (Bool^n), metapolítica mutável e trilha auditável.\n'
        '\n'
        "Cada execução é finita, com orçamentos explícitos. 'Aberta' significa que\n"
        'não existe lista fixa de tarefas nem teto hardcoded de gerações.\n'
        '"""\n'
        'from __future__ import annotations\n'
        'from itertools import product\n'
        'from pathlib import Path\n'
        'import json\n'
        '\n'
        'from . import logic\n'
        'from .checker import validate_task,verify_solution,fingerprint\n'
        '\n'
        "FORMAT='omega-open-chain-1'\n"
        'BASE=(0,0,0)\n'
        '\n'
        '\n'
        'def source_policy(weights):\n'
        '    a,b,c=weights\n'
        '    return ("# Omega 1.3: programa substituivel de priorizacao\\n"\n'
        '            "parametro nos = 0;\\nparametro profundidade = 0;\\nparametro operacoes = 0;\\n"\n'
        '            f"tensor prioridade = ({a}) * nos + ({b}) * profundidade + ({c}) * operacoes;\\n"\n'
        '            "mostrar prioridade;\\n")\n'
        '\n'
        '\n'
        'def canonical_write(path,obj):\n'
        "    Path(path).write_text(json.dumps(obj,ensure_ascii=False,sort_keys=True,indent=2)+'\\n',encoding='utf-8')\n"
        '\n'
        '\n'
        'def model_candidates(task,orders=12,max_nodes=200000):\n'
        '    result=[]\n'
        "    n=task['arity'];tab=task['outputs']\n"
        '    for name,expr in logic.candidates(tab,n,orders):\n'
        '        m=logic.metrics(expr)\n'
        "        if m['nos']>max_nodes:continue\n"
        "        witness={'estrategia':name,'ast':logic.encode(expr),'metricas':m,\n"
        "                 'semantica_sha256':fingerprint({'arity':n,'outputs':tab})}\n"
        '        if not verify_solution(task,witness,max_rows=max(len(tab),1),max_nodes=max_nodes):\n'
        "            raise RuntimeError('Inconsistência: o verificador rejeitou uma hipótese gerada')\n"
        '        result.append(witness)\n'
        "    if not result:raise ValueError('Orçamento de nós insuficiente para sintetizar a tarefa '+task['id'])\n"
        '    return result\n'
        '\n'
        '\n'
        'def priority(weights,metrics):\n'
        "    return sum(int(w)*metrics[k] for w,k in zip(weights,('nos','profundidade','operacoes')))\n"
        '\n'
        '\n'
        'def select(models,weights):\n'
        "    return min(enumerate(models),key=lambda t:(priority(weights,t[1]['metricas']),t[0]))[1]\n"
        '\n'
        '\n'
        'def measure(models,weights,train_ids):\n'
        '    chosen={tid:select(options,weights) for tid,options in models.items()}\n'
        "    train=[chosen[i]['metricas'] for i in train_ids]\n"
        "    return (sum(x['nos'] for x in train),sum(x['profundidade'] for x in train))\n"
        '\n'
        '\n'
        'def policy_search(models,train_ids,radius):\n'
        '    # A exploração é expandida a cada geração; não há número fixo de políticas.\n'
        "    if radius<1:raise ValueError('Raio deve ser positivo')\n"
        '    choices=product(range(radius+1),repeat=3)\n'
        '    return min(choices,key=lambda p:(measure(models,p,train_ids),sum(p),p))\n'
        '\n'
        '\n'
        'def record(index,radius,weights,models,train_ids,prev):\n'
        '    selected={tid:select(options,weights) for tid,options in models.items()}\n'
        '    tr=set(train_ids)\n'
        '    cost=measure(models,weights,train_ids)\n'
        "    test=[v['metricas'] for k,v in selected.items() if k not in tr]\n"
        "    row={'generation':index,'radius':radius,'weights':list(weights),\n"
        "         'training_cost':list(cost),\n"
        "         'holdout_cost':[sum(x['nos'] for x in test),sum(x['profundidade'] for x in test)],\n"
        "         'solutions':selected,'source_sha256':fingerprint(source_policy(weights)),\n"
        "         'previous':prev}\n"
        "    row['id']=fingerprint(row)\n"
        '    return row\n'
        '\n'
        '\n'
        'def build(tasks,train_ids,generations=3,max_rows=4096,max_orders=12,max_nodes=200000):\n'
        "    if type(tasks) is not list or not tasks:raise ValueError('Liste ao menos uma tarefa')\n"
        "    if not isinstance(generations,int) or generations<0:raise ValueError('Gerações inválidas')\n"
        "    if max_orders<1 or max_nodes<1 or max_rows<1:raise ValueError('Orçamentos inválidos')\n"
        '    for t in tasks:validate_task(t,max_rows)\n'
        "    ids=[x['id'] for x in tasks]\n"
        "    if len(set(ids))!=len(ids):raise ValueError('IDs de tarefas duplicados')\n"
        '    if not train_ids or len(set(train_ids))!=len(train_ids) or not set(train_ids)<=set(ids):\n'
        "        raise ValueError('Informe um conjunto de treinamento não vazio e válido')\n"
        "    models={t['id']:model_candidates(t,max_orders,max_nodes) for t in tasks}\n"
        "    rows=[record(0,0,BASE,models,train_ids,'GENESIS')]\n"
        '    for radius in range(1,generations+1):\n'
        '        cand=policy_search(models,train_ids,radius)\n'
        "        new=record(len(rows),radius,cand,models,train_ids,rows[-1]['id'])\n"
        "        if tuple(new['training_cost']) < tuple(rows[-1]['training_cost']):\n"
        '            rows.append(new)\n'
        "    chain={'format':FORMAT,'tasks':tasks,'train_ids':list(train_ids),\n"
        "           'max_orders':max_orders,'max_nodes':max_nodes,'max_rows':max_rows,\n"
        "           'searched_radii':generations,'generations':rows}\n"
        "    chain['sha256']=fingerprint(chain)\n"
        '    return chain\n'
        '\n'
        '\n'
        'def verify_chain(doc):\n'
        '    """Verifica soluções, proveniência por hash e métricas sem confiar na síntese.\n'
        '\n'
        '    A auditoria exaustiva das estratégias usa audit() para reproduzir busca.\n'
        '    """\n'
        '    try:\n'
        "        if type(doc) is not dict or set(doc)!={'format','tasks','train_ids','max_orders','max_nodes','max_rows','searched_radii','generations','sha256'}:return False\n"
        "        if doc['format']!=FORMAT or doc['sha256']!=fingerprint({k:v for k,v in doc.items() if k!='sha256'}):return False\n"
        "        tasks=doc['tasks'];max_rows=doc['max_rows'];max_nodes=doc['max_nodes']\n"
        '        if type(tasks) is not list or not tasks or type(max_rows) is not int or not 1<=max_rows<=1000000:return False\n'
        '        if type(max_nodes) is not int or not 1<=max_nodes<=1000000:return False\n'
        "        if type(doc['max_orders']) is not int or doc['max_orders']<1:return False\n"
        "        if type(doc['searched_radii']) is not int or doc['searched_radii']<0:return False\n"
        '        for t in tasks:validate_task(t,max_rows)\n'
        "        ids=[t['id'] for t in tasks]\n"
        '        if len(ids)!=len(set(ids)):return False\n'
        "        train=doc['train_ids']\n"
        '        if type(train) is not list or not train or len(train)!=len(set(train)) or not set(train)<=set(ids):return False\n'
        "        generations=doc['generations']\n"
        '        if type(generations) is not list or not generations:return False\n'
        "        prev='GENESIS';last=None;last_radius=0\n"
        "        tasks_by_id={t['id']:t for t in tasks}\n"
        '        for i,row in enumerate(generations):\n'
        "            if type(row) is not dict or set(row)!={'generation','radius','weights','training_cost','holdout_cost','solutions','source_sha256','previous','id'}:return False\n"
        "            if row['generation']!=i or row['previous']!=prev or row['id']!=fingerprint({k:v for k,v in row.items() if k!='id'}):return False\n"
        "            weights=row['weights']\n"
        "            if type(weights) is not list or len(weights)!=3 or any(type(v) is not int or v<0 or v>row['radius'] for v in weights):return False\n"
        "            if (i==0 and (row['radius']!=0 or weights!=list(BASE))) or (i>0 and not last_radius<row['radius']<=doc['searched_radii']):return False\n"
        "            if row['source_sha256']!=fingerprint(source_policy(weights)):return False\n"
        "            sols=row['solutions']\n"
        '            if type(sols) is not dict or set(sols)!=set(ids):return False\n'
        '            for tid,sol in sols.items():\n'
        '                if not verify_solution(tasks_by_id[tid],sol,max_rows,max_nodes):return False\n'
        "            tr=[sols[k]['metricas'] for k in train]\n"
        "            held=[sols[k]['metricas'] for k in ids if k not in train]\n"
        "            costs=[sum(v['nos'] for v in tr),sum(v['profundidade'] for v in tr)]\n"
        "            hold=[sum(v['nos'] for v in held),sum(v['profundidade'] for v in held)]\n"
        "            if row['training_cost']!=costs or row['holdout_cost']!=hold:return False\n"
        '            if last is not None and not tuple(costs)<tuple(last):return False\n'
        "            prev=row['id'];last=costs;last_radius=row['radius']\n"
        '        return True\n'
        '    except (ValueError,TypeError,KeyError,IndexError,OverflowError,RecursionError):return False\n'
        '\n'
        '\n'
        'def audit(doc):\n'
        "    if not verify_chain(doc):raise ValueError('Certificado inválido')\n"
        "    expected=build(doc['tasks'],doc['train_ids'],doc['searched_radii'],\n"
        "                   doc['max_rows'],doc['max_orders'],doc['max_nodes'])\n"
        "    if doc != expected:raise ValueError('Cadeia difere da síntese integral reproduzida')\n"
        "    return {'valid':True,'tasks':len(doc['tasks']),'generations':len(doc['generations']),\n"
        "            'train_costs':[r['training_cost'][0] for r in doc['generations']],\n"
        "            'holdout_costs':[r['holdout_cost'][0] for r in doc['generations']]}\n"
        '\n'
        '\n'
        'def compile_policy(weights):\n'
        '    """Compila de verdade no motor Ômega anterior quando disponível."""\n'
        '    try:\n'
        '        from omega.motor_v1 import MaquinaV1\n'
        '        from omega_selfhost.driver import compile_text\n'
        '        from omega.nucleo_v1 import validar_ir\n'
        '        from fractions import Fraction\n'
        '    except ImportError:\n'
        '        return None\n'
        '    ir=compile_text(source_policy(weights))\n'
        '    validar_ir(ir)\n'
        '    machine=MaquinaV1(ir).executar()\n'
        "    idx=ir['simbolos']['prioridade']\n"
        '    for n,d,o in ((0,0,0),(1,2,3),(7,3,4),(100,9,23)):\n'
        "        state={**machine.estado,'nos':Fraction(n),'profundidade':Fraction(d),'operacoes':Fraction(o)}\n"
        "        if machine.frente(state)[idx]!=priority(weights,{'nos':n,'profundidade':d,'operacoes':o}):\n"
        "            raise ValueError('Política compilada diverge da semântica exata')\n"
        '    return ir\n'
        '\n'
        '\n'
        'def export(doc,path):\n'
        "    if not verify_chain(doc):raise ValueError('Certificado inválido')\n"
        '    folder=Path(path);folder.mkdir(parents=True,exist_ok=True)\n'
        "    canonical_write(folder/'cadeia_aberta.json',doc)\n"
        "    for row in doc['generations']:\n"
        '        (folder/f\'politica_{row["generation"]}.omega\').write_text(source_policy(row[\'weights\']),encoding=\'utf-8\')\n'
        "        compiled=compile_policy(row['weights'])\n"
        '        if compiled is not None:\n'
        '            canonical_write(folder/f\'politica_{row["generation"]}.omc\',compiled)\n'
        "    (folder/'politica_ativa.omega').write_text(source_policy(doc['generations'][-1]['weights']),encoding='utf-8')\n"
        '    return folder\n'
        '\n'
        '\n'
        'def audit_directory(path):\n'
        "    p=Path(path);doc=json.loads((p/'cadeia_aberta.json').read_text(encoding='utf-8'))\n"
        '    result=audit(doc)\n'
        "    for row in doc['generations']:\n"
        '        if (p/f\'politica_{row["generation"]}.omega\').read_text(encoding=\'utf-8\')!=source_policy(row[\'weights\']):\n'
        "            raise ValueError('Código-fonte de política adulterado')\n"
        "        generated=compile_policy(row['weights'])\n"
        '        if generated is not None:\n'
        '            saved=json.loads((p/f\'politica_{row["generation"]}.omc\').read_text(encoding=\'utf-8\'))\n'
        "            if saved!=generated:raise ValueError('IR da política alterada')\n"
        "    if (p/'politica_ativa.omega').read_text(encoding='utf-8')!=source_policy(doc['generations'][-1]['weights']):\n"
        "        raise ValueError('Política ativa adulterada')\n"
        '    return result\n'
    ),
    ('omega_open/logic.py',
        '"""Síntese exata de funções Bool^n: AST imutável com compartilhamento de DAG.\n'
        '\n'
        'Operadores têm interpretação booleana; o verificador está em checker.py.\n'
        'Nenhum eval, compilação de código não confiável ou operação de rede.\n'
        '"""\n'
        'from __future__ import annotations\n'
        'from itertools import permutations\n'
        '\n'
        "ZERO = ('c', 0)\n"
        "ONE = ('c', 1)\n"
        '\n'
        '\n'
        'def var(i):\n'
        "    return ('v', i)\n"
        '\n'
        '\n'
        'def neg(x):\n'
        '    if x == ZERO: return ONE\n'
        '    if x == ONE: return ZERO\n'
        "    if x[0] == 'not': return x[1]\n"
        "    return ('not', x)\n"
        '\n'
        '\n'
        'def gate(op, a, b):\n'
        "    if op in ('and', 'or', 'xor') and repr(a) > repr(b):\n"
        '        a, b = b, a\n'
        "    if op == 'and':\n"
        '        if a == ZERO or b == ZERO: return ZERO\n'
        '        if a == ONE: return b\n'
        '        if b == ONE or a == b: return a\n'
        '        if neg(a) == b: return ZERO\n'
        "    if op == 'or':\n"
        '        if a == ONE or b == ONE: return ONE\n'
        '        if a == ZERO: return b\n'
        '        if b == ZERO or a == b: return a\n'
        '        if neg(a) == b: return ONE\n'
        "    if op == 'xor':\n"
        '        if a == ZERO: return b\n'
        '        if b == ZERO: return a\n'
        '        if a == b: return ZERO\n'
        '        if a == ONE: return neg(b)\n'
        '        if b == ONE: return neg(a)\n'
        '    return (op, a, b)\n'
        '\n'
        '\n'
        'def choose(x, low, high):\n'
        '    if low == high: return low\n'
        '    if low == ZERO and high == ONE: return x\n'
        '    if low == ONE and high == ZERO: return neg(x)\n'
        "    return ('ite', x, low, high)\n"
        '\n'
        '\n'
        'def fold(op, terms, identity):\n'
        '    result = identity\n'
        '    for term in terms: result = gate(op, result, term)\n'
        '    return result\n'
        '\n'
        '\n'
        'def truth_table(expr, arity):\n'
        '    """Executor rápido para síntese; checker.py usa avaliador independente."""\n'
        '    def evaluate(node, bits):\n'
        '        op=node[0]\n'
        "        if op == 'c': return node[1]\n"
        "        if op == 'v': return (bits >> node[1]) & 1\n"
        "        if op == 'not': return 1-evaluate(node[1], bits)\n"
        "        if op == 'ite': return evaluate(node[3] if evaluate(node[1], bits) else node[2], bits)\n"
        '        a,b=evaluate(node[1], bits),evaluate(node[2], bits)\n'
        "        return {'and':a & b, 'or':a | b, 'xor':a ^ b}[op]\n"
        '    return [evaluate(expr,i) for i in range(1 << arity)]\n'
        '\n'
        '\n'
        'def metrics(root):\n'
        '    seen=set()\n'
        '    def walk(t):\n'
        '        if t in seen: return 0,0\n'
        '        seen.add(t)\n'
        '        depths=[walk(a)[1] for a in t[1:] if isinstance(a,tuple)]\n'
        '        return 1,1 + (max(depths) if depths else 0)\n'
        '    # Depth independently of sharing; count unique DAG nodes.\n'
        '    def depth(t):\n'
        '        return 1+max((depth(x) for x in t[1:] if isinstance(x,tuple)),default=0)\n'
        '    walk(root)\n'
        "    return {'nos':len(seen),'profundidade':depth(root),'operacoes':sum(t[0] not in ('c','v') for t in seen)}\n"
        '\n'
        '\n'
        'def dnf(table, n):\n'
        '    clauses=[]\n'
        '    for row,val in enumerate(table):\n'
        '        if val:\n'
        "            clauses.append(fold('and',(var(j) if row >> j & 1 else neg(var(j)) for j in range(n)),ONE))\n"
        "    return fold('or',clauses,ZERO)\n"
        '\n'
        '\n'
        'def anf(table,n):\n'
        '    coeff=list(table)\n'
        '    for j in range(n):\n'
        '        for mask in range(1 << n):\n'
        '            if mask & (1 << j): coeff[mask] ^= coeff[mask^(1 << j)]\n'
        '    terms=[]\n'
        '    for mask,c in enumerate(coeff):\n'
        "        if c: terms.append(fold('and',(var(j) for j in range(n) if mask >> j & 1),ONE))\n"
        "    return fold('xor',terms,ZERO)\n"
        '\n'
        '\n'
        'def shannon(table, n, order):\n'
        '    def recur(rows, offset):\n'
        '        values={table[r] for r in rows}\n'
        '        if len(values)==1: return ONE if 1 in values else ZERO\n'
        "        if offset >= n: raise ValueError('Tabela inconsistente')\n"
        '        j=order[offset]\n'
        '        lows=[r for r in rows if not (r >> j & 1)]\n'
        '        highs=[r for r in rows if r >> j & 1]\n'
        '        return choose(var(j),recur(lows,offset+1),recur(highs,offset+1))\n'
        '    return recur(list(range(1 << n)),0)\n'
        '\n'
        '\n'
        'def candidates(table,n,max_orders=12):\n'
        '    """Gera famílias diferentes; max_orders é orçamento, não limite da linguagem."""\n'
        "    yield 'dnf',dnf(table,n)\n"
        "    yield 'anf',anf(table,n)\n"
        '    # Ordens permitem árvores não fixadas a Bool²; enumerador preguiçoso.\n'
        '    for ix,order in enumerate(permutations(range(n))):\n'
        '        if ix>=max_orders: break\n'
        "        yield 'shannon_'+''.join(str(x)+'_' for x in order),shannon(table,n,order)\n"
        '\n'
        '\n'
        'def encode(expr):\n'
        '    return [expr[0]]+[encode(a) if isinstance(a,tuple) else a for a in expr[1:]]\n'
    ),
