        '    return result,ANALYZER_IMAGE\n'
        '\n'
        '\n'
        "def validate(root,*,count=48,analyzer='host'):\n"
        '    root=Path(root).resolve()\n'
        '    rows=[]\n'
        '    def record(target,text,out,expected=None):\n'
        "        sanitizer=any(s in out.stderr for s in ('AddressSanitizer','LeakSanitizer','runtime error:'))\n"
        '        good=not sanitizer and not out.timed_out and out.returncode in (0,1)\n'
        '        if expected is not None:good=good and out.returncode==expected\n'
        "        rows.append({'target':target,'input_sha256':hashlib.sha256(text.encode()).hexdigest(),\n"
        "                     'input':text,'returncode':out.returncode,'passed':good,\n"
