        '"""Refinement contracts and fail-closed Lean admission for Omega programs."""\n'
        'from .contracts import verify_contract, check_program\n'
        'from .compiler import build\n'
        '\n'
        "__all__ = ['verify_contract', 'check_program', 'build']\n"
