        '        if match:declarations.append((index,int(match.group(1))))\n'
        "    output=next(i for i,line in enumerate(lines) if 'output[0]' in line)\n"
        '    insertions={}\n'
        '    for position,(start,node) in enumerate(declarations):\n'
        '        end=declarations[position+1][0] if position+1<len(declarations) else output\n'
        "        op=1 if node<graph['inputs'] else 7 if graph['nodes'][node-graph['inputs']]['op']=='relu' else 8\n"
        '        branch=\'0\' if op!=7 else f\'(x{graph["nodes"][node-graph["inputs"]]["input"]}>0)\'\n'
        '        insertions.setdefault(end,[]).append(f\'  if (omega_trace_record(trace, cycle, {node}, {op}, {branch}, x{node}, {result["node_scales"][node]}ULL)) return -3;\')\n'
        '    text=[\'#include "proof_envelope.h"\']\n'
        '    for i,line in enumerate(lines):\n'
        '        text.extend(insertions.get(i,[]))\n'
        "        text.append(line.replace('int omega_edge(const int64_t *input, int64_t *output) {',\n"
        "                    'int omega_edge_traced(const int64_t *input, int64_t *output, OmegaTraceRing *trace, uint64_t cycle) {'))\n"
        "    source.write_text('\\n'.join(text)+'\\n')\n"
        "    for name in ('proof_envelope.h','glass_box_trace.c'):(root/name).write_bytes(Path(__file__).with_name(name).read_bytes())\n"
        "    return {**result,'trace_event_count':len(declarations),'trace_storage':'caller-owned fixed-capacity circular buffer; overwrites count as dropped',\n"
