        ' if(!ring||!storage||!capacity||capacity>SIZE_MAX/sizeof(OmegaTraceEvent))return -1;\n'
        ' *ring=(OmegaTraceRing){storage,capacity,0,0,0,0,0};return 0;\n'
        '}\n'
        'int omega_trace_record(OmegaTraceRing *ring,uint64_t cycle,uint32_t node,uint16_t operation,uint8_t branch,int64_t numerator,uint64_t denominator){\n'
        ' if(!ring||!ring->events||!ring->capacity||!denominator||denominator>INT64_MAX||numerator==INT64_MIN||branch>1||ring->halted)return -1;\n'
        ' if(ring->sequence==UINT64_MAX||ring->dropped==UINT64_MAX){ring->halted=1;return -2;}\n'
        ' OmegaTraceEvent event={ring->sequence++,cycle,node,operation,branch,0,numerator,denominator};\n'
        ' ring->events[ring->next]=event;ring->next=(ring->next+1)%ring->capacity;\n'
        ' if(ring->count<ring->capacity)ring->count++;else ring->dropped++;\n'
        ' return 0;\n'
        '}\n'
        'int omega_trace_get(const OmegaTraceRing *ring,size_t index,OmegaTraceEvent *event){\n'
