        '    if type(value) is list:\n'
        '        if len(value) > meter[0]:\n'
        "            raise ValueError('Scientific request structure budget')\n"
        '        return [_plain(x, depth+1, meter) for x in value]\n'
        '    if type(value) is dict:\n'
        '        if 2*len(value) > meter[0]:\n'
        "            raise ValueError('Scientific request structure budget')\n"
        '        if any(type(k) is not str for k in value):\n'
        "            raise ValueError('Scientific object keys must be strings')\n"
        '        return {_plain(k, depth+1, meter): _plain(v, depth+1, meter) for k, v in value.items()}\n'
        "    raise ValueError('Scientific requests contain exact numbers, strings, arrays and objects; no floats/bools/null')\n"
        '\n'
        '\n'
        'def run(identifier, request, *, budget=COMPILER_BUDGET):\n'
        '    entry = kernel(identifier)\n'
        '    if type(request) is not dict or type(budget) is not Budget:\n'
        "        raise ValueError('Scientific object request and OS budget required')\n"
        '    # Count structure before conversion/serialization, including repeated aliases.\n'
        '    # Fractions are strings at this data boundary, not floating point values.\n'
        '    plain = _plain(request)\n'
        '    data = canonical(plain, max_bytes=REQUEST_LIMIT, max_nodes=50000, max_depth=40)\n'
        "    binary = build(entry['group'])\n"
        "    with tempfile.TemporaryDirectory(prefix='omega-science-request-') as tmp:\n"
        "        path = Path(tmp) / 'request.json'\n"
        '        path.write_bytes(data)\n'
        '        outcome = isolated_run([binary, str(identifier), path], readonly=[path], budget=budget, check=True)\n'
        '    if len(outcome.stdout.encode()) > budget.output_bytes:\n'
        "        raise ValueError('Scientific output budget')\n"
