        'def data_envelope(document):\n'
        "    if type(document) is not UntrustedDocument:raise TypeError('Origin-labeled document required')\n"
        "    return {'kind':'untrusted_data','source':document.source,'sha256':document.digest,\n"
        "            'observed_at':document.observed_at,'content':document.content.decode('utf-8','replace'),'authority':False}\n"
        'def extract_json(document,allowed_fields):\n'
        '    value=json.loads(document.content)\n'
        "    if type(value) is not dict or not set(value)<=set(allowed_fields):raise ValueError('Unexpected document fields')\n"
        '    return value\n'
