    ('omega_self_evolve_v2/bridge_lean_filter.py',
        '"""Bounded asynchronous elite queue and signed Lean object manifests.\n'
        '\n'
        'CUDA only supplies data. This host renderer reconstructs the proposition and\n'
        'compiles it with the trusted Lean toolchain. A .olean has no intrinsic signature;\n'
        'Ed25519 signs the manifest binding its bytes to the specification and AST.\n'
        '"""\n'
        'import asyncio\n'
        'from concurrent.futures import ThreadPoolExecutor\n'
        'from fractions import Fraction as Q\n'
        'import hashlib\n'
        'import json\n'
        'from pathlib import Path\n'
        'import re\n'
        'import tempfile\n'
        'from omega_refine_check.syntax import tree,evaluate\n'
        'from omega_refine_check.contracts import verify_contract\n'
        'from omega_synth_mcts.search import specification\n'
        'from omega_selfhost.proof_protocol import encode\n'
        'from omega_platform.sandbox import trusted\n'
        'from omega_platform.budget import PROOF_BUDGET\n'
        'from omega_selfhost.proof import lake_binary\n'
        'from omega_selfhost.axiom_policy import DEFAULT\n'
        '\n'
        '\n'
        'def digest(value):return hashlib.sha256(encode(value)).hexdigest()\n'
        '\n'
        '\n'
        'def _compiled(source,expected,directory):\n'
        "    root=Path(__file__).resolve().parents[1]/'formal/tensor'\n"
        "    path=directory/'Candidate.lean';path.write_text(source);obj=directory/'Candidate.olean'\n"
        "    result=trusted([lake_binary(),'env','lean','--root='+str(directory.resolve()),'-o',obj.resolve(),path.resolve()],cwd=root,budget=PROOF_BUDGET,check=True)\n"
        '    output=result.stdout+result.stderr\n'
        "    if 'warning:' in output or not obj.is_file() or not obj.stat().st_size:raise ValueError('Lean object compilation was not clean')\n"
        '    reports={}\n'
        '    for name,body in re.findall(r"\'([^\']+)\' depends on axioms: \\[([^\\]]*)\\]",output):reports[name]={x.strip() for x in body.split(\',\') if x.strip()}\n'
        '    for name in re.findall(r"\'([^\']+)\' does not depend on any axioms",output):reports[name]=set()\n'
        "    if any(name not in reports or not reports[name]<=DEFAULT for name in expected):raise ValueError('Unauthorized .olean proof dependencies')\n"
        '    return obj\n'
        '\n'
        '\n'
        'def _proof_data(spec,ast,bounds):\n'
        "    proof=verify_contract(spec['variables'],ast,spec['ensures'],requires=spec.get('requires',()))\n"
        '    if bounds is None:return proof\n'
        "    if type(bounds) is not dict or set(bounds)!={'inputs','output'} or len(bounds['inputs'])!=len(spec['variables']):raise ValueError('Tier-2 analysis-bound shape mismatch')\n"
        '    from omega_gpu_mcts.flat import RationalInterval\n'
        "    for pair in [*bounds['inputs'],bounds['output']]:RationalInterval.from_pair(pair)\n"
        "    premises=list(spec.get('requires',()))\n"
        "    for name,pair in zip(spec['variables'],bounds['inputs']):premises.extend([f'{name} >= ({Q(pair[0])})',f'{name} <= ({Q(pair[1])})'])\n"
        "    lo,hi=map(Q,bounds['output'])\n"
        "    checked=verify_contract(spec['variables'],ast,f'result >= ({lo}) and result <= ({hi})',requires=premises)\n"
        "    source=checked['source'].replace('import Omega.Refinement\\n','').replace('namespace OmegaRefinement','namespace OmegaTierBounds').replace('end OmegaRefinement','end OmegaTierBounds')\n"
        "    names={name:name.replace('OmegaRefinement.','OmegaTierBounds.') for name in checked['admission']['theorems']}\n"
        "    combined=proof['source']+'\\n'+source\n"
        "    admission={'checker':'Lean 4.19.0','source_sha256':hashlib.sha256(combined.encode()).hexdigest(),\n"
        "               'theorems':proof['admission']['theorems']+list(names.values()),\n"
        "               'axioms':{**proof['admission']['axioms'],**{names[name]:deps for name,deps in checked['admission']['axioms'].items()}}}\n"
        "    return {'source':combined,'admission':admission}\n"
        '\n'
        '\n'
        'def prove_candidate(spec,candidate,directory,*,signing_key,input_bounds=None,output_bounds=None):\n'
        "    input_names=list(spec['variables'])\n"
        '    spec=json.loads(encode(spec))\n'
        "    examples=specification(spec);ast=tree(candidate['ast'])\n"
        "    if any(evaluate(ast,env)!=target for env,target in examples):raise ValueError('Elite fails independent exact example replay')\n"
        '    # No mask, reward, supplied C, supplied proof or supplied certificate can\n'
        '    # replace this independently reconstructed universal proposition.\n'
        '    bounds=None\n'
        '    if input_bounds is not None or output_bounds is not None:\n'
        "        if input_bounds is None or output_bounds is None:raise ValueError('Both analysis input/output bounds are required')\n"
        "        if len(input_bounds)!=len(input_names):raise ValueError('Tier-2 analysis-bound shape mismatch')\n"
        '        by_name=dict(zip(input_names,input_bounds))\n'
        "        bounds={'inputs':[by_name[name] for name in spec['variables']],'output':output_bounds}\n"
        '    proof=_proof_data(spec,ast,bounds)\n'
        '    root=Path(directory);root.mkdir(parents=True,exist_ok=False)\n'
        "    obj=_compiled(proof['source'],proof['admission']['theorems'],root)\n"
        "    statement={'format':'omega-tier2-statement-1','specification':spec,'ast':ast}\n"
        "    if bounds is not None:statement['analysis_bounds']=bounds\n"
        "    manifest={'format':'omega-tier2-object-1','statement':statement,'statement_sha256':digest(statement),\n"
        "              'lean_source_sha256':hashlib.sha256(proof['source'].encode()).hexdigest(),\n"
        "              'olean_sha256':hashlib.sha256(obj.read_bytes()).hexdigest(),'admission':proof['admission'],\n"
        "              'scope':'universal rational contract under stated premises, independent of Tier-1 flags'}\n"
        "    receipt={'manifest':manifest,'signature':signing_key.sign(encode(manifest)).hex()}\n"
        "    (root/'certificate.json').write_bytes(encode(receipt))\n"
        '    return receipt\n'
        '\n'
        '\n'
        'def verify_receipt(receipt,directory,*,public_key,expected_spec=None):\n'
        "    if type(receipt) is not dict or set(receipt)!={'manifest','signature'}:raise ValueError('Unknown Tier-2 receipt envelope')\n"
        "    if len(encode(receipt))>4*1024**2:raise ValueError('Tier-2 receipt byte budget exceeded')\n"
        '    from cryptography.exceptions import InvalidSignature\n'
        "    try:public_key.verify(bytes.fromhex(receipt['signature']),encode(receipt['manifest']))\n"
        "    except (ValueError,TypeError,InvalidSignature) as error:raise PermissionError('Invalid Tier-2 authority signature') from error\n"
        "    manifest=receipt['manifest'];statement=manifest['statement']\n"
        "    if manifest.get('format')!='omega-tier2-object-1' or statement.get('format')!='omega-tier2-statement-1' or digest(statement)!=manifest['statement_sha256']:raise ValueError('Changed Tier-2 statement')\n"
        "    if expected_spec is not None and encode(statement['specification'])!=encode(expected_spec):raise ValueError('Tier-2 receipt belongs to another specification')\n"
        '    root=Path(directory)\n'
        "    for name,field in [('Candidate.lean','lean_source_sha256'),('Candidate.olean','olean_sha256')]:\n"
        '        path=root/name\n'
        "        if path.is_symlink() or not path.is_file() or path.stat().st_size>64*1024**2 or hashlib.sha256(path.read_bytes()).hexdigest()!=manifest[field]:raise ValueError('Changed Tier-2 proof artifact')\n"
        '    # Authenticate and re-prove; never import an untrusted arbitrary .olean.\n'
        "    proof=_proof_data(statement['specification'],tree(statement['ast']),statement.get('analysis_bounds'))\n"
        "    if (root/'Candidate.lean').read_text()!=proof['source'] or manifest['admission']!=proof['admission']:raise ValueError('Unrelated Tier-2 proof object')\n"
        "    return {'valid':True,'statement':statement,'statement_sha256':manifest['statement_sha256']}\n"
        '\n'
        '\n'
        'class LeanBridge:\n'
        '    def __init__(self,*,signing_key,workers=2,queue_capacity=16):\n'
        "        if type(workers) is not int or not 1<=workers<=4 or type(queue_capacity) is not int or not workers<=queue_capacity<=256:raise ValueError('Bounded formal worker pool required')\n"
        "        self.key=signing_key;self.executor=ThreadPoolExecutor(max_workers=workers,thread_name_prefix='omega-tier2')\n"
        '        self.capacity=queue_capacity;self.closed=False\n'
        '        self.slots=asyncio.Semaphore(queue_capacity)\n'
        '    async def consume(self,spec,batch,directory):\n'
        "        if self.closed:raise RuntimeError('Formal bridge is closed')\n"
        "        candidates=batch.get('candidates')\n"
        "        if type(candidates) is not list or len(candidates)>self.capacity:raise ValueError('Formal candidate queue capacity exceeded')\n"
        '        root=Path(directory);root.mkdir(parents=True,exist_ok=False);loop=asyncio.get_running_loop()\n'
        '        async def job(index,candidate):\n'
        '            try:\n'
        '                async with self.slots:\n'
        "                    receipt=await loop.run_in_executor(self.executor,lambda:prove_candidate(spec,candidate,root/f'candidate-{index}',signing_key=self.key,\n"
        "                                                     input_bounds=batch.get('input_bounds'),output_bounds=batch.get('output_bounds')))\n"
        "                return {'accepted':True,'directory':str(root/f'candidate-{index}'),'receipt':receipt}\n"
        "            except Exception as error:return {'accepted':False,'reason':str(error)[-4000:]}\n"
        '        results=await asyncio.gather(*(job(i,c) for i,c in enumerate(candidates)))\n'
        "        report={'format':'omega-tier2-batch-1','results':results,'accepted':sum(r['accepted'] for r in results)}\n"
        "        (root/'results.json').write_bytes(encode(report));return report\n"
        '    async def search_and_consume(self,engine,spec,directory,**search_options):\n'
        '        batch=await asyncio.to_thread(engine.search,spec,**search_options)\n'
        '        return await self.consume(spec,batch,directory)\n'
        '    def close(self):\n'
        '        self.closed=True;self.executor.shutdown(wait=True,cancel_futures=True)\n'
        '    def __enter__(self):return self\n'
        '    def __exit__(self,*args):self.close()\n'
    ),
