    ('omega_self_evolve_v2/cycle.py',
        '"""Proof-gated generations, atomic selection and narrowly scoped Git publication."""\n'
        'import fcntl\n'
        'import hashlib\n'
        'import json\n'
        'import os\n'
        'from pathlib import Path\n'
        'import subprocess\n'
        'import tempfile\n'
        'from omega_selfhost.proof_protocol import encode\n'
        'from omega_self_mutate.rules import validate_rule,install_template\n'
        'from omega_self_mutate.bootstrap import evolve\n'
        'from omega_self_mutate.activation import activate,audit_generation\n'
        'from .bridge_lean_filter import verify_receipt\n'
        '\n'
        '\n'
        'def _git(repo,*arguments):\n'
        "    return subprocess.run(['git','-C',str(repo),*arguments],check=True,capture_output=True,text=True).stdout.strip()\n"
        '\n'
        '\n'
        'def publish_generation(generation,*,repo=None,commit=False,replace_source=False,restart_runtime=None,_canonical_change=None):\n'
        '    from omega_selfhost.driver import ROOT,PACKAGE\n'
        '    repo=Path(repo or ROOT).resolve();generation=Path(generation).resolve()\n'
        '    record=audit_generation(generation)\n'
        "    source=repo/'omega_selfhost/compiler.omega';original=source.read_bytes()\n"
        "    expected=install_template(original.decode(),record['rule']).encode()\n"
        "    if original!=(PACKAGE/'compiler.omega').read_bytes() or (generation/'bootstrap/compiler.omega').read_bytes()!=expected:raise ValueError('Published pass does not match this canonical source')\n"
        '    if commit:\n'
        "        dirty=_git(repo,'status','--porcelain','--untracked-files=normal')\n"
        "        own_change=(_canonical_change==original and not _git(repo,'diff','--cached','--name-only') and\n"
        "                    _git(repo,'diff','--name-only')=='omega_selfhost/compiler.omega' and\n"
        "                    not _git(repo,'ls-files','--others','--exclude-standard'))\n"
        "        if dirty and not own_change:raise ValueError('Automatic commit requires a clean repository and index')\n"
        "        if not replace_source:raise ValueError('Automatic source commits require explicit source replacement')\n"
        "    state=repo/'build/selfhost';state.mkdir(parents=True,exist_ok=True)\n"
        "    target=state/'active.json';old=target.read_bytes() if target.exists() else None\n"
        "    epoch_path=state/'runtime-epoch.json';old_epoch=epoch_path.read_bytes() if epoch_path.exists() else None\n"
        "    publication=repo/'omega_selfhost/evolved'/record['rule']['id']\n"
        "    if commit and publication.exists():raise ValueError('Refusing to overwrite a published generation')\n"
        '    paths=[];revision=None\n'
        "    with (state/'.hyper-cycle.lock').open('a') as lock:\n"
        '        fcntl.flock(lock,fcntl.LOCK_EX)\n'
        '        try:\n'
        '            selector=activate(generation,selection_root=state)\n'
        '            if replace_source:\n'
        "                temporary=source.with_suffix('.hyper.tmp');temporary.write_bytes(expected);os.replace(temporary,source)\n"
        '            if commit:\n'
        '                publication.mkdir(parents=True)\n'
        "                files={'compiler.omega':expected,'optimization.lean':(generation/'optimization.lean').read_bytes(),\n"
        "                       'generation.json':encode({'format':'omega-published-mutation-1','rule_id':record['rule']['id'],\n"
        "                          'base_sha256':hashlib.sha256(original).hexdigest(),'compiler_sha256':selector['binary_sha256'],\n"
        "                          'objective':record['objective'],'proof_sha256':record['proof']['source_sha256']})}\n"
        '                for name,data in files.items():(publication/name).write_bytes(data)\n'
        "                paths=['omega_selfhost/compiler.omega',publication.relative_to(repo).as_posix()]\n"
        "                _git(repo,'add','--',*paths)\n"
        "                _git(repo,'commit','-m','Adopt verified Omega optimizer '+record['rule']['id'][:16],'--',*paths)\n"
        "                revision=_git(repo,'rev-parse','HEAD')\n"
        '            if restart_runtime is not None:restart_runtime(selector)\n'
        "            epoch={'format':'omega-runtime-epoch-1','compiler_sha256':selector['binary_sha256'],\n"
        "                   'generation':str(generation),'git_commit':revision,'source_replaced':replace_source}\n"
        "            temporary=state/'.runtime-epoch.tmp';temporary.write_bytes(encode(epoch));os.replace(temporary,state/'runtime-epoch.json')\n"
        "            if replace_source and not (state/'hyper-canonical.json').exists():\n"
        "                baseline={'source':original.decode(),'sha256':hashlib.sha256(original).hexdigest()}\n"
        "                temporary=state/'.hyper-canonical.tmp';temporary.write_bytes(encode(baseline));os.replace(temporary,state/'hyper-canonical.json')\n"
        '            return epoch\n'
        '        except BaseException:\n'
        "            if revision is not None:_git(repo,'revert','--no-edit',revision)\n"
        '            if replace_source:\n'
        "                temporary=source.with_suffix('.hyper.tmp');temporary.write_bytes(original);os.replace(temporary,source)\n"
        '            if old is None:target.unlink(missing_ok=True)\n'
        '            else:\n'
        "                temporary=state/'.rollback-active.tmp';temporary.write_bytes(old);os.replace(temporary,target)\n"
        '            if old_epoch is None:epoch_path.unlink(missing_ok=True)\n'
        '            else:\n'
        "                temporary=state/'.rollback-epoch.tmp';temporary.write_bytes(old_epoch);os.replace(temporary,epoch_path)\n"
        "            if paths and revision is None:_git(repo,'reset','--',*paths)\n"
        '            raise\n'
        '\n'
        '\n'
        'def evolve_from_receipt(lhs,receipt,proof_directory,output,*,public_key,install=False,commit=False,replace_source=False,restart_runtime=None,expected_source_sha256=None):\n'
        "    if commit and not install:raise ValueError('A source commit requires installation')\n"
        "    if replace_source and not install:raise ValueError('Source replacement requires installation')\n"
        '    from omega_live.context import checkpoint,emit\n'
        "    checkpoint('mutation.proof-admission')\n"
        '    admitted=verify_receipt(receipt,proof_directory,public_key=public_key)\n'
        "    rule=validate_rule(lhs,admitted['statement']['ast'])\n"
        '    from omega_selfhost.driver import ROOT,PACKAGE\n'
        '    from omega_self_mutate.activation import load_active\n'
        "    state=ROOT/'build/selfhost';state.mkdir(parents=True,exist_ok=True)\n"
        "    source=PACKAGE/'compiler.omega'\n"
        "    with (state/'.hyper-evolution.lock').open('a') as lock:\n"
        '        fcntl.flock(lock,fcntl.LOCK_EX)\n'
        '        previous=source.read_bytes();base=previous\n'
        '        if expected_source_sha256 is not None and hashlib.sha256(previous).hexdigest()!=expected_source_sha256:raise ValueError("Compiler changed before the locked bootstrap cycle")\n'
        "        baseline=state/'hyper-canonical.json'\n"
        '        if baseline.exists():\n'
        "            if baseline.is_symlink() or not baseline.is_file() or baseline.stat().st_size>2*1024**2:raise ValueError('Invalid host canonical baseline')\n"
        "            data=json.loads(baseline.read_text());base=data['source'].encode()\n"
        "            if hashlib.sha256(base).hexdigest()!=data['sha256']:raise ValueError('Changed canonical baseline')\n"
        '            if previous!=base:\n'
        '                selected=load_active()\n'
        "                if selected is None or (selected.parent/'compiler.omega').read_bytes()!=previous:raise ValueError('User compiler changes cannot be replaced by a curiosity cycle')\n"
        "                if commit and _git(ROOT,'status','--porcelain','--untracked-files=normal'):raise ValueError('Automatic commit requires a clean repository and index')\n"
        '                source.write_bytes(base)\n'
        '        adopted=False\n'
        '        try:\n'
        "            checkpoint('mutation.four-stage-bootstrap',{'rule_id':rule['id']})\n"
        '            generation=evolve(rule,output)\n'
        "            emit('mutation.bootstrap-stable',{'rule_id':rule['id'],'fixed_point':generation['bootstrap']['fixed_point']})\n"
        "            root=Path(output);(root/'tier2-receipt.json').write_bytes(encode(receipt))\n"
        '            if install:\n'
        "                checkpoint('mutation.install',{'rule_id':rule['id'],'commit':commit,'replace_source':replace_source})\n"
        "                generation['runtime_epoch']=publish_generation(root,commit=commit,replace_source=replace_source,restart_runtime=restart_runtime,\n"
        '                                                               _canonical_change=base if previous!=base else None)\n'
        '                adopted=replace_source\n'
        '            return generation\n'
        '        finally:\n'
        '            if previous!=base and not adopted:source.write_bytes(previous)\n'
        '\n'
        '\n'
        'def propose_from_profile(profile):\n'
        '    from omega_selfhost.driver import build\n'
        '    from omega_platform.sandbox import run\n'
        '    from omega_platform.budget import COMPILER_BUDGET\n'
        "    with tempfile.TemporaryDirectory(prefix='omega-mutator-v2-') as temporary:\n"
        "        root=Path(temporary);path=root/'profile.json';path.write_bytes(encode(profile));output=root/'proposal.json'\n"
        "        binary=root/'mutator';build(Path(__file__).with_name('auto_mutator_v2.omega'),binary)\n"
        '        run([binary,path,output],readonly=[path],writable=[root],budget=COMPILER_BUDGET,check=True)\n'
        '        return json.loads(output.read_text())\n'
    ),
