        '    eval s (matmul m k n a b i j) =\n'
        '      ((List.finRange k).map (fun t => eval s (a i t) * eval s (b t j))).sum := by\n'
        '  simp [matmul, eval_sum, List.map_map, Function.comp_def, eval]\n'
        '\n'
        'def transpose (m n : Nat) (a : Fin m → Fin n → Expr) : Fin n → Fin m → Expr :=\n'
        '  fun j i => a i j\n'
