        'theorem add_zero (a : Expr) : equivalence (.add a (.lit 0)) a := by simp [equivalence, eval]\n'
        'theorem mul_one (a : Expr) : equivalence (.mul a (.lit 1)) a := by simp [equivalence, eval]\n'
        'theorem div_one (a : Expr) : equivalence (.div a (.lit 1)) a := by simp [equivalence, eval]\n'
        'theorem pow_one (a : Expr) : equivalence (.pow a 1) a := by simp [equivalence, eval]\n'
        'theorem double_neg (a : Expr) : equivalence (.neg (.neg a)) a := by simp [equivalence, eval]\n'
