    ('omega_selfhost/axiom_policy.py',
        '"""Axiom/dependency admission consumes checker output from the trusted Lean process."""\n'
        'import re\n'
        "DEFAULT=frozenset({'propext','Classical.choice','Quot.sound'})\n"
        'def inspect_output(output,expected,allowed=DEFAULT):\n'
        "    if type(output) is not str or len(output)>4*1024**2:raise ValueError('Invalid checker transcript')\n"
        '    found={}\n'
        '    for name,body in re.findall(r"\'([^\']+)\' depends on axioms: \\[([^\\]]*)\\]",output):\n'
        "        axioms=frozenset(a.strip() for a in body.split(',') if a.strip())\n"
        "        if name in found and found[name]!=axioms:raise ValueError('Ambiguous axiom report')\n"
        '        found[name]=axioms\n'
        "    if not set(expected)<=set(found):raise ValueError('Missing axiom reports')\n"
        '    for name in expected:\n'
        "        if not found[name]<=set(allowed):raise ValueError('Unauthorized axiom: '+name)\n"
        '    return {name:sorted(found[name]) for name in expected}\n'
        'def forbid_admissions(source):\n'
        '    # Conservative prefilter only; kernel/axiom inspection remains authoritative.\n'
        "    if re.search(r'\\b(sorry|admit|axiom)\\b',source):raise ValueError('Unapproved proof admission/declaration')\n"
        '    return source\n'
    ),
