        '\n'
        'def apply_c(name,args):\n'
        "    return '({' + ''.join('V a'+str(i)+'='+cexpr(a)+';' for i,a in enumerate(args)) + name+'('+','.join('a'+str(i) for i in range(len(args)))+');})'\n"
        '\n'
        '\n'
        'def c_literal(text):\n'
        '    """C string syntax differs from JSON for ASCII control characters."""\n'
        "    if '\\0' in text:raise ValueError('Embedded NUL is not supported')\n"
        "    text.encode('utf-8')\n"
        '    special={\'"\':\'\\\\"\',\'\\\\\':\'\\\\\\\\\',\'\\n\':\'\\\\n\',\'\\r\':\'\\\\r\',\'\\t\':\'\\\\t\'}\n'
        '    return \'"\'+\'\'.join(special.get(c,(\'\\\\\'+format(ord(c),\'03o\')) if ord(c)<32 or ord(c)==127 else c)\n'
