        "    if e[1] in ('&&','||'):return 'o_bool(o_truth('+cexpr(e[2])+')'+e[1]+'o_truth('+cexpr(e[3])+'))'\n"
        "    return apply_c('o_'+OPS[e[1]],e[2:])\n"
        '\n'
        '\n'
        'def cblock(stmts):\n'
        '    out=[]\n'
        '    for s in stmts:\n'
        '        op=s[0]\n'
