        ' if(!omega_q64_valid(a)||!omega_q64_valid(b)||!b.numerator)return OMEGA_Q_ZERO_DENOM;\n'
        ' __int128 numerator=(__int128)a.numerator*b.denominator;if(b.numerator<0)numerator=-numerator;\n'
        ' return omega_q64_make(out,numerator,(unsigned __int128)a.denominator*omega_abs128(b.numerator));\n'
        '}\n'
        '#endif\n'
