        'static V t_map2(V a, V b, V (*fn)(V, V), int broadcast) {\n'
        '  if (a->kind == 0 && b->kind == 0)\n'
        '    return fn(a, b);\n'
        '  if (a->kind != 2 && b->kind != 2)\n'
        '    o_die("Invalid tensor scalar");\n'
        '  if (a->kind == 2 && b->kind == 2 && a->n != b->n)\n'
        '    o_die("Tensor shape mismatch");\n'
        '  if (!broadcast && (a->kind != 2 || b->kind != 2))\n'
        '    o_die("Tensor shape mismatch");\n'
        '  V r = o_list();\n'
        '  size_t n = a->kind == 2 ? a->n : b->n;\n'
        '  for (size_t i = 0; i < n; i++)\n'
        '    o_push(r, t_map2(a->kind == 2 ? a->a[i] : a, b->kind == 2 ? b->a[i] : b, fn, broadcast));\n'
        '  return r;\n'
        '}\n'
        'static V t_add(V a, V b) { return t_map2(a, b, o_add, 0); }\n'
        'static V t_sub(V a, V b) { return t_map2(a, b, o_sub, 0); }\n'
        'static V t_mul(V a, V b) {\n'
        '  if (a->kind == 2 && b->kind == 2)\n'
        '    o_die("Scalar multiplication required");\n'
