        '  return t_map2(a, b, o_div, 1);\n'
        '}\n'
        'static V t_neg(V a) { return t_mul(a, o_int(-1)); }\n'
        'static V t_sum(V a) {\n'
        '  if (a->kind == 0)\n'
        '    return a;\n'
        '  V r = o_int(0);\n'
        '  for (size_t i = 0; i < a->n; i++)\n'
        '    r = o_add(r, t_sum(a->a[i]));\n'
