        '  if (a->kind == 0)\n'
        '    return o_cmp(a, o_int(0)) > 0 ? a : o_int(0);\n'
        '  V r = o_list();\n'
        '  for (size_t i = 0; i < a->n; i++)\n'
        '    o_push(r, t_relu(a->a[i]));\n'
