        '    for (size_t i = 0; i < a->n; i++) {\n'
        '      if (a->a[i]->kind != 2 || a->a[i]->n != a->a[0]->n)\n'
        '        o_die("Irregular matrix");\n'
        '      o_push(row, a->a[i]->a[j]);\n'
