        'static V t_pow(V a, long n) {\n'
        '  if (a->kind || n < 0 || n > 20)\n'
        '    o_die("Invalid scalar exponent");\n'
        '  V r = o_int(1);\n'
        '  for (long i = 0; i < n; i++)\n'
