        'static V d_param(V state, V dirs, V name, V shape) {\n'
        '  V a = o_truth(o_has(state, name)) ? o_get(state, name) : t_full(shape, 0, o_int(0));\n'
        '  V da = o_truth(o_has(dirs, name)) ? o_get(dirs, name) : t_zero(a);\n'
        '  return t_pair(a, da);\n'
        '}\n'
        'static V d_construct(V op, V shape) {\n'
        '  V a = t_full(shape, 0, o_int(0));\n'
        '  if (!strcmp(op->s, "identidade")) {\n'
        '    if (shape->n != 2 || o_long(shape->a[0]) != o_long(shape->a[1]))\n'
        '      o_die("Square identity required");\n'
        '    for (size_t i = 0; i < a->n; i++)\n'
        '      a->a[i]->a[i] = o_int(1);\n'
        '  }\n'
        '  return t_pair(a, t_zero(a));\n'
        '}\n'
        'static V d_stack(V args) {\n'
        '  V a = o_list(), da = o_list();\n'
        '  for (size_t i = 0; i < args->n; i++) {\n'
        '    o_push(a, args->a[i]->a[0]);\n'
        '    o_push(da, args->a[i]->a[1]);\n'
        '  }\n'
        '  return t_pair(a, da);\n'
        '}\n'
        'static V d_add(V a, V b) { return t_pair(t_add(a->a[0], b->a[0]), t_add(a->a[1], b->a[1])); }\n'
        'static V d_sub(V a, V b) { return t_pair(t_sub(a->a[0], b->a[0]), t_sub(a->a[1], b->a[1])); }\n'
        'static V d_neg(V a) { return t_pair(t_neg(a->a[0]), t_neg(a->a[1])); }\n'
        'static V d_mul(V a, V b) {\n'
        '  return t_pair(t_mul(a->a[0], b->a[0]), t_add(t_mul(a->a[1], b->a[0]), t_mul(a->a[0], b->a[1])));\n'
        '}\n'
        'static V d_div(V a, V b) {\n'
