    ('omega_synth_mcts/grammar.py',
        '"""Finite-budget traversals of an unbounded rational expression grammar."""\n'
        'from omega_refine_check.syntax import tree,identifier,rational,render\n'
        '\n'
        '\n'
        'def size(node):\n'
        '    return 1+sum(size(x) for x in node[1:] if isinstance(x,(tuple,list)))\n'
        '\n'
        '\n'
        'def holes(node):\n'
        "    if node[0]=='hole':return 1\n"
        '    return sum(holes(x) for x in node[1:] if isinstance(x,(tuple,list)))\n'
        '\n'
        '\n'
        'def first_hole(node,path=()):\n'
        "    if node[0]=='hole':return path\n"
        '    for i,child in enumerate(node[1:],1):\n'
        '        if isinstance(child,(tuple,list)):\n'
        '            found=first_hole(child,path+(i,))\n'
        '            if found is not None:return found\n'
        '    return None\n'
        '\n'
        '\n'
        'def replace(node,path,replacement):\n'
        '    if not path:return replacement\n'
        '    result=list(node);result[path[0]]=replace(node[path[0]],path[1:],replacement)\n'
        '    return tuple(result)\n'
        '\n'
        '\n'
        'class Grammar:\n'
        "    def __init__(self,variables,constants=(0,1,-1),*,operators=('+','-','*','/','neg','relu'),max_nodes=15,max_depth=8):\n"
        '        self.variables=tuple(identifier(v) for v in variables)\n'
        '        self.constants=tuple(dict.fromkeys(str(rational(c)) for c in constants))\n'
        "        if not self.variables and not self.constants:raise ValueError('A grammar atom is required')\n"
        "        if len(self.variables)>32 or len(self.constants)>64:raise ValueError('Grammar atom budget exceeded')\n"
        "        if any(op not in ('+','-','*','/','neg','relu') for op in operators) or len(set(operators))!=len(operators):raise ValueError('Unsupported grammar production')\n"
        "        if type(max_nodes) is not int or not 1<=max_nodes<=63 or type(max_depth) is not int or not 1<=max_depth<=16:raise ValueError('Grammar resource budget exceeded')\n"
        '        self.operators=tuple(operators);self.max_nodes=max_nodes;self.max_depth=max_depth\n'
        '    def productions(self,partial):\n'
        '        path=first_hole(partial)\n'
        '        if path is None:return []\n'
        "        options=[('var:'+v,('var',v)) for v in self.variables]+[('const:'+c,('const',c)) for c in self.constants]\n"
        '        for op in self.operators:\n'
        "            arity=1 if op in ('neg','relu') else 2\n"
        '            if len(path)+1<self.max_depth and size(partial)+arity<=self.max_nodes:\n'
        "                options.append((op,(op,*[('hole',)]*arity)))\n"
        '        return [(label,replace(partial,path,value)) for label,value in options]\n'
        '    def complete(self,partial,rng):\n'
        '        while holes(partial):\n'
        '            choices=self.productions(partial)\n'
        '            atoms=[choice for choice in choices if holes(choice[1])<holes(partial)]\n'
        "            if not choices:raise ValueError('Grammar cannot complete partial AST')\n"
        '            pool=atoms if rng.random()<0.72 else choices\n'
        '            partial=rng.choice(pool)[1]\n'
        '        return partial\n'
    ),
    ('omega_synth_mcts/policy.py',
        '"""Proposal guides have no admission authority; malformed priors are rejected."""\n'
        'import math\n'
        '\n'
        '\n'
        'def features(partial,variables):\n'
        '    from .grammar import size,holes\n'
        "    operations={'+':0,'-':0,'*':0,'/':0}\n"
        '    def visit(node):\n'
        '        if node[0] in operations:operations[node[0]]+=1\n'
        '        for child in node[1:]:\n'
        '            if isinstance(child,(tuple,list)):visit(child)\n'
        '    visit(partial)\n'
        '    return [size(partial)/63,holes(partial)/32,len(variables)/32,*[operations[op]/32 for op in operations],1.0]\n'
        '\n'
        '\n'
        'class HeuristicPolicy:\n'
        '    def __init__(self):self.statistics={}\n'
        '    def priors(self,partial,productions,variables):\n'
        '        weights=[]\n'
        '        for label,_ in productions:\n'
        '            visits,reward=self.statistics.get(label,(0,0.0))\n'
        "            base=2.0 if label.startswith('var:') else 1.2 if label.startswith('const:') else 1.0\n"
        '            weights.append(base*(1+reward/max(1,visits)))\n'
        '        total=sum(weights)\n'
        '        return [w/total for w in weights]\n'
        '    def update(self,labels,reward):\n'
        '        for label in labels:\n'
        '            visits,total=self.statistics.get(label,(0,0.0));self.statistics[label]=(visits+1,total+reward)\n'
        '\n'
        '\n'
        'class NeuralPolicy:\n'
        '    """Tiny optional PyTorch guide, trained on grammar decisions and rewards."""\n'
        '    def __init__(self,labels,*,seed=0):\n'
        '        import torch\n'
        "        if not labels or len(set(labels))!=len(labels) or len(labels)>128:raise ValueError('Bounded unique production labels required')\n"
        '        self.labels=tuple(labels);self.index={v:i for i,v in enumerate(labels)}\n'
        '        with torch.random.fork_rng():\n'
        '            torch.manual_seed(seed);self.network=torch.nn.Sequential(torch.nn.Linear(8,32),torch.nn.Tanh(),torch.nn.Linear(32,len(labels)))\n'
        '        self.optimizer=torch.optim.Adam(self.network.parameters(),lr=0.01)\n'
        '        self.history=[]\n'
        '    def priors(self,partial,productions,variables):\n'
        '        import torch\n'
        '        with torch.no_grad():logits=self.network(torch.tensor(features(partial,variables),dtype=torch.float32))\n'
        '        selected=[float(logits[self.index[label]]) if label in self.index else 0.0 for label,_ in productions]\n'
        '        maximum=max(selected);weights=[math.exp(v-maximum) for v in selected];total=sum(weights)\n'
        '        return [v/total for v in weights]\n'
        '    def train(self,observations,*,epochs=8):\n'
        '        import torch\n'
        "        if type(epochs) is not int or not 1<=epochs<=128 or not 1<=len(observations)<=4096:raise ValueError('Training budget exceeded')\n"
        '        vectors=[];targets=[]\n'
        '        for vector,label in observations:\n'
        "            if len(vector)!=8 or any(not math.isfinite(float(x)) for x in vector) or label not in self.index:raise ValueError('Invalid policy observation')\n"
        '            vectors.append(vector);targets.append(self.index[label])\n'
        '        x=torch.tensor(vectors,dtype=torch.float32);y=torch.tensor(targets)\n'
        '        for _ in range(epochs):\n'
        '            self.optimizer.zero_grad();loss=torch.nn.functional.cross_entropy(self.network(x),y)\n'
        "            if not torch.isfinite(loss):raise ValueError('Nonfinite guide loss')\n"
        '            loss.backward();self.optimizer.step();self.history.append(float(loss.detach()))\n'
        '        return tuple(self.history[-epochs:])\n'
        '    def update(self,labels,reward):pass\n'
    ),
    ('omega_synth_mcts/pruning.py',
        '"""Only a discharged contradiction may justify pruning a partial subtree."""\n'
        'from omega_refine_check.syntax import parse,substitute\n'
        'from omega_refine_check.lean import prove\n'
        '\n'
        '\n'
        'def contains_hole(node):\n'
        "    if node[0]=='hole':return True\n"
        '    return any(contains_hole(child) for child in node[1:] if isinstance(child,(tuple,list)))\n'
        '\n'
        '\n'
        'class LeanPruner:\n'
        '    def __init__(self,variables,*,enabled=True):\n'
        '        self.variables=variables;self.enabled=enabled;self.cache={};self.certificates=[]\n'
        '    def prune(self,partial):\n'
        '        if not self.enabled:return False\n'
        '        denominator=None\n'
        '        def visit(node):\n'
        '            nonlocal denominator\n'
        "            if node[0]=='/' and not contains_hole(node[2]):denominator=node[2]\n"
        '            for child in node[1:]:\n'
        '                if isinstance(child,(tuple,list)):visit(child)\n'
        '        visit(partial)\n'
        '        if denominator is None:return False\n'
        '        key=repr(denominator)\n'
        '        if key in self.cache:return self.cache[key]\n'
        '        # Test exact constant contradictions cheaply before invoking Lean.\n'
        "        if denominator[0]!='const' or denominator[1]!='0':self.cache[key]=False;return False\n"
        '        names=list(self.variables);premises=[]\n'
        "        for name,predicate in self.variables.items():premises.append(substitute(parse(predicate),{'self':('var',name),**{v:('var',v) for v in names}}))\n"
        "        proof=prove(names,premises,[('==',denominator,('const','0'))])\n"
        "        self.certificates.append({'reason':'identically zero divisor in every completion','denominator':denominator,'proof':proof})\n"
        '        self.cache[key]=True;return True\n'
    ),
    ('omega_synth_mcts/search.py',
        '"""PUCT over partial Omega ASTs with independent universal admission."""\n'
        'from dataclasses import dataclass,field\n'
        'from fractions import Fraction as Q\n'
        'import math\n'
        'import random\n'
        'import time\n'
        'from omega_refine_check.syntax import parse,evaluate,rational,render,substitute\n'
        'from omega_refine_check.contracts import verify_contract\n'
        'from .grammar import Grammar,holes,size\n'
        'from .policy import HeuristicPolicy\n'
        'from .pruning import LeanPruner\n'
        '\n'
        '\n'
        '@dataclass\n'
        'class Node:\n'
        '    ast:tuple\n'
        '    prior:float=1.0\n'
        "    label:str='root'\n"
        '    visits:int=0\n'
        '    value:float=0.0\n'
        '    children:list=field(default_factory=list)\n'
        '    expanded:bool=False\n'
        '\n'
        '\n'
        'def specification(spec):\n'
        "    fields={'variables','ensures','examples','constants','requires','operators'}\n"
        "    if type(spec) is not dict or not {'variables','ensures','examples'}<=set(spec)<=fields:raise ValueError('Explicit synthesis contract and examples required')\n"
        "    variables=spec['variables']\n"
        "    if type(variables) is not dict or len(variables)>32 or type(spec['examples']) is not list or not 1<=len(spec['examples'])<=64:raise ValueError('Problem budget exceeded')\n"
        '    normalized=[]\n'
        "    for observation in spec['examples']:\n"
        "        if type(observation) is not dict or set(observation)!={'inputs','output'} or set(observation['inputs'])!=set(variables):raise ValueError('Example schema mismatch')\n"
        "        env={v:rational(q) for v,q in observation['inputs'].items()}\n"
        '        for v,p in variables.items():\n'
        "            if evaluate(parse(p),{**env,'self':env[v]}) is not True:raise ValueError('Example violates variable contract')\n"
        "        if any(evaluate(parse(p),env) is not True for p in spec.get('requires',[])):raise ValueError('Example violates precondition')\n"
        "        target=rational(observation['output'])\n"
        "        if evaluate(parse(spec['ensures']),{**env,'result':target}) is not True:raise ValueError('Example target violates requested postcondition')\n"
        '        normalized.append((env,target))\n'
        '    return normalized\n'
        '\n'
        '\n'
        'def search(spec,*,iterations=1024,max_nodes=15,max_depth=8,seconds=30,seed=0,policy=None,verify=True,max_proof_checks=16):\n'
        '    if type(iterations) is not int or not 1<=iterations<=100000 or type(seconds) not in (int,float) or not math.isfinite(seconds) or not 0<seconds<=3600 or type(seed) is not int:\n'
        "        raise ValueError('MCTS execution budget exceeded')\n"
        "    if type(max_proof_checks) is not int or not 1<=max_proof_checks<=128:raise ValueError('Proof budget exceeded')\n"
        '    examples=specification(spec)\n'
        "    grammar=Grammar(spec['variables'],spec.get('constants',[0,1,-1]),operators=spec.get('operators',['+','-','*','/','neg','relu']),max_nodes=max_nodes,max_depth=max_depth)\n"
        "    guide=policy or HeuristicPolicy();pruner=LeanPruner(spec['variables'],enabled=verify)\n"
        "    root=Node(('hole',));rng=random.Random(seed);started=time.monotonic()\n"
        '    considered=set();rejected=[];proof_checks=0;pruned=0;evaluations=0;expansions=0;best=None;best_loss=None\n'
        '    for iteration in range(iterations):\n'
        '        if time.monotonic()-started>=seconds:break\n'
        '        node=root;path=[node]\n'
        '        while node.expanded and node.children:\n'
        '            node=max(node.children,key=lambda n:(n.value/max(1,n.visits)+1.4*n.prior*math.sqrt(max(1,path[-1].visits))/(1+n.visits),rng.random()))\n'
        '            path.append(node)\n'
        '        if holes(node.ast) and not node.expanded:\n'
        '            options=grammar.productions(node.ast);priors=guide.priors(node.ast,options,grammar.variables)\n'
        "            if len(priors)!=len(options) or any(type(p) not in (int,float) or not math.isfinite(p) or p<0 for p in priors) or sum(priors)<=0:raise ValueError('Invalid neural/heuristic proposal distribution')\n"
        '            total=sum(priors)\n'
        '            for (label,ast),prior in zip(options,priors):\n'
        '                if pruner.prune(ast):pruned+=1;continue\n'
        '                node.children.append(Node(ast,float(prior/total),label))\n'
        '            node.expanded=True;expansions+=len(options)\n'
        '            if node.children:\n'
        '                node=rng.choices(node.children,weights=[max(n.prior,1e-12) for n in node.children])[0];path.append(node)\n'
        '        candidate=grammar.complete(node.ast,rng) if holes(node.ast) else node.ast\n'
        '        try:\n'
        '            loss=sum((abs(evaluate(candidate,env)-target) for env,target in examples),Q(0))\n'
        "            if max(abs(loss.numerator).bit_length(),loss.denominator.bit_length())>16384:raise ValueError('Fitness arithmetic budget exceeded')\n"
        '            reward=1/(1+float(loss))\n'
        '        except (ValueError,ZeroDivisionError,OverflowError,TypeError):loss=None;reward=0.0\n'
        '        evaluations+=1\n'
        '        if loss is not None and (best_loss is None or loss<best_loss):best_loss=loss;best=candidate\n'
        '        for visited in path:visited.visits+=1;visited.value+=reward\n'
        '        guide.update([n.label for n in path[1:]],reward)\n'
        '        key=repr(candidate)\n'
        '        if loss==0 and key not in considered:\n'
        '            considered.add(key)\n'
        '            if not verify:\n'
        "                return {'candidate':candidate,'admission':None,'verified':False,'evaluations':evaluations,'expansions':expansions,'pruned':pruned,'seed':seed}\n"
        '            proof_checks+=1\n'
        '            try:\n'
        "                admission=verify_contract(spec['variables'],candidate,spec['ensures'],requires=spec.get('requires',()))\n"
        "                return {'candidate':candidate,'source':render(candidate),'verified':True,'admission':admission,\n"
        "                        'evaluations':evaluations,'expansions':expansions,'pruned':pruned,'pruning_certificates':pruner.certificates,\n"
        "                        'proof_checks':proof_checks,'rejected':rejected,'seed':seed,'optimality_proved':False}\n"
        "            except ValueError as error:rejected.append({'candidate':candidate,'reason':str(error)[-2000:]})\n"
        '            if proof_checks>=max_proof_checks:break\n'
        "    return {'candidate':None,'verified':False,'evaluations':evaluations,'expansions':expansions,'pruned':pruned,\n"
        "            'pruning_certificates':pruner.certificates,'proof_checks':proof_checks,'rejected':rejected,\n"
        "            'best_observed':best,'best_loss':str(best_loss),'seed':seed,'reason':'search or proof budget exhausted','optimality_proved':False}\n"
        '\n'
        '\n'
        'def synthesize(spec,directory,**limits):\n'
        '    import json\n'
        '    from pathlib import Path\n'
        '    result=search(spec,**limits)\n'
        '    root=Path(directory);root.mkdir(parents=True,exist_ok=False)\n'
        "    (root/'search.json').write_text(json.dumps(result,sort_keys=True,indent=2)+'\\n')\n"
        "    if result['verified']:\n"
        "        (root/'contract.lean').write_text(result['admission']['source'])\n"
        '        lines=[]\n'
        "        first=spec['examples'][0]['inputs']\n"
        '        for name,value in first.items():lines.append(f\'parametro {name}={render(("const",str(rational(value))))};\')\n'
        "        lines += ['tensor result='+result['source']+';','mostrar result;']\n"
        "        source=root/'candidate.omega';source.write_text('\\n'.join(lines)+'\\n')\n"
        '        from omega_selfhost.driver import build,run\n'
        "        build(source,root/'candidate');observed,native=run(root/'candidate')\n"
        "        if Q(observed['values']['result'])!=rational(spec['examples'][0]['output']):raise ValueError('Native synthesized result mismatch')\n"
        "        result['native_admission']=native\n"
        '    return result\n'
        '\n'
        '\n'
        'def isolated_search(spec,*,budget=None,**limits):\n'
        '    """No-network AST proposal process, followed by independent host admission."""\n'
        '    import json,sys,tempfile\n'
        '    from pathlib import Path\n'
        '    from omega_platform.sandbox import run\n'
        '    from omega_platform.budget import Budget\n'
        '    from omega_refine_check.syntax import tree\n'
        '    from dataclasses import asdict\n'
        '    specification(spec)\n'
        "    if set(limits)-{'iterations','max_nodes','max_depth','seconds','seed'}:raise ValueError('Unknown isolated search limit')\n"
        '    budget=budget or Budget(wall_seconds=60,cpu_seconds=45)\n'
        '    package=Path(__file__).resolve().parent;root=package.parent\n'
        "    with tempfile.TemporaryDirectory(prefix='omega-mcts-proposal-') as temporary:\n"
        "        path=Path(temporary)/'problem.json';path.write_text(json.dumps({'spec':spec,'limits':limits}))\n"
        "        mounts=[root/name for name in ('omega_synth_mcts','omega_refine_check','omega','omega_selfhost','omega_platform')]\n"
        "        outcome=run([sys.executable,'-E','-S','-B',package/'worker.py',path],\n"
        "                    readonly=[*mounts,path,Path(sys.base_prefix)/'lib'],budget=budget,check=True)\n"
        '    proposal=json.loads(outcome.stdout)\n'
        "    if type(proposal) is not dict or proposal.get('verified') is not False:raise ValueError('Invalid proposal envelope')\n"
        "    if proposal.get('candidate') is None:return {**proposal,'sandboxed':outcome.sandboxed,'budget':asdict(budget)}\n"
        "    candidate=tree(proposal['candidate'])\n"
        "    if size(candidate)>limits.get('max_nodes',15):raise ValueError('Proposal exceeds host AST budget')\n"
        '    examples=specification(spec)\n'
        "    if any(evaluate(candidate,env)!=target for env,target in examples):raise ValueError('Proposal fails host replay')\n"
        "    admission=verify_contract(spec['variables'],candidate,spec['ensures'],requires=spec.get('requires',()))\n"
        "    return {**proposal,'candidate':candidate,'source':render(candidate),'verified':True,'admission':admission,\n"
        "            'sandboxed':outcome.sandboxed,'budget':asdict(budget),'optimality_proved':False}\n"
    ),
