        '"""Fixed resource-bounded proposal worker; host verification is mandatory."""\n'
        'import json\n'
        'from pathlib import Path\n'
        'import sys\n'
        "if __package__ in (None,''):sys.path.insert(0,str(Path(__file__).resolve().parents[1]))\n"
        'from omega_synth_mcts.search import search\n'
        '\n'
        '\n'
        'def main():\n'
        '    path=Path(sys.argv[1])\n'
        "    if path.stat().st_size>1024*1024:raise ValueError('Worker input budget exceeded')\n"
        '    data=json.loads(path.read_text())\n'
        "    result=search(data['spec'],verify=False,**data.get('limits',{}))\n"
        '    print(json.dumps(result,sort_keys=True))\n'
