    ('omega_tools/approvals.py',
        'from dataclasses import dataclass\n'
        'import hashlib,json,time,math,re\n'
        'from threading import RLock\n'
        'from omega_security.encoding import digest as action_digest\n'
        '@dataclass(frozen=True)\n'
        'class Approval:\n'
        '    actor: str\n'
        '    action_digest: str\n'
        '    expires: float\n'
        '    signature: bytes\n'
        '    def __post_init__(self):\n'
        "        if type(self.actor) is not str or not self.actor or len(self.actor)>256:raise ValueError('Invalid approval actor')\n"
        "        if type(self.action_digest) is not str or not re.fullmatch('[0-9a-f]{64}',self.action_digest):raise ValueError('Invalid approval subject')\n"
        "        if type(self.expires) not in (int,float) or not math.isfinite(self.expires) or self.expires<=0:raise ValueError('Invalid approval expiry')\n"
        "        if type(self.signature) is not bytes or not 0<len(self.signature)<=1024:raise ValueError('Invalid approval signature')\n"
        'class ApprovalGate:\n'
        '    def __init__(self,authenticate,approvers):self.authenticate=authenticate;self.approvers=frozenset(approvers);self.used=set();self.lock=RLock()\n'
        '    def digest(self,action):return action_digest(action)\n'
        '    def consume(self,action,approval,proposer):\n'
        "        if type(approval) is not Approval or approval.actor not in self.approvers or approval.actor==proposer:raise PermissionError('Independent approver required')\n"
        '        digest=self.digest(action)\n'
        "        if approval.action_digest!=digest or time.time()>=approval.expires or self.authenticate(approval) is not True:raise PermissionError('Approval invalid')\n"
        '        identity=(approval.actor,approval.signature)\n'
        '        with self.lock:\n'
        "            if identity in self.used:raise PermissionError('Approval already consumed')\n"
        '            self.used.add(identity)\n'
        '        return digest\n'
    ),
    ('omega_tools/audio.py',
        'import io,wave,hashlib\n'
        'def inspect_wav(data):\n'
        "    if type(data) is not bytes or len(data)>32*1024**2:raise ValueError('Audio byte budget exceeded')\n"
        "    with wave.open(io.BytesIO(data),'rb') as stream:\n"
        '        channels=stream.getnchannels();rate=stream.getframerate();width=stream.getsampwidth();frames=stream.getnframes()\n'
        "        if channels not in (1,2) or width not in (2,3) or not 8000<=rate<=96000 or frames>rate*60:raise ValueError('Unsupported PCM audio budget/format')\n"
        "        if len(stream.readframes(frames))!=frames*channels*width:raise ValueError('Truncated PCM audio')\n"
        "    return {'channels':channels,'sample_rate':rate,'sample_width':width,'frames':frames,'sha256':hashlib.sha256(data).hexdigest()}\n"
        'def transcribe(data,provider,*,capability,verifier,principal):\n'
        "    verifier.require(capability,principal,'audio.transcribe');metadata=inspect_wav(data);text=provider(data,metadata)\n"
        "    if type(text) is not str or len(text)>65536:raise ValueError('Invalid transcription')\n"
        "    return {'text':text,'audio':metadata,'authority':False}\n"
        'def synthesize(text,provider,*,capability,verifier,principal):\n'
        "    verifier.require(capability,principal,'audio.synthesize')\n"
        "    if type(text) is not str or len(text)>4096:raise ValueError('Speech text budget exceeded')\n"
        '    data=provider(text);inspect_wav(data);return data\n'
    ),
    ('omega_tools/capability_adapter.py',
        '"""Registered host tools retain capability, path and approval boundaries."""\n'
        'from threading import RLock\n'
        'from .contracts import Tool\n'
        'from omega_security.encoding import digest\n'
        'from omega_security.capabilities import Capability\n'
        '\n'
        '\n'
        'class CapabilityAdapter:\n'
        '    def __init__(self,verifier,principal,audit,*,approval_gate=None,max_calls=128):\n'
        "        if type(max_calls) is not int or not 1<=max_calls<=10000:raise ValueError('Invalid tool call budget')\n"
        '        self.verifier=verifier;self.principal=principal;self.audit=audit\n'
        '        self.approval_gate=approval_gate;self.max_calls=max_calls\n'
        '        self._tools={};self._calls=0;self._lock=RLock();self._sealed=False\n'
        '\n'
        '    def register(self,tool):\n'
        "        if type(tool) is not Tool:raise TypeError('Typed tool registration required')\n"
        '        with self._lock:\n'
        "            if self._sealed or tool.name in self._tools:raise ValueError('Tool registry is sealed or name is duplicated')\n"
        "            if tool.approval_required and self.approval_gate is None:raise ValueError('Independent approval gate is missing')\n"
        '            self._tools[tool.name]=tool\n'
        '\n'
        '    def request(self,name,arguments):\n'
        '        with self._lock:\n'
        "            if name not in self._tools:raise PermissionError('Unknown tool')\n"
        '            tool=self._tools[name]\n'
        "        return {'tool':name,'action':tool.action,'arguments':tool.arguments.copy(arguments),'principal':self.principal}\n"
        '\n'
        '    def call(self,name,arguments,capability,*,approval=None):\n'
        "        if type(capability) is not Capability:raise PermissionError('Host-issued capability required')\n"
        '        request=self.request(name,arguments);tool=self._tools[name];subject=digest(request)\n'
        "        bound_subject=subject if 'subject' in capability.claims() else None\n"
        '        def authorize():\n'
        '            claim=self.verifier.require(capability,self.principal,tool.action,subject=bound_subject)\n'
        '            for field in tool.path_fields:\n'
        "                self.verifier.require(capability,self.principal,tool.action,path=request['arguments'][field],subject=bound_subject)\n"
        '            return claim\n'
        '        claim=authorize()\n'
        '        with self._lock:\n'
        "            if self._calls>=self.max_calls:raise ValueError('Tool call budget exhausted')\n"
        '            self._sealed=True;self._calls+=1\n'
        '        if tool.approval_required:self.approval_gate.consume(request,approval,self.principal)\n'
        "        self.audit.append({'tool':name,'principal':self.principal,'capability_id':claim['id'],'request_sha256':subject,'status':'started'})\n"
        '        authorize()\n'
        '        try:\n'
        "            result=tool.response.copy(tool.invoke(tool.arguments.copy(request['arguments'])))\n"
        '            authorize()\n'
        '        except Exception as exc:\n'
        "            try:self.audit.append({'tool':name,'request_sha256':subject,'status':'failed','error_type':type(exc).__name__,'effect_may_have_happened':True})\n"
        '            except Exception:pass\n'
        '            raise\n'
        "        self.audit.append({'tool':name,'request_sha256':subject,'response_sha256':digest(result,max_bytes=tool.response.max_bytes),'status':'completed'})\n"
        '        return result\n'
    ),
    ('omega_tools/contracts.py',
        '"""Bounded JSON-schema subset for tool boundaries. No implicit coercion."""\n'
        'from dataclasses import dataclass\n'
        'from types import MappingProxyType\n'
        'from omega_security.encoding import canonical,snapshot\n'
        '@dataclass(frozen=True)\n'
        'class Contract:\n'
        '    fields: dict\n'
        '    required: frozenset[str]\n'
        '    max_bytes: int=1024*1024\n'
        '    def __post_init__(self):\n'
        '        allowed={str,int,float,bool,list,dict,type(None)}\n'
        "        if type(self.fields) is not dict or any(type(k) is not str or not k or v not in allowed for k,v in self.fields.items()):raise ValueError('Invalid tool schema')\n"
        '        required=frozenset(self.required)\n'
        "        if not required<=set(self.fields) or type(self.max_bytes) is not int or not 1<=self.max_bytes<=8*1024**2:raise ValueError('Invalid contract bounds')\n"
        "        object.__setattr__(self,'fields',MappingProxyType(dict(self.fields)))\n"
        "        object.__setattr__(self,'required',required)\n"
        '    def check(self,value):\n'
        "        if type(value) is not dict or not self.required<=set(value)<=set(self.fields):raise ValueError('Tool fields do not match contract')\n"
        '        canonical(value,max_bytes=self.max_bytes)\n'
        '        for name,item in value.items():\n'
        '            expected=self.fields[name]\n'
        "            if type(item) is not expected:raise TypeError('Tool field type mismatch: '+name)\n"
        '        return value\n'
        '    def copy(self,value):return snapshot(self.check(value),max_bytes=self.max_bytes)\n'
        '@dataclass(frozen=True)\n'
        'class Tool:\n'
        '    name: str\n'
        '    action: str\n'
        '    arguments: Contract\n'
        '    response: Contract\n'
        '    invoke: object\n'
        '    path_fields: tuple[str,...]=()\n'
        '    approval_required: bool=False\n'
        '    def __post_init__(self):\n'
        "        if type(self.name) is not str or not self.name or type(self.action) is not str or not self.action or not callable(self.invoke):raise ValueError('Invalid tool registration')\n"
        "        if type(self.arguments) is not Contract or type(self.response) is not Contract:raise TypeError('Tool contracts required')\n"
        "        if type(self.path_fields) is not tuple or len(set(self.path_fields))!=len(self.path_fields):raise ValueError('Invalid tool path fields')\n"
        "        if any(self.arguments.fields.get(name) is not str or name not in self.arguments.required for name in self.path_fields):raise ValueError('Scoped paths must be required string fields')\n"
        "        if type(self.approval_required) is not bool:raise TypeError('Explicit tool approval policy required')\n"
        "        if self.action in {'file.write','code.write','database.write','git.write','github.pr.create','github.issue.create'} and not self.approval_required:\n"
        "            raise ValueError('Mutating tool needs an independent approval gate')\n"
    ),
    ('omega_tools/database.py',
        'from pathlib import Path\n'
        'from .worker import invoke\n'
        'from omega_platform.budget import Budget\n'
        'def query(path,sql,parameters=(),*,write=False,capability,verifier,principal,approval=None,approval_gate=None,budget=Budget()):\n'
        "    if type(write) is not bool:raise TypeError('Explicit boolean write mode required')\n"
        "    path=Path(path).resolve(strict=True);verifier.require(capability,principal,'database.write' if write else 'database.read',path=path)\n"
        "    if not isinstance(sql,str) or len(sql)>65536:raise ValueError('Query budget exceeded')\n"
        '    keyword=sql.lstrip().split(None,1)[0].upper()\n'
        "    if keyword not in ({'SELECT','INSERT','UPDATE','DELETE'} if write else {'SELECT'}):raise PermissionError('SQL operation not authorized')\n"
        "    action={'path':str(path),'sql':sql,'parameters':parameters}\n"
        '    if write:\n'
        "        if approval_gate is None:raise PermissionError('Mutation approval gate required')\n"
        '        approval_gate.consume(action,approval,principal)\n'
        "    request={**action,'query':sql,'write':write}\n"
        "    return invoke('database_worker',request,readonly=[] if write else [path],writable=[path.parent] if write else [],budget=budget)\n"
    ),
    ('omega_tools/database_worker.py',
        'import base64,json,sqlite3,sys,time\n'
        'from pathlib import Path\n'
        'def main():\n'
        "    request=json.loads(Path(sys.argv[2]).read_bytes());path=Path(request['path']);write=request['write'];query=request['query']\n"
        "    connection=sqlite3.connect(path.as_uri()+('?mode=rw' if write else '?mode=ro'),uri=True,timeout=2)\n"
        '    connection.enable_load_extension(False)\n'
        '    read={sqlite3.SQLITE_SELECT,sqlite3.SQLITE_READ,sqlite3.SQLITE_TRANSACTION}\n'
        '    mutation={sqlite3.SQLITE_UPDATE,sqlite3.SQLITE_INSERT,sqlite3.SQLITE_DELETE} if write else set()\n'
        "    functions={'count','sum','avg','min','max','length','lower','upper','coalesce','abs','substr','round','trim','like'}\n"
        '    def authorize(action,a,b,database,trigger):\n'
        '        if action==sqlite3.SQLITE_FUNCTION:return sqlite3.SQLITE_OK if isinstance(b,str) and b.lower() in functions else sqlite3.SQLITE_DENY\n'
        '        return sqlite3.SQLITE_OK if action in read|mutation else sqlite3.SQLITE_DENY\n'
        '    connection.set_authorizer(authorize);deadline=time.monotonic()+10;steps=[0]\n'
        '    def progress():steps[0]+=1;return int(steps[0]>10000 or time.monotonic()>deadline)\n'
        '    connection.set_progress_handler(progress,100)\n'
        '    try:\n'
        '        with connection:\n'
        "            cursor=connection.execute(query,request['parameters']);rows=cursor.fetchmany(10001)\n"
        "            if len(rows)>10000:raise ValueError('Database row budget exceeded')\n"
        "            def scalar(v):return {'base64':base64.b64encode(v).decode()} if isinstance(v,bytes) else v\n"
        "            result={'columns':[c[0] for c in cursor.description] if cursor.description else [],'rows':[[scalar(v) for v in row] for row in rows],'changed':cursor.rowcount}\n"
        "            if len(json.dumps(result).encode())>4*1024**2:raise ValueError('Database output budget exceeded')\n"
        '        print(json.dumps(result))\n'
        '    finally:connection.close()\n'
        "if __name__=='__main__':main()\n"
    ),
    ('omega_tools/document_worker.py',
        '"""Executed only inside the document parser sandbox."""\n'
        'import base64,json,sys,io\n'
        'from pathlib import Path\n'
        'def main():\n'
        "    sys.path.insert(0,sys.argv[1]);request=json.loads(Path(sys.argv[2]).read_bytes());data=base64.b64decode(request['data'],validate=True)\n"
        "    if len(data)>8*1024**2:raise ValueError('Document budget exceeded')\n"
        "    kind=request['kind'];result=[]\n"
        "    if kind=='pdf':\n"
        '        from pypdf import PdfReader\n'
        '        reader=PdfReader(io.BytesIO(data),strict=True)\n'
        "        if reader.is_encrypted or len(reader.pages)>256:raise ValueError('Unsupported encrypted/large PDF')\n"
        '        total=0\n'
        '        for number,page in enumerate(reader.pages):\n'
        "            text=page.extract_text() or '';total+=len(text)\n"
        "            if total>1000000:raise ValueError('Extracted document budget exceeded')\n"
        "            result.append({'page':number+1,'text':text})\n"
        "    elif kind in ('text','json'):\n"
        "        text=data.decode('utf-8')\n"
        "        if len(text)>1000000:raise ValueError('Text budget exceeded')\n"
        "        result=[{'page':1,'text':text}]\n"
        "        if kind=='json':json.loads(text)\n"
        "    else:raise ValueError('Unsupported document kind')\n"
        "    print(json.dumps({'pages':result},ensure_ascii=False))\n"
        "if __name__=='__main__':main()\n"
    ),
    ('omega_tools/documents.py',
        'import base64,hashlib\n'
        'from .worker import invoke\n'
        'from omega_platform.budget import Budget\n'
        'def extract(document,kind,*,budget=Budget()):\n'
        "    if len(document.content)>8*1024**2:raise ValueError('Document byte budget exceeded')\n"
        "    result=invoke('document_worker',{'kind':kind,'data':base64.b64encode(document.content).decode()},budget=budget)\n"
        "    if type(result) is not dict or type(result.get('pages')) is not list:raise ValueError('Document worker protocol mismatch')\n"
        "    return {'source':document.source,'observed_at':document.observed_at,'sha256':document.digest,'pages':result['pages'],'authority':False}\n"
    ),
    ('omega_tools/git_ci.py',
        'import json,re\n'
        'from pathlib import Path\n'
        'from omega_platform.sandbox import run,trusted\n'
        'from omega_platform.budget import BUILD_BUDGET\n'
        'def inspect(repository,operation,*,capability,verifier,principal):\n'
        "    repository=Path(repository).resolve(strict=True);verifier.require(capability,principal,'git.read',path=repository)\n"
        "    commands={'status':['status','--porcelain'],'diff':['diff','--no-ext-diff','--no-textconv'],\n"
        "              'log':['log','-20','--format=%H %s']}\n"
        "    if operation not in commands:raise PermissionError('Read-only Git operation required')\n"
        "    return run(['/usr/bin/git','--no-pager','-c','core.fsmonitor=false','-c','core.hooksPath=/dev/null','-C',repository,*commands[operation]],\n"
        "               readonly=[repository,'/usr/bin','/bin'],budget=BUILD_BUDGET,check=True).stdout\n"
        'def ci_runs(repository,*,capability,verifier,principal):\n'
        "    if not re.fullmatch(r'[\\w.-]+/[\\w.-]+',repository):raise ValueError('Invalid GitHub repository')\n"
        "    verifier.require(capability,principal,'github.ci.read')\n"
        "    result=trusted(['gh','run','list','--repo',repository,'--limit','20','--json','databaseId,headSha,status,conclusion'],budget=BUILD_BUDGET,check=True)\n"
        '    return json.loads(result.stdout)\n'
    ),
    ('omega_tools/local_files.py',
        '"""Register bounded UTF-8 file tools anchored in a supervisor-selected root."""\n'
        'import hashlib\n'
        'import re\n'
        'from pathlib import Path\n'
        'from .contracts import Contract, Tool\n'
        'from omega_security.filesystem import read, write\n'
        '\n'
        '\n'
        'def register_files(adapter, root, *, writable=False, max_bytes=256 * 1024):\n'
        '    root = Path(root).resolve(strict=True)\n'
        '    if not root.is_dir() or type(writable) is not bool or type(max_bytes) is not int or not 1 <= max_bytes <= 256 * 1024:\n'
        "        raise ValueError('Explicit file root and bounded byte limit required')\n"
        '    if writable and adapter.approval_gate is None:\n'
        "        raise PermissionError('Independent file mutation approval gate required')\n"
        '\n'
        '    def relative(path):\n'
        '        if type(path) is not str:\n'
        "            raise TypeError('Absolute file path required')\n"
        '        target = Path(path)\n'
        "        if not target.is_absolute() or str(target) != path or '..' in target.parts:\n"
        "            raise PermissionError('Normalized absolute file path required')\n"
        '        # Do not resolve the candidate path: anchored operations reject symlinks.\n'
        '        try:\n'
        '            value = target.relative_to(root).as_posix()\n'
        '        except ValueError as exc:\n'
        "            raise PermissionError('File outside configured tool root') from exc\n"
        "        if value == '.':\n"
        "            raise PermissionError('A file, not the root directory, is required')\n"
        '        return value\n'
        '\n'
        '    def read_text(arguments):\n'
        "        content = read(root, relative(arguments['path']), limit=max_bytes)\n"
        "        return {'path': arguments['path'], 'content': content.decode('utf-8'),\n"
        "                'sha256': hashlib.sha256(content).hexdigest(), 'authority': False}\n"
        '\n'
        "    adapter.register(Tool('files.read_text', 'file.read',\n"
        "                          Contract({'path': str}, frozenset({'path'}), 8192),\n"
        "                          Contract({'path': str, 'content': str, 'sha256': str, 'authority': bool},\n"
        "                                   frozenset({'path', 'content', 'sha256', 'authority'}), 2 * 1024**2),\n"
        "                          read_text, path_fields=('path',)))\n"
        '    if not writable:\n'
        '        return\n'
        '\n'
        '    def replace_text(arguments):\n'
        "        expected = arguments['expected_sha256']\n"
        "        if not re.fullmatch('[0-9a-f]{64}', expected):\n"
        "            raise ValueError('Full expected content digest required')\n"
        "        content = arguments['content'].encode('utf-8')\n"
        '        if len(content) > max_bytes:\n'
        "            raise ValueError('File write byte budget exceeded')\n"
        "        sha = write(root, relative(arguments['path']), content, expected_sha256=expected)\n"
        "        return {'path': arguments['path'], 'sha256': sha, 'bytes': len(content)}\n"
        '\n'
        "    adapter.register(Tool('files.replace_text', 'file.write',\n"
        "                          Contract({'path': str, 'content': str, 'expected_sha256': str},\n"
        "                                   frozenset({'path', 'content', 'expected_sha256'}), 2 * 1024**2),\n"
        "                          Contract({'path': str, 'sha256': str, 'bytes': int},\n"
        "                                   frozenset({'path', 'sha256', 'bytes'}), 8192),\n"
        "                          replace_text, path_fields=('path',), approval_required=True))\n"
    ),
    ('omega_tools/memory.py',
        '"""Read episodic memory through the consent facade, never through a raw DB."""\n'
        'from .contracts import Contract, Tool\n'
        'from omega_memory.privacy import PrivateMemory\n'
        '\n'
        '\n'
        'def register_memory(adapter, memory, consent_resolver):\n'
        '    if type(memory) is not PrivateMemory or memory.principal != adapter.principal or not callable(consent_resolver):\n'
        "        raise ValueError('Private memory and a host consent resolver required')\n"
        '\n'
        '    def retrieve(arguments):\n'
        "        id = arguments['id']\n"
        '        if not 0 < len(id) <= 256:\n'
        "            raise ValueError('Bounded episode identity required')\n"
        '        consent = consent_resolver(id, adapter.principal)\n'
        "        return {'episode': memory.get(id, purpose='retrieve', consent=consent), 'authority': False}\n"
        '\n'
        "    adapter.register(Tool('memory.retrieve', 'memory.retrieve',\n"
        "                          Contract({'id': str}, frozenset({'id'}), 4096),\n"
        "                          Contract({'episode': dict, 'authority': bool},\n"
        "                                   frozenset({'episode', 'authority'}), 2 * 1024**2), retrieve))\n"
    ),
    ('omega_tools/notebooks.py',
        '"""Notebook code executes only in a process sandbox, without inherited credentials."""\n'
        'import hashlib,json,sys,sysconfig,tempfile\n'
        'from pathlib import Path\n'
        'from omega_platform.sandbox import run\n'
        'from omega_platform.budget import Budget\n'
        'def execute(notebook,*,capability,verifier,principal,budget=Budget()):\n'
        "    verifier.require(capability,principal,'code.execute')\n"
        "    if type(notebook) is not dict or notebook.get('nbformat')!=4 or len(notebook.get('cells',()))>64:raise ValueError('Notebook format/budget invalid')\n"
        '    code=[]\n'
        "    for cell in notebook['cells']:\n"
        "        if cell.get('cell_type')!='code':continue\n"
        "        source=''.join(cell.get('source',())) if type(cell.get('source')) is list else cell.get('source','')\n"
        "        if not isinstance(source,str) or any(line.lstrip().startswith(('%','!')) for line in source.splitlines()):raise ValueError('Notebook magics/shell cells unsupported')\n"
        '        code.append(source)\n'
        "    source='\\n\\n'.join(code)\n"
        "    if len(source.encode())>1024*1024:raise ValueError('Notebook code budget exceeded')\n"
        "    site=Path(sysconfig.get_paths()['purelib'])\n"
        "    with tempfile.TemporaryDirectory(prefix='omega-notebook-') as tmp:\n"
        "        path=Path(tmp)/'cells.py';path.write_text('import sys\\nsys.path.insert(0,'+repr(str(site))+')\\n'+source)\n"
        '        result=run([sys.executable,path],readonly=[path,site,Path(sys.base_prefix)],budget=budget)\n'
        "    return {'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'cells':len(code),'returncode':result.returncode,\n"
        "            'stdout':result.stdout,'stderr':result.stderr,'sandboxed':result.sandboxed,'termination':result.termination}\n"
    ),
    ('omega_tools/simulation.py',
        '"""Finite MDP simulator with explicit state/action/reward contracts."""\n'
        'import math,random\n'
        'class Simulation:\n'
        '    def __init__(self,transitions,initial,terminal=(),seed=0):\n'
        '        self.transitions=transitions;self.initial=initial;self.state=initial;self.terminal=frozenset(terminal);self.rng=random.Random(seed);self.steps=0\n'
        "        if len(transitions)>10000 or initial not in transitions:raise ValueError('Invalid simulation state space')\n"
        '        for state,actions in transitions.items():\n'
        '            for action,outcomes in actions.items():\n'
        "                if not outcomes or abs(sum(p for p,s,r in outcomes)-1)>1e-8:raise ValueError('Transition probabilities must sum to one')\n"
        "                if any(not 0<=p<=1 or s not in transitions or not math.isfinite(r) for p,s,r in outcomes):raise ValueError('Invalid finite transition')\n"
        '    def reset(self):self.state=self.initial;self.steps=0;return self.state\n'
        '    def actions(self):return tuple(sorted(self.transitions[self.state],key=repr))\n'
        '    def step(self,action):\n'
        "        if self.state in self.terminal or self.steps>=10000:raise ValueError('Simulation terminated')\n"
        '        outcomes=self.transitions[self.state][action];index=self.rng.choices(range(len(outcomes)),weights=[p for p,s,r in outcomes],k=1)[0]\n'
        '        _,state,reward=outcomes[index];self.state=state;self.steps+=1\n'
        "        return {'state':state,'reward':reward,'terminal':state in self.terminal,'step':self.steps}\n"
    ),
    ('omega_tools/vision.py',
        '"""Typed vision-provider adapter; model quality needs a separate held-out corpus."""\n'
        'import base64,hashlib\n'
        'def describe(image,provider,*,capability,verifier,principal):\n'
        "    verifier.require(capability,principal,'vision.infer')\n"
        "    if type(image) is not bytes or not 0<len(image)<=16*1024**2:raise ValueError('Image byte budget exceeded')\n"
        '    digest=hashlib.sha256(image).hexdigest()\n'
        "    response=provider({'image_base64':base64.b64encode(image).decode(),'sha256':digest,'input_is_untrusted_data':True})\n"
        "    if type(response) is not dict or set(response)!={'description','objects'} or type(response['description']) is not str or type(response['objects']) is not list or len(response['description'])>32768 or len(response['objects'])>1024:raise ValueError('Invalid vision response')\n"
        "    for item in response['objects']:\n"
        "        if type(item) is not dict or set(item)!={'label','confidence','box'} or type(item['label']) is not str:raise ValueError('Malformed vision object')\n"
        "        if not 0<=item['confidence']<=1 or len(item['box'])!=4 or any(not 0<=v<=1 for v in item['box']):raise ValueError('Invalid vision object geometry')\n"
        "    return {**response,'source_sha256':digest,'authority':False}\n"
    ),
    ('omega_tools/web.py',
        '"""Explicitly authorized HTTPS retrieval; redirects need their own capability scope."""\n'
        'import datetime,hashlib,urllib.request,urllib.parse\n'
        'from omega_security.untrusted_data import UntrustedDocument\n'
        'class Retrieval:\n'
        '    def __init__(self,verifier,principal,capability):self.verifier=verifier;self.principal=principal;self.capability=capability\n'
        '    def require(self,url):\n'
        '        parsed=urllib.parse.urlsplit(url)\n'
        "        if parsed.scheme!='https' or not parsed.hostname or parsed.username or parsed.password or parsed.port not in (None,443):raise PermissionError('Only ordinary HTTPS URLs allowed')\n"
        "        self.verifier.require(self.capability,self.principal,'network:'+parsed.hostname.lower())\n"
        '    def get(self,url,max_bytes=4*1024**2,timeout=15):\n'
        "        if not 1<=max_bytes<=8*1024**2 or not 0<timeout<=30:raise ValueError('Invalid retrieval budget')\n"
        '        self.require(url);owner=self\n'
        '        class Redirect(urllib.request.HTTPRedirectHandler):\n'
        '            max_redirections=3\n'
        '            def redirect_request(self,request,fp,code,msg,headers,newurl):\n'
        '                owner.require(newurl);return super().redirect_request(request,fp,code,msg,headers,newurl)\n'
        '        opener=urllib.request.build_opener(Redirect())\n'
        "        request=urllib.request.Request(url,headers={'User-Agent':'Omega-Research/2.0','Accept':'text/*,application/json,application/pdf'})\n"
        '        with opener.open(request,timeout=timeout) as response:\n'
        '            self.require(response.url);content=response.read(max_bytes+1);final=response.url\n'
        "        if len(content)>max_bytes:raise ValueError('Retrieval byte budget exceeded')\n"
        '        observed=datetime.datetime.now(datetime.timezone.utc).isoformat()\n'
        '        return UntrustedDocument(final,content,observed)\n'
    ),
    ('omega_tools/worker.py',
        '"""Private parsing workers get only bounded requests and explicit mounts."""\n'
        'import json,sys,sysconfig,tempfile\n'
        'from pathlib import Path\n'
        'from omega_platform.sandbox import run\n'
        'from omega_platform.budget import Budget\n'
        "WORKERS=frozenset({'document_worker','database_worker'})\n"
        'def invoke(name,request,*,readonly=(),writable=(),budget=Budget()):\n'
        "    if name not in WORKERS:raise ValueError('Unknown trusted worker')\n"
        '    data=json.dumps(request,allow_nan=False).encode()\n'
        "    if len(data)>16*1024**2:raise ValueError('Worker input budget exceeded')\n"
        "    site=Path(sysconfig.get_paths()['purelib']);worker=Path(__file__).with_name(name+'.py')\n"
        "    with tempfile.TemporaryDirectory(prefix='omega-tool-') as tmp:\n"
        "        path=Path(tmp)/'request.json';path.write_bytes(data)\n"
        '        result=run([sys.executable,worker,site,path],readonly=[worker,site,Path(sys.base_prefix),path,*readonly],writable=writable,budget=budget,check=True)\n'
        '    return json.loads(result.stdout)\n'
    ),
