    ('runtime/cellular_micro_arena.h',
        '#ifndef OMEGA_CELLULAR_MICRO_ARENA_H\n'
        '#define OMEGA_CELLULAR_MICRO_ARENA_H\n'
        '/* Allocation-free, stackless, single-thread cooperative microactors.\n'
        ' * Caller owns storage and immutable bytecode. Exact bounded rationals use\n'
        ' * checked 128-bit intermediates. No GMP, OS, threads, callbacks or I/O here. */\n'
        '#include <stdint.h>\n'
        '#include <stddef.h>\n'
        '#include <limits.h>\n'
        '#ifndef __SIZEOF_INT128__\n'
        '#error "This bounded rational backend requires compiler 128-bit integer support"\n'
        '#endif\n'
        '\n'
        'typedef struct { int64_t n; uint64_t d; } OmegaMicroQ;\n'
        'enum { OMEGA_MICRO_SET, OMEGA_MICRO_ADD, OMEGA_MICRO_MUL,\n'
        '       OMEGA_MICRO_ASSERT, OMEGA_MICRO_SEND, OMEGA_MICRO_RECV,\n'
        '       OMEGA_MICRO_JUMP, OMEGA_MICRO_JNZ, OMEGA_MICRO_YIELD, OMEGA_MICRO_HALT };\n'
        'enum { OMEGA_MICRO_READY, OMEGA_MICRO_BLOCKED_SEND,\n'
        '       OMEGA_MICRO_BLOCKED_RECEIVE, OMEGA_MICRO_HALTED };\n'
        'typedef struct {\n'
        '    uint32_t op, reg, target;\n'
        '    OmegaMicroQ value;\n'
        '} OmegaMicroInstruction;\n'
        'typedef struct {\n'
        '    uint32_t pc, head, tail, count, halted, status;\n'
        '    uint64_t executed;\n'
        '    OmegaMicroQ registers[16], mailbox[64];\n'
        '} OmegaMicroCell;\n'
        'typedef struct {\n'
        '    unsigned char *storage;\n'
        '    size_t storage_bytes, stride, code_length;\n'
        '    uint32_t actors, registers, mailbox_capacity, quantum, completed, deadlock;\n'
        '    uint64_t turns, instructions, messages, mailbox_peak, idle_turns;\n'
        '    const OmegaMicroInstruction *code;\n'
        '} OmegaMicroRuntime;\n'
        '_Static_assert(sizeof(OmegaMicroRuntime) <= 256, "Update shared runtime reservation");\n'
        '_Static_assert(sizeof(OmegaMicroInstruction) <= 64, "Update shared instruction reservation");\n'
        '\n'
        'static inline OmegaMicroCell *omega_micro_cell(OmegaMicroRuntime *r, uint32_t id) {\n'
        '    return (OmegaMicroCell *)(void *)(r->storage + (size_t)id * r->stride);\n'
        '}\n'
        'static inline unsigned __int128 omega_micro_gcd(unsigned __int128 a, unsigned __int128 b) {\n'
        '    while (b) { unsigned __int128 t = a % b; a = b; b = t; }\n'
        '    return a;\n'
        '}\n'
        'static inline int omega_micro_normalize(__int128 n, unsigned __int128 d, OmegaMicroQ *out) {\n'
        '    if (!d || !out) return -1;\n'
        '    unsigned __int128 magnitude = n < 0 ? (unsigned __int128)(-(n + 1)) + 1 : (unsigned __int128)n;\n'
        '    unsigned __int128 g = omega_micro_gcd(magnitude, d);\n'
        '    magnitude /= g; d /= g;\n'
        '    if (magnitude > INT64_MAX || d > INT64_MAX) return -1;\n'
        '    out->n = n < 0 ? -(int64_t)magnitude : (int64_t)magnitude;\n'
        '    out->d = (uint64_t)d;\n'
        '    return 0;\n'
        '}\n'
        'static inline int omega_micro_arithmetic(OmegaMicroQ a, OmegaMicroQ b, uint32_t op, OmegaMicroQ *out) {\n'
        '    if (!a.d || !b.d || a.d > INT64_MAX || b.d > INT64_MAX || a.n == INT64_MIN || b.n == INT64_MIN) return -1;\n'
        '    __int128 numerator;\n'
        '    if (op == OMEGA_MICRO_ADD) numerator = (__int128)a.n * b.d + (__int128)b.n * a.d;\n'
        '    else if (op == OMEGA_MICRO_MUL) numerator = (__int128)a.n * b.n;\n'
        '    else return -1;\n'
        '    return omega_micro_normalize(numerator, (unsigned __int128)a.d * b.d, out);\n'
        '}\n'
        'static inline int omega_micro_init(OmegaMicroRuntime *r, void *storage, size_t bytes,\n'
        '        size_t stride, uint32_t actors, uint32_t registers, uint32_t mailbox_capacity,\n'
        '        uint32_t quantum, const OmegaMicroInstruction *code, size_t code_length) {\n'
        '    if (!r || !storage || !code || !actors || actors > 256 || !registers || registers > 16 ||\n'
        '        !mailbox_capacity || mailbox_capacity > 64 || !quantum || quantum > 64 ||\n'
        '        !code_length || code_length > 128 || stride < 4096 || stride > 524288 ||\n'
        '        stride < sizeof(OmegaMicroCell) || (uintptr_t)storage % _Alignof(OmegaMicroCell) ||\n'
        '        stride % _Alignof(OmegaMicroCell) || actors > SIZE_MAX / stride || bytes < actors * stride) return -1;\n'
        '    for (size_t i = 0; i < code_length; ++i) {\n'
        '        const OmegaMicroInstruction *c = &code[i];\n'
        '        if (c->op > OMEGA_MICRO_HALT) return -2;\n'
        '        if (c->op <= OMEGA_MICRO_RECV || c->op == OMEGA_MICRO_JNZ) {\n'
        '            if (c->reg >= registers) return -2;\n'
        '        }\n'
        '        if (c->op == OMEGA_MICRO_SEND && c->target >= actors) return -2;\n'
        '        if ((c->op == OMEGA_MICRO_JUMP || c->op == OMEGA_MICRO_JNZ) && c->target >= code_length) return -2;\n'
        '        if (c->op <= OMEGA_MICRO_ASSERT && (!c->value.d || c->value.d > INT64_MAX || c->value.n == INT64_MIN)) return -2;\n'
        '    }\n'
        '    *r = (OmegaMicroRuntime){0}; r->storage = storage; r->storage_bytes = bytes;\n'
        '    r->stride = stride; r->actors = actors; r->registers = registers;\n'
        '    r->mailbox_capacity = mailbox_capacity; r->quantum = quantum;\n'
        '    r->code = code; r->code_length = code_length;\n'
        '    for (size_t i = 0; i < (size_t)actors * stride; ++i) r->storage[i] = 0;\n'
        '    for (uint32_t i = 0; i < actors; ++i) {\n'
        '        OmegaMicroCell *cell = omega_micro_cell(r, i);\n'
        '        for (uint32_t j = 0; j < registers; ++j) cell->registers[j] = (OmegaMicroQ){0, 1};\n'
        '        cell->registers[0].n = i;\n'
        '    }\n'
        '    return 0;\n'
        '}\n'
        '/* One bounded quantum; 0=blocked/inactive, 1=progress, negative=typed fault. */\n'
        'static inline int omega_micro_quantum(OmegaMicroRuntime *r, uint32_t id) {\n'
        '    OmegaMicroCell *cell = omega_micro_cell(r, id);\n'
        '    if (cell->halted) return 0;\n'
        '    int progress = 0;\n'
        '    for (uint32_t used = 0; used < r->quantum; ++used) {\n'
        '        if (cell->pc >= r->code_length) return -3;\n'
        '        const OmegaMicroInstruction *c = &r->code[cell->pc];\n'
        '        uint32_t next = cell->pc + 1;\n'
        '        switch (c->op) {\n'
        '        case OMEGA_MICRO_SET: cell->registers[c->reg] = c->value; break;\n'
        '        case OMEGA_MICRO_ADD: case OMEGA_MICRO_MUL:\n'
        '            if (omega_micro_arithmetic(cell->registers[c->reg], c->value, c->op, &cell->registers[c->reg])) return -4;\n'
        '            break;\n'
        '        case OMEGA_MICRO_ASSERT:\n'
        '            if ((__int128)cell->registers[c->reg].n * c->value.d != (__int128)c->value.n * cell->registers[c->reg].d) return -5;\n'
        '            break;\n'
        '        case OMEGA_MICRO_SEND: {\n'
        '            OmegaMicroCell *recipient = omega_micro_cell(r, c->target);\n'
        '            if (recipient->count == r->mailbox_capacity) { cell->status = OMEGA_MICRO_BLOCKED_SEND; return progress; }\n'
        '            recipient->mailbox[recipient->tail] = cell->registers[c->reg];\n'
        '            recipient->tail = (recipient->tail + 1) % r->mailbox_capacity; recipient->count++; r->messages++;\n'
        '            if (recipient->count > r->mailbox_peak) r->mailbox_peak = recipient->count;\n'
        '            break;\n'
        '        }\n'
        '        case OMEGA_MICRO_RECV:\n'
        '            if (!cell->count) { cell->status = OMEGA_MICRO_BLOCKED_RECEIVE; return progress; }\n'
        '            cell->registers[c->reg] = cell->mailbox[cell->head]; cell->mailbox[cell->head] = (OmegaMicroQ){0, 1};\n'
        '            cell->head = (cell->head + 1) % r->mailbox_capacity; cell->count--; break;\n'
        '        case OMEGA_MICRO_JUMP: next = c->target; break;\n'
        '        case OMEGA_MICRO_JNZ: if (cell->registers[c->reg].n) next = c->target; break;\n'
        '        case OMEGA_MICRO_YIELD: case OMEGA_MICRO_HALT: break;\n'
        '        default: return -2;\n'
        '        }\n'
        '        cell->pc = next; cell->executed++; r->instructions++; progress = 1; cell->status = OMEGA_MICRO_READY;\n'
        '        if (c->op == OMEGA_MICRO_HALT) { cell->halted = 1; cell->status = OMEGA_MICRO_HALTED; r->completed++; return progress; }\n'
        '        if (c->op == OMEGA_MICRO_YIELD) return progress;\n'
        '    }\n'
        '    return progress;\n'
        '}\n'
        'static inline int omega_micro_run(OmegaMicroRuntime *r, uint64_t max_turns) {\n'
        '    if (!r || !max_turns || max_turns > 100000) return -1;\n'
        '    while (r->turns < max_turns && r->completed < r->actors && !r->deadlock) {\n'
        '        int progress = omega_micro_quantum(r, (uint32_t)(r->turns % r->actors));\n'
        '        if (progress < 0) return progress;\n'
        '        r->idle_turns = progress ? 0 : r->idle_turns + 1;\n'
        '        if (r->idle_turns >= r->actors && r->completed < r->actors) r->deadlock = 1;\n'
        '        r->turns++;\n'
        '    }\n'
        '    return 0;\n'
        '}\n'
        '#endif\n'
    ),
    ('runtime/memory_arena.omega',
        'modulo memory_arena;\n'
        'exportar create, allocate, move, borrow, unborrow, release, finish;\n'
        'funcao natural(x){se(x%1!=0||x<0){fail("Natural number required");}retornar x;}\n'
        'funcao create(capacity){natural(capacity);se(capacity<1||capacity>10485760){fail("Arena capacity 1..10 MiB");}var a=obj();put(a,"capacity",capacity);put(a,"used",0);put(a,"peak",0);put(a,"entries",[]);put(a,"active",[]);put(a,"depth",0);put(a,"borrow_stack",[]);put(a,"borrow_depth",0);put(a,"next_borrow",0);retornar a;}\n'
        'funcao checked(a,h){\n'
        ' var slot=natural(h[0]);se(slot>=len(a["entries"])){fail("Unknown arena handle");}var e=a["entries"][slot];\n'
        ' se(!e["alive"]||e["generation"]!=h[1]||e["owner"]!=h[2]){fail("Expired linear handle");}retornar e;\n'
        '}\n'
        'funcao allocate(a,size,owner){\n'
        ' natural(size);natural(owner);se(size==0||size>a["capacity"]-a["used"]){fail("Arena exhausted");}\n'
        ' var slot=0;enquanto(slot<len(a["entries"])&&a["entries"][slot]["alive"]){slot=slot+1;}se(slot>=1024){fail("Arena descriptor capacity");}\n'
        ' var generation=1;se(slot<len(a["entries"])){generation=a["entries"][slot]["generation"]+1;}\n'
        ' var e=obj();put(e,"alive",1);put(e,"generation",generation);put(e,"owner",owner);put(e,"offset",a["used"]);put(e,"size",size);put(e,"borrows",0);\n'
        ' se(slot==len(a["entries"])){push(a["entries"],e);}senao{put(a["entries"],slot,e);}\n'
        ' var depth=a["depth"];se(depth==len(a["active"])){push(a["active"],slot);}senao{put(a["active"],depth,slot);}put(a,"depth",depth+1);put(a,"used",a["used"]+size);se(a["used"]>a["peak"]){put(a,"peak",a["used"]);}retornar [slot,generation,owner];\n'
        '}\n'
        'funcao move(a,h,owner){natural(owner);var e=checked(a,h);se(e["borrows"]){fail("Borrowed resource cannot move");}put(e,"owner",owner);put(e,"generation",e["generation"]+1);retornar [h[0],e["generation"],owner];}\n'
        'funcao borrow(a,h){var e=checked(a,h);put(e,"borrows",e["borrows"]+1);var serial=a["next_borrow"]+1;put(a,"next_borrow",serial);var stack=a["borrow_stack"];var depth=a["borrow_depth"];se(depth>=1024){fail("Borrow capacity");}se(depth==len(stack)){push(stack,serial);}senao{put(stack,depth,serial);}put(a,"borrow_depth",depth+1);retornar [h[0],h[1],h[2],serial];}\n'
        'funcao unborrow(a,h){var e=checked(a,h);se(len(h)!=4||e["borrows"]==0||a["borrow_depth"]==0||h[3]!=a["borrow_stack"][a["borrow_depth"]-1]){fail("Borrow release must be linear/LIFO");}put(a,"borrow_depth",a["borrow_depth"]-1);put(e,"borrows",e["borrows"]-1);retornar 0;}\n'
        'funcao release(a,h){var e=checked(a,h);var depth=a["depth"];se(e["borrows"]||depth==0||a["active"][depth-1]!=h[0]){fail("Arena release must be exclusive and LIFO");}put(a,"used",e["offset"]);put(a,"depth",depth-1);put(e,"alive",0);put(e,"generation",e["generation"]+1);retornar 0;}\n'
        'funcao finish(a){se(a["depth"]!=0||a["used"]!=0){fail("Unconsumed arena resources");}retornar a["peak"];}\n'
    ),
    ('runtime/quantum_gate_emulator.omega',
        'modulo science_115;\n'
        'importar "../ciencia/core/exato.omega" como u;\n'
        'importar "../std/math.omega" como m;\n'
        'importar "../std/string.omega" como s;\n'
        'importar "../std/math/linalg_exact.omega" como la;\n'
        'importar "../std/math/complex_rational.omega" como c;\n'
        'exportar execute;\n'
        '# Sparse exact Q(i) gates up to 32 address bits with active-amplitude quota; H/T and dense 2^32 storage are not falsely supported.\n'
        'funcao accumulate(state,index,amplitude)  {\n'
        '  var key=text(index);\n'
        '  se(has(state,key))  {\n'
        '    put(state,key,c::add(state[key],amplitude));\n'
        '  }\n'
        '  senao  {\n'
        '    put(state,key,amplitude);\n'
        '  }\n'
        '  retornar 0;\n'
        '}\n'
        'funcao bit(index,target)  {\n'
        '  retornar qfloor(index/u::power(2,target))%2;\n'
        '}\n'
        'funcao flip(index,target)  {\n'
        '  var value=u::power(2,target);\n'
        '  se(bit(index,target))  {\n'
        '    retornar index-value;\n'
        '  }\n'
        '  retornar index+value;\n'
        '}\n'
        'funcao norm(state)  {\n'
        '  var sum=0;\n'
        '  var names=keys(state);\n'
        '  var i=0;\n'
        '  enquanto(i<len(names))  {\n'
        '    sum=sum+c::norm2(state[names[i]]);\n'
        '    i=i+1;\n'
        '  }\n'
        '  retornar sum;\n'
        '}\n'
        'funcao execute(r)  {\n'
        '  var qubits=u::count(r,"qubits",1,32);\n'
        '  var cap=u::integer(u::num(r,"max_active",1024),1,4096);\n'
        '  var initial=s::as_list(r["state"]);\n'
        '  se(len(initial)<1||len(initial)>cap)  {\n'
        '    fail("Sparse quantum state budget");\n'
        '  }\n'
        '  var state=obj();\n'
        '  var i=0;\n'
        '  enquanto(i<len(initial))  {\n'
        '    var index=u::integer(u::val(initial[i][0]),0,u::power(2,qubits)-1);\n'
        '    var key=text(index);\n'
        '    se(has(state,key))  {\n'
        '      fail("Duplicate basis amplitude");\n'
        '    }\n'
        '    put(state,key,c::value(initial[i][1]));\n'
        '    i=i+1;\n'
        '  }\n'
        '  se(norm(state)!=1)  {\n'
        '    fail("Quantum state must have exact unit norm");\n'
        '  }\n'
        '  var gates=s::as_list(r["gates"]);\n'
        '  u::budget(len(gates),256);\n'
        '  i=0;\n'
        '  enquanto(i<len(gates))  {\n'
        '    var gate=gates[i];\n'
        '    var op=u::text_field(gate,"operation",8);\n'
        '    var target=u::count(gate,"target",0,qubits-1);\n'
        '    var next=obj();\n'
        '    var names=keys(state);\n'
        '    var j=0;\n'
        '    enquanto(j<len(names))  {\n'
        '      var index=number(names[j]);\n'
        '      var amplitude=state[names[j]];\n'
        '      var b=bit(index,target);\n'
        '      se(op=="X")  {\n'
        '        accumulate(next,flip(index,target),amplitude);\n'
        '      }\n'
        '      senao  {\n'
        '        se(op=="Y")  {\n'
        '          var phase=[0,1];\n'
        '          se(b)  {\n'
        '            phase=[0,-1];\n'
        '          }\n'
        '          accumulate(next,flip(index,target),c::mul(phase,amplitude));\n'
        '        }\n'
        '        senao  {\n'
        '          se(op=="Z")  {\n'
        '            var sign=1;\n'
        '            se(b)  {\n'
        '              sign=-1;\n'
        '            }\n'
        '            accumulate(next,index,c::mul([sign,0],amplitude));\n'
        '          }\n'
        '          senao  {\n'
        '            se(op=="S")  {\n'
        '              var phase=[1,0];\n'
        '              se(b)  {\n'
        '                phase=[0,1];\n'
        '              }\n'
        '              accumulate(next,index,c::mul(phase,amplitude));\n'
        '            }\n'
        '            senao  {\n'
        '              se(op=="CNOT")  {\n'
        '                var control=u::count(gate,"control",0,qubits-1);\n'
        '                se(control==target)  {\n'
        '                  fail("CNOT control equals target");\n'
        '                }\n'
        '                var dest=index;\n'
        '                se(bit(index,control))  {\n'
        '                  dest=flip(index,target);\n'
        '                }\n'
        '                accumulate(next,dest,amplitude);\n'
        '              }\n'
        '              senao  {\n'
        '                se(op=="SWAP")  {\n'
        '                  var other=u::count(gate,"other",0,qubits-1);\n'
        '                  var dest=index;\n'
        '                  se(bit(index,other)!=b)  {\n'
        '                    dest=flip(flip(index,target),other);\n'
        '                  }\n'
        '                  accumulate(next,dest,amplitude);\n'
        '                }\n'
        '                senao  {\n'
        '                  se(op=="R")  {\n'
        '                    var a=u::q(gate,"a");\n'
        '                    var bvalue=u::q(gate,"b");\n'
        '                    se(a*a+bvalue*bvalue!=1)  {\n'
        '                      fail("Rational rotation must be unitary");\n'
        '                    }\n'
        '                    var zero=index;\n'
        '                    var one=flip(index,target);\n'
        '                    se(b)  {\n'
        '                      zero=one;\n'
        '                      one=index;\n'
        '                      accumulate(next,zero,c::mul([-bvalue,0],amplitude));\n'
        '                      accumulate(next,one,c::mul([a,0],amplitude));\n'
        '                    }\n'
        '                    senao  {\n'
        '                      accumulate(next,zero,c::mul([a,0],amplitude));\n'
        '                      accumulate(next,one,c::mul([bvalue,0],amplitude));\n'
        '                    }\n'
        '                  }\n'
        '                  senao  {\n'
        '                    fail("Unsupported gate: H/T need amplitudes outside Q(i)");\n'
        '                  }\n'
        '                }\n'
        '              }\n'
        '            }\n'
        '          }\n'
        '        }\n'
        '      }\n'
        '      j=j+1;\n'
        '    }\n'
        '    state=obj();\n'
        '    names=keys(next);\n'
        '    j=0;\n'
        '    enquanto(j<len(names))  {\n'
        '      var amplitude=next[names[j]];\n'
        '      se(c::norm2(amplitude)!=0)  {\n'
        '        put(state,names[j],amplitude);\n'
        '      }\n'
        '      j=j+1;\n'
        '    }\n'
        '    se(len(keys(state))>cap)  {\n'
        '      fail("Sparse quantum amplitude budget exceeded");\n'
        '    }\n'
        '    se(norm(state)!=1)  {\n'
        '      fail("Quantum norm preservation failed");\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  var names=keys(state);\n'
        '  var ids=[];\n'
        '  i=0;\n'
        '  enquanto(i<len(names))  {\n'
        '    push(ids,number(names[i]));\n'
        '    i=i+1;\n'
        '  }\n'
        '  i=1;\n'
        '  enquanto(i<len(ids))  {\n'
        '    var j=i;\n'
        '    enquanto(j>0&&ids[j]<ids[j-1])  {\n'
        '      var t=ids[j];\n'
        '      put(ids,j,ids[j-1]);\n'
        '      put(ids,j-1,t);\n'
        '      j=j-1;\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  var values=[];\n'
        '  i=0;\n'
        '  enquanto(i<len(ids))  {\n'
        '    push(values,[ids[i],state[text(ids[i])]]);\n'
        '    i=i+1;\n'
        '  }\n'
        '  var out=u::result("sparse-unitary-Qi-quantum-emulator",values);\n'
        '  put(out,"qubits",qubits);\n'
        '  put(out,"norm_squared",1);\n'
        '  put(out,"dense_32_qubit_state_supported",0);\n'
        '  retornar out;\n'
        '}\n'
    ),
    ('runtime/static_arena.h',
        '#ifndef OMEGA_STATIC_ARENA_H\n'
        '#define OMEGA_STATIC_ARENA_H\n'
        '#include <stddef.h>\n'
        '#include <stdint.h>\n'
        '#include <string.h>\n'
        '#define OMEGA_STATIC_SLOTS 1024\n'
        'typedef struct {uint32_t slot,generation,owner;} OmegaLinearHandle;\n'
        'typedef struct {size_t offset,size;uint32_t generation,owner,borrows;uint8_t alive,retired;} OmegaLinearRegion;\n'
        'typedef struct {unsigned char *memory;size_t capacity,used,peak;uint32_t depth,active[OMEGA_STATIC_SLOTS],borrow_depth,next_borrow,borrow_tokens[OMEGA_STATIC_SLOTS],borrow_slots[OMEGA_STATIC_SLOTS];OmegaLinearRegion regions[OMEGA_STATIC_SLOTS];} OmegaStaticArena;\n'
        'static inline int omega_static_init(OmegaStaticArena *a,void *storage,size_t capacity){if(!a||!storage||!capacity)return -1;memset(a,0,sizeof *a);a->memory=storage;a->capacity=capacity;return 0;}\n'
        'static inline OmegaLinearRegion *omega_static_region(OmegaStaticArena *a,OmegaLinearHandle h){if(!a||h.slot>=OMEGA_STATIC_SLOTS)return NULL;OmegaLinearRegion *r=&a->regions[h.slot];return r->alive&&r->generation==h.generation&&r->owner==h.owner?r:NULL;}\n'
        'static inline int omega_static_allocate(OmegaStaticArena *a,size_t size,uint32_t owner,OmegaLinearHandle *out){\n'
        ' if(!a||!out||!size||a->used>a->capacity||size>a->capacity-a->used||a->depth>=OMEGA_STATIC_SLOTS)return -1;\n'
        ' uint32_t slot=0;while(slot<OMEGA_STATIC_SLOTS&&(a->regions[slot].alive||a->regions[slot].retired))slot++;if(slot==OMEGA_STATIC_SLOTS)return -2;\n'
        ' OmegaLinearRegion *r=&a->regions[slot];if(r->generation>=UINT32_MAX-1){r->retired=1;return -3;}\n'
        ' r->generation++;r->owner=owner;r->offset=a->used;r->size=size;r->alive=1;r->borrows=0;a->active[a->depth++]=slot;a->used+=size;if(a->used>a->peak)a->peak=a->used;\n'
        ' *out=(OmegaLinearHandle){slot,r->generation,owner};return 0;\n'
        '}\n'
        'static inline int omega_static_move(OmegaStaticArena *a,OmegaLinearHandle old,uint32_t owner,OmegaLinearHandle *out){OmegaLinearRegion *r=omega_static_region(a,old);if(!r||!out||r->borrows||r->generation==UINT32_MAX)return -1;r->generation++;r->owner=owner;*out=(OmegaLinearHandle){old.slot,r->generation,owner};return 0;}\n'
        'static inline int omega_static_write(OmegaStaticArena *a,OmegaLinearHandle h,size_t offset,const void *data,size_t count){OmegaLinearRegion *r=omega_static_region(a,h);if(!r||r->borrows||!data||offset>r->size||count>r->size-offset)return -1;memcpy(a->memory+r->offset+offset,data,count);return 0;}\n'
        'static inline int omega_static_read(OmegaStaticArena *a,OmegaLinearHandle h,size_t offset,void *data,size_t count){OmegaLinearRegion *r=omega_static_region(a,h);if(!r||!data||offset>r->size||count>r->size-offset)return -1;memcpy(data,a->memory+r->offset+offset,count);return 0;}\n'
        'static inline int omega_static_borrow(OmegaStaticArena *a,OmegaLinearHandle h,uint32_t *serial){OmegaLinearRegion *r=omega_static_region(a,h);if(!r||!serial||a->borrow_depth>=OMEGA_STATIC_SLOTS||a->next_borrow==UINT32_MAX)return -1;*serial=++a->next_borrow;a->borrow_tokens[a->borrow_depth]=*serial;a->borrow_slots[a->borrow_depth++]=h.slot;r->borrows++;return 0;}\n'
        'static inline int omega_static_unborrow(OmegaStaticArena *a,OmegaLinearHandle h,uint32_t serial){OmegaLinearRegion *r=omega_static_region(a,h);if(!r||!serial||!r->borrows||!a->borrow_depth||serial!=a->borrow_tokens[a->borrow_depth-1]||h.slot!=a->borrow_slots[a->borrow_depth-1])return -1;a->borrow_depth--;r->borrows--;return 0;}\n'
        'static inline int omega_static_release(OmegaStaticArena *a,OmegaLinearHandle h){OmegaLinearRegion *r=omega_static_region(a,h);if(!r||r->borrows||!a->depth||a->active[a->depth-1]!=h.slot)return -1;a->depth--;a->used=r->offset;r->alive=0;if(r->generation==UINT32_MAX)r->retired=1;else r->generation++;return 0;}\n'
        'static inline int omega_static_finish(const OmegaStaticArena *a){return a&&a->depth==0&&a->used==0&&a->borrow_depth==0?0:-1;}\n'
        '#endif\n'
    ),
    ('scripts/build-manifest.py',
        '#!/usr/bin/env python3\n'
        '"""Record/verify the packages, native stages and Lean kernels of this build."""\n'
        'import argparse\n'
        'import json\n'
        'from pathlib import Path\n'
        'import sys\n'
        'import re\n'
        'import tomllib\n'
        '\n'
        'ROOT=Path(__file__).resolve().parents[1]\n'
        'sys.path.insert(0,str(ROOT))\n'
        'from omega_platform.manifest import build_manifest,verify\n'
        '\n'
        'parser=argparse.ArgumentParser()\n'
        "parser.add_argument('--output',type=Path,default=ROOT/'artifacts/build-manifest.json')\n"
        "parser.add_argument('--verify',type=Path)\n"
        'args=parser.parse_args()\n'
        'if args.verify:\n'
        '    verify(json.loads(args.verify.read_text()),ROOT)\n'
        "    print('Artifact integrity verified')\n"
        'else:\n'
        "    project=tomllib.loads((ROOT/'pyproject.toml').read_text())['project']\n"
        "    distribution=re.sub(r'[-_.]+','_',project['name'])\n"
        "    version=project['version']\n"
        "    paths=[*sorted((ROOT/'build/selfhost').glob('omegac-stage*')),\n"
        "           *sorted((ROOT/'dist').glob(f'{distribution}-{version}-*.whl')),\n"
        "           ROOT/f'dist/{distribution}-{version}.tar.gz',\n"
        "           ROOT/'formal/lean/.lake/build/bin/omega_kernel',\n"
        "           ROOT/'formal/tensor/.lake/build/bin/omega_tensor_kernel']\n"
        "    if not paths:raise SystemExit('No build artifacts found')\n"
        '    record=build_manifest(ROOT,paths)\n'
        '    args.output.parent.mkdir(parents=True,exist_ok=True)\n'
        "    args.output.write_text(json.dumps(record,indent=2,ensure_ascii=False)+'\\n')\n"
        '    verify(record,ROOT)\n'
        "    print(f'{len(paths)} artifacts recorded and verified: {args.output}')\n"
    ),
    ('scripts/build-monolith.py',
        '#!/usr/bin/env python3\n'
        '"""Reproduce a readable single-file source distribution without invented code.\n'
        '\n'
        'Embedded sources are existing implementations, not 133 newly completed tasks.\n'
        'Run with --check in CI to detect a stale or modified source distribution.\n'
        '"""\n'
        'from pathlib import Path\n'
        'import argparse\n'
        'import hashlib\n'
        'import json\n'
        'import subprocess\n'
        '\n'
        'ROOT=Path(__file__).resolve().parents[1]\n'
        "OUTPUT=ROOT/'omega/omega_3_monolith.py'\n"
        "FOLDERS={'omega_engines','omega_core','omega_ml','ciencia','agentes_cientificos','omega_science','omega_live','omega_ingest','civilizacao_agentes','incubadora_continua','sociedade_hierarquica','metamorfose_cognitiva','fabrica_descobertas','imunologia_sistemica','infraestrutura_soberana','std','runtime','tools','omega_native','validation','omega_agent','omega_coder','omega_memory','omega_learning','omega_evolution','omega_tools','omega_security','omega_bench','omega','omega_open','omega_selfhost','omega_platform','omega_nextorch','nextorch',\n"
        "         'omega_refine_check','omega_synth_mcts','omega_self_mutate','omega_agent_sandbox','omega_cognition','hardware',\n"
        "         'omega_gpu_mcts','omega_abstract_domain','omega_autotelic','omega_self_evolve_v2','omega_runtime_verified',\n"
        "         'formal','scripts','requirements','roadmap','docs','testes','exemplos','.github'}\n"
        "EXTENSIONS={'.py','.h','.omega','.lean','.json','.lock','.tsv','.md','.sh','.yml','.c','.svg','.sv','.cu','.cuh','.cpp'}\n"
        '\n'
        'LAUNCHER=\'\'\'"""Readable single-file Omega source distribution.\n'
        '\n'
        'This bundles existing code; line count is not acceptance of OM-018..OM-150.\n'
        'No code is downloaded or candidates executed during extraction/verification.\n'
        'The installed system prerequisites and Python dependencies are still required.\n'
        '"""\n'
        'from __future__ import annotations\n'
        'import argparse\n'
        'import ast\n'
        'import ctypes\n'
        'import errno\n'
        'import hashlib\n'
        'import importlib\n'
        'import json\n'
        'import os\n'
        'from pathlib import Path, PurePosixPath\n'
        'import shutil\n'
        'import sys\n'
        'import tempfile\n'
        'import unittest\n'
        '\n'
        'MAX_BYTES=16*1024*1024\n'
        '\n'
        '\n'
        'def validated_sources():\n'
        '    if len(SOURCES)>2000:\n'
        "        raise ValueError('Source count budget exceeded')\n"
        '    sources={};total=0\n'
        '    for name,content in SOURCES:\n'
        '        if type(name) is not str:\n'
        "            raise ValueError('Malformed bundle path')\n"
        '        path=PurePosixPath(name)\n'
        '        if (type(name) is not str or not name or path.is_absolute() or\n'
        "            str(path)!=name or any(part in ('.','..','.git') for part in path.parts) or\n"
        "            ':' in name or chr(92) in name or name in sources):\n"
        "            raise ValueError('Unsafe or duplicate bundle path')\n"
        '        if type(content) is not str:\n'
        "            raise ValueError('Malformed bundle source')\n"
        "        data=content.encode('utf-8');total+=len(data)\n"
        '        if total>MAX_BYTES:\n'
        "            raise ValueError('Source byte budget exceeded')\n"
        "        if MANIFEST['files'].get(name)!={'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest()}:\n"
        "            raise ValueError('Embedded source integrity mismatch: '+name)\n"
        '        sources[name]=data\n'
        "    if set(sources)!=set(MANIFEST['files']):\n"
        "        raise ValueError('Incomplete source manifest')\n"
        "    canonical=json.dumps(MANIFEST['files'],sort_keys=True,separators=(',',':')).encode()\n"
        "    if hashlib.sha256(canonical).hexdigest()!=MANIFEST['tree_sha256']:\n"
        "        raise ValueError('Source tree integrity mismatch')\n"
        '    return sources\n'
        '\n'
        '\n'
        'def verify():\n'
        '    sources=validated_sources()\n'
        '    for name,data in sources.items():\n'
        "        if name.endswith('.py'):\n"
        "            ast.parse(data.decode('utf-8'),filename=name)\n"
        "    return {'format':'omega-single-file-1','files':len(sources),\n"
        "            'source_bytes':sum(map(len,sources.values())),\n"
        "            'embedded_code_lines':MANIFEST['embedded_code_lines'],\n"
        "            'tree_sha256':MANIFEST['tree_sha256'],\n"
        "            'all_150_tasks_accepted':False}\n"
        '\n'
        '\n'
        'def _publish(stage,target):\n'
        '    # Atomic and exclusive: rename must never replace a concurrently created\n'
        '    # destination. Linux is also the supported sandbox platform.\n'
        '    libc=ctypes.CDLL(None,use_errno=True)\n'
        "    rename=getattr(libc,'renameat2',None)\n"
        '    if rename is None:\n'
        "        raise RuntimeError('Atomic exclusive publication requires Linux renameat2')\n"
        '    rename.argtypes=[ctypes.c_int,ctypes.c_char_p,ctypes.c_int,ctypes.c_char_p,ctypes.c_uint]\n'
        '    rename.restype=ctypes.c_int\n'
        '    if rename(-100,os.fsencode(stage),-100,os.fsencode(target),1):\n'
        '        error=ctypes.get_errno()\n'
        '        if error==errno.EEXIST:\n'
        "            raise FileExistsError('Destination already exists')\n"
        '        raise OSError(error,os.strerror(error))\n'
        '\n'
        '\n'
        'def extract(destination):\n'
        '    sources=validated_sources()\n'
        '    requested=Path(destination)\n'
        '    parent=requested.parent.resolve(strict=True)\n'
        "    if requested.name in ('','.','..'):\n"
        "        raise ValueError('A fresh destination directory is required')\n"
        '    target=parent/requested.name\n'
        '    if target.exists() or target.is_symlink():\n'
        "        raise FileExistsError('Destination already exists')\n"
        "    stage=Path(tempfile.mkdtemp(prefix='.omega-source-',dir=parent))\n"
        '    try:\n'
        '        for name,data in sources.items():\n'
        '            path=stage/name\n'
        '            path.parent.mkdir(parents=True,exist_ok=True)\n'
        "            with path.open('xb') as stream:\n"
        '                stream.write(data)\n'
        '            path.chmod(0o644)\n'
        '        _publish(stage,target)\n'
        '    finally:\n'
        '        if stage.exists():\n'
        '            shutil.rmtree(stage)\n'
        '    return target\n'
        '\n'
        '\n'
        'def coverage():\n'
        '    sources=validated_sources()\n'
        "    progress=json.loads(sources['roadmap/progress.json'])\n"
        "    statuses={item['id']:item['status'] for item in progress['tasks']}\n"
        '    records=[]\n'
        "    for line in sources['roadmap/tasks.tsv'].decode().splitlines():\n"
        '        task,phase,title,acceptance=line.split(chr(9))\n'
        '        if int(task[3:])>=18:\n'
        "            records.append({'id':task,'phase':int(phase),'title':title,\n"
        "                            'acceptance':acceptance,'status':statuses[task],\n"
        "                            'accepted':False})\n"
        '    return records\n'
        '\n'
        '\n'
        'def main(argv=None):\n'
        '    parser=argparse.ArgumentParser(description=__doc__)\n'
        "    parser.add_argument('action',choices=['verify','extract','coverage','self-test','omega'])\n"
        "    parser.add_argument('arguments',nargs=argparse.REMAINDER)\n"
        '    args=parser.parse_args(argv)\n'
        "    if args.action=='extract':\n"
        '        if len(args.arguments)!=1:\n'
        "            parser.error('extract requires exactly one fresh destination')\n"
        '        print(extract(args.arguments[0]));return 0\n'
        "    if args.action=='verify':\n"
        '        print(json.dumps(verify(),sort_keys=True));return 0\n'
        "    if args.action=='coverage':\n"
        '        print(json.dumps(coverage(),ensure_ascii=False,indent=2));return 0\n'
        "    with tempfile.TemporaryDirectory(prefix='omega-single-file-') as tmp:\n"
        "        root=extract(Path(tmp)/'source')\n"
        "        if any(name.startswith('omega.') and name!=__name__ for name in sys.modules):\n"
        "            raise RuntimeError('Launch this file in a fresh Python interpreter')\n"
        "        package=sys.modules.get('omega')\n"
        '        previous_path=list(package.__path__) if package is not None else None\n'
        '        if package is not None:\n'
        "            package.__path__=[str(root/'omega')]\n"
        '        sys.path.insert(0,str(root))\n'
        '        try:\n'
        "            if args.action=='self-test':\n"
        '                verify()\n'
        "                module=importlib.import_module('omega.monolith_components')\n"
        '                suite=unittest.defaultTestLoader.loadTestsFromTestCase(module.MonolithTests)\n'
        '                result=unittest.TextTestRunner(verbosity=2).run(suite)\n'
        '                return 0 if result.wasSuccessful() else 1\n'
        '            # Explicitly requested application entry point. Candidate programs\n'
        '            # remain subject to the bundled driver/sandbox/Lean requirements.\n'
        "            cli=importlib.import_module('omega.cli')\n"
        '            return cli.principal(args.arguments)\n'
        '        finally:\n'
        '            sys.path.remove(str(root))\n'
        '            if package is not None:\n'
        '                package.__path__=previous_path\n'
        '\n'
        "'''\n"
        '\n'
        '\n'
        'def build():\n'
        "    tracked=subprocess.check_output(['git','ls-files','-z'],cwd=ROOT).decode().split('\\0')\n"
        '    selected=[]\n'
        '    for name in sorted(set(tracked)):\n'
        '        path=Path(name)\n'
        "        if not name or ROOT/path==OUTPUT or '.lake' in path.parts or '__pycache__' in path.parts:\n"
        '            continue\n'
        "        if name=='scripts/monolith-components.py.txt' or (path.parts[0] in FOLDERS and\n"
        "            (path.suffix in EXTENSIONS or path.name=='lean-toolchain')) or name in {'setup.py','pyproject.toml','MANIFEST.in','README.md','LICENSE','banco_de_dados.omega','synthesis.omega','fitness.omega','civilizacao_agentes.omega','incubadora_continua.omega','ginasio.omega'}:\n"
        '            selected.append(name)\n'
        "    sources={name:(ROOT/name).read_bytes().decode('utf-8') for name in selected}\n"
        '    # The virtual module lives only inside the requested single-file artifact.\n'
        '    # Its source is maintained as a template for reproducible regeneration.\n'
        "    sources['omega/monolith_components.py']=(ROOT/'scripts/monolith-components.py.txt').read_bytes().decode('utf-8')\n"
        '    sources=dict(sorted(sources.items()))\n'
        "    files={name:{'bytes':len(text.encode()),'sha256':hashlib.sha256(text.encode()).hexdigest()} for name,text in sources.items()}\n"
        "    digest=hashlib.sha256(json.dumps(files,sort_keys=True,separators=(',',':')).encode()).hexdigest()\n"
        "    code_lines=sum(len(content.splitlines()) for name,content in sources.items() if Path(name).suffix in {'.py','.h','.c','.omega','.lean'})\n"
        "    manifest={'format':'omega-source-tree-1','files':files,'tree_sha256':digest,'embedded_code_lines':code_lines}\n"
        "    output=[LAUNCHER,'MANIFEST = '+repr(manifest)+'\\n\\nSOURCES = (\\n']\n"
        '    for name,content in sources.items():\n'
        "        output.append('    ('+repr(name)+',\\n')\n"
        '        for line in content.splitlines(keepends=True):\n'
        "            output.append('        '+repr(line)+'\\n')\n"
        '        if not content:output.append("        \'\'\\n")\n'
        "        output.append('    ),\\n')\n"
        '    output.append(")\\n\\nif __name__ == \'__main__\':\\n    raise SystemExit(main())\\n")\n'
        "    return ''.join(output)\n"
        '\n'
        '\n'
        "if __name__=='__main__':\n"
        '    parser=argparse.ArgumentParser(description=__doc__)\n'
        "    parser.add_argument('--check',action='store_true')\n"
        '    args=parser.parse_args()\n'
        '    result=build()\n'
        '    if args.check:\n'
        '        if OUTPUT.read_text()!=result:\n'
        "            raise SystemExit('Single-file distribution is stale; run scripts/build-monolith.py')\n"
        '    else:\n'
        "        OUTPUT.write_text(result,encoding='utf-8')\n"
        "    print(f'{len(result.splitlines())} physical lines: {OUTPUT.name}')\n"
    ),
    ('scripts/monolith-components.py.txt',
        '"""Components embedded in the single-file distribution; acceptance remains pending."""\n'
        'from dataclasses import dataclass\n'
        'import json\n'
        'from .generics import Registry, expand\n'
        '\n'
        '# Additional components share this file so the requested delivery is auditable.\n'
        '# Task coverage is explicitly measured; inclusion here never grants acceptance.\n'
        'from concurrent.futures import ThreadPoolExecutor\n'
        'from collections import deque\n'
        'import math\n'
        'import random\n'
        'import time\n'
        'import unittest\n'
        '\n'
        '\n'
        'class BoundedQueue:\n'
        '    """FIFO with explicit capacity; overflow never discards an existing item."""\n'
        '    def __init__(self, capacity):\n'
        '        if type(capacity) is not int or not 1 <= capacity <= 100000:\n'
        "            raise ValueError('Invalid queue capacity')\n"
        '        self.capacity = capacity\n'
        '        self._items = deque()\n'
        '\n'
        '    def push(self, value):\n'
        '        if len(self._items) >= self.capacity:\n'
        "            raise OverflowError('Queue capacity exhausted')\n"
        '        self._items.append(value)\n'
        '\n'
        '    def pop(self):\n'
        '        if not self._items:\n'
        "            raise IndexError('Empty queue')\n"
        '        return self._items.popleft()\n'
        '\n'
        '    def __len__(self):\n'
        '        return len(self._items)\n'
        '\n'
        '\n'
        'class ArenaBudget:\n'
        '    """Accounting contract only: this does not implement native garbage collection."""\n'
        '    def __init__(self, limit):\n'
        '        if type(limit) is not int or limit <= 0:\n'
        "            raise ValueError('Positive allocation budget required')\n"
        '        self.limit = limit\n'
        '        self.used = 0\n'
        '        self._allocations = {}\n'
        '        self._next = 0\n'
        '\n'
        '    def reserve(self, size):\n'
        '        if type(size) is not int or size < 0:\n'
        "            raise ValueError('Invalid allocation size')\n"
        '        if size > self.limit - self.used:\n'
        "            raise MemoryError('Allocation budget exhausted')\n"
        '        self._next += 1\n'
        '        self._allocations[self._next] = size\n'
        '        self.used += size\n'
        '        return self._next\n'
        '\n'
        '    def release(self, handle):\n'
        '        if type(handle) is not int or handle not in self._allocations:\n'
        "            raise ValueError('Unknown or already released allocation')\n"
        '        self.used -= self._allocations.pop(handle)\n'
        '\n'
        '\n'
        '@dataclass(frozen=True)\n'
        'class Measurement:\n'
        '    name: str\n'
        '    seed: int\n'
        '    elapsed_seconds: float\n'
        '    correct: bool\n'
        '    detail: str\n'
        '\n'
        '\n'
        'def deterministic_map(operation, values, workers=1):\n'
        '    """Ordered results for trusted pure host functions, not a candidate sandbox.\n'
        '\n'
        '    Callers must provide pure operations. Shared mutable state is not made safe\n'
        "    by this helper, and process isolation remains the existing sandbox's job.\n"
        '    """\n'
        '    if type(workers) is not int or not 1 <= workers <= 16:\n'
        "        raise ValueError('Invalid worker count')\n"
        '    values = tuple(values)\n'
        '    if len(values) > 10000:\n'
        "        raise ValueError('Batch budget exhausted')\n"
        '    with ThreadPoolExecutor(max_workers=workers) as executor:\n'
        '        return tuple(executor.map(operation, values))\n'
        '\n'
        '\n'
        'def paired_bootstrap(before, after, *, seed=0, samples=2000):\n'
        '    """Paired mean improvement and percentile CI; no automatic promotion."""\n'
        '    before, after = tuple(before), tuple(after)\n'
        '    if len(before) != len(after) or not 2 <= len(before) <= 10000:\n'
        "        raise ValueError('Paired measurements required')\n"
        '    if type(samples) is not int or not 100 <= samples <= 10000:\n'
        "        raise ValueError('Invalid resampling budget')\n"
        '    if samples * len(before) > 2000000:\n'
        "        raise ValueError('Resampling work budget exhausted')\n"
        '    if any(type(x) not in (int, float) or not math.isfinite(x) for x in before + after):\n'
        "        raise ValueError('Finite measurements required')\n"
        '    delta = tuple(y-x for x,y in zip(before,after))\n'
        '    rng = random.Random(seed)\n'
        '    means = sorted(sum(rng.choice(delta) for _ in delta)/len(delta) for _ in range(samples))\n'
        "    return {'mean_delta':sum(delta)/len(delta), 'ci95':[means[int(samples*.025)],means[int(samples*.975)]],\n"
        "            'seed':seed,'samples':samples,'pairs':len(delta),'promotion_authorized':False}\n"
        '\n'
        '\n'
        'def benchmark(name, operation, verify, *, seed=0):\n'
        '    """Measure a trusted adapter; preserve negative outcomes as measurements."""\n'
        '    started = time.perf_counter()\n'
        '    try:\n'
        '        value = operation(seed)\n'
        '        correct = verify(value)\n'
        '        if type(correct) is not bool:\n'
        "            raise TypeError('Verifier must return bool')\n"
        "        detail = 'accepted' if correct else 'rejected'\n"
        '    except Exception as exc:\n'
        '        correct = False\n'
        '        detail = type(exc).__name__\n'
        '    return Measurement(name,seed,time.perf_counter()-started,correct,detail)\n'
        '\n'
        '\n'
        'def coverage(root):\n'
        '    """Report actual scope against every requested task, without success stubs."""\n'
        '    from pathlib import Path\n'
        '    tasks=[]\n'
        "    for line in (Path(root)/'roadmap/tasks.tsv').read_text().splitlines():\n"
        "        task,phase,title,acceptance=line.split('\\t')\n"
        '        if int(task[3:]) < 18:\n'
        '            continue\n'
        "        tasks.append({'id':task,'phase':int(phase),'title':title,'acceptance':acceptance,\n"
        "                      'status':'partial' if task in {'OM-018','OM-019','OM-020','OM-021','OM-109','OM-136'} else 'not_implemented',\n"
        "                      'accepted':False})\n"
        '    return tasks\n'
        '\n'
        '\n'
        'class MonolithTests(unittest.TestCase):\n'
        '    def test_queue_properties(self):\n'
        '        rng=random.Random(19)\n'
        '        queue=BoundedQueue(20)\n'
        '        reference=[]\n'
        '        for _ in range(1000):\n'
        '            if reference and rng.randrange(2):\n'
        '                self.assertEqual(queue.pop(),reference.pop(0))\n'
        '            elif len(reference)<20:\n'
        '                value=rng.randrange(100);queue.push(value);reference.append(value)\n'
        '            self.assertEqual(len(queue),len(reference))\n'
        '        full=BoundedQueue(1);full.push(7)\n'
        '        with self.assertRaises(OverflowError):full.push(8)\n'
        '        self.assertEqual(full.pop(),7)\n'
        '        with self.assertRaises(IndexError):full.pop()\n'
        '\n'
        '    def test_allocation_accounting(self):\n'
        '        arena=ArenaBudget(10);handle=arena.reserve(8)\n'
        '        with self.assertRaises(MemoryError):arena.reserve(3)\n'
        '        self.assertEqual(arena.used,8)\n'
        '        arena.release(handle)\n'
        '        self.assertEqual(arena.used,0)\n'
        '        with self.assertRaises(ValueError):arena.release(handle)\n'
        '\n'
        '    def test_ordered_execution(self):\n'
        '        self.assertEqual(deterministic_map(lambda x:x*x,range(100),4),tuple(x*x for x in range(100)))\n'
        '\n'
        '    def test_statistics_do_not_authorize_promotion(self):\n'
        '        result=paired_bootstrap([0,0,0],[1,1,1],samples=100)\n'
        "        self.assertEqual(result['ci95'],[1,1])\n"
        "        self.assertFalse(result['promotion_authorized'])\n"
        "        with self.assertRaises(ValueError):paired_bootstrap([0,float('nan')],[1,2])\n"
        '\n'
        '    def test_negative_benchmark_is_preserved(self):\n'
        "        result=benchmark('negative',lambda seed:0,lambda value:False)\n"
        '        self.assertFalse(result.correct)\n'
        "        self.assertEqual(result.detail,'rejected')\n"
        '\n'
        '    def test_generic_expansion(self):\n'
        "        registry=Registry.from_dict({'format':'omega-generics-1','schema_version':'1.0.0','functions':[\n"
        "            {'name':'square','parameters':[{'name':'x','shape':[]}],'returns':[],'body':'x*x'}]})\n"
        "        result=expand('parametro x=3;perda l=square(x);mostrar l;',registry)\n"
        "        self.assertEqual(result.manifest()['instances'][0]['result'],{'element':'rational','shape':[]})\n"
        '\n'
        '\n'
        "if __name__ == '__main__':\n"
        '    import argparse\n'
        '    from pathlib import Path\n'
        "    parser=argparse.ArgumentParser(description='Single-file Omega components; unfinished roadmap tasks are explicitly reported.')\n"
        "    parser.add_argument('action',choices=['self-test','coverage'])\n"
        '    args=parser.parse_args()\n'
        "    if args.action=='self-test':\n"
        '        suite=unittest.defaultTestLoader.loadTestsFromTestCase(MonolithTests)\n'
        '        outcome=unittest.TextTestRunner(verbosity=2).run(suite)\n'
        '        raise SystemExit(0 if outcome.wasSuccessful() else 1)\n'
        '    print(json.dumps(coverage(Path(__file__).resolve().parents[1]),ensure_ascii=False,indent=2))\n'
    ),
    ('scripts/package.py',
        '#!/usr/bin/env python3\n'
        '"""Build reproducible Python archives for a fixed source tree/toolchain."""\n'
        'import gzip\n'
        'import io\n'
        'import os\n'
        'from pathlib import Path\n'
        'import subprocess\n'
        'import sys\n'
        'import tarfile\n'
        'import tempfile\n'
        '\n'
        'ROOT=Path(__file__).resolve().parents[1]\n'
        'sys.path.insert(0,str(ROOT))\n'
        'from omega_platform.budget import BUILD_BUDGET\n'
        'from omega_platform.sandbox import trusted\n'
        '\n'
        "epoch=int(subprocess.run(['git','log','-1','--format=%ct'],cwd=ROOT,\n"
        '                         capture_output=True,text=True,check=True).stdout.strip())\n'
        "os.environ['SOURCE_DATE_EPOCH']=str(epoch)\n"
        "os.environ['PYTHONHASHSEED']='0'\n"
        "destination=ROOT/'dist';destination.mkdir(exist_ok=True)\n"
        "with tempfile.TemporaryDirectory(prefix='.omega-packaging-',dir=destination) as tmp:\n"
        "    trusted([sys.executable,'-m','build','--no-isolation','--outdir',tmp],\n"
        '            cwd=ROOT,budget=BUILD_BUDGET,check=True)\n'
        '    for path in sorted(Path(tmp).iterdir()):\n'
        "        if path.name.endswith('.tar.gz'):\n"
        '            # Source-checkout mtimes, ownership and gzip timestamps must not\n'
        '            # change the sdist bytes across two clean checkouts of one commit.\n'
        "            with tarfile.open(path,'r:gz') as source:\n"
        '                data=io.BytesIO()\n'
        "                with tarfile.open(fileobj=data,mode='w',format=tarfile.PAX_FORMAT) as output:\n"
        '                    for member in sorted(source.getmembers(),key=lambda m:m.name):\n'
        '                        stream=source.extractfile(member) if member.isfile() else None\n'
        "                        member.uid=member.gid=0;member.uname=member.gname=''\n"
        '                        member.mtime=epoch;member.pax_headers={}\n'
        '                        member.mode=0o755 if member.isdir() or member.mode&0o111 else 0o644\n'
        '                        output.addfile(member,stream)\n'
        "                with path.open('wb') as target:\n"
        "                    with gzip.GzipFile(filename='',mode='wb',fileobj=target,mtime=epoch) as zipped:\n"
        '                        zipped.write(data.getvalue())\n'
        '        os.replace(path,destination/path.name)\n'
        '        print(destination/path.name)\n'
    ),
