    ('scripts/security.py',
        '#!/usr/bin/env python3\n'
        'import argparse\n'
        'import json\n'
        'from pathlib import Path\n'
        'import sys\n'
        '\n'
        'ROOT=Path(__file__).resolve().parents[1]\n'
        'sys.path.insert(0,str(ROOT))\n'
        'from omega_platform.security import validate\n'
        '\n'
        'parser=argparse.ArgumentParser()\n'
        "parser.add_argument('--output',type=Path,default=ROOT/'artifacts/foundation/security.json')\n"
        "parser.add_argument('--mutations',type=int,default=48)\n"
        "parser.add_argument('--analyzer',choices=['host','docker'],default='host')\n"
        'args=parser.parse_args()\n'
        "if not 1<=args.mutations<=10000:parser.error('mutations must be between 1 and 10000')\n"
        'report=validate(ROOT,count=args.mutations,analyzer=args.analyzer)\n'
        'args.output.parent.mkdir(parents=True,exist_ok=True)\n'
        "args.output.write_text(json.dumps(report,indent=2,ensure_ascii=False)+'\\n')\n"
        'print(f"Native security: {report[\'passed\']} passed; {report[\'failed\']} failed. {args.output}")\n'
        "for case in report['cases']:\n"
        "    if case['passed']:continue\n"
        "    print(json.dumps({k:v for k,v in case.items() if k!='stderr'},ensure_ascii=False))\n"
        "    diagnostic=case.get('stderr','')\n"
        "    markers=('error:','warning:','runtime error:','SUMMARY:','ERROR:')\n"
        '    lines=[line for line in diagnostic.splitlines() if any(word in line for word in markers)]\n'
        "    print('\\n'.join(lines[:80]) if lines else diagnostic[-6000:])\n"
        "raise SystemExit(0 if report['valid'] else 1)\n"
    ),
