        'importar "../math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Balanced median-split KD-tree and exact squared-distance pruning; bounded static point sets, deterministic ties.\n'
        'funcao build(points,ids,depth,nodes,dimensions)  {\n'
        '  se(len(ids)==0)  {\n'
        '    retornar -1;\n'
        '  }\n'
        '  var axis=depth%dimensions;\n'
        '  var i=1;\n'
        '  enquanto(i<len(ids))  {\n'
        '    var j=i;\n'
        '    enquanto(j>0&&(points[ids[j]][axis]<points[ids[j-1]][axis]||(points[ids[j]][axis]==points[ids[j-1]][axis]&&ids[j]<ids[j-1])))  {\n'
        '      var v=ids[j];\n'
        '      put(ids,j,ids[j-1]);\n'
        '      put(ids,j-1,v);\n'
        '      j=j-1;\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  var middle=qfloor(len(ids)/2);\n'
        '  var node=obj();\n'
        '  put(node,"point",ids[middle]);\n'
        '  put(node,"axis",axis);\n'
        '  put(node,"left",-1);\n'
        '  put(node,"right",-1);\n'
        '  var id=len(nodes);\n'
        '  push(nodes,node);\n'
        '  put(node,"left",build(points,slice(ids,0,middle),depth+1,nodes,dimensions));\n'
        '  put(node,"right",build(points,slice(ids,middle+1,len(ids)),depth+1,nodes,dimensions));\n'
        '  retornar id;\n'
        '}\n'
        'funcao nearest(points,nodes,id,query,best)  {\n'
        '  se(id<0)  {\n'
        '    retornar 0;\n'
        '  }\n'
        '  var node=nodes[id];\n'
        '  var index=node["point"];\n'
        '  var delta=u::add(points[index],u::scale(query,-1));\n'
        '  var distance=u::dot(delta,delta);\n'
        '  se(best[0]<0||distance<best[1]||(distance==best[1]&&index<best[0]))  {\n'
        '    put(best,0,index);\n'
        '    put(best,1,distance);\n'
        '  }\n'
        '  var axis=node["axis"];\n'
        '  var split=query[axis]-points[index][axis];\n'
        '  var near=node["left"];\n'
        '  var far=node["right"];\n'
        '  se(split>0)  {\n'
        '    near=node["right"];\n'
        '    far=node["left"];\n'
        '  }\n'
        '  nearest(points,nodes,near,query,best);\n'
        '  se(split*split<=best[1])  {\n'
        '    nearest(points,nodes,far,query,best);\n'
        '  }\n'
        '  retornar 0;\n'
        '}\n'
        'funcao execute(r)  {\n'
        '  var points=u::mat(r["points"]);\n'
        '  var query=u::vector(r["query"]);\n'
        '  se(len(query)!=len(points[0])||len(query)>16)  {\n'
        '    fail("KD-tree query dimensions");\n'
        '  }\n'
        '  var ids=[];\n'
        '  var i=0;\n'
        '  enquanto(i<len(points))  {\n'
        '    push(ids,i);\n'
        '    i=i+1;\n'
        '  }\n'
        '  var nodes=[];\n'
        '  var root=build(points,ids,0,nodes,len(query));\n'
        '  var best=[-1,0];\n'
        '  nearest(points,nodes,root,query,best);\n'
        '  var out=u::result("balanced-exact-KD-nearest-neighbour",best);\n'
        '  put(out,"nodes",nodes);\n'
        '  put(out,"root",root);\n'
        '  retornar out;\n'
        '}\n'
