    ('std/io/csv_dataset_parser.omega',
        'modulo science_113;\n'
        'importar "../../ciencia/core/exato.omega" como u;\n'
        'importar "../math.omega" como m;\n'
        'importar "../string.omega" como s;\n'
        'importar "../math/linalg_exact.omega" como la;\n'
        'exportar execute;\n'
        '# Bounded quoted CSV with escaped quotes/newlines and optional exact scalar conversion; byte delimiter semantics.\n'
        'funcao execute(r)  {\n'
        '  var data=u::text_field(r,"text",65536);\n'
        '  var delimiter=",";\n'
        '  se(has(r,"delimiter"))  {\n'
        '    delimiter=u::text_field(r,"delimiter",1);\n'
        '  }\n'
        '  se(len(delimiter)!=1||delimiter=="\\""||delimiter=="\\n"||delimiter=="\\r")  {\n'
        '    fail("One-byte CSV delimiter required");\n'
        '  }\n'
        '  var rows=[];\n'
        '  var row=[];\n'
        '  var field="";\n'
        '  var quoted=0;\n'
        '  var closed=0;\n'
        '  var i=0;\n'
        '  enquanto(i<len(data))  {\n'
        '    var ch=data[i];\n'
        '    se(quoted)  {\n'
        '      se(ch=="\\"")  {\n'
        '        se(i+1<len(data)&&data[i+1]=="\\"")  {\n'
        '          field=field+"\\"";\n'
        '          i=i+1;\n'
        '        }\n'
        '        senao  {\n'
        '          quoted=0;\n'
        '          closed=1;\n'
        '        }\n'
        '      }\n'
        '      senao  {\n'
        '        field=field+ch;\n'
        '      }\n'
        '    }\n'
        '    senao  {\n'
        '      se(ch==delimiter)  {\n'
        '        push(row,field);\n'
        '        field="";\n'
        '        closed=0;\n'
        '      }\n'
        '      senao  {\n'
        '        se(ch=="\\n"||ch=="\\r")  {\n'
        '          push(row,field);\n'
        '          push(rows,row);\n'
        '          row=[];\n'
        '          field="";\n'
        '          closed=0;\n'
        '          se(ch=="\\r"&&i+1<len(data)&&data[i+1]=="\\n")  {\n'
        '            i=i+1;\n'
        '          }\n'
        '        }\n'
        '        senao  {\n'
        '          se(ch=="\\"")  {\n'
        '            se(len(field)!=0||closed)  {\n'
        '              fail("Quote outside a CSV field start");\n'
        '            }\n'
        '            quoted=1;\n'
        '          }\n'
        '          senao  {\n'
        '            se(closed)  {\n'
        '              fail("Unexpected bytes after a quoted field");\n'
        '            }\n'
        '            field=field+ch;\n'
        '          }\n'
        '        }\n'
        '      }\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  se(quoted)  {\n'
        '    fail("Unclosed CSV quotation");\n'
        '  }\n'
        '  se(len(field)>0||closed||len(row)>0||(len(data)>0&&data[len(data)-1]==delimiter))  {\n'
        '    push(row,field);\n'
        '    push(rows,row);\n'
        '  }\n'
        '  se(len(rows)>1024)  {\n'
        '    fail("CSV row budget");\n'
        '  }\n'
        '  var width=0;\n'
        '  i=0;\n'
        '  enquanto(i<len(rows))  {\n'
        '    se(i==0)  {\n'
        '      width=len(rows[i]);\n'
        '    }\n'
        '    se(len(rows[i])!=width||width>128)  {\n'
        '      fail("CSV ragged table or column budget");\n'
        '    }\n'
        '    i=i+1;\n'
        '  }\n'
        '  var header=[];\n'
        '  se(u::num(r,"header",0)&&len(rows)>0)  {\n'
        '    header=rows[0];\n'
        '    rows=slice(rows,1,len(rows));\n'
        '  }\n'
        '  se(u::num(r,"numeric",0))  {\n'
        '    i=0;\n'
        '    enquanto(i<len(rows))  {\n'
        '      var j=0;\n'
        '      enquanto(j<width)  {\n'
        '        put(rows[i],j,u::val(s::trim(rows[i][j])));\n'
        '        j=j+1;\n'
        '      }\n'
        '      i=i+1;\n'
        '    }\n'
        '  }\n'
        '  var out=u::result("bounded-RFC4180-style-CSV",rows);\n'
        '  put(out,"header",header);\n'
        '  put(out,"columns",width);\n'
        '  retornar out;\n'
        '}\n'
    ),
