        'importar "../string.omega" como s;\n'
        'importar "../math.omega" como m;\n'
        'exportar matrix, identity, transpose, multiply, norm, inverse, lu, svd, execute;\n'
        'funcao matrix(raw){se(!islist(raw)||len(raw)<1||len(raw)>16||!islist(raw[0])||len(raw[0])<1||len(raw[0])>16){fail("Static matrix dimensions 1..16");}var out=[];var i=0;enquanto(i<len(raw)){se(len(raw[i])!=len(raw[0])){fail("Ragged matrix");}var row=[];var j=0;enquanto(j<len(raw[i])){push(row,s::rational(text(raw[i][j])));j=j+1;}push(out,row);i=i+1;}retornar out;}\n'
        'funcao identity(n){var a=[];var i=0;enquanto(i<n){var row=[];var j=0;enquanto(j<n){push(row,i==j);j=j+1;}push(a,row);i=i+1;}retornar a;}\n'
        'funcao transpose(a){var out=[];var j=0;enquanto(j<len(a[0])){var row=[];var i=0;enquanto(i<len(a)){push(row,a[i][j]);i=i+1;}push(out,row);j=j+1;}retornar out;}\n'
