        ' var out=obj();put(out,"L",l);put(out,"U",u);put(out,"P",p);put(out,"swaps",swaps);retornar out;}\n'
        'funcao inverse(a){var n=len(a);se(n!=len(a[0])){fail("Square inverse matrix required");}var b=clone(a);var inv=identity(n);var k=0;enquanto(k<n){var pivot=k;enquanto(pivot<n&&b[pivot][k]==0){pivot=pivot+1;}se(pivot==n){fail("Singular matrix");}var t=b[k];put(b,k,b[pivot]);put(b,pivot,t);t=inv[k];put(inv,k,inv[pivot]);put(inv,pivot,t);var d=b[k][k];var j=0;enquanto(j<n){put(b[k],j,b[k][j]/d);put(inv[k],j,inv[k][j]/d);j=j+1;}var i=0;enquanto(i<n){se(i!=k){var f=b[i][k];j=0;enquanto(j<n){put(b[i],j,b[i][j]-f*b[k][j]);put(inv[i],j,inv[i][j]-f*inv[k][j]);j=j+1;}}i=i+1;}k=k+1;}retornar inv;}\n'
        'funcao svd(a,bits){\n'
        ' // A generic exact rational SVD does not exist. This bounded 2-column routine\n'
