        '#include <stdio.h>\n'
        'int main(void) {\n'
        '  OmegaArena arena; omega_arena_init(&arena,4096);\n'
        '  unsigned char *p=omega_arena_alloc(&arena,128);\n'
        '  assert(p && arena.allocations==1);\n'
        '  for(size_t i=0;i<128;i++) assert(p[i]==0);\n'
        '  assert(((uintptr_t)p % _Alignof(max_align_t))==0);\n'
        '  size_t used=arena.used;\n'
        '  assert(omega_arena_alloc(&arena,SIZE_MAX)==NULL);\n'
        '  assert(arena.error==OM_MEMORY_LIMIT && arena.used==used && p[0]==0);\n'
        '  p[127]=7;\n'
        '  omega_arena_reset(&arena);\n'
        '  assert(arena.used==0 && arena.head==NULL && arena.allocations==0);\n'
        '  for(int n=0;n<100;n++) { assert(omega_arena_alloc(&arena,64)); omega_arena_reset(&arena); }\n'
        '  puts("arena-ok"); return 0;\n'
        '}\n'
