        "        assert record['sources'][path] == hashlib.sha256((ROOT / path).read_bytes()).hexdigest()\n"
        '\n'
        '\n'
        "@pytest.mark.parametrize('artifact', ['program', 'program.c', 'program.build.json'])\n"
        'def test_replay_links_delivered_native_artifacts_to_rebuilt_source(native_bundle, tmp_path, artifact):\n'
        '    import shutil\n'
        '    directory, _ = native_bundle\n'
        "    copy = tmp_path / 'copy'\n"
        '    shutil.copytree(directory, copy)\n'
        '    # Rehashing malicious bytes is not sufficient to establish source/binary\n'
        '    # correspondence. The independent rebuild must reproduce those bytes too.\n'
        '    path = copy / artifact\n'
        "    path.write_bytes(path.read_bytes() + b'\\n')\n"
        '    data = path.read_bytes()\n'
        "    manifest = json.loads((copy / 'manifest.json').read_text())\n"
        "    manifest['files'][artifact] = {'sha256': hashlib.sha256(data).hexdigest(), 'bytes': len(data)}\n"
        "    (copy / 'manifest.json').write_bytes(canonical(manifest))\n"
        "    with pytest.raises(ValueError, match='synthesis replay disagreement'):\n"
        '        workflow.audit(copy)\n'
