    ('testes/acceptance/test_validation_fixes.py',
        '"""Regression coverage for exact trace inputs and nested ASan resource limits."""\n'
        'from fractions import Fraction\n'
        'import json\n'
        'import sys\n'
        'import pytest\n'
        'from omega.trace import evaluate\n'
        'from omega.motor_v1 import CompiladorV1\n'
        'from omega.sintaxe import analisar\n'
        'from omega.typed_ir import TypedIR\n'
        'from omega_platform.budget import Budget\n'
        'from omega_platform.sandbox import trusted,ASAN_VIRTUAL_BYTES\n'
        '\n'
        '\n'
        "@pytest.mark.parametrize('value',[3,Fraction(3),Fraction(1,3)])\n"
        'def test_trace_accepts_exact_scalars_without_mutating_input(typed_graph,value):\n'
        "    state={'x':value};frames=evaluate(typed_graph,state)\n"
        '    assert frames[-1].value==str(Fraction(value)**2)\n'
        "    assert state=={'x':value} and type(state['x']) is type(value)\n"
        '\n'
        '\n'
        'def test_trace_normalizes_list_vectors_and_checks_shape_before_copying():\n'
        "    ir=TypedIR.from_legacy(CompiladorV1().programa(analisar('parametro vetor w=[1,2];perda l=dot(w,w);mostrar l;')))\n"
        "    state={'w':[3,4]}\n"
        "    assert evaluate(ir,state)[-1].value=='25'\n"
        "    assert state=={'w':[3,4]}\n"
        "    with pytest.raises(ValueError):evaluate(ir,{'w':[3,4,5]})\n"
        '\n'
        '\n'
        "@pytest.mark.parametrize('value',[True,3.0,'3',float('nan')])\n"
        'def test_trace_does_not_silently_coerce_inexact_or_ambiguous_scalars(typed_graph,value):\n'
        "    with pytest.raises(TypeError):evaluate(typed_graph,{'x':value})\n"
        '\n'
        '\n'
        "@pytest.mark.parametrize('diagnostics',[False,True])\n"
        'def test_only_explicit_trusted_diagnostic_profile_can_raise_as_limit(diagnostics):\n'
        "    program='''import json,resource\n"
        'before=resource.getrlimit(resource.RLIMIT_AS)\n'
        'raised=False\n'
        'try:\n'
        '    resource.setrlimit(resource.RLIMIT_AS,(32*1024**4,32*1024**4))\n'
        '    raised=True\n'
        'except (ValueError,OSError):pass\n'
        "print(json.dumps({'before':before,'after':resource.getrlimit(resource.RLIMIT_AS),'raised':raised}))\n"
        "'''\n"
        '    budget=Budget(memory_bytes=64*1024**2,cpu_seconds=2,wall_seconds=10,processes=1024)\n'
        "    result=trusted([sys.executable,'-c',program],budget=budget,check=True,instrumented_children=diagnostics)\n"
        '    observed=json.loads(result.stdout)\n'
        "    assert observed['before'][0]==budget.memory_bytes\n"
        "    assert observed['before'][1]==(ASAN_VIRTUAL_BYTES if diagnostics else budget.memory_bytes)\n"
        "    assert observed['raised'] is diagnostics\n"
        "    assert observed['after']==([ASAN_VIRTUAL_BYTES]*2 if diagnostics else [budget.memory_bytes]*2)\n"
        '\n'
        '\n'
        "@pytest.mark.parametrize('extra',['tools','dev'])\n"
        'def test_cpu_lock_satisfies_optional_validation_dependencies(extra):\n'
        '    from pathlib import Path\n'
        '    import tomllib\n'
        '    from packaging.requirements import Requirement\n'
        '    from packaging.utils import canonicalize_name\n'
        '    root=Path(__file__).resolve().parents[2]\n'
        '    requirements={}\n'
        "    for line in (root/'requirements/cpu-py312.lock').read_text().splitlines():\n"
        "        if not line.strip() or line.lstrip().startswith('#'):continue\n"
        '        requirement=Requirement(line)\n'
        "        pins=[specifier.version for specifier in requirement.specifier if specifier.operator=='==']\n"
        '        assert len(pins)==1\n'
        '        requirements[canonicalize_name(requirement.name)]=pins[0]\n'
        "    project=tomllib.loads((root/'pyproject.toml').read_text())\n"
        "    for raw in project['project']['optional-dependencies'][extra]:\n"
        '        requirement=Requirement(raw)\n'
        '        assert requirements[canonicalize_name(requirement.name)] in requirement.specifier\n'
    ),
