        'def jepa_loss(data):\n'
        "    w=[list(map(Q,row)) for row in data['encoder']]; teacher=[list(map(Q,row)) for row in data['target_encoder']]\n"
        "    p=[list(map(Q,row)) for row in data['predictor']]; action=[list(map(Q,row)) for row in data['action_map']]\n"
        '    dot=lambda a,b:sum((x*Q(y) for x,y in zip(a,b)),Q(0))\n'
        "    z=[[dot(row,x) for row in w] for x in data['context']]\n"
        "    t=[[dot(row,y) for row in teacher] for y in data['target']]\n"
        '    b=len(z); d=len(w); loss=Q(0)\n'
        "    for state,expected,u in zip(z,t,data['actions']):\n"
        '        for i in range(d): loss+=(dot(p[i],state)+dot(action[i],u)-expected[i])**2/b\n'
        '    means=[sum(row[i] for row in z)/b for i in range(d)]\n'
        '    cov=[[sum((row[i]-means[i])*(row[j]-means[j]) for row in z)/(b-1) for j in range(d)] for i in range(d)]\n'
        "    loss+=Q(data['variance_weight'])*sum(max(0,Q(data['variance_floor'])-cov[i][i])**2 for i in range(d))\n"
        "    loss+=Q(data['covariance_weight'])*sum(cov[i][j]**2 for i in range(d) for j in range(d) if i!=j)\n"
        '    return loss\n'
        '\n'
        '\n'
        'def test_jepa_gradient_ema_and_collapse_diagnostic_against_independent_objective():\n'
        "    data=request(14); result=example(14); assert result['before']['loss']==jepa_loss(data)\n"
        '    epsilon=Q(1,10**6)\n'
        "    for key,gradient in [('encoder','encoder_gradient'),('predictor','predictor_gradient'),('action_map','action_gradient')]:\n"
        '        for i,row in enumerate(data[key]):\n'
        '            for j,_ in enumerate(row):\n'
        '                plus,minus=deepcopy(data),deepcopy(data)\n'
        '                plus[key][i][j]=Q(row[j])+epsilon;minus[key][i][j]=Q(row[j])-epsilon\n'
        '                numerical=(jepa_loss(plus)-jepa_loss(minus))/(2*epsilon)\n'
        "                assert abs(numerical-result['before'][gradient][i][j])<Q(1,10**10)\n"
        "    for i,row in enumerate(result['value']):\n"
        "        for j,x in enumerate(row):assert result['target_encoder'][i][j]==Q(9,10)*Q(data['target_encoder'][i][j])+x/10\n"
        "    assert result['after']['prediction_loss']<result['before']['prediction_loss']\n"
        "    collapsed=run(14,{**data,'encoder':[[0,0],[0,0]],'target_encoder':[[0,0],[0,0]]})\n"
        "    assert collapsed['after']['collapsed']==1 and collapsed['noncollapse_guaranteed']==0\n"
