    ('testes/foundation/runtime_harness.c',
        '/* Fixed diagnostic target: inputs are data, never C source. */\n'
        '#include "runtime.h"\n'
        'int main(int argc, char **argv) {\n'
        '  o_init(argc, argv);\n'
        '  if (argc < 2) o_die("Mode required");\n'
        '  if (!strcmp(argv[1], "json")) {\n'
        '    if (argc != 3) o_die("Input required");\n'
        '    o_print(o_json(o_parsejson(o_str(argv[2]))));\n'
        '  } else if (!strcmp(argv[1], "number")) {\n'
        '    if (argc != 3) o_die("Input required");\n'
        '    o_print(o_text(o_num(argv[2])));\n'
        '  } else if (!strcmp(argv[1], "cycle")) {\n'
        '    V a=o_list();o_push(a,a);o_print(o_json(a));\n'
        '  } else if (!strcmp(argv[1], "equalcycle")) {\n'
        '    V a=o_list();o_push(a,a);o_print(o_eq(a,a));\n'
        '  } else if (!strcmp(argv[1], "fuel")) {\n'
        '    for (;;) o_tick();\n'
        '  } else o_die("Unknown mode");\n'
        '  return 0;\n'
        '}\n'
    ),
