        '\n'
        '\n'
        'def test_symbolic_product_requires_all_bindings_and_equal_inner_dimensions():\n'
        "    contract=dimension_contract('@',(('rows','inner'),('other','cols')))\n"
        "    assert contract.output==('rows','cols')\n"
        "    assert contract.specialize({'rows':3,'inner':4,'other':4,'cols':2})==NumericType((3,2))\n"
        "    for bindings in ({'rows':3,'inner':4,'other':5,'cols':2},{'rows':3},\n"
        "                     {'rows':True,'inner':4,'other':4,'cols':2},\n"
        "                     {'rows':2048,'inner':4,'other':4,'cols':2048}):\n"
        '        with pytest.raises(TypeCheckError):contract.specialize(bindings)\n'
        '\n'
        '\n'
        'def test_repeated_symbols_propagate_constraints_transitively():\n'
        "    contract=dimension_contract('+',(('a','b'),('b',3)))\n"
        '    assert contract.output==(3,3)\n'
        "    assert contract.specialize({'a':3,'b':3})==NumericType((3,3))\n"
        "    with pytest.raises(TypeCheckError):contract.specialize({'a':2,'b':3})\n"
        "    with pytest.raises(TypeCheckError):dimension_contract('+',(('a','a'),(2,3)))\n"
        '\n'
        '\n'
        'def test_contract_roundtrip_rejects_forged_outputs_and_equations():\n'
        "    contract=dimension_contract('dot',(('n',),('m',)))\n"
        '    encoded=json.loads(json.dumps(contract.to_dict()))\n'
        '    assert DimensionContract.from_dict(encoded)==contract\n'
        "    for field,value in [('output',[4]),('equalities',[]),('format','omega-dimensions-2'),('extra',0)]:\n"
        '        changed=deepcopy(encoded);changed[field]=value\n'
        '        with pytest.raises(TypeCheckError):DimensionContract.from_dict(changed)\n'
        "    forged=DimensionContract('@',((2,3),(3,4)),(2,5),())\n"
        '    with pytest.raises(TypeCheckError):forged.specialize({})\n'
        "    changed=dimension_contract('neg',((1,),)).to_dict();changed['output']=[True]\n"
        '    with pytest.raises(TypeCheckError):DimensionContract.from_dict(changed)\n'
        '\n'
        '\n'
        'def test_all_small_concrete_shapes_match_two_existing_independent_type_rules():\n'
        '    shapes=[(),*(s for rank in (1,2) for s in itertools.product((1,2,3),repeat=rank))]\n'
        '    comparisons=0\n'
        "    for operator,arity in [('neg',1),('relu',1),('soma',1),('transposta',1),\n"
        "                           *[(op,2) for op in ('+','-','*','/','^','@','dot')]]:\n"
        '        for inputs in itertools.product(shapes,repeat=arity):\n'
        '            try:expected=vshape(operator,inputs)\n'
        '            except ErroOmega:\n'
        '                with pytest.raises(TypeCheckError):dimension_contract(operator,inputs)\n'
        '                with pytest.raises(TypeCheckError):infer_operation(operator,[NumericType(s) for s in inputs])\n'
        '            else:\n'
        '                actual=dimension_contract(operator,inputs).specialize({}).shape\n'
        '                assert actual==expected==infer_operation(operator,[NumericType(s) for s in inputs]).shape\n'
        '            comparisons+=1\n'
        '    assert comparisons==1235\n'
        '\n'
        '\n'
        'def test_every_corpus_node_checked_and_certificate_bound_to_dimensions():\n'
        '    from omega_selfhost.driver import compile_ir\n'
        "    cases=json.loads((ROOT/'testes/corpus.json').read_text())['cases']\n"
        '    seen=0\n'
        '    for case in cases:\n'
        "        if case['language']!='tensor' or case['expected']=='compile_reject':continue\n"
        "        ir=compile_ir(ROOT/case['path']);cert=certify_graph_shapes(ir)\n"
        '        assert verify_graph_shapes(ir,cert)\n'
        "        assert len(cert['nodes'])==len(ir['nos'])\n"
        "        bad=deepcopy(cert);bad['shape_graph_sha256']='0'*64\n"
        '        with pytest.raises(TypeCheckError):verify_graph_shapes(ir,bad)\n'
        "        if cert['nodes']:\n"
        "            bad=deepcopy(cert);bad['nodes'][0]['shape']=[7]\n"
        '            with pytest.raises(TypeCheckError):verify_graph_shapes(ir,bad)\n'
        "        seen+=len(ir['nos'])\n"
        '    assert seen>100\n'
        '\n'
        '\n'
        "@pytest.mark.parametrize('mutation',[\n"
        "    lambda ir:ir['nos'][2].update(forma=[2]),\n"
        "    lambda ir:ir['nos'][1].update(args=[1]),\n"
