        'from omega.typed_ir import TypedIR\n'
        '\n'
        'ROOT=Path(__file__).resolve().parents[2]\n'
        '\n'
        '\n'
        'def v(name,op,args=(),incoming=(),literal=None,annotation=RATIONAL):\n'
        '    return Value(name,op,tuple(args),annotation,tuple(incoming),literal)\n'
        '\n'
        '\n'
        'def diamond():\n'
        "    return Graph('entry',(\n"
        "        Block('entry',(v('condition','input'),),Terminator('branch',('left','right'),('condition',))),\n"
        "        Block('left',(v('a','num',literal='1'),),Terminator('jump',('merge',))),\n"
        "        Block('right',(v('b','num',literal='2'),),Terminator('jump',('merge',))),\n"
        "        Block('merge',(v('result','phi',incoming=(('left','a'),('right','b'))),),Terminator('return',(),('result',))),\n"
        '    ))\n'
        '\n'
        '\n'
        'def loop():\n'
        "    return Graph('entry',(\n"
        "        Block('entry',(v('zero','num',literal='0'),v('one','num',literal='1'),v('limit','input')),Terminator('jump',('header',))),\n"
        "        Block('header',(v('i','phi',incoming=(('entry','zero'),('body','next_value'))),v('condition','-',('limit','i'))),\n"
        "              Terminator('branch',('body','exit'),('condition',))),\n"
        "        Block('body',(v('next_value','+',('i','one')),),Terminator('jump',('header',))),\n"
        "        Block('exit',(),Terminator('return',(),('i',))),\n"
        '    ))\n'
        '\n'
        '\n'
        'def test_diamond_phi_operands_are_uses_on_predecessor_edges():\n'
        '    graph=diamond();report=analyze(graph)\n'
        "    assert report['blocks']['merge']['dominators']==['entry','merge']\n"
        "    assert report['blocks']['left']['dominance_frontier']==['merge']\n"
        "    assert report['values']['a']['uses']==[{'block':'merge','index':0,'operand':0,'edge':'left'}]\n"
        '    assert verify_analysis(graph,report)\n'
        '    assert analyze(replace(graph,blocks=tuple(reversed(graph.blocks))))==report\n'
        '\n'
        '\n'
        'def test_loop_backedge_is_valid_and_header_is_its_own_frontier():\n'
        '    report=analyze(loop())\n'
        "    assert report['blocks']['body']['immediate_dominator']=='header'\n"
        "    assert report['blocks']['header']['dominance_frontier']==['header']\n"
