        'from omega.sintaxe import analisar\n'
        '\n'
        'ROOT=Path(__file__).resolve().parents[2]\n'
        '\n'
        '\n'
        'def graph():\n'
        "    return CompiladorV1().programa(analisar('parametro x=2; perda l=(x-1)^2; gradiente l em x; passo_livre l em x taxa 1/8; mostrar l;'))\n"
        '\n'
        '\n'
        "def encoded(document):return json.dumps(document,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()\n"
        '\n'
        '\n'
        'def test_canonical_bytes_independent_of_object_insertion_order_and_immutable():\n'
        '    def reverse(value):\n'
