        '        if type(value) is list:return [reverse(v) for v in value]\n'
        '        return value\n'
        '    original=graph();ir=TypedIR.from_legacy(original)\n'
        '    assert ir.to_bytes()==TypedIR.from_legacy(reverse(original)).to_bytes()\n'
        '    assert ir.sha256==TypedIR(ir.to_bytes()).sha256\n'
        "    original['nos'][0]['v']='99'\n"
        "    copy=ir.to_dict();copy['graph']['nos'][0]['v']='98'\n"
        "    assert ir.legacy()['nos'][0]['v']=='2'\n"
        '\n'
        '\n'
        "@pytest.mark.parametrize('mutation',[\n"
        "    lambda d:d.update(schema_version='2.0.0'),\n"
