        "    lambda d:d['graph']['perdas'].update(l=1),\n"
        "    lambda d:d['graph']['comandos'][0].update(nome='missing'),\n"
        "    lambda d:d['graph']['comandos'][2].update(parametro='missing'),\n"
        "    lambda d:d['graph']['comandos'][3].update(taxa=9999),\n"
        "    lambda d:d['graph']['comandos'][3].update(semente=True),\n"
        '])\n'
        'def test_tampered_schema_values_types_tables_and_commands_rejected(mutation):\n'
        '    document=TypedIR.from_legacy(graph()).to_dict();mutation(document)\n'
        '    with pytest.raises(TypeCheckError):TypedIR(encoded(document))\n'
        '\n'
        '\n'
        "@pytest.mark.parametrize('raw',[\n"
        '    b\'{"format":"omega-typed-ir-1","format":"other"}\',\n'
        '    b\'{"number":NaN}\',b\'{"number":Infinity}\',b\'{"number":true}\',\n'
        '    b\'{"number":1.5}\',b\'\\xff\',b\'{"value":"\\\\ud800"}\',\n'
        "    b'['*1000+b']'*1000,\n"
        '])\n'
        'def test_malformed_and_ambiguous_json_fails_closed(raw):\n'
