        "    with pytest.raises(TypeCheckError,match='budget'):TypedIR.load(path)\n"
        '\n'
        '\n'
        'def test_large_canonical_rational_does_not_change_python_global_limits():\n'
        "    original=graph();original['nos'][0]['v']='9'*6000\n"
        '    before=sys.get_int_max_str_digits()\n'
        "    assert TypedIR.from_legacy(original).legacy()['nos'][0]['v']=='9'*6000\n"
        '    assert sys.get_int_max_str_digits()==before\n'
        '\n'
        '\n'
        'def test_false_identity_is_structurally_valid_but_never_admitted_by_ir_reader():\n'
        "    ir={'formato':'omega-ir-2','versao':'1.0.0','nos':[],'simbolos':{},'parametros':[],'perdas':{},\n"
        "        'comandos':[{'tipo':'provar','nome':'','left':['n','1'],'right':['n','2']}]}\n"
        '    assert TypedIR.from_legacy(ir).legacy()==ir\n'
