        "        if rng.randrange(2):current[key]=rng.choice([None,True,False,-1,2**40,'unknown',[],{}])\n"
        '        elif type(current) is dict:del current[key]\n'
        '        else:current.pop(key)\n'
        '        try:TypedIR(encoded(bad));accepted+=1\n'
        '        except TypeCheckError:pass\n'
        '    assert accepted<10\n'
        '\n'
        '\n'
        'def test_corpus_original_and_optimized_graphs_roundtrip_without_semantic_rewriting():\n'
        '    from omega_selfhost.driver import compile_ir\n'
        "    cases=json.loads((ROOT/'testes/corpus.json').read_text())['cases']\n"
        '    count=0\n'
