        'def affine_oracle(a,b,match=2,mismatch=-1,opening=2,extension=1):\n'
        '    @lru_cache(None)\n'
        '    def best(i,j,last):\n'
        '        if i==len(a) and j==len(b):\n'
        '            return Q(0)\n'
        '        choices=[]\n'
        '        if i<len(a) and j<len(b):\n'
        '            choices.append((match if a[i]==b[j] else mismatch)+best(i+1,j+1,0))\n'
        '        if i<len(a):\n'
        '            choices.append(-(extension if last==1 else opening)+best(i+1,j,1))\n'
        '        if j<len(b):\n'
        '            choices.append(-(extension if last==2 else opening)+best(i,j+1,2))\n'
        '        return max(choices)\n'
        '    return best(0,0,0)\n'
