        ' assert(omega_kernel_borrow(&k,h,0,&pointer));assert(!omega_kernel_consume(&k,m));\n'
        ' assert(!omega_kernel_allocate(&k,1,32,&next));assert(omega_kernel_consume(&k,m));\n'
        ' assert(!omega_kernel_consume(&k,next));return 0;\n'
        "}''')\n"
