    ('testes/test_hyper_flat.py',
        'from fractions import Fraction as Q\n'
        'import random\n'
        'import pytest\n'
        'from omega_gpu_mcts.flat import FlatBatch\n'
        'from omega_gpu_mcts.backend import CudaSearch,CudaUnavailable,decode_prefix\n'
        'from omega_gpu_mcts.build import nvcc\n'
        'from omega_refine_check.syntax import parse,evaluate\n'
        '\n'
        '\n'
        'def test_flat_soa_jobs_match_independent_exact_evaluation():\n'
        "    expressions=['(x+1)*(y-2)','relu(x-y)','1/(x*x+1)','x/y','-x']\n"
        "    batch=FlatBatch.create(expressions,['x','y'])\n"
        "    cases=[{'x':str(Q(x,3)),'y':str(Q(y,7))} for x in (-5,0,3) for y in (-2,0,4)]\n"
        '    observed=batch.evaluate(cases)\n'
        '    for ast,result in zip(batch.expressions,observed):\n'
        '        for i,case in enumerate(cases):\n'
        '            try:expected=evaluate(ast,{k:Q(v) for k,v in case.items()})\n'
        "            except (ZeroDivisionError,ValueError):assert result['errors'][i]==1\n"
        "            else:assert result['errors'][i]==0 and result['values'][i]==expected\n"
        '\n'
        '\n'
        'def test_interval_filter_conservative_rejection_and_overflow():\n'
        "    batch=FlatBatch.create(['x+1','x*x','1/x','x*9223372036854775807'],['x'])\n"
        '    result=batch.filter([[-1,1]],[-2,2])\n'
        "    assert result['admissible']==[True,True,False,False]\n"
        "    assert result['errors'][2]==1 and not result['formal_admission']\n"
        "    assert FlatBatch.create(['x*x'],['x']).filter([[-2,2]],[0,4])['admissible']==[False] # dependency loss is not a false proof\n"
        "    assert FlatBatch.create(['1/x'],['x']).filter([[1,2]],['1/2',1])['admissible']==[True]\n"
        '\n'
        '\n'
        'def test_corrupted_flat_child_cycle_is_refused_before_read():\n'
        "    batch=FlatBatch.create(['x+1'],['x'])\n"
        '    batch.left[2]=2\n'
        "    assert batch.evaluate([{'x':1}])[0]['errors']==[4]\n"
        "    assert batch.filter([[0,1]],[0,2])['admissible']==[False]\n"
        "    with pytest.raises(ValueError):decode_prefix([48,0],['x'],[])\n"
        "    with pytest.raises(ValueError):decode_prefix([31],['x'],[])\n"
        '\n'
        '\n'
        'def test_accepted_interval_boxes_contain_sampled_reference_results():\n'
        '    rng=random.Random(12)\n'
        '    for _ in range(100):\n'
        '        lo=rng.randint(-5,0);hi=rng.randint(1,5)\n'
        "        ast=f'relu((x+{rng.randint(0,3)})*{rng.randint(0,3)})'\n"
        "        batch=FlatBatch.create([ast],['x']);result=batch.filter([[lo,hi]],[-100,100])\n"
        "        assert result['admissible']==[True]\n"
        "        for i in range(7):assert -100<=evaluate(parse(ast),{'x':Q(lo)+(Q(hi-lo)*i/6)})<=100\n"
        '\n'
        '\n'
        'def test_complete_cuda_pipeline_compiles_and_reports_device_absence():\n'
        '    try:nvcc()\n'
        "    except RuntimeError:pytest.skip('CUDA SDK unavailable; pipeline compile pending')\n"
        '    try:engine=CudaSearch()\n'
        "    except CudaUnavailable:pytest.skip('CUDA pipeline compiled; device execution pending: no GPU')\n"
        "    spec={'variables':{'x':'self>=-1 and self<=1'},'ensures':'result==x+1',\n"
        "          'examples':[{'inputs':{'x':str(x)},'output':str(x+1)} for x in (-1,0,1)]}\n"
        '    result=engine.search(spec,input_bounds=[[-1,1]],output_bounds=[0,2],rollouts=256,iterations=200)\n'
        "    assert result['statistics']['candidates']==51200\n"
        "    assert result['statistics']['nodes_evaluated']>=50000\n"
        "    assert result['statistics']['elapsed_ms']<1000,'50,000-node GPU latency target was not met on this device'\n"
        "    assert result['candidates'] and all(not c['formal_admission'] for c in result['candidates'])\n"
    ),
    ('testes/test_hyper_rational.py',
        'from fractions import Fraction as Q\n'
        'import math,random,subprocess\n'
        'import pytest\n'
        'from omega_gpu_mcts.numeric import Numeric\n'
        'from omega_gpu_mcts.build import compile_cuda,ROOT,nvcc\n'
        '\n'
        '\n'
        "@pytest.fixture(scope='module')\n"
        'def numeric():return Numeric(sanitize=True)\n'
        '\n'
        '\n'
        'def test_shared_rational_alu_matches_independent_fraction(numeric):\n'
        '    rng=random.Random(912)\n'
        '    for _ in range(2500):\n'
        '        a=Q(rng.randint(-10**6,10**6),rng.randint(1,10**6));b=Q(rng.randint(-10**6,10**6),rng.randint(1,10**6))\n'
        "        for op,expected in [('+',a+b),('-',a-b),('*',a*b),('/',a/b if b else None)]:\n"
        '            if expected is not None:assert numeric.operation(op,a,b)==expected\n'
        '        x=rng.getrandbits(64);y=rng.getrandbits(64)\n'
        '        assert numeric.gcd(x,y)==math.gcd(x,y)\n'
        '\n'
        '\n'
        'def test_pruning_including_large_intermediate_error_products(numeric):\n'
        '    rng=random.Random(21)\n'
        '    cases=[(Q(355,113),100),(Q(-1,2),1),(Q(0),1)]\n'
        '    cases += [(Q(rng.randint(-(2**63-1),2**63-1),rng.randint(1,2**63-1)),rng.randint(1,2**63-1)) for _ in range(1000)]\n'
        '    for q,cap in cases:\n'
        '        value,error=numeric.prune(q,cap)\n'
        '        assert value==q.limit_denominator(cap) and error==abs(q-value)\n'
        '\n'
        '\n'
        'def test_overflow_and_zero_division_are_explicit(numeric):\n'
        "    with pytest.raises(OverflowError):numeric.operation('+',2**63-1,1)\n"
        "    with pytest.raises(ZeroDivisionError):numeric.operation('/',1,0)\n"
        "    assert numeric.operation('*',Q(2**63-1,2),Q(2,2**63-1))==1\n"
        '    assert numeric.gcd(0,0)==0 and numeric.gcd(0,2**64-1)==2**64-1\n'
        '\n'
        '\n'
        'def test_cuda_numeric_target_compiles_and_ten_million_ops_if_device(tmp_path):\n'
        '    try:nvcc()\n'
        "    except RuntimeError:pytest.skip('CUDA SDK unavailable: CUDA compilation and device stress pending')\n"
        "    binary=compile_cuda([ROOT/'testes/cuda/rational_stress.cu'],tmp_path/'stress')\n"
        "    result=subprocess.run([binary,'10000000'],capture_output=True,text=True,timeout=300)\n"
        "    if result.returncode==77:pytest.skip('CUDA target compiled; 10,000,000 device operations pending: no GPU')\n"
        '    assert result.returncode==0,result.stderr\n'
        "    assert '10000000' in result.stdout\n"
    ),
