    ('testes/test_omega_orange.py',
        'import os\n'
        'import tempfile\n'
        '\n'
        'os.environ.setdefault("QT_QPA_PLATFORM", "offscreen")\n'
        'os.environ.setdefault("MPLCONFIGDIR", os.path.join(tempfile.gettempdir(), "omega-matplotlib"))\n'
        'os.environ.setdefault("XDG_CONFIG_HOME", os.path.join(tempfile.gettempdir(), "omega-config"))\n'
        'os.environ.setdefault("XDG_CACHE_HOME", os.path.join(tempfile.gettempdir(), "omega-cache"))\n'
        '\n'
        'try:\n'
        '    import pytest\n'
        '    import numpy as np\n'
        '    import Orange\n'
        'except ImportError:\n'
        '    import unittest\n'
        '    raise unittest.SkipTest("Install the dev and orange extras")\n'
        'from Orange.data import ContinuousVariable, DiscreteVariable, Domain, Table\n'
        'from Orange.widgets.tests import base as widget_test_base\n'
        'from omega_nextorch.orange_bridge import task_from_table\n'
        'from omega_nextorch.orange.OWOmegaCertifier import OWOmegaCertifier\n'
        'from omega_nextorch.gate import verify\n'
        '\n'
        '\n'
        'def truth_table():\n'
        '    domain = Domain([ContinuousVariable("x0"), ContinuousVariable("x1")],\n'
        '                    DiscreteVariable("xor", values=("0", "1")))\n'
        '    return Table.from_numpy(domain, np.array([[0, 0], [1, 0], [0, 1], [1, 1]]),\n'
        '                            np.array([0, 1, 1, 0]))\n'
        '\n'
        '\n'
        'def test_boolean_bridge_rejects_partial_duplicate_and_missing_data():\n'
        '    data = truth_table()\n'
        '    assert task_from_table(data)["outputs"] == [0, 1, 1, 0]\n'
        '    for invalid in (data[:3], data[[0, 0, 2, 3]]):\n'
        '        with pytest.raises(ValueError):\n'
        '            task_from_table(invalid)\n'
        '    with data.unlocked():\n'
        '        data.X[0, 0] = np.nan\n'
        '    with pytest.raises(ValueError):\n'
        '        task_from_table(data)\n'
        '\n'
        '\n'
        'def test_boolean_bridge_respects_categorical_labels():\n'
        '    variable = DiscreteVariable("x", values=("1", "0"))\n'
        '    domain = Domain([variable], DiscreteVariable("y", values=("1", "0")))\n'
        '    data = Table.from_numpy(domain, np.array([[0], [1]]), np.array([0, 1]))\n'
        '    assert task_from_table(data)["outputs"] == [0, 1]\n'
        '\n'
        '\n'
        'def test_workflow_and_supplied_table_are_loadable():\n'
        '    from pathlib import Path\n'
        '    from orangecanvas.registry import WidgetRegistry\n'
        '    from orangecanvas.scheme import Scheme\n'
        '    from orangewidget.workflow.discovery import WidgetDiscovery\n'
        '    root = Path(__file__).resolve().parents[1]\n'
        '    assert task_from_table(Table(str(root / "exemplos/intuicao_xor.tab")))["outputs"] == [0, 1, 1, 0]\n'
        '    registry = WidgetRegistry()\n'
        '    discovery = WidgetDiscovery(registry)\n'
        '    for package in ("omega_nextorch.orange", "Orange.widgets.data"):\n'
        '        discovery.process_category_package(package)\n'
        '    scheme = Scheme()\n'
        '    with (root / "exemplos/omega_nextorch.ows").open("rb") as stream:\n'
        '        scheme.load_from(stream, registry=registry)\n'
        '    assert len(scheme.nodes) == 2 and len(scheme.links) == 1\n'
        '\n'
        '\n'
        'class TestOmegaWidget(widget_test_base.WidgetTest):\n'
        '    def setUp(self):\n'
        '        super().setUp()\n'
        '        self.widget = self.create_widget(OWOmegaCertifier,\n'
        '            stored_settings={"epochs": 2, "require_lean": False})\n'
        '\n'
        '    def test_real_certification_and_replacement(self):\n'
        '        self.send_signal(self.widget.Inputs.data, truth_table())\n'
        '        self.widget.apply()\n'
        '        self.wait_until_finished(self.widget, timeout=30000)\n'
        '        assert not self.widget.Error.failed.is_shown(), self.widget.Error.failed.formatted\n'
        '        assert verify(self.get_output(self.widget.Outputs.certificate))\n'
        '        self.send_signal(self.widget.Inputs.data, None)\n'
        '        assert self.get_output(self.widget.Outputs.certificate) is None\n'
        '\n'
        '    def test_partial_specification_has_no_output(self):\n'
        '        self.send_signal(self.widget.Inputs.data, truth_table()[:2])\n'
        '        self.widget.apply()\n'
        '        self.wait_until_finished(self.widget, timeout=30000)\n'
        '        assert self.widget.Error.failed.is_shown()\n'
        '        assert self.get_output(self.widget.Outputs.certificate) is None\n'
        '\n'
        '    def test_category_is_registered(self):\n'
        '        from importlib.metadata import entry_points\n'
        '        assert any(p.value == "omega_nextorch.orange" for p in entry_points(group="orange.widgets"))\n'
    ),
    ('testes/test_open_v13.py',
        'import copy\n'
        'import json\n'
        'import tempfile\n'
        'import unittest\n'
        'from pathlib import Path\n'
        'from omega_open import logic\n'
        'from omega_open.engine import build,audit,export,audit_directory,verify_chain\n'
        'from omega_open.checker import verify_solution, validate_task\n'
        '\n'
        '\n'
        'def task(name,n,fn):\n'
        "    return {'id':name,'arity':n,'outputs':[int(fn(i)) for i in range(1<<n)]}\n"
        '\n'
        '\n'
        'class TestOpenOmega(unittest.TestCase):\n'
        '    def setUp(self):\n'
        '        self.tasks=[\n'
        "            task('paridade_3',3,lambda i:i.bit_count()%2),\n"
        "            task('majoria_3',3,lambda i:i.bit_count()>=2),\n"
        "            task('e_4',4,lambda i:i==15),\n"
        "            task('ou_4',4,lambda i:i!=0),\n"
        "            task('mux_3',3,lambda i:(i>>1 & 1) if i&1 else (i>>2 & 1)),\n"
        "            task('paridade_4',4,lambda i:i.bit_count()%2),\n"
        '        ]\n'
        "        self.train=['paridade_3','majoria_3','e_4','mux_3']\n"
        '\n'
        '    def test_synthesis_every_strategy(self):\n'
        '        for n in range(5):\n'
        '            for code in range(min(1<<(1<<n),16)):\n'
        '                table=[(code>>i)&1 for i in range(1<<n)]\n'
        '                for name,e in logic.candidates(table,n,3):\n'
        '                    self.assertEqual(logic.truth_table(e,n),table,(n,name))\n'
        '\n'
        '    def test_certified_evolution(self):\n'
        '        doc=build(self.tasks,self.train,generations=2)\n'
        '        self.assertTrue(verify_chain(doc))\n'
        "        self.assertTrue(audit(doc)['valid'])\n"
        "        self.assertLessEqual(doc['generations'][-1]['training_cost'][0],doc['generations'][0]['training_cost'][0])\n"
        '\n'
        '    def test_temper_attempts(self):\n'
        '        doc=build(self.tasks,self.train,generations=1)\n'
        '        changes=[\n'
        "            lambda x:x['tasks'][0]['outputs'].__setitem__(0,1-x['tasks'][0]['outputs'][0]),\n"
        "            lambda x:x['generations'][0]['solutions']['paridade_3']['ast'].__setitem__(0,'unknown'),\n"
        "            lambda x:x['generations'][0].__setitem__('training_cost',[0,0]),\n"
        "            lambda x:x['generations'][0].__setitem__('weights',[10,0,0]),\n"
        '        ]\n'
        '        for change in changes:\n'
        '            bad=copy.deepcopy(doc);change(bad)\n'
        '            self.assertFalse(verify_chain(bad))\n'
        '\n'
        '    def test_dir_audit(self):\n'
        '        doc=build(self.tasks,self.train,generations=1)\n'
        '        with tempfile.TemporaryDirectory() as td:\n'
        '            export(doc,td)\n'
        "            self.assertTrue(audit_directory(td)['valid'])\n"
        "            path=Path(td)/'politica_ativa.omega'\n"
        "            path.write_text('malicioso',encoding='utf-8')\n"
        '            with self.assertRaises(ValueError):audit_directory(td)\n'
        '\n'
        '    def test_arbitrary_arity_and_budget(self):\n'
        "        t=task('parity7',7,lambda x:x.bit_count()%2)\n"
        "        doc=build([t],['parity7'],generations=0,max_orders=1,max_rows=128)\n"
        '        self.assertTrue(verify_chain(doc))\n'
        "        with self.assertRaises(ValueError):build([t],['parity7'],max_rows=64)\n"
        '\n'
        '    def test_reject_bad_task(self):\n'
        "        bad=task('a',2,lambda i:i&1);bad['outputs']=[0,1]\n"
        '        with self.assertRaises(ValueError):validate_task(bad)\n'
        "        bad=task('a',2,lambda i:i&1);bad['outputs'][0]=True\n"
        '        with self.assertRaises(ValueError):validate_task(bad)\n'
        '\n'
        '    def test_reject_fake_ast_even_new_hash(self):\n'
        "        t=task('and2',2,lambda i:i==3)\n"
        "        doc=build([t],['and2'],generations=0)\n"
        "        sol=copy.deepcopy(doc['generations'][0]['solutions']['and2'])\n"
        "        sol['ast']=['c',1]\n"
        '        self.assertFalse(verify_solution(t,sol))\n'
        '\n'
        '    def test_determinism(self):\n'
        '        a=build(self.tasks,self.train,generations=1)\n'
        '        b=build(self.tasks,self.train,generations=1)\n'
        '        self.assertEqual(a,b)\n'
        '\n'
        "if __name__=='__main__':unittest.main()\n"
    ),
