        'from pathlib import Path\n'
        'import pytest\n'
        'from omega_refine_check.contracts import check_program,verify_contract\n'
        'from omega_refine_check.syntax import lower,parse\n'
        '\n'
        "PROGRAM='''// Input and result contracts\n"
        'type Probability = Rational where { self >= 0/1 and self <= 1/1 }\n'
        'parametro x: Probability = 1/2;\n'
        'tensor y: Probability = x*(1-x);\n'
        'mostrar y;\n'
        "'''\n"
        '\n'
        '\n'
        'def test_refinement_metadata_and_universal_contract():\n'
        '    result=check_program(PROGRAM)\n'
        "    assert result['obligations']==4\n"
        "    assert result['metadata']==lower(PROGRAM)\n"
        "    assert '(v0 : ℚ)' in result['source']\n"
        '\n'
        '\n'
        "@pytest.mark.parametrize('source',[\n"
        "    'type P = Rational where {self>=0} parametro x:P=-1; mostrar x;',\n"
        "    'type Empty = Rational where {self>0 and self<0} parametro x:Empty=0; mostrar x;',\n"
        "    'parametro x=0; tensor y=1/x; mostrar y;',\n"
        "    'type P = Rational where {self>=0} parametro x:P=1; tensor y:P=x-2; mostrar y;',\n"
        '])\n'
        'def test_unproved_refinement_or_division_rejected(source):\n'
        '    with pytest.raises(ValueError):check_program(source)\n'
        '\n'
        '\n'
        'def test_nonzero_divisor_requires_explicit_premise():\n'
        "    result=verify_contract({'x':'self != 0'},'1/x','result*x == 1')\n"
        "    assert result['obligations']==2\n"
        "    with pytest.raises(ValueError):verify_contract({'x':'true'},'1/x','result*x == 1')\n"
        '\n'
        '\n'
        'def test_static_vector_norm_and_denominator():\n'
        "    result=check_program('type V = Tensor[Rational,3] where {norm(self)<=50} parametro v:V=[3,4,0]; mostrar v;')\n"
        "    assert result['obligations']==1\n"
        "    assert verify_contract({'x':'self.denom != 0'},'x','result.denom != 0')['obligations']==1\n"
