        'def generation(tmp_path_factory):\n'
        "    root=tmp_path_factory.mktemp('mutation')/'generation'\n"
        "    rule=discover_rule('(x*2)-x',iterations=128)\n"
        '    result=evolve(rule,root)\n'
        '    return root,result\n'
        '\n'
        '\n'
        'def test_four_native_stages_full_equivalence_and_activation(generation,tmp_path):\n'
        '    root,result=generation\n'
        "    assert result['bootstrap']['fixed_point'] and len(result['bootstrap']['stages'])==4\n"
        "    assert result['objective']['after']<result['objective']['before']\n"
        "    assert 'domain_' in (root/'optimization.lean').read_text()\n"
        '    selected=activate(root,selection_root=tmp_path)\n'
        "    assert load_active(selection_root=tmp_path)==Path(selected['binary'])\n"
        '    deactivate(selection_root=tmp_path)\n'
        '    assert load_active(selection_root=tmp_path) is None\n'
        '\n'
        '\n'
        "@pytest.mark.parametrize('lhs,rhs',[('x+1','x'),('x/x','x'),('x*0','x')])\n"
        'def test_nonidentical_or_partial_rules_rejected(lhs,rhs):\n'
        '    with pytest.raises(ValueError):validate_rule(lhs,rhs)\n'
        '\n'
        '\n'
        'def test_forged_generation_cannot_authenticate_its_own_executable(generation,tmp_path):\n'
        '    import shutil,hashlib\n'
        "    source,_=generation;root=tmp_path/'forged';shutil.copytree(source,root)\n"
        "    binary=root/'bootstrap/stage3';binary.write_bytes(b'forged executable')\n"
        "    path=root/'generation.json';record=json.loads(path.read_text())\n"
        "    record['files']['bootstrap/stage3']=hashlib.sha256(binary.read_bytes()).hexdigest()\n"
        '    path.write_text(json.dumps(record))\n'
        "    with pytest.raises(ValueError,match='Untrusted'):audit_generation(root)\n"
        "    assert not (tmp_path/'active.json').exists()\n"
        '\n'
