        '        with tempfile.TemporaryDirectory() as pasta:\n'
        "            alvo = Path(pasta) / 's.omc'\n"
        '            p = subprocess.run([sys.executable, "-m", "omega", "compile",\n'
        "                                str(ROOT / 'exemplos/tipos_e_teoremas.omega'),\n"
        "                                '-o', str(alvo)], cwd=ROOT, capture_output=True, text=True)\n"
        '            self.assertEqual(p.returncode, 0, p.stderr)\n'
        '            t = checar_tipos(ler_comandos(alvo))\n'
        "            self.assertIn('quadrado_da_soma', t.simbolos)\n"
        "            for action in ('run', 'types', 'check'):\n"
        "                r = subprocess.run([sys.executable, '-m', 'omega', action, str(alvo)],\n"
        '                                   cwd=ROOT, capture_output=True, text=True)\n'
        '                self.assertEqual(r.returncode, 0, r.stderr)\n'
        '\n'
        '\n'
        'class Nucleo02(unittest.TestCase):\n'
