        '        from omega import nucleo\n'
        "        self.assertNotIn('omega.algebra', nucleo.__dict__)\n"
        '\n'
        '    def test_certificado_alterado_forma(self):\n'
        '        m = MaquinaOmega().executar(analisar("teorema e=(u+v)^2 == u^2+2*u*v+v^2;"))\n'
        '        falso = copy.deepcopy(m.certificados[0])\n'
        "        falso['forma_normal'][0]['coeficiente'] = '999'\n"
        '        self.assertFalse(verificar_certificado(falso))\n'
        '\n'
        '    def test_certificado_passo_alterado_gradiente(self):\n'
        '        m = MaquinaOmega().executar(analisar("parametro x=3; perda f=x^2; passo f em x taxa 1/4;"))\n'
        '        falso = copy.deepcopy(m.certificados[0])\n'
        "        falso['gradiente'] = '0'\n"
        '        self.assertFalse(verificar_certificado(falso))\n'
        '\n'
        '    def test_identidade_como_divisao_constante(self):\n'
        '        m = MaquinaOmega().executar(analisar("provar x/2+x/2 == x;"))\n'
        '        self.assertTrue(verificar_certificado(m.certificados[0]))\n'
        '\n'
        '    def test_truncamento_de_certificado(self):\n'
        '        self.assertFalse(verificar_certificado({"tipo":"identidade"}))\n'
        '        self.assertFalse(verificar_certificado({"tipo":"passo"}))\n'
        '        self.assertFalse(verificar_certificado({"tipo":"gradiente"}))\n'
        '        self.assertFalse(verificar_certificado({"tipo":"inesperado"}))\n'
        '\n'
        '    def test_tabela_verdade_simbologica_aleatoria(self):\n'
        '        # Comparações independentes entre o executor e o núcleo usando 120 polinômios.\n'
        '        r = random.Random(20261023)\n'
        "        atomos = ['x', 'y', 'z', '-2', '0', '1', '1/3', '(x+y)']\n"
        '        for _ in range(120):\n'
        '            termos = []\n'
        '            for __ in range(5):\n'
        '                a, b = r.choice(atomos), r.choice(atomos)\n'
        "                termos.append(f'({a})*({b})')\n"
        "            fonte = '+'.join(termos)\n"
        "            expr = analisar(f'provar {fonte} == {fonte};')[0].expressao\n"
        '            direto = normalizar(expr)\n'
        '            kernel = polinomio(expressao_para_dict(expr))\n'
        '            self.assertEqual(direto.forma_normal(), forma_normal(kernel))\n'
        "            estado = {'x':Fraction(r.randint(-3,3)), 'y':Fraction(r.randint(-3,3)), 'z':Fraction(r.randint(-3,3))}\n"
        '            self.assertEqual(direto.avaliar(estado), avaliar(kernel, estado))\n'
        '            for var in estado:\n'
        '                self.assertEqual(direto.derivar(var).avaliar(estado), avaliar(derivada(kernel, var), estado))\n'
        '\n'
        '\n'
        "if __name__ == '__main__':\n"
        '    unittest.main()\n'
