        '"""Regressão 0.4: matrizes/vetores mutáveis, AD tensorial e provas independentes."""\n'
        'from __future__ import annotations\n'
        '\n'
        'import copy\n'
        'from fractions import Fraction\n'
        'from pathlib import Path\n'
        'import random\n'
        'import subprocess\n'
        'import sys\n'
        'import tempfile\n'
        'import unittest\n'
        '\n'
        'from omega.algebra import normalizar\n'
        'from omega.autodiff_tensor import retropropagar_tensores\n'
        'from omega.execucao import MaquinaOmega, verificar_certificado\n'
        'from omega.sintaxe import ErroOmega, analisar, comando_de_dict, comando_para_dict\n'
        'from omega.tipos import checar_tipos\n'
        '\n'
        'ROOT = Path(__file__).resolve().parents[1]\n'
        '\n'
        '\n'
        'def rodar(codigo):\n'
        '    return MaquinaOmega().executar(analisar(codigo))\n'
        '\n'
        '\n'
        'class ParametrosTensoriais(unittest.TestCase):\n'
        '    def test_dimensoes_e_inicializacao(self):\n'
        "        src = 'parametro vetor a=[1,2]; parametro matriz B=[[3,4],[5,6]]; mostrar a; mostrar B;'\n"
        '        maquina = rodar(src)\n'
        "        self.assertEqual(checar_tipos(analisar(src)).simbolos['a'], 'ParametroVetor[2]')\n"
        "        self.assertEqual(checar_tipos(analisar(src)).simbolos['B'], 'ParametroMatriz[2,2]')\n"
        '        self.assertIn("a = [\'1\', \'2\']", maquina.saidas)\n'
        '        self.assertIn("B = [[\'3\', \'4\'], [\'5\', \'6\']]", maquina.saidas)\n'
        '\n'
        '    def test_gradiente_vetor_passo_exato(self):\n'
        "        m = rodar('parametro vetor w=[3,4]; perda L=dot(w,w); gradiente L em w; passo L em w taxa 1/4; mostrar w; mostrar L;')\n"
        '        self.assertIn("d(L)/d(w) [tensor] = [\'6\', \'8\']", m.saidas)\n'
        '        self.assertIn("w = [\'3/2\', \'2\']", m.saidas)\n'
        "        self.assertIn('L = 25/4', m.saidas)\n"
        '        self.assertTrue(all(verificar_certificado(c) for c in m.certificados))\n'
        '\n'
        '    def test_gradiente_matriz_e_atualizacao(self):\n'
